def _gc14_has_surface_value(value: object) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, dict, tuple, set)):
        return bool(value)
    return True


def _gc14_surface_status(payloads: dict[str, object]) -> str:
    filled_axes = [name for name, value in payloads.items() if _gc14_has_surface_value(value)]
    if not filled_axes:
        return "empty"
    if len(filled_axes) == len(payloads):
        return "ready"
    return "partial"


def _gc14_clean_text_list(raw: object, *, max_items: int, max_len: int = 200) -> list[str]:
    if not isinstance(raw, list):
        return []
    items: list[str] = []
    seen: set[str] = set()
    for item in raw:
        text = _clean_canonical_text_r1a(item, max_len=max_len)
        if not text:
            continue
        key = text.casefold()
        if key in seen:
            continue
        seen.add(key)
        items.append(text)
        if len(items) >= max_items:
            break
    return items


def _sg14_build_handoff_edge(*, story_frame: dict, turn_directives: dict) -> str:
    pressure = _clean_canonical_text_r1a(turn_directives.get("tempo_band"), max_len=40) or "steady"
    carry_targets = turn_directives.get("carry_targets") or []
    beat_queue = story_frame.get("beat_queue") or []
    scene_drive = _clean_canonical_text_r1a(turn_directives.get("scene_drive"), max_len=160)
    if pressure in {"strong", "critical"}:
        return "End on a visible pressure beat without forcing a full resolution."
    if carry_targets:
        return "Land at least one visible beat before ending, while keeping unresolved carry targets open."
    if beat_queue or scene_drive:
        return "End on a clear continuation edge that preserves the active scene drive."
    return "End on a conservative continuation edge without forcing a hard scene jump."


def _sg15_build_execution_contract(*, story_frame: dict, turn_directives: dict) -> dict:
    carry_threads = story_frame.get("carry_threads") or []
    carry_targets = turn_directives.get("carry_targets") or []
    blocked_routes = turn_directives.get("blocked_routes") or []
    return {
        "must_hit": carry_targets[:4],
        "forbidden": blocked_routes[:4],
        "pacing_pressure": _clean_canonical_text_r1a(turn_directives.get("tempo_band"), max_len=40) or "steady",
        "ending_requirement": _clean_canonical_text_r1a(turn_directives.get("handoff_edge"), max_len=180) or "",
        "continuity_lock": _sg15_pick_first_text(carry_threads, max_len=160),
    }


def _sg15_build_fail_mode(*, story_frame: dict, turn_directives: dict) -> dict:
    has_carry_targets = bool(turn_directives.get("carry_targets"))
    has_scene_drive = bool(turn_directives.get("scene_drive"))
    has_story_drive = bool((story_frame.get("beat_queue") or []) or story_frame.get("narrative_drive"))
    if turn_directives.get("tempo_band") in {"strong", "critical"}:
        mode = "pressure_continuation_without_resolution"
    elif has_carry_targets:
        mode = "carry_forward_without_forcing_resolution"
    elif has_scene_drive or has_story_drive:
        mode = "scene_continuation_without_scene_jump"
    else:
        mode = "conservative_continuation"
    return {
        "mode": mode,
        "allow_scene_jump": False,
        "allow_forced_resolution": False,
        "respect_explicit_user_correction": True,
        "preserve_carry_targets": has_carry_targets,
    }


def _build_story_guidance_surface_sg14(story_plan_data: dict | None, director_data: dict | None) -> dict:
    sp = story_plan_data if isinstance(story_plan_data, dict) else {}
    dr = director_data if isinstance(director_data, dict) else {}

    story_frame = {
        "stage_type": "story_frame",
        "arc_focus": _clean_canonical_text_r1a(sp.get("current_arc"), max_len=160) or "",
        "narrative_drive": _clean_canonical_text_r1a(sp.get("narrative_goal"), max_len=200) or "",
        "live_tensions": _gc14_clean_text_list(sp.get("active_tensions"), max_items=4, max_len=160),
        "beat_queue": _gc14_clean_text_list(sp.get("next_beats"), max_items=4, max_len=180),
        "carry_threads": _gc14_clean_text_list(sp.get("continuity_anchors"), max_items=4, max_len=140),
        "spotlight_characters": _gc14_clean_text_list(sp.get("focus_characters"), max_items=4, max_len=80),
    }
    story_frame["status"] = _gc14_surface_status({
        "arc_focus": story_frame["arc_focus"],
        "narrative_drive": story_frame["narrative_drive"],
        "live_tensions": story_frame["live_tensions"],
        "beat_queue": story_frame["beat_queue"],
        "carry_threads": story_frame["carry_threads"],
    })

    turn_directives = {
        "stage_type": "turn_directives",
        "scene_drive": _clean_canonical_text_r1a(dr.get("scene_mandate"), max_len=180) or "",
        "carry_targets": _gc14_clean_text_list(dr.get("required_outcomes"), max_items=4, max_len=180),
        "blocked_routes": _gc14_clean_text_list(dr.get("forbidden_moves"), max_items=4, max_len=180),
        "tempo_band": _clean_canonical_text_r1a(dr.get("pressure_level"), max_len=40) or "steady",
        "turn_checklist": _gc14_clean_text_list(dr.get("execution_checklist"), max_items=4, max_len=180),
        "voice_guardrails": _gc14_clean_text_list(dr.get("persona_guardrails"), max_items=4, max_len=160),
        "setting_guardrails": _gc14_clean_text_list(dr.get("world_guardrails"), max_items=4, max_len=180),
        "spotlight_characters": _gc14_clean_text_list(dr.get("focus_characters") or sp.get("focus_characters"), max_items=4, max_len=80),
    }
    turn_directives["handoff_edge"] = _sg14_build_handoff_edge(
        story_frame=story_frame,
        turn_directives=turn_directives,
    )
    turn_directives["execution_contract"] = _sg15_build_execution_contract(
        story_frame=story_frame,
        turn_directives=turn_directives,
    )
    turn_directives["fail_mode"] = _sg15_build_fail_mode(
        story_frame=story_frame,
        turn_directives=turn_directives,
    )
    turn_directives["status"] = _gc14_surface_status({
        "scene_drive": turn_directives["scene_drive"],
        "carry_targets": turn_directives["carry_targets"],
        "blocked_routes": turn_directives["blocked_routes"],
        "handoff_edge": turn_directives["handoff_edge"],
    })

    precedence = {
        "policy_version": _STORY_GUIDANCE_SURFACE_VERSION,
        "status": "fixed",
        "guidance_authority": "subordinate",
        "higher_priority_sources": [
            "current_user_input",
            "explicit_user_correction",
            "hard_world_rule",
            "latest_direct_evidence",
            "canonical_truth_floor",
        ],
        "disallowed_usage": [
            "current_user_input_override",
            "explicit_user_correction_override",
            "hard_world_rule_bypass",
            "canonical_truth_floor_overwrite",
        ],
        "precedence_note": (
            "Story guidance is a subordinate planning surface. Follow current user input, explicit user corrections, "
            "direct evidence, canonical truth, and hard world rules first."
        ),
    }

    status = _gc14_surface_status({
        "story_frame": story_frame if story_frame.get("status") != "empty" else None,
        "turn_directives": turn_directives if turn_directives.get("status") != "empty" else None,
    })
    return {
        "surface_version": _STORY_GUIDANCE_SURFACE_VERSION,
        "surface_type": "story_guidance_surface",
        "status": status,
        "story_frame": story_frame,
        "turn_directives": turn_directives,
        "precedence": precedence,
    }


def _sg15_pick_first_text(values: object, *, max_len: int = 180) -> str:
    if not isinstance(values, list):
        return ""
    for item in values:
        text = _clean_canonical_text_r1a(item, max_len=max_len)
        if text:
            return text
    return ""


def _normalize_consumed_beat_label_n2a(raw: str) -> str:
    """N-2a: consumed beat label??compact??臾몄옄?대줈 ?뺢퇋?뷀븳??"""
    text = " ".join(str(raw or "").split()).strip()
    if not text:
        return ""
    for prefix in ("[resolved]", "Resolved:"):
        if text.startswith(prefix):
            text = text[len(prefix):].strip()
    return text[:200]


def _normalize_story_ledger_label_lw1a(raw: object, *, max_len: int = 200) -> str:
    text = " ".join(str(raw or "").split()).strip()
    return text[:max_len] if text else ""


def _contains_payoff_hint_lw1a(text: str) -> bool:
    lowered = text.lower()
    return any(
        token in lowered
        for token in ("payoff", "callback", "promise", "?뚯닔", "?쎌냽", "蹂듭꽑")
    )


def _derive_anchor_relations_lw1b(label: str, story_plan_data: dict, director_data: dict) -> list[str]:
    """LW-1b: ledger ??ぉ??affected_relations瑜?deterministic?섍쾶 異붾줎?쒕떎."""
    candidates: list[str] = []
    for raw in (director_data.get("focus_characters") or []):
        text = _normalize_story_ledger_label_lw1a(raw, max_len=64)
        if text and text not in candidates:
            candidates.append(text)
    for raw in (story_plan_data.get("focus_characters") or []):
        text = _normalize_story_ledger_label_lw1a(raw, max_len=64)
        if text and text not in candidates:
            candidates.append(text)

    lowered = label.lower()
    matched = [name for name in candidates if name.lower() in lowered]
    if matched:
        return matched[:4]
    return candidates[:2]


def _derive_anchor_world_lw1b(label: str, story_plan_data: dict, director_data: dict) -> list[str]:
    """LW-1b: ledger ??ぉ??affected_world瑜?deterministic?섍쾶 異붾줎?쒕떎."""
    candidates: list[str] = []
    for raw in (director_data.get("world_guardrails") or []):
        text = _normalize_story_ledger_label_lw1a(raw, max_len=72)
        if text and text not in candidates:
            candidates.append(text)
    for raw in (story_plan_data.get("guardrails") or []):
        text = _normalize_story_ledger_label_lw1a(raw, max_len=72)
        if text and text not in candidates:
            candidates.append(text)

    current_arc = _normalize_story_ledger_label_lw1a(story_plan_data.get("current_arc"), max_len=72)
    if current_arc and current_arc not in candidates:
        candidates.append(current_arc)

    lowered = label.lower()
    matched = [item for item in candidates if item.lower() in lowered]
    if matched:
        return matched[:4]
    return candidates[:2]


def _build_story_ledger_anchor_lw1b(
    *,
    label: str,
    story_plan_data: dict,
    director_data: dict,
) -> dict:
    """LW-1b: ledger entry 怨듯넻 anchor payload瑜?議곕┰?쒕떎."""
    return {
        "source_record_id": None,
        "source_message_ids": [],
        "affected_relations": _derive_anchor_relations_lw1b(label, story_plan_data, director_data),
        "affected_world": _derive_anchor_world_lw1b(label, story_plan_data, director_data),
    }


def _classify_world_pressure_bucket_lw1d(label: str) -> str:
    lowered = label.lower()
    if any(tok in lowered for tok in ("faction", "guild", "clan", "house", "family", "group")):
        return "factions"
    if any(tok in lowered for tok in ("region", "city", "village", "harbor", "capital", "area", "town")):
        return "regions"
    if any(tok in lowered for tok in ("offscreen", "elsewhere", "distant", "?꾨갑", "?먯젙", "?吏", "?몃?")):
        return "offscreen_threads"
    if any(tok in lowered for tok in ("public", "rumor", "panic", "trust", "誘쇱떖", "?щ줎", "?뚮Ц", "怨듯룷")):
        return "public_pressure"
    return "public_pressure"


def _build_world_pressure_lw1d(
    *,
    story_plan_data: dict,
    director_data: dict,
    pending_beats: list[str],
    consumed_beats: list[str],
    last_turn: int | None,
) -> dict:
    """LW-1d: world pressure structured support layer瑜?deterministic?섍쾶 議곕┰?쒕떎."""
    buckets = {
        "factions": [],
        "regions": [],
        "offscreen_threads": [],
        "public_pressure": [],
    }

    def _append(bucket: str, label: str, source: str, pressure_state: str):
        text = _normalize_story_ledger_label_lw1a(label, max_len=220)
        if not text:
            return
        if any(text == item.get("label") for item in buckets[bucket]):
            return
        buckets[bucket].append({
            "label": text,
            "source": source,
            "pressure_state": pressure_state,
            "deterministic": True,
        })

    for item in (director_data.get("world_guardrails") or []):
        label = _normalize_story_ledger_label_lw1a(item, max_len=220)
        _append(_classify_world_pressure_bucket_lw1d(label), label, "director.world_guardrails", "active")

    for item in (story_plan_data.get("execution_notes") or []):
        label = _normalize_story_ledger_label_lw1a(item, max_len=220)
        _append(_classify_world_pressure_bucket_lw1d(label), label, "story_plan.execution_notes", "escalating")

    for item in pending_beats:
        label = _normalize_story_ledger_label_lw1a(item, max_len=220)
        _append("offscreen_threads", label, "story_plan.next_beats", "latent")

    for item in consumed_beats:
        label = _normalize_story_ledger_label_lw1a(item, max_len=220)
        _append("public_pressure", label, "director.resolved_outcomes", "aftermath")

    timeline = [{
        "turn": int(last_turn or 0),
        "marker": "world_pressure_snapshot",
        "factions": len(buckets["factions"]),
        "regions": len(buckets["regions"]),
        "offscreen_threads": len(buckets["offscreen_threads"]),
        "public_pressure": len(buckets["public_pressure"]),
    }]

    return {
        "status": "structured_support",
        "factions": buckets["factions"][:10],
        "regions": buckets["regions"][:10],
        "offscreen_threads": buckets["offscreen_threads"][:10],
        "public_pressure": buckets["public_pressure"][:10],
        "timeline": timeline,
    }


def _build_supporting_precedence_guard_lw1e() -> dict:
    """LW-1e: story ledger/world pressure???곗꽑?쒖쐞 ceiling 怨꾩빟??怨좎젙?쒕떎."""
    return {
        "status": "supporting_only",
        "supporting_only": True,
        "cannot_override_current_user_input": True,
        "cannot_override_verified_direct_evidence": True,
        "precedence_ceiling": "below_current_user_input_and_verified_direct_evidence",
        "allowed_usage": ["continuity_hint", "narrative_support"],
        "disallowed_usage": ["truth_overwrite", "canonical_override"],
    }


def _build_compatibility_contract_lw1f() -> dict:
    """LW-1f: ?꾩옱 chapter/arc/continuity 援ъ“????명솚 ?쒕㈃ 怨꾩빟??怨좎젙?쒕떎."""
    return {
        "status": "compatible",
        "targets": ["chapter_summary", "arc_summary", "continuity_pack"],
        "shape_mode": "additive_non_breaking",
        "consumer_safe": True,
        "adapter_required": False,
    }


def _build_lifecycle_model_lw1g() -> dict:
    """LW-1g: ledger lifecycle/pressure/decay 紐⑤뜽 怨꾩빟??怨좎젙?쒕떎."""
    return {
        "status": "active",
        "states": ["latent", "active", "escalating", "aftermath", "resolved", "dormant"],
        "pressure_scale": {"min": 0, "max": 3},
        "decay_rules": {
            "latent": 5,
            "active": 4,
            "escalating": 3,
            "aftermath": 2,
            "resolved": 1,
            "dormant": 0,
        },
        "mode": "deterministic_no_llm",
    }


def _lifecycle_profile_for_state_lw1g(state: str, lifecycle_model: dict) -> tuple[int, int]:
    pressure_map = {
        "latent": 1,
        "active": 2,
        "escalating": 3,
        "aftermath": 1,
        "resolved": 0,
        "dormant": 0,
    }
    decay_map = (lifecycle_model or {}).get("decay_rules") or {}
    return int(pressure_map.get(state, 1)), int(decay_map.get(state, 2))


def _build_do_not_resolve_guard_lw1h() -> dict:
    """LW-1h: ?κ린 payoff/tension??議곌린 ?댁냼瑜?留됰뒗 guard 怨꾩빟??怨좎젙?쒕떎."""
    return {
        "status": "active",
        "mode": "deterministic_no_llm",
        "min_turn_gap": 2,
        "protected_entry_types": ["unresolved_tension", "payoff"],
        "protected_sources": ["story_plan.next_beats", "director.required_outcomes"],
        "long_horizon_tokens": ["promise", "payoff", "callback", "?쎌냽", "蹂듭꽑", "?뚯닔"],
    }


def _is_long_horizon_candidate_lw1h(*, label: str, source: str, guard: dict) -> bool:
    normalized = str(label or "").strip().lower()
    source_key = str(source or "").strip().lower()
    if not normalized:
        return False
    tokens = [str(item or "").strip().lower() for item in (guard.get("long_horizon_tokens") or []) if str(item or "").strip()]
    if any(token and token in normalized for token in tokens):
        return True
    protected_sources = {
        str(item or "").strip().lower()
        for item in (guard.get("protected_sources") or [])
        if str(item or "").strip()
    }
    return source_key in protected_sources


def _attach_do_not_resolve_fields_lw1h(*, entry: dict, guard: dict, last_turn: int | None) -> None:
    label = str((entry or {}).get("label") or "")
    source = str((entry or {}).get("source") or "")
    should_protect = _is_long_horizon_candidate_lw1h(label=label, source=source, guard=guard)
    min_turn_gap = int(guard.get("min_turn_gap") or 0)
    base_turn = int(last_turn or 0)
    entry["do_not_resolve_yet"] = bool(should_protect)
    entry["resolve_guard_reason"] = "long_horizon_candidate" if should_protect else None
    entry["resolve_earliest_turn"] = (base_turn + min_turn_gap) if should_protect else None


def _build_story_ledger_lw1a(
    *,
    story_plan_data: dict | None,
    director_data: dict | None,
    pending_beats: list[str],
    consumed_beats: list[str],
    last_turn: int | None,
) -> dict:
    """LW-1a: deterministic story ledger瑜?story_plan/director?먯꽌 議곕┰?쒕떎.

    no-LLM 寃쎈줈瑜?湲곕낯?쇰줈 ?섎ŉ, 湲곗〈 narrative-control ?곗씠?곕쭔?쇰줈
    unresolved_tensions / consequences / payoffs / scene_deltas瑜?怨꾩궛?쒕떎.
    """
    sp = story_plan_data if isinstance(story_plan_data, dict) else {}
    dr = director_data if isinstance(director_data, dict) else {}
    consumed_set = {" ".join(str(item or "").split()).strip().lower() for item in consumed_beats if str(item or "").strip()}
    lifecycle_model = _build_lifecycle_model_lw1g()
    do_not_resolve_guard = _build_do_not_resolve_guard_lw1h()

    unresolved_tensions: list[dict] = []
    for beat in pending_beats:
        label = _normalize_story_ledger_label_lw1a(beat)
        if not label:
            continue
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("latent", lifecycle_model)
        unresolved_tensions.append({
            "entry_type": "unresolved_tension",
            "label": label,
            "source": "story_plan.next_beats",
            "status": "open",
            "lifecycle_state": "latent",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })
        _attach_do_not_resolve_fields_lw1h(
            entry=unresolved_tensions[-1],
            guard=do_not_resolve_guard,
            last_turn=last_turn,
        )

    for item in (dr.get("required_outcomes") or []):
        label = _normalize_story_ledger_label_lw1a(item)
        if not label:
            continue
        if label.lower() in consumed_set:
            continue
        if any(label == existing.get("label") for existing in unresolved_tensions):
            continue
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("active", lifecycle_model)
        unresolved_tensions.append({
            "entry_type": "unresolved_tension",
            "label": label,
            "source": "director.required_outcomes",
            "status": "open",
            "lifecycle_state": "active",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })
        _attach_do_not_resolve_fields_lw1h(
            entry=unresolved_tensions[-1],
            guard=do_not_resolve_guard,
            last_turn=last_turn,
        )

    consequences: list[dict] = []
    for item in (sp.get("execution_notes") or []):
        label = _normalize_story_ledger_label_lw1a(item)
        if not label:
            continue
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("escalating", lifecycle_model)
        consequences.append({
            "entry_type": "consequence",
            "label": label,
            "source": "story_plan.execution_notes",
            "status": "pending",
            "lifecycle_state": "escalating",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })
    for item in (dr.get("execution_checklist") or []):
        label = _normalize_story_ledger_label_lw1a(item)
        if not label:
            continue
        if any(label == existing.get("label") for existing in consequences):
            continue
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("active", lifecycle_model)
        consequences.append({
            "entry_type": "consequence",
            "label": label,
            "source": "director.execution_checklist",
            "status": "pending",
            "lifecycle_state": "active",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })

    payoffs: list[dict] = []
    payoff_labels: set[str] = set()
    for item in (dr.get("resolved_outcomes") or []):
        label = _normalize_story_ledger_label_lw1a(_normalize_consumed_beat_label_n2a(str(item or "")))
        if not label:
            continue
        if label in payoff_labels:
            continue
        payoff_labels.add(label)
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("resolved", lifecycle_model)
        payoffs.append({
            "entry_type": "payoff",
            "label": label,
            "source": "director.resolved_outcomes",
            "status": "resolved",
            "payoff_state": "completed",
            "lifecycle_state": "resolved",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })
        _attach_do_not_resolve_fields_lw1h(
            entry=payoffs[-1],
            guard=do_not_resolve_guard,
            last_turn=last_turn,
        )

    for item in (dr.get("expired_forbidden") or []):
        label = _normalize_story_ledger_label_lw1a(str(item or ""))
        if not label:
            continue
        if label in payoff_labels:
            continue
        payoff_labels.add(label)
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("dormant", lifecycle_model)
        payoffs.append({
            "entry_type": "payoff",
            "label": label,
            "source": "director.expired_forbidden",
            "status": "invalid",
            "payoff_state": "invalid",
            "lifecycle_state": "dormant",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })
        _attach_do_not_resolve_fields_lw1h(
            entry=payoffs[-1],
            guard=do_not_resolve_guard,
            last_turn=last_turn,
        )

    for beat in pending_beats:
        label = _normalize_story_ledger_label_lw1a(beat)
        if not label or not _contains_payoff_hint_lw1a(label):
            continue
        if label in payoff_labels:
            continue
        payoff_labels.add(label)
        anchors = _build_story_ledger_anchor_lw1b(label=label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("latent", lifecycle_model)
        payoffs.append({
            "entry_type": "payoff",
            "label": label,
            "source": "story_plan.next_beats",
            "status": "pending",
            "payoff_state": "pending",
            "lifecycle_state": "latent",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })
        _attach_do_not_resolve_fields_lw1h(
            entry=payoffs[-1],
            guard=do_not_resolve_guard,
            last_turn=last_turn,
        )

    scene_deltas: list[dict] = []
    scene_mandate = _normalize_story_ledger_label_lw1a(dr.get("scene_mandate"), max_len=240)
    if scene_mandate:
        anchors = _build_story_ledger_anchor_lw1b(label=scene_mandate, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("active", lifecycle_model)
        scene_deltas.append({
            "entry_type": "scene_delta",
            "label": scene_mandate,
            "source": "director.scene_mandate",
            "status": "observed",
            "turn_hint": int(last_turn or 0),
            "lifecycle_state": "active",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })

    pressure_level = _normalize_story_ledger_label_lw1a(dr.get("pressure_level"))
    if pressure_level:
        pressure_label = f"pressure={pressure_level}"
        anchors = _build_story_ledger_anchor_lw1b(label=pressure_label, story_plan_data=sp, director_data=dr)
        pressure_score, decay_turns = _lifecycle_profile_for_state_lw1g("escalating", lifecycle_model)
        scene_deltas.append({
            "entry_type": "scene_delta",
            "label": pressure_label,
            "source": "director.pressure_level",
            "status": "observed",
            "turn_hint": int(last_turn or 0),
            "lifecycle_state": "escalating",
            "pressure_score": pressure_score,
            "decay_turns": decay_turns,
            "deterministic": True,
            **anchors,
        })

    world_pressure = _build_world_pressure_lw1d(
        story_plan_data=sp,
        director_data=dr,
        pending_beats=pending_beats,
        consumed_beats=consumed_beats,
        last_turn=last_turn,
    )
    supporting_precedence_guard = _build_supporting_precedence_guard_lw1e()
    compatibility_contract = _build_compatibility_contract_lw1f()

    return {
        "ledger_policy_version": "lw1h.v1",
        "ledger_mode": "deterministic_no_llm",
        "unresolved_tensions": unresolved_tensions[:12],
        "consequences": consequences[:12],
        "payoffs": payoffs[:12],
        "scene_deltas": scene_deltas[:8],
        "world_pressure_policy_version": "lw1d.v1",
        "world_pressure": world_pressure,
        "continuity_precedence_policy_version": "lw1e.v1",
        "supporting_precedence_guard": supporting_precedence_guard,
        "compatibility_policy_version": "lw1f.v1",
        "compatibility_contract": compatibility_contract,
        "lifecycle_policy_version": "lw1g.v1",
        "lifecycle_model": lifecycle_model,
        "do_not_resolve_policy_version": "lw1h.v1",
        "do_not_resolve_guard": do_not_resolve_guard,
    }


def _build_progression_ledger_n2a(
    story_plan_data: dict | None,
    director_data: dict | None,
    last_turn: int | None,
    state_status: str | None,
) -> dict:
    """N-2a: narrative-control 湲곕컲 progression ledger skeleton/tracking 議곕┰.

    ?먯튃:
    - 怨꾩빟 ?뺤쓽 ?④퀎?대?濡?蹂댁닔?곸쑝濡?怨꾩궛?쒕떎.
    - last_validated_turn? ready/user_patched ?곹깭?먯꽌留?梨꾩슫??
    - consumed/pending beat??湲곗〈 state JSON?먯꽌 ?뚯깮?쒕떎(?좉퇋 DB 而щ읆 異붽? ?놁쓬).
    """
    sp = story_plan_data if isinstance(story_plan_data, dict) else {}
    dr = director_data if isinstance(director_data, dict) else {}

    pending_beats: list[str] = []
    for item in (sp.get("next_beats") or []):
        beat = " ".join(str(item or "").split()).strip()
        if beat and beat not in pending_beats:
            pending_beats.append(beat)

    consumed_beats: list[str] = []
    for item in (dr.get("resolved_outcomes") or []):
        beat = _normalize_consumed_beat_label_n2a(item)
        if beat and beat not in consumed_beats:
            consumed_beats.append(beat)

    last_advanced_turn = last_turn if isinstance(last_turn, int) and last_turn > 0 else None
    if last_advanced_turn is not None and state_status in ("ready", "user_patched"):
        last_validated_turn = last_advanced_turn
    else:
        last_validated_turn = None

    # N-2c: state_status 湲곕컲 invalidation_reason 寃곗젙
    _VALID_STATUSES = {"ready", "user_patched", "skeleton", None, ""}
    if state_status == "user_patched":
        invalidation_reason = "user_patched"
    elif state_status not in _VALID_STATUSES:
        # rollback / corrupt / unknown ?곹깭: ?덉? 臾댄슚??
        invalidation_reason = "rollback_or_unknown_state"
    else:
        invalidation_reason = None

    status = "tracking" if (last_advanced_turn or pending_beats or consumed_beats) else "skeleton"
    story_ledger = _build_story_ledger_lw1a(
        story_plan_data=sp,
        director_data=dr,
        pending_beats=pending_beats,
        consumed_beats=consumed_beats,
        last_turn=last_turn,
    )

    return ProgressionLedgerState(
        status=status,
        last_advanced_turn=last_advanced_turn,
        last_validated_turn=last_validated_turn,
        consumed_beats=consumed_beats[:8],
        pending_beats=pending_beats[:8],
        invalidation_reason=invalidation_reason,
        ledger_policy_version=story_ledger.get("ledger_policy_version") or "lw1h.v1",
        ledger_mode=story_ledger.get("ledger_mode") or "deterministic_no_llm",
        unresolved_tensions=story_ledger.get("unresolved_tensions") or [],
        consequences=story_ledger.get("consequences") or [],
        payoffs=story_ledger.get("payoffs") or [],
        scene_deltas=story_ledger.get("scene_deltas") or [],
        world_pressure_policy_version=story_ledger.get("world_pressure_policy_version") or "lw1d.v1",
        world_pressure=story_ledger.get("world_pressure") or {},
        continuity_precedence_policy_version=story_ledger.get("continuity_precedence_policy_version") or "lw1e.v1",
        supporting_precedence_guard=story_ledger.get("supporting_precedence_guard") or {},
        compatibility_policy_version=story_ledger.get("compatibility_policy_version") or "lw1f.v1",
        compatibility_contract=story_ledger.get("compatibility_contract") or {},
        lifecycle_policy_version=story_ledger.get("lifecycle_policy_version") or "lw1g.v1",
        lifecycle_model=story_ledger.get("lifecycle_model") or {},
        do_not_resolve_policy_version=story_ledger.get("do_not_resolve_policy_version") or "lw1h.v1",
        do_not_resolve_guard=story_ledger.get("do_not_resolve_guard") or {},
    ).model_dump()


bind_lc1_builder_callbacks(progression_ledger_builder=_build_progression_ledger_n2a)


def _build_autonomy_plan_n2b(ledger: dict) -> dict:
    """N-2b: progression ledger ??autonomy planner 寃고빀.

    ledger dict(_build_progression_ledger_n2a 寃곌낵)瑜??쎄퀬,
    ?대쾲 ?댁뿉??autonomy媛 ?쒖븞?????덈뒗 ?댁슜怨?gate 寃곗젙??諛섑솚?쒕떎.

    mode:
      "pass"     ??ledger ?뺣낫 ?놁쓬(skeleton), autonomy 蹂댁“ ?놁쓬
      "suppress" ??議곌굔 誘몄땐議?pending ?놁쓬 ?먮뒗 beat ?대? ?뚮え??
      "assist"   ???ㅼ쓬 pending beat瑜??쒖븞?????덈뒗 ?곹깭

    N-2b?먯꽌??autonomy_plan??怨꾪쉷/?몄텧?섎뒗 ?섏?留?援ы쁽?쒕떎.
    ?ㅼ젣 LLM proposal? N-3?먯꽌 ?곌껐?쒕떎.
    """
    led_status = ledger.get("status", "skeleton") if ledger else "skeleton"
    pending: list[str] = (ledger.get("pending_beats") or []) if ledger else []
    consumed: list[str] = (ledger.get("consumed_beats") or []) if ledger else []

    invalidation_reason = ledger.get("invalidation_reason") if ledger else None

    if invalidation_reason:
        # N-2c: user_patched ?먮뒗 rollback ?곹깭??autonomy planner瑜??낆뒪?몃┝ ?놁씠 suppress
        return {
            "mode": "suppress",
            "suggested_beat": None,
            "blocked_beats": (ledger.get("consumed_beats") or [])[:4],
            "gate_reason": invalidation_reason,
        }

    if led_status == "skeleton" or not ledger:
        return {
            "mode": "pass",
            "suggested_beat": None,
            "blocked_beats": [],
            "gate_reason": "ledger_skeleton",
        }

    if not pending:
        return {
            "mode": "suppress",
            "suggested_beat": None,
            "blocked_beats": consumed[:4],
            "gate_reason": "no_pending_beat",
        }

    # N-2d: all pending beats already consumed ??suppress (repeated beat prevention)
    unmet = [b for b in pending if b not in consumed]
    if not unmet:
        return {
            "mode": "suppress",
            "suggested_beat": None,
            "blocked_beats": consumed[:4],
            "gate_reason": "all_pending_consumed",
        }

    first_pending = unmet[0]
    if first_pending in consumed:
        return {
            "mode": "suppress",
            "suggested_beat": first_pending,
            "blocked_beats": consumed[:4],
            "gate_reason": "beat_already_consumed",
        }

    # N-2d: false advance guard ??last_advanced_turn ?놁씠 consumed ?대젰留??덉쑝硫?
    # progression ?곹깭瑜??좊ː?????놁쑝誘濡?suppress
    last_adv = ledger.get("last_advanced_turn") if ledger else None
    if last_adv is None and consumed:
        return {
            "mode": "suppress",
            "suggested_beat": first_pending,
            "blocked_beats": consumed[:4],
            "gate_reason": "ledger_stale_no_advance",
        }

    return {
        "mode": "assist",
        "suggested_beat": unmet[0],
        "blocked_beats": consumed[:4],
        "gate_reason": "ok",
    }


def _build_micro_beat_proposal_n3a(
    autonomy_plan: dict | None,
    narrative_control: dict | None,
) -> dict | None:
    """N-3a: autonomy mode=assist????micro-beat hint瑜?議곕┰?쒕떎.

    - suggested_beat 湲곕컲?쇰줈 吏㏃? hint_text瑜?留뚮뱺??
    - director.forbidden_moves? beat媛 寃뱀튂硫?blocked_by??湲곕줉??hint瑜?諛쒗뻾?섏? ?딅뒗??
    - ?ㅼ젣 LLM proposal? N-3 ?댄썑 ?④퀎?먯꽌 ?곌껐?쒕떎.
      ???④퀎?먯꽌??hint ?띿뒪??寃쎈줈留??뺣┰?쒕떎.

    諛섑솚 ?뺥깭:
      {"hint_text": str, "source_beat": str, "proposal_type": "micro_beat", "blocked_by": list}
    mode != "assist"?대㈃ None 諛섑솚.
    """
    if not autonomy_plan or autonomy_plan.get("mode") != "assist":
        return None

    suggested_beat: str | None = autonomy_plan.get("suggested_beat")
    if not suggested_beat:
        return None

    # forbidden_moves 泥댄겕
    forbidden_moves: list[str] = []
    if isinstance(narrative_control, dict):
        director = narrative_control.get("director") or {}
        if isinstance(director, dict):
            for item in (director.get("forbidden_moves") or []):
                label = " ".join(str(item or "").split()).strip().lower()
                if label:
                    forbidden_moves.append(label)

    beat_lower = suggested_beat.lower()
    blocked_by: list[str] = []
    for fm in forbidden_moves:
        # 遺遺??ы븿 ?щ?濡?媛꾨떒??泥댄겕 (N-3?먯꽌??heuristic ?섏??쇰줈 異⑸텇)
        if fm in beat_lower or beat_lower in fm:
            blocked_by.append(fm)

    if blocked_by:
        # forbidden_moves??嫄몃━硫?hint 諛쒗뻾 ????
        return {
            "hint_text": None,
            "source_beat": suggested_beat,
            "proposal_type": "micro_beat",
            "blocked_by": blocked_by,
        }

    hint_text = f"[micro-beat hint] {suggested_beat}"
    return {
        "hint_text": hint_text,
        "source_beat": suggested_beat,
        "proposal_type": "micro_beat",
        "blocked_by": [],
    }


# N-3b ?꾪뿕 ?⑦꽩 ?ㅼ썙???????⑥뼱媛 beat ?띿뒪?몄뿉 ?ы븿?섎㈃ scene-step scope?먯꽌 ?쒖쇅
_N3B_RISKY_KEYWORDS = frozenset([
    "resolve", "resolved", "kill", "killed", "die", "dies", "dead", "death",
    "end", "finale", "conclude", "concluded", "over", "done", "finish", "finished",
])
def _build_scene_step_proposal_n3b(
    autonomy_plan: dict | None,
    micro_beat_proposal: dict | None,
    narrative_control: dict | None,
) -> dict | None:
    """N-3b: bounded scene-step proposal.

    micro_beat_proposal(N-3a)媛 ready=True ?곹깭???뚮쭔 ?ㅽ뻾?쒕떎.
    progression ledger??pending beats 以묒뿉??max_step=2 ?대궡 beats瑜??덉쟾 踰붿쐞濡?臾띠뼱
    scene_step_scope瑜?諛섑솚?쒕떎.

    ?덉쟾 gate:
    1. micro_beat_proposal.ready=False ??None (N-3a 李⑤떒 ?곸냽)
    2. pending beats 以?forbidden_moves / risky keywords??嫄몃━??寃껋? scope ?쒖쇅
    3. scope???⑤뒗 beats??理쒕? max_step=2媛?

    諛섑솚 ?뺥깭:
      {"scope_beats": [...], "max_step": 2, "excluded_beats": [...], "proposal_type": "scene_step"}
    """
    if not micro_beat_proposal or not micro_beat_proposal.get("hint_text"):
        # N-3a媛 李⑤떒?덉쑝硫?N-3b??skip
        return None

    if not autonomy_plan or autonomy_plan.get("mode") != "assist":
        return None

    # pending beats ?섏쭛 (autonomy_plan?먯꽌 suggested_beat + 理쒕? 1媛?異붽?)
    # ?ㅼ젣 pending list??autonomy_plan??吏곸젒 ?놁쑝誘濡?narrative_control?먯꽌 ?뚯깮
    pending_beats: list[str] = []
    if isinstance(narrative_control, dict):
        sp = narrative_control.get("story_plan") or {}
        if isinstance(sp, dict):
            for item in (sp.get("next_beats") or []):
                beat = " ".join(str(item or "").split()).strip()
                if beat and beat not in pending_beats:
                    pending_beats.append(beat)

    if not pending_beats:
        # narrative_control??pending ?뺣낫 ?놁쑝硫?suggested_beat ?⑥씪 ??ぉ留??ъ슜
        suggested = autonomy_plan.get("suggested_beat") or micro_beat_proposal.get("source_beat")
        if suggested:
            pending_beats = [suggested]
        else:
            return None

    # forbidden_moves ?섏쭛
    forbidden_lower: list[str] = []
    if isinstance(narrative_control, dict):
        director = narrative_control.get("director") or {}
        if isinstance(director, dict):
            for item in (director.get("forbidden_moves") or []):
                label = " ".join(str(item or "").split()).strip().lower()
                if label:
                    forbidden_lower.append(label)

    consumed: list[str] = [b.lower() for b in (autonomy_plan.get("blocked_beats") or [])]

    max_step = 2
    scope_beats: list[str] = []
    excluded_beats: list[str] = []

    for beat in pending_beats:
        if len(scope_beats) >= max_step:
            break
        beat_lower = beat.lower()

        # ?대? ?뚮え?먯쑝硫?skip
        if beat_lower in consumed:
            excluded_beats.append(beat)
            continue

        # forbidden_moves 泥댄겕
        forbidden_hit = any(fm in beat_lower or beat_lower in fm for fm in forbidden_lower)
        if forbidden_hit:
            excluded_beats.append(beat)
            continue

        # risky keywords 泥댄겕
        risky_hit = any(kw in beat_lower for kw in _N3B_RISKY_KEYWORDS)
        if risky_hit:
            excluded_beats.append(beat)
            continue

        scope_beats.append(beat)

    if not scope_beats:
        return {
            "scope_beats": [],
            "max_step": max_step,
            "excluded_beats": excluded_beats[:4],
            "proposal_type": "scene_step",
            "gate_reason": "all_beats_excluded",
        }

    return {
        "scope_beats": scope_beats,
        "max_step": max_step,
        "excluded_beats": excluded_beats[:4],
        "proposal_type": "scene_step",
        "gate_reason": "ok",
    }


def _build_combined_planner_n3c(
    micro_beat_proposal: dict | None,
    scene_step_proposal: dict | None,
    narrative_control: dict | None,
    supervisor_pack: dict | None,
    raw_user_input: str = "",
) -> dict | None:
    """N-3c: story plan + director + maintenance signal 寃고빀 planner.

    ???좏샇瑜?寃고빀??combined_hint_text? proposal_confidence瑜?諛섑솚?쒕떎.

    confidence:
      "low"    ??micro_beat留??쒖꽦
      "medium" ??scene_step???쒖꽦 (2 beat scope)
      "high"   ??scene_step + director scene_mandate媛 議댁옱?섎ŉ ?쇨???

    combined_hint_text 議곕┰:
      "[N-3c] {scene_mandate}: {scope_beat}" ?먮뒗 "{scene_mandate}: {micro_beat}"
      scene_mandate媛 ?놁쑝硫?beat hint留??ы븿.

    plan_signals: ?대뼡 ?좏샇媛 寃고빀?먮뒗吏 湲곕줉.
    """
    # 理쒖냼 議곌굔: micro_beat_proposal??ready?ъ빞 ??
    if not micro_beat_proposal or not micro_beat_proposal.get("hint_text"):
        return None

    micro_hint: str = micro_beat_proposal["hint_text"]
    source_beat: str = micro_beat_proposal.get("source_beat") or ""

    # director ?좏샇
    scene_mandate = ""
    required_outcomes: list[str] = []
    if isinstance(narrative_control, dict):
        director = narrative_control.get("director") or {}
        if isinstance(director, dict):
            scene_mandate = " ".join(str(director.get("scene_mandate") or "").split()).strip()
            required_outcomes = [
                " ".join(str(r or "").split()).strip()
                for r in (director.get("required_outcomes") or [])
                if str(r or "").strip()
            ][:3]

    # maintenance signal ??supervisor_pack??drift correction hints ?뺤씤
    maintenance_hint: str | None = None
    if isinstance(supervisor_pack, dict):
        guide_suffix = supervisor_pack.get("guide_suffix") or ""
        if guide_suffix and len(guide_suffix.strip()) > 0:
            maintenance_hint = guide_suffix.strip()[:120]

    plan_signals: list[str] = ["micro_beat"]
    confidence = "low"

    # scene_step??ready硫?scope_beats ?곗꽑 ?ъ슜
    primary_beat = source_beat
    if scene_step_proposal and scene_step_proposal.get("gate_reason") == "ok":
        scope_beats = scene_step_proposal.get("scope_beats") or []
        if scope_beats:
            primary_beat = scope_beats[0]
            plan_signals.append("scene_step")
            confidence = "medium"

    # director scene_mandate媛 ?덉쑝硫?confidence ?곹뼢
    if scene_mandate:
        plan_signals.append("director_mandate")
        if confidence == "medium":
            confidence = "high"
        elif confidence == "low":
            confidence = "medium"

    if maintenance_hint:
        plan_signals.append("maintenance_signal")

    # combined_hint_text assembly
    if scene_mandate and primary_beat:
        combined_hint = f"[N-3c] {scene_mandate}: {primary_beat}"
    elif primary_beat:
        combined_hint = f"[N-3c] {primary_beat}"
    else:
        combined_hint = micro_hint

    return {
        "combined_hint_text": combined_hint,
        "primary_beat": primary_beat,
        "scene_mandate": scene_mandate or None,
        "required_outcomes": required_outcomes,
        "maintenance_hint": maintenance_hint,
        "proposal_confidence": confidence,
        "plan_signals": plan_signals,
        "proposal_type": "combined",
    }


def _build_generation_packet_o1b(
    injection_pack: "dict | None",
    combined_proposal: "dict | None",
    autonomy_plan: "dict | None",
    narrative_control: "dict | None",
    source: str = "partial",
    takeover_mode: str = "off",
    raw_user_input: str = "",
) -> "GenerationPacket":
    """O-1b / O-3a: prepare-turn?먯꽌 議곕┰???곗씠?곕? GenerationPacket?쇰줈 ?⑦궎吏?

    packet_mode 寃곗젙 洹쒖튃:
      - source == "off" ?먮뒗 injection_pack ?놁쓬 ??"off"
      - O-3a: takeover_mode == "default_takeover" AND raw_user_input.strip() ??effective_input = raw_user_input
      - injection_pack ?덇퀬 effective_user_input ?덉쓬 ??"assisted"
      - injection_pack ?덉?留?effective_user_input ?놁쓬 ??"guidance"
      - ?덉쇅 諛쒖깮 ????"degraded"

    guidance_metadata:
      combined_proposal???듭떖 ?꾨뱶 (combined_hint_text, confidence, plan_signals이
      autonomy_plan??mode / suggested_beat / gate_reason

    safety_metadata:
      narrative_control.director.forbidden_moves
      combined_proposal??blocked_beats (N-3a?먯꽌 ?섏쭛)

    trace_summary:
      O-2 shadow compare ?먮떒???꾩슂??寃쎈웾 ?붿빟
    """
    try:
        if source == "off" or not injection_pack:
            return GenerationPacket(
                packet_mode="off",
                fallback_reason="no_injection_pack" if source != "off" else "source_off",
                trace_summary={"takeover_mode": takeover_mode},
            )

        ip = injection_pack or {}
        effective_input: str | None = ip.get("effective_user_input") or None
        injection_text: str | None = ip.get("injection_text") or None
        canon_drift_benchmark = ip.get("canon_drift_benchmark") or {}

        # O-3a: default_takeover ??raw_user_input??effective_user_input?쇰줈 ?ъ슜
        # plugin local LLM improvement ?놁씠??backend媛 ?ㅼ젣 input??packet???댁븘 ?꾨떖
        # (partial_takeover/shadow_compare/off?먯꽌??誘몄쟻????guidance_metadata留??ъ슜)
        if takeover_mode == "default_takeover" and raw_user_input and raw_user_input.strip():
            effective_input = raw_user_input.strip()

        # packet_mode 寃곗젙
        # O-3a: effective_input???덉쑝硫?injection_text ?좊Т? 臾닿??섍쾶 "assisted"
        # (raw_user_input ?쇱슦?낆쑝濡?梨꾩썙吏?寃쎌슦 ?ы븿)
        if effective_input:
            packet_mode = "assisted"
        elif injection_text:
            packet_mode = "guidance"
        else:
            # injection_pack 議댁옱?섏?留??댁슜 ?놁쓬 ??guidance (degraded ?꾨떂)
            packet_mode = "guidance"

        # guidance_metadata: combined_proposal + autonomy_plan ?듭떖 ?꾨뱶
        guidance_metadata: dict = {}
        if combined_proposal:
            guidance_metadata["combined_hint_text"] = combined_proposal.get("combined_hint_text")
            guidance_metadata["proposal_confidence"] = combined_proposal.get("proposal_confidence", "none")
            guidance_metadata["plan_signals"] = combined_proposal.get("plan_signals") or []
            guidance_metadata["primary_beat"] = combined_proposal.get("primary_beat")
        if autonomy_plan:
            guidance_metadata["autonomy_mode"] = autonomy_plan.get("mode", "pass")
            guidance_metadata["suggested_beat"] = autonomy_plan.get("suggested_beat")
            guidance_metadata["gate_reason"] = autonomy_plan.get("gate_reason", "no_plan")

        # safety_metadata: forbidden_moves + blocked_beats
        safety_metadata: dict = {}
        if narrative_control:
            director = (narrative_control.get("director") or {})
            forbidden = director.get("forbidden_moves") or []
            safety_metadata["forbidden_moves"] = [str(f) for f in forbidden if f]
        if autonomy_plan:
            safety_metadata["blocked_beats"] = autonomy_plan.get("blocked_beats") or []

        # trace_summary: O-2 shadow compare??寃쎈웾 ?붿빟 + O-3a routing 吏꾨떒
        trace_summary = {
            "packet_mode": packet_mode,
            "has_injection": bool(injection_text),
            "has_effective_input": bool(effective_input),
            "autonomy_mode": (autonomy_plan or {}).get("mode", "pass"),
            "proposal_confidence": (combined_proposal or {}).get("proposal_confidence", "none"),
            "forbidden_count": len(safety_metadata.get("forbidden_moves") or []),
            "canon_drift_status": str(canon_drift_benchmark.get("status") or "empty"),
            "canon_drift_ratio": round(float(canon_drift_benchmark.get("canon_drift_ratio") or 0.0), 4),
            "canon_priority_applied": bool(canon_drift_benchmark.get("canon_priority_applied")),
            "canon_drift_dimension_count": int(canon_drift_benchmark.get("drift_dimension_count") or 0),
            "canon_drift_covered_count": int(canon_drift_benchmark.get("covered_dimension_count") or 0),
            # O-3a: input routing 吏꾨떒 (raw_user_input?쇰줈 梨꾩썙吏?寃쎌슦 true)
            "effective_input_from_raw": (
                takeover_mode == "default_takeover"
                and bool(raw_user_input and raw_user_input.strip())
                and effective_input == (raw_user_input.strip() if raw_user_input else None)
            ),
        }

        packet = GenerationPacket(
            packet_mode=packet_mode,
            effective_user_input=effective_input,
            injection_text=injection_text,
            guidance_metadata=guidance_metadata,
            safety_metadata=safety_metadata,
            degraded=False,
            fallback_reason="",
            trace_summary={**trace_summary, "takeover_mode": takeover_mode},
        )
        # O-2b: shadow compare record 利됱떆 議곕┰ (old-path 鍮꾧탳??plugin?먯꽌 ?꾩꽦)
        packet.shadow_compare_record = _build_shadow_compare_record_o2b(
            packet,
            takeover_mode,
            injection_pack=ip,
        )
        return packet

    except Exception as exc:
        return GenerationPacket(
            packet_mode="degraded",
            degraded=True,
            fallback_reason=f"assembly_error: {exc!s}"[:120],
        )


def _build_shadow_compare_record_o2b(
    generation_packet: "GenerationPacket",
    takeover_mode: str,
    injection_pack: "dict | None" = None,
) -> "dict":
    """O-2b: shadow compare record ??generation_packet vs old-path 鍮꾧탳 硫뷀??곗씠??議곕┰.

    ??record??plugin??old-path 寃곌낵? ?議고빐 trace??湲곕줉?섎뒗 援ъ“泥대떎.
    backend??new-path 愿???꾨뱶留?梨꾩슱 ???덇퀬,
    old-path ?꾨뱶(local_injection_chars, local_input_changed ????
    plugin???ㅽ뻾 ??梨꾩썙 ?ｋ뒗??

    fields:
      takeover_mode       ???꾩옱 紐⑤뱶 (off/shadow_compare/partial_takeover/default_takeover)
      new_packet_mode     ??generation_packet.packet_mode
      new_has_injection   ??packet??injection_text媛 ?덈뒗吏
      new_has_input       ??packet??effective_user_input???덈뒗吏
      new_proposal_conf   ??combined proposal confidence
      new_autonomy_mode   ??autonomy_plan mode
      new_forbidden_count ??safety_metadata forbidden_moves ??
      new_has_chapter     ??backend injection_pack??real chapter block???ы븿?먮뒗吏
      new_chapter_chars   ??backend chapter_text 湲몄씠
      new_has_chapter_input ??backend input_context_text??[Chapter] anchor媛 ?덈뒗吏
      new_has_saga        ??backend injection_pack??saga digest block???ы븿?먮뒗吏
      new_saga_chars      ??backend saga_text 湲몄씠
      new_has_saga_input  ??backend input_context_text??[Saga] anchor媛 ?덈뒗吏
      divergence_fields   ??plugin??梨꾩슱 鍮꾧탳 ?꾨뱶 紐⑸줉 (placeholder)
    """
    ts = generation_packet.trace_summary or {}
    gm = generation_packet.guidance_metadata or {}
    sm = generation_packet.safety_metadata or {}
    ip = injection_pack or {}
    canon_text = str(ip.get("canon_text") or "")
    chapter_text = str(ip.get("chapter_text") or "")
    saga_text = str(ip.get("saga_text") or "")
    input_context_text = str(ip.get("input_context_text") or "")
    return {
        "takeover_mode": takeover_mode,
        "new_packet_mode": generation_packet.packet_mode,
        "new_has_injection": bool(generation_packet.injection_text),
        "new_has_input": bool(generation_packet.effective_user_input),
        "new_proposal_conf": gm.get("proposal_confidence", "none") or ts.get("proposal_confidence", "none"),
        "new_autonomy_mode": gm.get("autonomy_mode", "pass") or ts.get("autonomy_mode", "pass"),
        "new_forbidden_count": len(sm.get("forbidden_moves") or []),
        "new_has_canon": bool(canon_text.strip()),
        "new_canon_chars": len(canon_text),
        "new_has_chapter": bool(chapter_text.strip()),
        "new_chapter_chars": len(chapter_text),
        "new_has_chapter_input": "[Chapter]" in input_context_text,
        "new_has_saga": bool(saga_text.strip()),
        "new_saga_chars": len(saga_text),
        "new_has_saga_input": "[Saga]" in input_context_text,
        # plugin???ㅽ뻾 ??梨꾩썙 ?ｋ뒗 old-path 鍮꾧탳 ?꾨뱶 (珥덇린媛?None)
        "old_injection_chars": None,
        "old_input_changed": None,
        "old_has_canon": None,
        "old_canon_chars": None,
        "old_has_chapter": None,
        "old_chapter_chars": None,
        "old_has_chapter_input": None,
        "old_has_saga": None,
        "old_saga_chars": None,
        "old_has_saga_input": None,
        "divergence_injection": None,   # True = injection ?댁슜???щ씪吏?
        "divergence_input": None,        # True = effective_user_input???щ씪吏?
        "divergence_canon": None,        # True = canon block ?좊Т/湲몄씠媛 ?щ씪吏?
        "divergence_chapter": None,      # True = chapter block ?좊Т媛 ?щ씪吏?
        "divergence_chapter_input": None,  # True = [Chapter] input anchor ?좊Т媛 ?щ씪吏?
        "divergence_saga": None,         # True = saga block ?좊Т媛 ?щ씪吏?
        "divergence_saga_input": None,   # True = [Saga] input anchor ?좊Т媛 ?щ씪吏?
        "divergence_note": "",
    }


