def _normalize_sc19_relative_lookup_key(value: object, *, mode: str = "compact") -> str:
    raw_label = str(value or "").strip()
    compact_label = re.sub(r"\s+", "", raw_label)
    raw_casefold_label = raw_label.casefold()
    compact_casefold_label = compact_label.casefold()
    if mode == "raw":
        return raw_label
    if mode == "raw_casefold":
        return raw_casefold_label
    if mode == "compact_casefold":
        return compact_casefold_label
    return compact_label


def _normalize_relative_label_fields_sc19(
    relative_label_value: str,
    *,
    active_locale_keys: tuple[str, ...] = (),
) -> dict:
    relation_schema = _SC19_RELATION_SCHEMA
    raw_label = str(relative_label_value or "").strip()
    if not raw_label:
        return {}

    locale_keys = tuple(active_locale_keys) or tuple(relation_schema["default_active_locale_keys"])
    for locale_key in locale_keys:
        locale_pack = relation_schema["locale_packs"].get(locale_key)
        if not isinstance(locale_pack, dict):
            continue

        lookup_mode = str(locale_pack.get("lookup_input_mode") or "compact")
        lookup_value = _normalize_sc19_relative_lookup_key(raw_label, mode=lookup_mode)
        exact_rule = (locale_pack.get("compact_relative_label_rules") or {}).get(lookup_value)
        if isinstance(exact_rule, dict):
            return dict(exact_rule)

        direction_multipliers = locale_pack.get("direction_multipliers") or {}
        unit_map = locale_pack.get("relative_unit_map") or {}
        day_count_words = locale_pack.get("day_count_words") or {}
        for rule in (locale_pack.get("pattern_rules") or ()):
            match = re.match(
                str(rule.get("pattern") or ""),
                _normalize_sc19_relative_lookup_key(
                    raw_label,
                    mode=str(rule.get("input_mode") or lookup_mode),
                ),
            )
            if not match:
                continue
            kind = str(rule.get("kind") or "")
            if kind == "counted_unit":
                canonical_unit = unit_map.get(str(match.group("unit") or "").strip())
                direction = direction_multipliers.get(str(match.group("direction") or "").strip())
                if canonical_unit is None or direction is None:
                    return {}
                offset_value = int(match.group("count")) * int(direction)
                return {
                    "offset_value_min": offset_value,
                    "offset_value_max": offset_value,
                    "offset_unit": canonical_unit,
                    "precision": "exact" if canonical_unit == "day" else "coarse",
                }
            if kind == "counted_day_word":
                count_value = day_count_words.get(str(match.group("count_word") or "").strip())
                direction = direction_multipliers.get(str(match.group("direction") or "").strip())
                if count_value is None or direction is None:
                    return {}
                offset_value = int(count_value) * int(direction)
                return {
                    "offset_value_min": offset_value,
                    "offset_value_max": offset_value,
                    "offset_unit": "day",
                    "precision": "exact",
                }
            if kind == "bounded_unit":
                canonical_unit = unit_map.get(str(match.group("unit") or "").strip())
                if canonical_unit is None:
                    return {}
                return {
                    "offset_value_min": None,
                    "offset_value_max": None,
                    "offset_unit": canonical_unit,
                    "precision": "coarse",
                }
    return {}


