def _build_temporal_state_surface_sc19(raw_states: list[dict] | None) -> dict:
    relation_schema = _SC19_RELATION_SCHEMA
    elapsed_policy = _SC19_ELAPSED_POLICY

    def _resolve_active_relation_locales(raw_active_locales: object) -> tuple[str, ...]:
        default_locale_keys = tuple(relation_schema["default_active_locale_keys"])
        if isinstance(raw_active_locales, str):
            raw_locale_items = [item for item in re.split(r"[\s,]+", raw_active_locales) if item]
        elif isinstance(raw_active_locales, (list, tuple, set)):
            raw_locale_items = list(raw_active_locales)
        else:
            return default_locale_keys

        resolved_locale_keys: list[str] = []
        for item in raw_locale_items:
            locale_key = relation_schema["locale_aliases"].get(str(item or "").strip().casefold())
            if locale_key in relation_schema["locale_packs"] and locale_key not in resolved_locale_keys:
                resolved_locale_keys.append(locale_key)
        return tuple(resolved_locale_keys) or default_locale_keys

    def _normalize_temporal_relation_entry(
        entry: dict,
        *,
        default_source_turn: object = None,
        default_anchor_ref: str | None = None,
        active_locale_keys: tuple[str, ...] = (),
    ) -> dict:
        def _pick(*keys: str) -> object:
            for key in keys:
                if key in entry and entry.get(key) is not None:
                    return entry.get(key)
            return None

        def _parse_optional_int(value: object) -> int | None:
            numeric = _to_float_q1a(value)
            if numeric is None:
                return None
            return int(numeric)

        def _normalize_relative_label_fields(relative_label_value: str) -> dict:
            return _normalize_relative_label_fields_sc19(
                relative_label_value,
                active_locale_keys=active_locale_keys,
            )

        relative_label = str(_pick("relative_label", "relativeLabel") or "").strip()
        normalized_relative_fields = _normalize_relative_label_fields(relative_label)
        anchor_ref_raw = _pick("anchor_ref", "anchorRef", "anchor")
        anchor_ref = str(anchor_ref_raw).strip() if anchor_ref_raw is not None and str(anchor_ref_raw).strip() else None
        if anchor_ref is None and normalized_relative_fields and default_anchor_ref:
            anchor_ref = default_anchor_ref

        target_kind_raw = str(_pick("target_kind", "targetKind") or "").strip()
        target_kind = (
            target_kind_raw
            if target_kind_raw in relation_schema["target_kind_values"]
            else relation_schema["default_target_kind"]
        )

        offset_value_min = _parse_optional_int(_pick("offset_value_min", "offsetValueMin"))
        offset_value_max = _parse_optional_int(_pick("offset_value_max", "offsetValueMax"))
        legacy_day_offsets_used = False
        if offset_value_min is None and _pick("offset_days_min", "offsetDaysMin") is not None:
            offset_value_min = _parse_optional_int(_pick("offset_days_min", "offsetDaysMin"))
            legacy_day_offsets_used = True
        if offset_value_max is None and _pick("offset_days_max", "offsetDaysMax") is not None:
            offset_value_max = _parse_optional_int(_pick("offset_days_max", "offsetDaysMax"))
            legacy_day_offsets_used = True
        if offset_value_min is None:
            offset_value_min = _parse_optional_int(normalized_relative_fields.get("offset_value_min"))
        if offset_value_max is None:
            offset_value_max = _parse_optional_int(normalized_relative_fields.get("offset_value_max"))

        offset_unit_raw = str(_pick("offset_unit", "offsetUnit") or "").strip()
        normalized_offset_unit = str(normalized_relative_fields.get("offset_unit") or "").strip()
        if offset_unit_raw in relation_schema["offset_unit_values"]:
            offset_unit = offset_unit_raw
        elif normalized_offset_unit in relation_schema["offset_unit_values"]:
            offset_unit = normalized_offset_unit
        elif legacy_day_offsets_used:
            offset_unit = relation_schema["legacy_day_offset_unit"]
        else:
            offset_unit = relation_schema["default_offset_unit"]

        precision_raw = str(_pick("precision") or normalized_relative_fields.get("precision") or "").strip()
        precision = precision_raw if precision_raw in _SC19_CLOCK_PRECISION_VALUES else "unknown"

        source_turn = _parse_optional_int(_pick("source_turn", "sourceTurn"))
        if source_turn is None:
            source_turn = _parse_optional_int(default_source_turn)

        status_raw = str(_pick("status") or "").strip()
        if status_raw in relation_schema["status_values"]:
            status = status_raw
        elif offset_value_min is None and offset_value_max is None:
            status = (
                relation_schema["unresolved_range_status"]
                if precision in relation_schema["bounded_precision_values"]
                or offset_unit != relation_schema["default_offset_unit"]
                else relation_schema["unresolved_status"]
            )
        elif anchor_ref:
            status = relation_schema["resolved_status"]
        else:
            status = relation_schema["unresolved_status"]

        valid_from_turn = source_turn
        valid_to_turn = source_turn
        anchor_resolution_status = (
            relation_schema["anchored_resolution"]
            if anchor_ref
            else relation_schema["carry_forward_resolution"]
        )
        if (
            status == relation_schema["resolved_status"]
            and offset_value_min is not None
            and offset_value_max is not None
            and offset_value_min == offset_value_max
        ):
            range_kind = relation_schema["exact_offset_range_kind"]
        elif (
            status == relation_schema["unresolved_range_status"]
            or precision in relation_schema["bounded_precision_values"]
        ):
            range_kind = relation_schema["bounded_ambiguous_range_kind"]
        else:
            range_kind = relation_schema["unresolved_range_kind"]
        bounded_range = None
        if range_kind == relation_schema["bounded_ambiguous_range_kind"]:
            bounded_range = {
                "offset_value_min": offset_value_min,
                "offset_value_max": offset_value_max,
                "offset_unit": offset_unit,
                "precision": precision,
            }
        ambiguity_mode = (
            relation_schema["anchored_exact_ambiguity_mode"]
            if anchor_resolution_status == relation_schema["anchored_resolution"]
            and range_kind == relation_schema["exact_offset_range_kind"]
            else (
                relation_schema["bounded_ambiguity_mode"]
                if range_kind == relation_schema["bounded_ambiguous_range_kind"]
                else relation_schema["carry_forward_unresolved_ambiguity_mode"]
            )
        )

        return {
            "relative_label": relative_label,
            "anchor_ref": anchor_ref,
            "target_kind": target_kind,
            "offset_value_min": offset_value_min,
            "offset_value_max": offset_value_max,
            "offset_unit": offset_unit,
            "precision": precision,
            "status": status,
            "source_turn": source_turn,
            "valid_from_turn": valid_from_turn,
            "valid_to_turn": valid_to_turn,
            "range_kind": range_kind,
            "bounded_range": bounded_range,
            "anchor_resolution_status": anchor_resolution_status,
            "ambiguity_mode": ambiguity_mode,
        }

    def _pick_payload_value(payload: dict | None, *keys: str) -> object:
        if not isinstance(payload, dict):
            return None
        for key in keys:
            if key in payload and payload.get(key) is not None:
                return payload.get(key)
        return None

    def _normalize_elapsed_policy_fields(
        elapsed_payload: dict,
        clock_payload: dict,
        *,
        current_scene_relations: list[dict],
        relation_only_relations: list[dict],
    ) -> tuple[dict, dict]:
        def _normalize_signal_text(value: object, mode: str) -> str:
            raw_text = str(value or "").strip()
            if mode == "compact_casefold":
                return re.sub(r"\s+", "", raw_text).casefold()
            if mode == "compact":
                return re.sub(r"\s+", "", raw_text)
            if mode == "raw_casefold":
                return raw_text.casefold()
            return raw_text

        def _extract_structured_signal_forms(value: object, mode: str) -> tuple[set[str], str]:
            raw_text = str(value or "").strip()
            if mode != "structured_code_hint":
                normalized_text = _normalize_signal_text(raw_text, mode)
                return ({normalized_text} if normalized_text else set()), normalized_text
            if not raw_text or not raw_text.isascii() or re.search(r"\s", raw_text):
                return set(), ""
            camel_split_text = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", raw_text)
            token_text = re.sub(r"[^0-9A-Za-z]+", " ", camel_split_text).casefold()
            tokens = {token for token in token_text.split() if token}
            compact = "".join(token_text.split())
            if compact:
                tokens.add(compact)
            return tokens, compact

        def _derive_trigger_category_from_signal(value: object, mode: str) -> str | None:
            signal_tokens, signal_compact = _extract_structured_signal_forms(value, mode)
            if not signal_tokens and not signal_compact:
                return None
            for category in elapsed_policy["trigger_categories"]:
                if category == elapsed_policy["default_trigger_category"]:
                    continue
                if category in signal_tokens or (signal_compact and category in signal_compact):
                    return category
            for category, aliases in (elapsed_policy.get("structured_trigger_aliases") or {}).items():
                for alias in (aliases or ()):
                    alias_tokens, alias_compact = _extract_structured_signal_forms(alias, mode)
                    if signal_tokens.intersection(alias_tokens) or (alias_compact and alias_compact in signal_compact):
                        return category
            return None

        if not elapsed_payload and not clock_payload:
            return {}, {}

        explicit_trigger_raw = str(
            _pick_payload_value(elapsed_payload, *elapsed_policy["trigger_field_keys"])
            or _pick_payload_value(clock_payload, *elapsed_policy["trigger_field_keys"])
            or ""
        ).strip()
        if explicit_trigger_raw in elapsed_policy["trigger_categories"]:
            trigger_category = explicit_trigger_raw
            trigger_category_source = "explicit_field"
        else:
            trigger_category = elapsed_policy["default_trigger_category"]
            trigger_category_source = "none"
            trigger_payload_map = {"elapsed": elapsed_payload, "clock": clock_payload}
            for signal_pack in (elapsed_policy.get("trigger_signal_packs") or ()):
                source_key = str(signal_pack.get("source") or "").strip()
                field_key = str(signal_pack.get("field") or "").strip()
                if not source_key or not field_key:
                    continue
                matched_category = _derive_trigger_category_from_signal(
                    _pick_payload_value(trigger_payload_map.get(source_key), field_key),
                    str(signal_pack.get("input_mode") or "structured_code_hint"),
                )
                if matched_category in elapsed_policy["trigger_categories"]:
                    trigger_category = matched_category
                    trigger_category_source = f"derived_from_{source_key}_{field_key}"
                    break

        explicit_scene_progression_raw = str(
            _pick_payload_value(elapsed_payload, *elapsed_policy["scene_progression_field_keys"])
            or _pick_payload_value(clock_payload, *elapsed_policy["scene_progression_field_keys"])
            or ""
        ).strip()
        explicit_write_discipline_raw = str(
            _pick_payload_value(clock_payload, *elapsed_policy["write_discipline_field_keys"])
            or ""
        ).strip()

        normalized_action = str(elapsed_payload.get("action") or "no_advance")
        if normalized_action not in _SC19_ELAPSED_ACTION_VALUES:
            normalized_action = "no_advance"

        if normalized_action == "relation_only":
            derived_scene_progression_evidence = "relation_only"
            derived_write_discipline = "block_relation_only_write"
        elif normalized_action == "advance" and (trigger_category != elapsed_policy["default_trigger_category"] or current_scene_relations):
            derived_scene_progression_evidence = (
                "advance_trigger_present"
                if trigger_category != elapsed_policy["default_trigger_category"]
                else "current_scene_anchor_present"
            )
            derived_write_discipline = "commit_explicit_advance"
        elif current_scene_relations:
            derived_scene_progression_evidence = "current_scene_anchor_present"
            derived_write_discipline = "commit_current_scene_anchor"
        else:
            derived_scene_progression_evidence = "no_scene_progression_evidence"
            derived_write_discipline = "carry_forward_only"

        scene_progression_evidence = (
            explicit_scene_progression_raw
            if explicit_scene_progression_raw in elapsed_policy["scene_progression_evidence_values"]
            else derived_scene_progression_evidence
        )
        write_discipline = (
            explicit_write_discipline_raw
            if explicit_write_discipline_raw in elapsed_policy["write_discipline_values"]
            else derived_write_discipline
        )
        write_allowed = write_discipline in elapsed_policy["commit_write_disciplines"]

        normalized_elapsed_payload = {
            "action": normalized_action,
            "advance_value": elapsed_payload.get("advance_value"),
            "advance_unit": elapsed_payload.get("advance_unit"),
            "reason": elapsed_payload.get("reason"),
            "evidence_type": elapsed_payload.get("evidence_type"),
            "source_turn": elapsed_payload.get("source_turn"),
            "committed_to_clock": bool(elapsed_payload.get("committed_to_clock") or False),
            "trigger_category": trigger_category,
            "trigger_category_source": trigger_category_source,
            "scene_progression_evidence": scene_progression_evidence,
            "policy_version": elapsed_policy["version"],
        }
        normalized_clock_payload = {
            **clock_payload,
            "trigger_category": trigger_category,
            "trigger_category_source": trigger_category_source,
            "scene_progression_evidence": scene_progression_evidence,
            "write_discipline": write_discipline,
            "write_allowed": write_allowed,
            "normalized_status": "ready" if write_allowed else "hold",
            "policy_version": elapsed_policy["version"],
        }
        return normalized_elapsed_payload, normalized_clock_payload

    scene_state_payload: dict = {}
    scene_state_source = "missing"
    scene_state_turn_index = None

    for row in (raw_states or []):
        if not isinstance(row, dict) or str(row.get("state_type") or "") != "scene_state":
            continue
        scene_state_turn_index = row.get("turn_index")
        content = row.get("content")
        if isinstance(content, dict):
            scene_state_payload = dict(content)
            scene_state_source = "active_state_dict"
        elif isinstance(content, str):
            try:
                parsed = json.loads(content)
            except Exception:
                parsed = None
            if isinstance(parsed, dict):
                scene_state_payload = parsed
                scene_state_source = "active_state_json"
            else:
                scene_state_source = "active_state_unparsed"
        break

    current_story_clock = dict(scene_state_payload.get("current_story_clock") or {}) if isinstance(scene_state_payload.get("current_story_clock"), dict) else {}
    elapsed_time_decision = dict(scene_state_payload.get("elapsed_time_decision") or {}) if isinstance(scene_state_payload.get("elapsed_time_decision"), dict) else {}
    clock_write_directive = dict(scene_state_payload.get("clock_write_directive") or {}) if isinstance(scene_state_payload.get("clock_write_directive"), dict) else {}
    active_relation_locales = _resolve_active_relation_locales(
        scene_state_payload.get("active_locales") or scene_state_payload.get("activeLocales")
    )
    relation_entries = [
        _normalize_temporal_relation_entry(
            entry,
            default_source_turn=scene_state_turn_index,
            default_anchor_ref=(
                _SC19_RELATION_SCHEMA["default_deictic_anchor_ref"]
                if current_story_clock
                else None
            ),
            active_locale_keys=active_relation_locales,
        )
        for entry in (scene_state_payload.get("temporal_relation_ledger") or [])
        if isinstance(entry, dict)
    ]
    current_scene_relations = [
        entry for entry in relation_entries
        if str(entry.get("target_kind") or "") in _SC19_CURRENT_SCENE_TARGET_KINDS
    ]
    relation_only_relations = [
        entry for entry in relation_entries
        if str(entry.get("target_kind") or "") in _SC19_RELATION_ONLY_TARGET_KINDS
    ]
    elapsed_time_decision, clock_write_directive = _normalize_elapsed_policy_fields(
        elapsed_time_decision,
        clock_write_directive,
        current_scene_relations=current_scene_relations,
        relation_only_relations=relation_only_relations,
    )
    resolution_order_raw = clock_write_directive.get("resolution_order") or current_story_clock.get("resolution_order") or _SC19_CLOCK_RESOLUTION_ORDER
    resolution_order = [
        str(item)
        for item in (resolution_order_raw if isinstance(resolution_order_raw, (list, tuple)) else _SC19_CLOCK_RESOLUTION_ORDER)
        if str(item)
    ] or list(_SC19_CLOCK_RESOLUTION_ORDER)
    precision_value = str(current_story_clock.get("precision") or "unknown")
    if precision_value == "exact":
        precision_label = "exact"
        precision_label_reason = "raw_precision_exact"
    elif precision_value == "daypart" or (not precision_value or precision_value == "unknown") and current_story_clock.get("daypart"):
        precision_label = "daypart"
        precision_label_reason = "daypart_anchor_present"
    elif precision_value in {"bounded_range", "coarse"}:
        precision_label = "bounded_range"
        precision_label_reason = "bounded_or_coarse_precision"
    else:
        precision_label = "unknown"
        precision_label_reason = "no_supported_precision_evidence"
    elapsed_action = str(elapsed_time_decision.get("action") or "no_advance")
    status = "ready" if (current_story_clock or relation_entries or elapsed_time_decision or clock_write_directive) else "empty"
    effective_resolution_source = str(
        clock_write_directive.get("resolution_source")
        or current_story_clock.get("anchor_source")
        or ("carry_forward" if status == "empty" else "session_state_clock")
    )
    current_scene_write_allowed = bool(clock_write_directive.get("write_allowed"))
    effective_write_lane = (
        "current_scene"
        if current_scene_write_allowed
        else (
            "relation_only"
            if clock_write_directive.get("write_discipline") == "block_relation_only_write"
            else "carry_forward"
        )
    )

    return {
        "version": _SC19_TEMPORAL_STATE_SURFACE_VERSION,
        "status": status,
        "mode": "read_only_session_state_surface",
        "current_story_clock": {
            "story_day_index": current_story_clock.get("story_day_index"),
            "daypart": current_story_clock.get("daypart"),
            "precision": precision_value if precision_value in _SC19_CLOCK_PRECISION_VALUES else "unknown",
            "raw_precision": precision_value,
            "precision_label": precision_label,
            "precision_label_reason": precision_label_reason,
            "anchor_source": current_story_clock.get("anchor_source"),
            "source_turn": current_story_clock.get("source_turn"),
            "last_advance_turn": current_story_clock.get("last_advance_turn"),
            "carry_forward_status": current_story_clock.get("carry_forward_status"),
            "calendar_ref": current_story_clock.get("calendar_ref"),
            "resolution_order": resolution_order,
        },
        "temporal_relation_ledger": relation_entries,
        "elapsed_time_decision": {
            **elapsed_time_decision,
            "action": elapsed_action if elapsed_action in _SC19_ELAPSED_ACTION_VALUES else "no_advance",
            "committed_to_clock": bool(elapsed_time_decision.get("committed_to_clock") or False),
        },
        "clock_write_directive": clock_write_directive,
        "temporal_split_rule": {
            "status": "defined",
            "current_scene_target_kinds": list(_SC19_CURRENT_SCENE_TARGET_KINDS),
            "relation_only_target_kinds": list(_SC19_RELATION_ONLY_TARGET_KINDS),
            "current_scene_relation_count": len(current_scene_relations),
            "relation_only_relation_count": len(relation_only_relations),
            "current_scene_write_allowed": current_scene_write_allowed,
            "relation_only_blocks_clock_write": clock_write_directive.get("write_discipline") == "block_relation_only_write",
            "effective_write_lane": effective_write_lane,
        },
        "resolution": {
            "scene_state_source": scene_state_source,
            "scene_state_turn_index": scene_state_turn_index,
            "effective_resolution_source": effective_resolution_source,
            "active_relation_locales": list(active_relation_locales),
            "current_story_clock_present": bool(current_story_clock),
            "temporal_relation_count": len(relation_entries),
            "elapsed_time_decision_present": bool(elapsed_time_decision),
            "clock_write_directive_present": bool(clock_write_directive),
        },
        "schema": {
            "clock_precision_values": list(_SC19_CLOCK_PRECISION_VALUES),
            "clock_precision_labels": list(_SC19_CLOCK_PRECISION_LABELS),
            "elapsed_action_values": list(_SC19_ELAPSED_ACTION_VALUES),
            "clock_resolution_order": list(_SC19_CLOCK_RESOLUTION_ORDER),
            "current_scene_target_kinds": list(_SC19_CURRENT_SCENE_TARGET_KINDS),
            "relation_only_target_kinds": list(_SC19_RELATION_ONLY_TARGET_KINDS),
            "relation_target_kinds": list(_SC19_RELATION_SCHEMA["target_kind_values"]),
            "relation_status_values": list(_SC19_RELATION_SCHEMA["status_values"]),
            "relation_offset_unit_values": list(_SC19_RELATION_SCHEMA["offset_unit_values"]),
            "relation_label_normalization_version": _SC19_RELATION_SCHEMA["label_normalization_version"],
            "relation_locale_pack_keys": list(_SC19_RELATION_SCHEMA["locale_packs"].keys()),
            "relation_active_locale_keys": list(active_relation_locales),
            "relation_unsupported_label_mode": _SC19_RELATION_SCHEMA["unsupported_relative_label_mode"],
            "relation_range_kind_values": list(_SC19_RELATION_SCHEMA["range_kind_values"]),
            "relation_anchor_resolution_values": list(_SC19_RELATION_SCHEMA["anchor_resolution_values"]),
            "elapsed_trigger_categories": list(_SC19_ELAPSED_POLICY["trigger_categories"]),
            "elapsed_scene_progression_evidence_values": list(_SC19_ELAPSED_POLICY["scene_progression_evidence_values"]),
            "clock_write_discipline_values": list(_SC19_ELAPSED_POLICY["write_discipline_values"]),
        },
    }


def _build_temporal_support_packet_sc19(session_state_data: dict | None) -> dict:
    policy = _SC19_TEMPORAL_PACKET_POLICY
    empty_packet = {
        "version": policy["version"],
        "status": "empty",
        "mode": policy["mode"],
        "source_surface": policy["source_surface"],
        "clock_summary": {},
        "resolution_summary": {},
        "elapsed_summary": {},
        "write_summary": {},
        "relation_summary": {
            "total_count": 0,
            "current_scene_count": 0,
            "relation_only_count": 0,
            "current_scene_samples": [],
            "relation_only_samples": [],
        },
        "text": "",
    }
    if not isinstance(session_state_data, dict):
        return empty_packet

    temporal_state = session_state_data.get("temporal_state")
    if not isinstance(temporal_state, dict):
        return empty_packet
    if str(temporal_state.get("status") or "empty") == "empty":
        return empty_packet

    def _clean_packet_value(value: object) -> str:
        return " ".join(str(value or "").split()).strip()

    def _format_relation_sample(entry: dict) -> str:
        label = _clean_packet_value(entry.get("relative_label") or entry.get("anchor_ref") or "")
        if not label:
            return ""
        target_kind = _clean_packet_value(entry.get("target_kind"))
        range_kind = _clean_packet_value(entry.get("range_kind"))
        precision = _clean_packet_value(entry.get("precision"))
        sample = label
        if target_kind and target_kind != "current_scene":
            sample += f"<{target_kind}>"
        if range_kind and range_kind not in {"exact", "exact_offset", "none"}:
            sample += f"/{range_kind}"
        elif precision and precision not in {"exact", "unknown"}:
            sample += f"/{precision}"
        return sample

    current_story_clock = dict(temporal_state.get("current_story_clock") or {}) if isinstance(temporal_state.get("current_story_clock"), dict) else {}
    elapsed_time_decision = dict(temporal_state.get("elapsed_time_decision") or {}) if isinstance(temporal_state.get("elapsed_time_decision"), dict) else {}
    clock_write_directive = dict(temporal_state.get("clock_write_directive") or {}) if isinstance(temporal_state.get("clock_write_directive"), dict) else {}
    temporal_split_rule = dict(temporal_state.get("temporal_split_rule") or {}) if isinstance(temporal_state.get("temporal_split_rule"), dict) else {}
    resolution = dict(temporal_state.get("resolution") or {}) if isinstance(temporal_state.get("resolution"), dict) else {}
    schema = dict(temporal_state.get("schema") or {}) if isinstance(temporal_state.get("schema"), dict) else {}
    relation_entries = [entry for entry in (temporal_state.get("temporal_relation_ledger") or []) if isinstance(entry, dict)]

    clock_summary = {
        "story_day_index": current_story_clock.get("story_day_index"),
        "daypart": _clean_packet_value(current_story_clock.get("daypart")),
        "precision_label": _clean_packet_value(current_story_clock.get("precision_label") or current_story_clock.get("precision") or "unknown") or "unknown",
        "anchor_source": _clean_packet_value(current_story_clock.get("anchor_source")),
        "source_turn": current_story_clock.get("source_turn"),
        "last_advance_turn": current_story_clock.get("last_advance_turn"),
    }
    resolution_order = [
        _clean_packet_value(item)
        for item in (current_story_clock.get("resolution_order") or [])
        if _clean_packet_value(item)
    ]
    resolution_summary = {
        "effective_resolution_source": _clean_packet_value(resolution.get("effective_resolution_source") or "carry_forward") or "carry_forward",
        "resolution_order": resolution_order,
        "scene_state_turn_index": resolution.get("scene_state_turn_index"),
    }
    elapsed_summary = {
        "action": _clean_packet_value(elapsed_time_decision.get("action") or "no_advance") or "no_advance",
        "trigger_category": _clean_packet_value(elapsed_time_decision.get("trigger_category") or "none") or "none",
        "trigger_category_source": _clean_packet_value(elapsed_time_decision.get("trigger_category_source") or "none") or "none",
        "scene_progression_evidence": _clean_packet_value(elapsed_time_decision.get("scene_progression_evidence") or "no_scene_progression_evidence") or "no_scene_progression_evidence",
        "committed_to_clock": bool(elapsed_time_decision.get("committed_to_clock") or False),
    }
    write_summary = {
        "write_discipline": _clean_packet_value(clock_write_directive.get("write_discipline") or "carry_forward_only") or "carry_forward_only",
        "write_allowed": bool(clock_write_directive.get("write_allowed") or False),
        "normalized_status": _clean_packet_value(clock_write_directive.get("normalized_status") or clock_write_directive.get("status") or "hold") or "hold",
        "effective_write_lane": _clean_packet_value(temporal_split_rule.get("effective_write_lane") or "carry_forward") or "carry_forward",
    }

    current_scene_target_kinds = {
        _clean_packet_value(item)
        for item in (schema.get("current_scene_target_kinds") or [])
        if _clean_packet_value(item)
    }
    relation_only_target_kinds = {
        _clean_packet_value(item)
        for item in (schema.get("relation_only_target_kinds") or [])
        if _clean_packet_value(item)
    }
    relation_summary = {
        "total_count": len(relation_entries),
        "current_scene_count": int(temporal_split_rule.get("current_scene_relation_count") or 0),
        "relation_only_count": int(temporal_split_rule.get("relation_only_relation_count") or 0),
        "current_scene_samples": [],
        "relation_only_samples": [],
    }
    for entry in relation_entries:
        target_kind = _clean_packet_value(entry.get("target_kind"))
        relation_sample = _format_relation_sample(entry)
        if not relation_sample:
            continue
        if target_kind in current_scene_target_kinds and len(relation_summary["current_scene_samples"]) < int(policy["max_relation_samples_per_lane"]):
            relation_summary["current_scene_samples"].append(relation_sample)
        elif target_kind in relation_only_target_kinds and len(relation_summary["relation_only_samples"]) < int(policy["max_relation_samples_per_lane"]):
            relation_summary["relation_only_samples"].append(relation_sample)

    clock_tokens: list[str] = []
    if clock_summary["story_day_index"] is not None:
        clock_tokens.append(f"day={clock_summary['story_day_index']}")
    if clock_summary["daypart"]:
        clock_tokens.append(f"daypart={clock_summary['daypart']}")
    if clock_summary["precision_label"]:
        clock_tokens.append(f"precision={clock_summary['precision_label']}")
    clock_segment = "clock:" + ("unknown" if not clock_tokens else ",".join(clock_tokens))

    resolution_segment = "resolution:" + resolution_summary["effective_resolution_source"]
    if resolution_summary["resolution_order"]:
        resolution_segment += "[" + ">".join(resolution_summary["resolution_order"]) + "]"

    elapsed_segment = "elapsed:" + ",".join(
        [
            f"action={elapsed_summary['action']}",
            f"trigger={elapsed_summary['trigger_category']}",
            f"evidence={elapsed_summary['scene_progression_evidence']}",
        ]
    )
    write_segment = "write:" + ",".join(
        [
            f"discipline={write_summary['write_discipline']}",
            f"allowed={str(write_summary['write_allowed']).lower()}",
            f"lane={write_summary['effective_write_lane']}",
        ]
    )

    relation_tokens = [
        f"current_scene={relation_summary['current_scene_count']}",
        f"relation_only={relation_summary['relation_only_count']}",
    ]
    if relation_summary["current_scene_samples"]:
        relation_tokens.append("current=" + ";".join(relation_summary["current_scene_samples"]))
    if relation_summary["relation_only_samples"]:
        relation_tokens.append("other=" + ";".join(relation_summary["relation_only_samples"]))
    relation_segment = "relations:" + ",".join(relation_tokens)

    text = f"[{policy['surface_label']}] " + " | ".join(
        [clock_segment, resolution_segment, elapsed_segment, write_segment, relation_segment]
    )
    if len(text) > int(policy["max_text_chars"]):
        text = text[: int(policy["max_text_chars"]) - 3].rstrip() + "..."

    return {
        "version": policy["version"],
        "status": "ready",
        "mode": policy["mode"],
        "source_surface": policy["source_surface"],
        "clock_summary": clock_summary,
        "resolution_summary": resolution_summary,
        "elapsed_summary": elapsed_summary,
        "write_summary": write_summary,
        "relation_summary": relation_summary,
        "text": text,
    }


