@asynccontextmanager
async def lifespan(app: FastAPI):
    logger.info("Startup: creating tables if not exist...")
    Base.metadata.create_all(bind=engine)

    # Bind maintenance queue callbacks so the service layer can call back into main.py logic.
    bind_maintenance_callbacks(
        run_maintenance_pass=run_maintenance_pass,
        run_summary_refresh=_run_summary_refresh_r3c,
    )

    # Sprint 3-C-3: 湲곗〈 DB??embedding_model 而щ읆???놁쓣 ???덉쑝誘濡??덉쟾?섍쾶 異붽?
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        existing_cols = {c["name"] for c in inspector.get_columns("memories")}
        if "embedding_model" not in existing_cols:
            with engine.begin() as conn:
                conn.execute(text("ALTER TABLE memories ADD COLUMN embedding_model VARCHAR(255)"))
            logger.info("Added embedding_model column to memories table.")
        # Phase 5-1: evidence, emotional_intensity, narrative_significance 而щ읆 異붽?
        # Phase 5-2: emotional_boost 而щ읆 異붽?
        for col_name, col_type in [("evidence", "TEXT"), ("emotional_intensity", "REAL"), ("narrative_significance", "REAL"), ("emotional_boost", "REAL")]:
            if col_name not in existing_cols:
                with engine.begin() as conn:
                    conn.execute(text(f"ALTER TABLE memories ADD COLUMN {col_name} {col_type}"))
                logger.info("Added %s column to memories table.", col_name)
    except Exception as exc:
        logger.warning("memories column migration check: %s", exc)
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        storyline_cols = {c["name"] for c in inspector.get_columns("storylines")}
        for col_name, col_type in [
            ("confidence", "REAL"),
            ("evidence_count", "INTEGER"),
            ("last_evidence_turn", "INTEGER"),
        ]:
            if col_name not in storyline_cols:
                with engine.begin() as conn:
                    conn.execute(text(f"ALTER TABLE storylines ADD COLUMN {col_name} {col_type}"))
                logger.info("Added %s column to storylines table.", col_name)
    except Exception as exc:
        logger.warning("storylines column migration check: %s", exc)
    # I-3a: Memory Trust Controls ??3媛??뚯씠釉붿뿉 pinned/suppressed/user_corrected 而щ읆 異붽?
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        _TRUST_COLS = [("pinned", "INTEGER"), ("suppressed", "INTEGER"), ("user_corrected", "INTEGER")]
        for table_name in ("storylines", "world_rules", "pending_threads"):
            try:
                existing = {c["name"] for c in inspector.get_columns(table_name)}
                for col_name, col_type in _TRUST_COLS:
                    if col_name not in existing:
                        with engine.begin() as conn:
                            conn.execute(text(f"ALTER TABLE {table_name} ADD COLUMN {col_name} {col_type} NOT NULL DEFAULT 0"))
                        logger.info("Added %s column to %s table.", col_name, table_name)
            except Exception as exc_inner:
                logger.warning("trust_controls migration for %s: %s", table_name, exc_inner)
    except Exception as exc:
        logger.warning("trust_controls migration check: %s", exc)
    # H-5 legacy compatibility: ?ㅻ옒??pending_threads ?ㅽ궎留덉뿉 ?듭떖 而щ읆 諛깊븘
    # (?댁쁺 DB媛 怨쇨굅 援ъ“瑜??좎???寃쎌슦 GET /pending-threads?먯꽌 500???좊컻?????덉쓬)
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        pending_cols = {c["name"] for c in inspector.get_columns("pending_threads")}
        pending_defs = [
            ("chat_session_id", "TEXT NOT NULL DEFAULT 'default'"),
            ("thread_type", "TEXT NOT NULL DEFAULT 'open_question'"),
            ("title", "TEXT NOT NULL DEFAULT ''"),
            ("status", "TEXT NOT NULL DEFAULT 'open'"),
            ("owner", "TEXT"),
            ("target", "TEXT"),
            ("source_turn", "INTEGER"),
            ("last_seen_turn", "INTEGER"),
            ("confidence", "REAL"),
            ("details_json", "TEXT"),
            ("resolution_note", "TEXT"),
            ("created_at", "DATETIME"),
            ("updated_at", "DATETIME"),
        ]
        for col_name, col_type in pending_defs:
            if col_name not in pending_cols:
                with engine.begin() as conn:
                    conn.execute(text(f"ALTER TABLE pending_threads ADD COLUMN {col_name} {col_type}"))
                logger.info("Added %s column to pending_threads table.", col_name)
    except Exception as exc:
        logger.warning("pending_threads legacy migration: %s", exc)
    # Step 11 HS-1e: canonical_state_layers provenance 而щ읆 諛깊븘
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        canonical_cols = {c["name"] for c in inspector.get_columns("canonical_state_layers")}
        canonical_defs = [
            ("source_turn", "INTEGER"),
            ("source_record", "INTEGER"),
            ("last_verified_turn", "INTEGER"),
            ("confidence", "REAL"),
        ]
        for col_name, col_type in canonical_defs:
            if col_name not in canonical_cols:
                with engine.begin() as conn:
                    conn.execute(text(f"ALTER TABLE canonical_state_layers ADD COLUMN {col_name} {col_type}"))
                logger.info("Added %s column to canonical_state_layers table.", col_name)
    except Exception as exc:
        logger.warning("canonical_state_layers provenance migration: %s", exc)
    # I-4a: World Graph Lite ??world_rules??scope_name 而щ읆 異붽?
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        wr_cols = {c["name"] for c in inspector.get_columns("world_rules")}
        if "scope_name" not in wr_cols:
            with engine.begin() as conn:
                conn.execute(text("ALTER TABLE world_rules ADD COLUMN scope_name TEXT NULL"))
            logger.info("Added scope_name column to world_rules table.")
    except Exception as exc:
        logger.warning("world_rules scope_name migration: %s", exc)
    # Step 9 P-3d + Step 11 DS-1c: arc_summaries 援ъ“ 而щ읆 諛깊븘
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        arc_cols = {c["name"] for c in inspector.get_columns("arc_summaries")}
        for col_name in (
            "unresolved_debts_json",
            "callback_candidates_json",
            "irreversible_turns_json",
            "callback_debts_json",
            "relationship_pivots_json",
        ):
            if col_name not in arc_cols:
                with engine.begin() as conn:
                    conn.execute(text(f"ALTER TABLE arc_summaries ADD COLUMN {col_name} TEXT"))
                logger.info("Added %s column to arc_summaries table.", col_name)
    except Exception as exc:
        logger.warning("arc_summaries column migration check: %s", exc)
    # Step 11 DS-1a: episode_summaries structured anchor 而щ읆 諛깊븘
    try:
        from sqlalchemy import inspect as sa_inspect, text
        inspector = sa_inspect(engine)
        episode_cols = {c["name"] for c in inspector.get_columns("episode_summaries")}
        for col_name in ("open_loops_json", "relationship_changes_json"):
            if col_name not in episode_cols:
                with engine.begin() as conn:
                    conn.execute(text(f"ALTER TABLE episode_summaries ADD COLUMN {col_name} TEXT"))
                logger.info("Added %s column to episode_summaries table.", col_name)
    except Exception as exc:
        logger.warning("episode_summaries DS-1a migration check: %s", exc)
    # I-4c: session_active_scopes ?뚯씠釉??앹꽦 (?놁쓣 寃쎌슦)
    try:
        SessionActiveScopeCache.__table__.create(bind=engine, checkfirst=True)
        logger.info("session_active_scopes table ready.")
    except Exception as exc:
        logger.warning("session_active_scopes table creation: %s", exc)
    logger.info("Tables ready: chat_logs, memories, kg_triples")
    logger.info("ArchiveBridge initialized.")
    yield
    logger.info("Shutdown.")


