#  K-3d: PATCH /narrative-control/{session_id}/director-patch
#  director state???쇰? ?꾨뱶瑜??섎룞?쇰줈 ?⑥튂?쒕떎.
#  - user_corrected ?뚮옒洹??명똿?쇰줈 auto-overwrite 諛⑹?
#  - ?덉슜 ?꾨뱶: scene_mandate, required_outcomes, forbidden_moves,
#              pressure_level, execution_checklist, persona_guardrails,
#              world_guardrails
# ------------------------------------------------------------------ #

class DirectorPatchRequest(BaseModel):
    """director state ?섎룞 ?⑥튂 ?붿껌.
    吏?뺥븯吏 ?딆? ?꾨뱶??蹂寃쏀븯吏 ?딅뒗??(partial update).
    """
    scene_mandate: str | None = None
    required_outcomes: list[str] | None = None
    forbidden_moves: list[str] | None = None
    pressure_level: str | None = None
    execution_checklist: list[str] | None = None
    persona_guardrails: list[str] | None = None
    world_guardrails: list[str] | None = None


@app.patch("/narrative-control/{chat_session_id}/director-patch")
def patch_director_state(chat_session_id: str, patch: DirectorPatchRequest):
    """K-3d: director state ?섎룞 ?⑥튂 ?붾뱶?ъ씤??

    GuidancePlanState??director_json??遺遺??낅뜲?댄듃?쒕떎.
    ?⑥튂???곹깭??state_status="user_patched"濡??쒖떆?섏뼱 ?ㅼ쓬 freshness ?먯젙 ??
    auto-overwrite ??곸뿉???쒖쇅?쒕떎.
    """
    import json as _json

    sid = (chat_session_id or "").strip()
    if not sid:
        return Utf8JSONResponse(
            content={"error": "chat_session_id is required"}, status_code=400
        )

    # pressure_level ?덉슜媛?寃利?
    if patch.pressure_level is not None and patch.pressure_level not in (
        "light", "steady", "strong", "critical"
    ):
        return Utf8JSONResponse(
            content={"error": "pressure_level must be one of: light, steady, strong, critical"},
            status_code=400,
        )

    db = SessionLocal()
    try:
        cached: GuidancePlanState | None = (
            db.query(GuidancePlanState)
            .filter(GuidancePlanState.chat_session_id == sid)
            .first()
        )

        # 湲곗〈 director_json 濡쒕뱶 (?놁쑝硫?湲곕낯媛?
        if cached and cached.director_json:
            try:
                dr_dict = _json.loads(cached.director_json)
            except Exception:
                dr_dict = {}
        else:
            dr_dict = {}

        # 遺遺??낅뜲?댄듃: None???꾨땶 ?꾨뱶留???뼱?곌린
        patch_data = patch.model_dump(exclude_none=True)
        dr_dict.update(patch_data)
        # ?섎룞 ?⑥튂 ?쒖떆 ??freshness ?먯젙 ??auto-overwrite 諛⑹?
        dr_dict["state_status"] = "user_patched"

        new_dr_json = _json.dumps(dr_dict, ensure_ascii=False)

        if cached is not None:
            cached.director_json = new_dr_json
            cached.state_status = "user_patched"
        else:
            # GuidancePlanState ?덉퐫???먯껜媛 ?놁쑝硫??앹꽦
            cached = GuidancePlanState(
                chat_session_id=sid,
                director_json=new_dr_json,
                story_plan_json=_json.dumps({}),
                state_status="user_patched",
                last_turn=-1,
            )
            db.add(cached)

        db.commit()
        logger.info("[K-3d] director-patch applied for session %s: %s", sid, list(patch_data.keys()))
        return Utf8JSONResponse(content={
            "status": "ok",
            "patched_fields": list(patch_data.keys()),
            "state_status": "user_patched",
        })

    except Exception as e:
        db.rollback()
        logger.error("[K-3d] director-patch failed: %s", e)
        return Utf8JSONResponse(
            content={"error": str(e)[:200]}, status_code=500
        )
    finally:
        db.close()


def _bundle_resume_pack(
    sid: str,
    continuity_trigger_mode: str,
) -> "dict | None":
    """P-4c: long-gap resume?먯꽌 hierarchy summary 以묒떖??read-only pack??議곕┰?쒕떎.

    ???④퀎?먯꽌??injection/input_context?먮뒗 ?곌껐?섏? ?딄퀬, prepare-turn ?묐떟?먮쭔 ?몄텧?쒕떎.
    """
    trigger_raw = (continuity_trigger_mode or "none").strip().lower()
    if trigger_raw in ("resume", "manual_resume"):
        trigger = "resume"
    elif trigger_raw in ("idle", "idle_reentry"):
        trigger = "idle"
    elif trigger_raw in ("empty", "empty_input"):
        trigger = "empty"
    else:
        return None

    db = SessionLocal()
    try:
        latest_saga = (
            db.query(SagaDigest)
            .filter(SagaDigest.chat_session_id == sid)
            .order_by(SagaDigest.to_turn.desc(), SagaDigest.id.desc())
            .first()
        )
        latest_arc = (
            db.query(ArcSummary)
            .filter(ArcSummary.chat_session_id == sid)
            .order_by(ArcSummary.to_turn.desc(), ArcSummary.id.desc())
            .first()
        )
        latest_chapter = (
            db.query(ChapterSummary)
            .filter(ChapterSummary.chat_session_id == sid)
            .order_by(ChapterSummary.to_turn.desc(), ChapterSummary.id.desc())
            .first()
        )
    except Exception as exc:
        logger.warning("[prepare-turn] _bundle_resume_pack query failed: %s", exc)
        db.close()
        return None
    finally:
        db.close()

    sources_used: list[str] = []
    sections: list[str] = []

    def _clean_text(raw: object, *, max_len: int) -> str:
        text = " ".join(str(raw or "").split()).strip()
        if len(text) > max_len:
            text = text[: max_len - 3] + "..."
        return text

    saga_payload = None
    if latest_saga:
        saga_text = _clean_text(latest_saga.resume_pack_text or latest_saga.saga_summary, max_len=900)
        saga_payload = {
            "id": latest_saga.id,
            "from_turn": latest_saga.from_turn,
            "to_turn": latest_saga.to_turn,
            "era_label": latest_saga.era_label,
            "resume_pack_text": latest_saga.resume_pack_text,
            "saga_summary": latest_saga.saga_summary,
            "created_at": to_kst(latest_saga.created_at),
        }
        if saga_text:
            header = latest_saga.era_label or f"Saga {latest_saga.from_turn}-{latest_saga.to_turn}"
            sections.append(f"?곣봺 Saga Digest ?곣봺\n[{header}] {saga_text}")
            sources_used.append("saga")

    arc_payload = None
    if latest_arc:
        arc_text = _clean_text(latest_arc.arc_resume_text or latest_arc.core_conflict, max_len=700)
        arc_payload = {
            "id": latest_arc.id,
            "from_turn": latest_arc.from_turn,
            "to_turn": latest_arc.to_turn,
            "arc_index": latest_arc.arc_index,
            "arc_name": latest_arc.arc_name,
            "arc_status": latest_arc.arc_status,
            "arc_resume_text": latest_arc.arc_resume_text,
            "core_conflict": latest_arc.core_conflict,
            "irreversible_turns_json": latest_arc.irreversible_turns_json,
            "callback_debts_json": latest_arc.callback_debts_json,
            "relationship_pivots_json": latest_arc.relationship_pivots_json,
            "created_at": to_kst(latest_arc.created_at),
        }
        if arc_text:
            header = latest_arc.arc_name or f"Arc {latest_arc.from_turn}-{latest_arc.to_turn}"
            sections.append(f"?곣봺 Arc Resume ?곣봺\n[{header}] {arc_text}")
            sources_used.append("arc")

    chapter_payload = None
    if latest_chapter:
        chapter_text = _clean_text(latest_chapter.resume_text or latest_chapter.summary_text, max_len=500)
        chapter_payload = {
            "id": latest_chapter.id,
            "from_turn": latest_chapter.from_turn,
            "to_turn": latest_chapter.to_turn,
            "chapter_index": latest_chapter.chapter_index,
            "chapter_title": latest_chapter.chapter_title,
            "resume_text": latest_chapter.resume_text,
            "summary_text": latest_chapter.summary_text,
            "created_at": to_kst(latest_chapter.created_at),
        }
        if chapter_text:
            header = latest_chapter.chapter_title or f"Chapter {latest_chapter.from_turn}-{latest_chapter.to_turn}"
            sections.append(f"?곣봺 Chapter Resume ?곣봺\n[{header}] {chapter_text}")
            sources_used.append("chapter")

    pack_status = "ready" if sections else "empty"
    return {
        "pack_status": pack_status,
        "trigger": trigger,
        "sources_used": sources_used,
        "layer_count": len(sources_used),
        "assembled_text": "\n\n".join(sections),
        "saga": saga_payload,
        "arc": arc_payload,
        "chapter": chapter_payload,
        "assembly_note": "P-4c: read-only long-gap resume pack; not wired into injection or input_context",
    }


