def _build_profile_layer_rank_map_r2c(profile_name: str) -> dict[str, int]:
    profile = profile_name if profile_name in _R2A_CONTEXT_WINDOW_PROFILE_ORDER else "mid_context_300k"
    layer_priority = list(_R2B_PROFILE_LAYER_PRIORITY_MAP.get(profile) or [])
    rank_map: dict[str, int] = {}
    for idx, layer in enumerate(layer_priority):
        key = str(layer or "").strip()
        if key and key not in rank_map:
            rank_map[key] = idx

    next_rank = len(rank_map)
    for layer in _R2C_PROFILE_LAYER_FALLBACK_ORDER:
        if layer not in rank_map:
            rank_map[layer] = next_rank
            next_rank += 1
    return rank_map


def _resolve_context_window_profile_details_r2a(
    settings_obj: "PrepareTurnSettings | None" = None,
    client_meta: dict | None = None,
) -> tuple[str, str]:
    """R-2a: active profile + resolution source瑜??④퍡 諛섑솚?쒕떎."""
    raw_hint = " ".join(str((client_meta or {}).get("context_window_profile") or "").split()).strip().lower()
    if raw_hint in _CONTEXT_WINDOW_PROFILES_P4D:
        return raw_hint, "client_meta_hint"

    max_injection_chars = int((getattr(settings_obj, "max_injection_chars", None) or 3000))
    if max_injection_chars >= 7000:
        return "extreme_long_2m_plus", "max_injection_chars_proxy"
    if max_injection_chars >= 5000:
        return "ultra_long_1m_plus", "max_injection_chars_proxy"
    if max_injection_chars >= 3600:
        return "wide_context_500k", "max_injection_chars_proxy"
    return "mid_context_300k", "max_injection_chars_proxy"


def _resolve_context_window_profile_p4d(
    settings_obj: "PrepareTurnSettings | None" = None,
    client_meta: dict | None = None,
) -> str:
    """P-4d: context-window delivery profile??蹂댁닔?곸쑝濡?寃곗젙?쒕떎.

    1?쒖쐞: client_meta.context_window_profile 紐낆떆 ?뚰듃.
    2?쒖쐞: ?꾩옱 injection budget(max_injection_chars)???꾩떆 profile proxy濡??ъ슜.
    dedicated window-profile plumbing ?댁쟾??蹂댁닔??fallback?대떎.
    """
    profile, _ = _resolve_context_window_profile_details_r2a(
        settings_obj=settings_obj,
        client_meta=client_meta,
    )
    return profile


