def _tm1a_normalize_text(raw: object) -> str:
    return " ".join(str(raw or "").split()).strip().lower()


def _tm1a_parse_json(raw: object, fallback):
    if isinstance(raw, type(fallback)):
        return raw
    if raw is None:
        return fallback
    try:
        parsed = json.loads(str(raw))
    except Exception:
        return fallback
    return parsed if isinstance(parsed, type(fallback)) else fallback


def _tm1c_clamp_importance(value: object) -> float:
    try:
        score = float(value)
    except Exception:
        score = 5.0
    return max(TM1C_IMPORTANCE_FLOOR, min(TM1C_IMPORTANCE_CEIL, score))


def _tm1c_memory_summary_map(row: Memory) -> dict:
    return _tm1a_parse_json(row.summary_json, {})


def _tm1c_memory_summary_text(row: Memory) -> str:
    summary_map = _tm1c_memory_summary_map(row)
    if isinstance(summary_map, dict):
        text = summary_map.get("turn_summary") or summary_map.get("summary")
        if text:
            return str(text)
    return str(row.summary_json or "")


def _tm1c_iter_text_values(raw: object):
    if raw is None:
        return
    if isinstance(raw, str):
        text = raw.strip()
        if text:
            yield text
        return
    if isinstance(raw, dict):
        for value in raw.values():
            yield from _tm1c_iter_text_values(value)
        return
    if isinstance(raw, list):
        for item in raw:
            yield from _tm1c_iter_text_values(item)


def _tm1c_join_text_parts(parts: list[object]) -> str:
    result: list[str] = []
    for part in parts:
        if isinstance(part, str):
            parsed = _tm1a_parse_json(part, None)
            if isinstance(parsed, (dict, list)):
                result.extend(list(_tm1c_iter_text_values(parsed)))
                continue
        result.extend(list(_tm1c_iter_text_values(part)))
    return " ".join(text for text in result if text).strip()


def _tm1c_collect_recent_mention_keywords(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
) -> tuple[str, set[str]]:
    rows = (
        db.query(ChatLog)
        .filter(ChatLog.chat_session_id == chat_session_id)
        .filter(ChatLog.turn_index >= max(0, current_turn - TM1C_RECENT_REMENTION_TURN_WINDOW))
        .order_by(ChatLog.turn_index.desc(), ChatLog.id.desc())
        .limit(8)
        .all()
    )
    recent_text = " ".join(str(row.content or "") for row in rows)
    return recent_text, set(_extract_drift_keywords(recent_text))


def _tm1c_match_signal_keywords(
    *,
    memory_text: str,
    memory_keywords: set[str],
    signal_text: str,
    signal_keywords: set[str],
) -> bool:
    if not memory_text or not signal_text:
        return False

    normalized_memory = _tm1a_normalize_text(memory_text)
    normalized_signal = _tm1a_normalize_text(signal_text)
    if normalized_signal and len(normalized_signal) >= 5 and normalized_signal in normalized_memory:
        return True

    overlap = memory_keywords & signal_keywords
    if not overlap:
        return False
    required_overlap = 1 if min(len(memory_keywords), len(signal_keywords)) <= 1 else 2
    return len(overlap) >= required_overlap


def _tm1c_collect_reference_signals(db, *, chat_session_id: str) -> dict[str, list[dict]]:
    resolved_entries: list[dict] = []
    protected_entries: list[dict] = []

    storylines = (
        db.query(Storyline)
        .filter(Storyline.chat_session_id == chat_session_id)
        .all()
    )
    for row in storylines:
        signal_text = _tm1c_join_text_parts([
            row.name,
            row.current_context,
            row.key_points_json,
            row.ongoing_tensions_json,
        ])
        signal_keywords = set(_extract_drift_keywords(signal_text))
        if not signal_text or not signal_keywords:
            continue
        entry = {
            "kind": "storyline",
            "title": row.name,
            "text": signal_text,
            "keywords": signal_keywords,
        }
        if row.status == "resolved":
            resolved_entries.append(entry)
        if bool(row.pinned) or bool(row.user_corrected):
            protected_entries.append(entry)

    pending_threads = (
        db.query(PendingThread)
        .filter(PendingThread.chat_session_id == chat_session_id)
        .all()
    )
    for row in pending_threads:
        signal_text = _tm1c_join_text_parts([
            row.title,
            row.resolution_note,
            row.details_json,
        ])
        signal_keywords = set(_extract_drift_keywords(signal_text))
        if not signal_text or not signal_keywords:
            continue
        entry = {
            "kind": "pending_thread",
            "title": row.title,
            "text": signal_text,
            "keywords": signal_keywords,
        }
        if row.status == "resolved":
            resolved_entries.append(entry)
        if bool(row.pinned) or bool(row.user_corrected):
            protected_entries.append(entry)

    return {
        "resolved": resolved_entries,
        "protected": protected_entries,
    }


def _tm1c_apply_memory_importance_reevaluation(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
) -> dict:
    if current_turn < 0:
        return {
            "policy_version": TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
            "updates": [],
            "protected_count": 0,
            "boosted_count": 0,
            "decayed_count": 0,
        }

    recent_text, recent_keywords = _tm1c_collect_recent_mention_keywords(
        db,
        chat_session_id=chat_session_id,
        current_turn=current_turn,
    )
    reference_signals = _tm1c_collect_reference_signals(db, chat_session_id=chat_session_id)

    rows = (
        db.query(Memory)
        .filter(Memory.chat_session_id == chat_session_id)
        .order_by(Memory.turn_index.desc(), Memory.id.desc())
        .limit(TM1C_MEMORY_SCAN_LIMIT)
        .all()
    )

    updates: list[dict] = []
    protected_count = 0
    boosted_count = 0
    decayed_count = 0

    for row in rows:
        summary_map = _tm1c_memory_summary_map(row)
        summary_text = _tm1c_memory_summary_text(row)
        memory_keywords = set(_extract_drift_keywords(summary_text))
        if not summary_text or not memory_keywords:
            continue

        turn_index = int(row.turn_index or 0)
        age_gap = current_turn - turn_index
        if age_gap < 0:
            continue

        old_importance = _tm1c_clamp_importance(
            row.importance if row.importance is not None else summary_map.get("importance_score")
        )
        new_importance = old_importance
        reasons: list[str] = []

        matched_protected_titles: list[str] = []
        for entry in reference_signals["protected"]:
            if _tm1c_match_signal_keywords(
                memory_text=summary_text,
                memory_keywords=memory_keywords,
                signal_text=entry["text"],
                signal_keywords=entry["keywords"],
            ):
                matched_protected_titles.append(str(entry["title"]))
        is_protected = bool(matched_protected_titles)
        if is_protected:
            protected_count += 1
            reasons.append("protected_reference")

        recent_rementioned = bool(recent_keywords) and _tm1c_match_signal_keywords(
            memory_text=summary_text,
            memory_keywords=memory_keywords,
            signal_text=recent_text,
            signal_keywords=recent_keywords,
        )
        if recent_rementioned:
            new_importance += TM1C_RECENT_REMENTION_BOOST
            reasons.append("recent_remention_boost")

        if not is_protected and age_gap >= TM1C_FRESHNESS_DECAY_START:
            steps = 1 + max(0, (age_gap - TM1C_FRESHNESS_DECAY_START) // TM1C_FRESHNESS_DECAY_START)
            decay_amount = steps * TM1C_FRESHNESS_DECAY_STEP
            new_importance -= decay_amount
            reasons.append("freshness_decay")

        if not is_protected:
            matched_resolved_titles = [
                str(entry["title"])
                for entry in reference_signals["resolved"]
                if _tm1c_match_signal_keywords(
                    memory_text=summary_text,
                    memory_keywords=memory_keywords,
                    signal_text=entry["text"],
                    signal_keywords=entry["keywords"],
                )
            ]
            if matched_resolved_titles:
                new_importance -= TM1C_RESOLVED_REFERENCE_DECAY
                reasons.append("resolved_reference_decay")
        else:
            matched_resolved_titles = []

        emotional_intensity = None
        try:
            emotional_intensity = float(row.emotional_intensity) if row.emotional_intensity is not None else None
        except Exception:
            emotional_intensity = None
        has_emotional_signal = (row.emotional_boost is not None) or ((emotional_intensity or 0.0) >= 0.7)
        if (
            not is_protected
            and not recent_rementioned
            and has_emotional_signal
            and age_gap >= TM1C_EMOTIONAL_DECAY_START
        ):
            new_importance -= TM1C_EMOTIONAL_DECAY
            reasons.append("emotional_decay")

        new_importance = round(_tm1c_clamp_importance(new_importance), 4)
        if abs(new_importance - old_importance) < 0.049:
            continue

        row.importance = new_importance
        if isinstance(summary_map, dict):
            summary_map["importance_score"] = new_importance
            row.summary_json = json.dumps(summary_map, ensure_ascii=False)

        boosted = new_importance > old_importance
        decayed = new_importance < old_importance
        if boosted:
            boosted_count += 1
        if decayed:
            decayed_count += 1

        updates.append(
            {
                "memory_id": row.id,
                "turn_index": turn_index,
                "old_importance": old_importance,
                "new_importance": new_importance,
                "age_gap": age_gap,
                "recent_rementioned": recent_rementioned,
                "protected_titles": matched_protected_titles,
                "resolved_titles": matched_resolved_titles,
                "reasons": reasons,
            }
        )

    return {
        "policy_version": TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
        "updates": updates,
        "protected_count": protected_count,
        "boosted_count": boosted_count,
        "decayed_count": decayed_count,
    }


def _tm1d_unique_preserve_order(values: list[object]) -> list[str]:
    ordered: list[str] = []
    seen: set[str] = set()
    for value in values:
        normalized = str(value or "").strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        ordered.append(normalized)
    return ordered


def _tm1d_dirty_targets_for_drift_signal(signal_type: object) -> list[str]:
    signal_key = str(signal_type or "").strip()
    targets = TM1D_DRIFT_SIGNAL_TO_DIRTY_TARGETS.get(signal_key, TM1D_DEFAULT_DIRTY_TARGETS)
    return _tm1d_unique_preserve_order(list(targets))


def _tm1d_dirty_targets_for_importance_reason(reason: object) -> list[str]:
    reason_key = str(reason or "").strip()
    targets = TM1D_IMPORTANCE_REASON_TO_DIRTY_TARGETS.get(reason_key, TM1D_DEFAULT_DIRTY_TARGETS)
    return _tm1d_unique_preserve_order(list(targets))


def _tm1d_importance_replay_metric_refs(reason: object) -> list[str]:
    refs = ["tm_importance_pass_count", "tm_importance_updated_count"]
    reason_key = str(reason or "").strip()
    if reason_key == "recent_remention_boost":
        refs.append("tm_importance_boosted_count")
    elif reason_key.endswith("decay"):
        refs.append("tm_importance_decayed_count")
    elif reason_key == "protected_reference":
        refs.append("tm_importance_protected_count")
    return _tm1d_unique_preserve_order(refs)


def _tm1d_build_drift_dirty_matrix_rows(*, details: dict) -> list[dict]:
    maintenance_pass_id = details.get("maintenance_pass_id")
    turn_index = details.get("turn_index")
    source_policy_version = details.get("policy_version") or TM1B_CANONICAL_MAINTENANCE_POLICY_VERSION
    rows: list[dict] = []
    for item in details.get("canonical_updates") or []:
        if str(item.get("status") or "") != "confidence_degraded":
            continue
        signal_type = str(item.get("signal_type") or "canonical_drift")
        rows.append(
            {
                "event_type": "drift_detected",
                "maintenance_pass_id": maintenance_pass_id,
                "turn_index": turn_index,
                "source_policy_version": source_policy_version,
                "or_phase_trigger": "truth_maintenance_drift",
                "dirty_signal": signal_type,
                "dirty_scope": str(item.get("layer_type") or "canonical_state"),
                "dirty_targets": _tm1d_dirty_targets_for_drift_signal(signal_type),
                "replay_metric_refs": [
                    "tm_drift_pass_count",
                    "tm_drift_layer_count",
                    "tm_drift_signal_type_count",
                ],
                "severity": item.get("severity"),
            }
        )
    return rows


def _tm1d_build_importance_dirty_matrix_rows(*, details: dict) -> list[dict]:
    maintenance_pass_id = details.get("maintenance_pass_id")
    turn_index = details.get("turn_index")
    source_policy_version = details.get("policy_version") or TM1C_MEMORY_IMPORTANCE_POLICY_VERSION
    grouped_rows: dict[str, dict] = {}
    for item in details.get("memory_updates") or []:
        memory_id = item.get("memory_id")
        delta = round(float(item.get("new_importance") or 0.0) - float(item.get("old_importance") or 0.0), 4)
        for reason in item.get("reasons") or ["importance_changed"]:
            reason_key = str(reason or "importance_changed").strip() or "importance_changed"
            if reason_key not in grouped_rows:
                grouped_rows[reason_key] = {
                    "event_type": "importance_reevaluation",
                    "maintenance_pass_id": maintenance_pass_id,
                    "turn_index": turn_index,
                    "source_policy_version": source_policy_version,
                    "or_phase_trigger": "truth_maintenance_importance",
                    "dirty_signal": reason_key,
                    "dirty_scope": "memory_importance",
                    "dirty_targets": _tm1d_dirty_targets_for_importance_reason(reason_key),
                    "replay_metric_refs": _tm1d_importance_replay_metric_refs(reason_key),
                    "affected_memory_ids": [],
                    "importance_deltas": [],
                }
            row = grouped_rows[reason_key]
            if memory_id is not None:
                row["affected_memory_ids"].append(memory_id)
            row["importance_deltas"].append(delta)

    rows: list[dict] = []
    for reason_key in sorted(grouped_rows):
        row = grouped_rows[reason_key]
        row["affected_memory_ids"] = sorted({int(mid) for mid in row["affected_memory_ids"]})
        row["affected_count"] = len(row["affected_memory_ids"])
        deltas = row.pop("importance_deltas")
        row["delta_direction"] = (
            "boost" if any(delta > 0 for delta in deltas) else "decay" if any(delta < 0 for delta in deltas) else "stable"
        )
        rows.append(row)
    return rows


def _tm1d_build_audit_replay_contract(*, event_type: str, details: dict) -> dict:
    if not isinstance(details, dict):
        details = {}

    if event_type == "drift_detected":
        rows = _tm1d_build_drift_dirty_matrix_rows(details=details)
        replay_measurements = {
            "measurement_policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
            "tm_drift_pass_count": 1 if rows else 0,
            "tm_drift_layer_count": len(rows),
            "tm_drift_signal_type_count": len({row["dirty_signal"] for row in rows}),
        }
    elif event_type == "importance_reevaluation":
        rows = _tm1d_build_importance_dirty_matrix_rows(details=details)
        replay_measurements = {
            "measurement_policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
            "tm_importance_pass_count": 1 if details.get("memory_updates") else 0,
            "tm_importance_updated_count": int(details.get("updated_count") or len(details.get("memory_updates") or [])),
            "tm_importance_boosted_count": int(details.get("boosted_count") or 0),
            "tm_importance_decayed_count": int(details.get("decayed_count") or 0),
            "tm_importance_protected_count": int(details.get("protected_count") or 0),
        }
    else:
        rows = []
        replay_measurements = {
            "measurement_policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
        }

    return {
        "or_phase_dirty_matrix": {
            "policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
            "matrix_version": TM1D_OR_DIRTY_MATRIX_VERSION,
            "event_type": event_type,
            "rows": rows,
        },
        "replay_measurements": replay_measurements,
    }


def _tm1d_parse_audit_details(raw: object) -> dict:
    if isinstance(raw, dict):
        return raw
    if raw is None:
        return {}
    try:
        parsed = json.loads(str(raw))
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _build_tm1d_truth_maintenance_audit_replay(*, db, chat_session_id: str, max_audit_rows: int = 80) -> dict:
    sid = (chat_session_id or "").strip()
    if not sid:
        return {
            "policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
            "status": "off",
            "reason": "session_missing",
            "gate_result": "off",
        }

    limit_rows = max(1, min(int(max_audit_rows or 80), 200))
    audit_rows = (
        db.query(AuditLog)
        .filter(
            AuditLog.chat_session_id == sid,
            AuditLog.event_type.in_(["drift_detected", "importance_reevaluation"]),
        )
        .order_by(AuditLog.created_at.desc(), AuditLog.id.desc())
        .limit(limit_rows)
        .all()
    )

    if not audit_rows:
        return {
            "policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
            "status": "off",
            "reason": "audit_surface_missing",
            "gate_result": "off",
            "audit_event_counts": {
                "drift_detected": 0,
                "importance_reevaluation": 0,
            },
        }

    audit_event_counts = {
        "drift_detected": 0,
        "importance_reevaluation": 0,
    }
    dirty_rows: list[dict] = []
    dirty_target_counts: dict[str, int] = {}
    measurement_totals = {
        "tm_drift_pass_count": 0,
        "tm_drift_layer_count": 0,
        "tm_drift_signal_type_count": 0,
        "tm_importance_pass_count": 0,
        "tm_importance_updated_count": 0,
        "tm_importance_boosted_count": 0,
        "tm_importance_decayed_count": 0,
        "tm_importance_protected_count": 0,
    }
    maintenance_pass_ids: list[int] = []
    linked_matrix_event_count = 0
    linked_replay_event_count = 0

    for audit_row in reversed(audit_rows):
        event_type = str(audit_row.event_type or "").strip()
        if event_type not in audit_event_counts:
            continue
        audit_event_counts[event_type] += 1
        details = _tm1d_parse_audit_details(audit_row.details_json)
        contract = _tm1d_build_audit_replay_contract(event_type=event_type, details=details)

        stored_matrix = details.get("or_phase_dirty_matrix") if isinstance(details.get("or_phase_dirty_matrix"), dict) else {}
        matrix_rows = stored_matrix.get("rows") if isinstance(stored_matrix.get("rows"), list) else None
        if matrix_rows is None:
            matrix_rows = contract["or_phase_dirty_matrix"]["rows"]
        if matrix_rows:
            linked_matrix_event_count += 1

        stored_replay = details.get("replay_measurements") if isinstance(details.get("replay_measurements"), dict) else {}
        replay_measurements = stored_replay or contract["replay_measurements"]
        if replay_measurements:
            linked_replay_event_count += 1

        maintenance_pass_id = details.get("maintenance_pass_id")
        if isinstance(maintenance_pass_id, int):
            maintenance_pass_ids.append(maintenance_pass_id)

        for key in measurement_totals:
            measurement_totals[key] += int(replay_measurements.get(key) or 0)

        for row in matrix_rows:
            dirty_rows.append(row)
            for target in row.get("dirty_targets") or []:
                target_key = str(target or "").strip()
                if not target_key:
                    continue
                dirty_target_counts[target_key] = dirty_target_counts.get(target_key, 0) + 1

    rows_with_targets = sum(1 for row in dirty_rows if row.get("dirty_targets"))
    rows_with_metric_refs = sum(1 for row in dirty_rows if row.get("replay_metric_refs"))
    checks = [
        {
            "name": "audit_events_linked_to_or_dirty_matrix",
            "passed": linked_matrix_event_count == len(audit_rows),
            "detail": f"linked={linked_matrix_event_count}, audit_rows={len(audit_rows)}",
        },
        {
            "name": "audit_events_linked_to_replay_measurements",
            "passed": linked_replay_event_count == len(audit_rows),
            "detail": f"linked={linked_replay_event_count}, audit_rows={len(audit_rows)}",
        },
        {
            "name": "dirty_matrix_rows_reference_targets_and_metrics",
            "passed": rows_with_targets == len(dirty_rows) and rows_with_metric_refs == len(dirty_rows),
            "detail": (
                f"rows={len(dirty_rows)}, rows_with_targets={rows_with_targets}, "
                f"rows_with_metric_refs={rows_with_metric_refs}"
            ),
        },
    ]
    failed = [item["name"] for item in checks if not item.get("passed")]

    return {
        "policy_version": TM1D_TRUTH_MAINTENANCE_REPLAY_POLICY_VERSION,
        "status": "ok",
        "gate_result": "pass" if not failed else "warn",
        "dirty_matrix_version": TM1D_OR_DIRTY_MATRIX_VERSION,
        "audit_rows_analyzed": len(audit_rows),
        "audit_event_counts": audit_event_counts,
        "replay_measurements": measurement_totals,
        "dirty_target_counts": dict(sorted(dirty_target_counts.items())),
        "maintenance_pass_ids": sorted(set(maintenance_pass_ids)),
        "dirty_matrix_rows": dirty_rows,
        "checks": checks,
        "failed_checks": failed,
        "sources": {
            "audit_event_types": ["drift_detected", "importance_reevaluation"],
            "maintenance_policy_versions": [
                TM1B_CANONICAL_MAINTENANCE_POLICY_VERSION,
                TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
            ],
            "or_phase_matrix_ref": TM1D_OR_DIRTY_MATRIX_VERSION,
        },
    }


def _tm1a_normalize_thread_title(raw: object) -> str:
    text = _tm1a_normalize_text(raw)
    if text.startswith("[resolved] "):
        text = text[len("[resolved] "):].strip()
    elif text.startswith("resolved:"):
        text = text[len("resolved:"):].strip()
    return text


def _tm1a_relationship_pair_label(item: dict, left: str, right: str) -> str:
    identity = item.get("identity") if isinstance(item.get("identity"), dict) else {}
    pair_key = str(identity.get("pair_key") or item.get("pair") or "").strip()
    if pair_key:
        return pair_key
    return f"{left}<->{right}"


def _tm1a_find_recent_scene_memory_row(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
) -> Memory | None:
    memory_rows = (
        db.query(Memory)
        .filter(Memory.chat_session_id == chat_session_id)
        .order_by(Memory.turn_index.desc(), Memory.id.desc())
        .limit(8)
        .all()
    )
    for row in memory_rows:
        if current_turn >= 0 and row.turn_index is not None and row.turn_index < current_turn - 3:
            continue
        archive_wing = _tm1a_normalize_text(row.archive_wing)
        archive_room = _tm1a_normalize_text(row.archive_room)
        if not archive_wing and not archive_room:
            continue
        is_generic_slot = (
            archive_wing in TM1A_GENERIC_ARCHIVE_WINGS
            and archive_room in TM1A_GENERIC_ARCHIVE_ROOMS
        )
        if is_generic_slot:
            continue
        return row
    return None


def _tm1a_collect_relationship_mismatch_signal(db, *, chat_session_id: str) -> DriftSignal | None:
    canonical_row = (
        db.query(CanonicalStateLayer)
        .filter(
            CanonicalStateLayer.chat_session_id == chat_session_id,
            CanonicalStateLayer.layer_type == "relationship_state",
        )
        .order_by(CanonicalStateLayer.id.desc())
        .first()
    )
    if canonical_row is None:
        return None

    canonical_payload = _tm1a_parse_json(canonical_row.content, [])
    if not canonical_payload:
        return None

    latest_character_rows: dict[str, CharacterState] = {}
    rows = (
        db.query(CharacterState)
        .filter(CharacterState.chat_session_id == chat_session_id)
        .order_by(CharacterState.turn_index.desc(), CharacterState.id.desc())
        .all()
    )
    for row in rows:
        character_name = _tm1a_normalize_text(row.character_name)
        if not character_name or character_name in latest_character_rows:
            continue
        latest_character_rows[character_name] = row

    relationship_targets: dict[str, set[str]] = {}
    for character_name, row in latest_character_rows.items():
        parsed_relationships = _tm1a_parse_json(row.relationships_json, [])
        targets = {
            target
            for target in (
                _tm1a_normalize_text(rel.get("target"))
                for rel in parsed_relationships
                if isinstance(rel, dict)
            )
            if target
        }
        if targets:
            relationship_targets[character_name] = targets

    unmatched_pairs: list[str] = []
    for item in canonical_payload:
        if not isinstance(item, dict):
            continue
        identity = item.get("identity") if isinstance(item.get("identity"), dict) else {}
        left = _tm1a_normalize_text(identity.get("left_entity") or item.get("from"))
        right = _tm1a_normalize_text(identity.get("right_entity") or item.get("to"))
        if not left or not right or left == right:
            continue

        left_targets = relationship_targets.get(left, set())
        right_targets = relationship_targets.get(right, set())
        if right in left_targets or left in right_targets:
            continue

        unmatched_pairs.append(_tm1a_relationship_pair_label(item, left, right))

    if not unmatched_pairs:
        return None

    preview = ", ".join(unmatched_pairs[:3])
    return DriftSignal(
        signal_type="canonical_relationship_mismatch",
        severity="medium",
        detail=(
            f"canonical relationship_state has {len(unmatched_pairs)} unmatched pair(s) "
            f"against CharacterState.relationships_json: {preview}"
        ),
        correction_hint="review CharacterState relationships for the latest canonical pairs",
        source="canonical_state",
    )


def _tm1a_collect_unresolved_thread_mismatch_signal(db, *, chat_session_id: str) -> DriftSignal | None:
    canonical_row = (
        db.query(CanonicalStateLayer)
        .filter(
            CanonicalStateLayer.chat_session_id == chat_session_id,
            CanonicalStateLayer.layer_type == "unresolved_threads",
        )
        .order_by(CanonicalStateLayer.id.desc())
        .first()
    )
    if canonical_row is None:
        return None

    canonical_payload = _tm1a_parse_json(canonical_row.content, {})
    canonical_open = {
        normalized
        for normalized in (
            _tm1a_normalize_thread_title(item)
            for item in (canonical_payload.get("opened") or [])
        )
        if normalized
    }
    pending_open = {
        normalized
        for normalized in (
            _tm1a_normalize_thread_title(row.title)
            for row in (
                db.query(PendingThread)
                .filter(
                    PendingThread.chat_session_id == chat_session_id,
                    PendingThread.status == "open",
                )
                .all()
            )
        )
        if normalized
    }

    if canonical_open == pending_open:
        return None

    missing_in_pending = sorted(canonical_open - pending_open)
    missing_in_canonical = sorted(pending_open - canonical_open)
    detail_parts: list[str] = []
    if missing_in_pending:
        detail_parts.append(f"missing_in_pending={', '.join(missing_in_pending[:2])}")
    if missing_in_canonical:
        detail_parts.append(f"missing_in_canonical={', '.join(missing_in_canonical[:2])}")

    return DriftSignal(
        signal_type="canonical_unresolved_thread_mismatch",
        severity="medium",
        detail=(
            "canonical unresolved_threads.opened diverges from PendingThread(status='open')"
            + (f" ({'; '.join(detail_parts)})" if detail_parts else "")
        ),
        correction_hint="reconcile unresolved_threads.opened with open pending thread rows",
        source="canonical_state",
    )


def _tm1a_collect_scene_archive_mismatch_signal(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
) -> DriftSignal | None:
    canonical_row = (
        db.query(CanonicalStateLayer)
        .filter(
            CanonicalStateLayer.chat_session_id == chat_session_id,
            CanonicalStateLayer.layer_type == "scene_state",
        )
        .order_by(CanonicalStateLayer.id.desc())
        .first()
    )
    if canonical_row is None:
        return None

    scene_payload = _tm1a_parse_json(canonical_row.content, {})
    scene_label = ""
    for key in TM1A_SCENE_LOCATION_KEYS:
        scene_label = _tm1a_normalize_text(scene_payload.get(key))
        if scene_label:
            break
    if not scene_label:
        return None

    recent_memory = _tm1a_find_recent_scene_memory_row(
        db,
        chat_session_id=chat_session_id,
        current_turn=current_turn,
    )
    if recent_memory is None:
        return None

    archive_wing = _tm1a_normalize_text(recent_memory.archive_wing)
    archive_room = _tm1a_normalize_text(recent_memory.archive_room)
    archive_slot = " ".join(part for part in (archive_room, archive_wing) if part).strip()
    if not archive_slot:
        return None

    scene_keywords = set(_extract_drift_keywords(scene_label))
    archive_keywords = set(_extract_drift_keywords(archive_slot))
    matched = bool(scene_keywords & archive_keywords)
    if not matched:
        matched = scene_label in archive_slot or archive_slot in scene_label
    if matched:
        return None

    return DriftSignal(
        signal_type="canonical_scene_archive_mismatch",
        severity="low",
        detail=(
            f"canonical scene location '{scene_label}' does not align with recent memory archive slot "
            f"'{archive_room or archive_wing}'"
        ),
        correction_hint="review recent memory archive_wing/archive_room for the current scene",
        source="canonical_state",
    )


def _tm1a_collect_canonical_consistency_drift_signals(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
) -> list[DriftSignal]:
    signals: list[DriftSignal] = []
    checks = (
        ("relationship_state", lambda: _tm1a_collect_relationship_mismatch_signal(db, chat_session_id=chat_session_id)),
        ("unresolved_threads", lambda: _tm1a_collect_unresolved_thread_mismatch_signal(db, chat_session_id=chat_session_id)),
        ("scene_state", lambda: _tm1a_collect_scene_archive_mismatch_signal(db, chat_session_id=chat_session_id, current_turn=current_turn)),
    )
    for label, build_signal in checks:
        try:
            signal = build_signal()
        except Exception as exc:
            logger.debug("[TM-1a] canonical consistency check failed (%s, session=%s): %s", label, chat_session_id, exc)
            continue
        if signal is not None:
            signals.append(signal)
    return signals


def _tm1b_get_latest_canonical_rows(db, *, chat_session_id: str) -> dict[str, CanonicalStateLayer]:
    latest_rows: dict[str, CanonicalStateLayer] = {}
    for layer_type in sorted(set(TM1B_CANONICAL_SIGNAL_TO_LAYER_TYPE.values())):
        row = (
            db.query(CanonicalStateLayer)
            .filter(
                CanonicalStateLayer.chat_session_id == chat_session_id,
                CanonicalStateLayer.layer_type == layer_type,
            )
            .order_by(CanonicalStateLayer.id.desc())
            .first()
        )
        if row is not None:
            latest_rows[layer_type] = row
    return latest_rows


def _tm1b_can_verify_scene_layer(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
    canonical_row: CanonicalStateLayer,
) -> bool:
    scene_payload = _tm1a_parse_json(canonical_row.content, {})
    scene_label = ""
    for key in TM1A_SCENE_LOCATION_KEYS:
        scene_label = _tm1a_normalize_text(scene_payload.get(key))
        if scene_label:
            break
    if not scene_label:
        return False
    return _tm1a_find_recent_scene_memory_row(
        db,
        chat_session_id=chat_session_id,
        current_turn=current_turn,
    ) is not None


def _tm1b_apply_canonical_provenance_maintenance(
    db,
    *,
    chat_session_id: str,
    current_turn: int,
    drift_signals: list[DriftSignal],
) -> list[dict]:
    latest_rows = _tm1b_get_latest_canonical_rows(db, chat_session_id=chat_session_id)
    drift_by_layer: dict[str, DriftSignal] = {}
    for signal in drift_signals:
        layer_type = TM1B_CANONICAL_SIGNAL_TO_LAYER_TYPE.get(signal.signal_type)
        if layer_type and layer_type not in drift_by_layer:
            drift_by_layer[layer_type] = signal

    updates: list[dict] = []
    for layer_type, row in latest_rows.items():
        if layer_type == "scene_state" and not _tm1b_can_verify_scene_layer(
            db,
            chat_session_id=chat_session_id,
            current_turn=current_turn,
            canonical_row=row,
        ):
            continue

        previous_confidence = row.confidence
        previous_last_verified_turn = row.last_verified_turn
        signal = drift_by_layer.get(layer_type)

        if signal is None:
            if current_turn >= 0:
                row.last_verified_turn = current_turn
            if row.confidence is None:
                row.confidence = TM1B_DEFAULT_CONFIDENCE
            updates.append(
                {
                    "layer_type": layer_type,
                    "row_id": row.id,
                    "status": "verified",
                    "signal_type": None,
                    "severity": None,
                    "previous_confidence": previous_confidence,
                    "new_confidence": row.confidence,
                    "previous_last_verified_turn": previous_last_verified_turn,
                    "new_last_verified_turn": row.last_verified_turn,
                }
            )
            continue

        base_confidence = previous_confidence if previous_confidence is not None else TM1B_DEFAULT_CONFIDENCE
        decay = TM1B_CONFIDENCE_DECAY_BY_SEVERITY.get(signal.severity, TM1B_CONFIDENCE_DECAY_BY_SEVERITY["low"])
        row.confidence = round(max(TM1B_CONFIDENCE_FLOOR, float(base_confidence) - decay), 4)
        updates.append(
            {
                "layer_type": layer_type,
                "row_id": row.id,
                "status": "confidence_degraded",
                "signal_type": signal.signal_type,
                "severity": signal.severity,
                "previous_confidence": previous_confidence,
                "new_confidence": row.confidence,
                "previous_last_verified_turn": previous_last_verified_turn,
                "new_last_verified_turn": row.last_verified_turn,
            }
        )

    return updates


@app.post("/maintenance-pass/{chat_session_id}")
def run_maintenance_pass(chat_session_id: str, req: MaintenancePassRequest):
    """L-1b/L-2b: maintenance pass ??shadow-only observation + drift detection.

    L-1b ?④퀎?먯꽌??
    - GuidancePlanState ?좊Т ?뺤씤 諛?state_status ?쎄린
    - shadow_only=True 媛뺤젣 (guidance state 誘몃?寃?
    - observations: story_plan/director ?곹깭瑜??쎌뼱 ?ъ떎 湲곕줉
        - TM-1a: canonical state? CharacterState/PendingThread/recent Memory 媛?遺덉씪移??먯?
    - L-1c: refresh_suggestions (rule-based)
    - L-2b: drift_signals (arc_mismatch / forbidden_conflict / anchor_break)
      쨌 heuristic keyword matching, LLM ?놁쓬, non-fatal
    - 寃곌낵瑜?MaintenancePassState ?뚯씠釉붿뿉 湲곕줉 (trace??
    """
    import json as _json
    from datetime import datetime, timezone

    sid = (chat_session_id or "").strip()
    if not sid:
        return Utf8JSONResponse(
            content={"status": "error", "detail": "chat_session_id is required"},
            status_code=400,
        )

    executed_at = datetime.now(timezone.utc).isoformat()

    # L-1a: shadow_only????긽 True濡?媛뺤젣 (?덉쟾 ?먯튃)
    shadow_only = True

    db = SessionLocal()
    try:
        auto_verify_result = _run_direct_evidence_auto_verification(
            db,
            chat_session_id=sid,
            current_turn=req.turn_index,
        )

        # ?꾩옱 GuidancePlanState 議고쉶 (state_status ?뺤씤??
        cached: GuidancePlanState | None = (
            db.query(GuidancePlanState)
            .filter(GuidancePlanState.chat_session_id == sid)
            .first()
        )

        if cached is None:
            # ?꾩쭅 guidance state媛 ?녿뒗 ?몄뀡 ??skipped
            result = MaintenancePassResult(
                status="skipped",
                chat_session_id=sid,
                executed_at=executed_at,
                turn_index=req.turn_index,
                shadow_only=shadow_only,
                state_status="no_state",
            )
            # DB 湲곕줉 (trace?? non-fatal)
            try:
                db.add(MaintenancePassState(
                    chat_session_id=sid,
                    turn_index=req.turn_index,
                    status="skipped",
                    shadow_only=shadow_only,
                    observations_json=_json.dumps([], ensure_ascii=False),
                    drift_signals_json=_json.dumps([], ensure_ascii=False),
                    refresh_suggestions_json=_json.dumps([], ensure_ascii=False),
                    story_plan_refreshed=False,
                    director_refreshed=False,
                ))
                db.commit()
            except Exception as rec_err:
                logger.debug("[L-1b] maintenance record save failed (non-fatal): %s", rec_err)
                db.rollback()

            return Utf8JSONResponse(content=result.model_dump())

        current_state_status = cached.state_status or "empty"

        # ?? L-1b/L-1c: shadow-only observations + refresh_suggestions ??
        # guidance state瑜??쎌뼱 ?꾩옱 ?곹깭瑜??ъ떎 湲곕줉?섍퀬,
        # ?ㅼ쓬 maintenance 二쇨린???꾩슂??refresh ?쒖븞???앹꽦?쒕떎.
        # ?대뼡 媛믩룄 蹂寃쏀븯吏 ?딆쓬 (shadow_only=True).
        observations: list[str] = []
        drift_signals: list[DriftSignal] = []   # L-2b?먯꽌 梨꾩썙吏??덉젙
        refresh_suggestions: list[str] = []

        if int(auto_verify_result.get("verified", 0) or 0) > 0:
            observations.append(
                f"direct_evidence_auto_verified: {int(auto_verify_result.get('verified', 0) or 0)}"
            )

        # L-1c suggestion 怨꾩궛?????뚯떛 寃곌낵 ??湲곕낯媛?
        _n_tensions = 0
        _n_next_beats = 0
        _n_anchors = 0
        _n_required = 0
        _pressure = ""
        _turns_elapsed = -1
        # L-2b drift detection?????뚯떛 寃곌낵 ??湲곕낯媛?(try 釉붾줉 ?몃? ?묎렐 蹂댄샇??
        sp = {}
        dr = {}
        active_tensions: list = []
        next_beats: list = []
        continuity_anchors: list = []
        forbidden_moves: list = []

        try:
            # state_status ??긽 ?ы븿
            observations.append(f"state_status: {current_state_status}")

            # story_plan_json ?뚯떛
            try:
                sp = _json.loads(cached.story_plan_json or "{}")
            except Exception:
                sp = {}

            active_tensions = sp.get("active_tensions") or []
            if isinstance(active_tensions, list):
                _n_tensions = len(active_tensions)
                observations.append(f"active_tensions: {_n_tensions}")

            next_beats = sp.get("next_beats") or []
            if isinstance(next_beats, list):
                _n_next_beats = len(next_beats)
                observations.append(f"next_beats: {_n_next_beats}")

            continuity_anchors = sp.get("continuity_anchors") or []
            if isinstance(continuity_anchors, list):
                _n_anchors = len(continuity_anchors)
                observations.append(f"continuity_anchors: {_n_anchors}")

            # director_json ?뚯떛
            try:
                dr = _json.loads(cached.director_json or "{}")
            except Exception:
                dr = {}

            pressure = (dr.get("pressure_level") or "").strip()
            if pressure:
                _pressure = pressure
                observations.append(f"pressure_level: {pressure}")

            required_outcomes = dr.get("required_outcomes") or []
            if isinstance(required_outcomes, list):
                _n_required = len(required_outcomes)
                observations.append(f"open_required_outcomes: {_n_required}")

            forbidden_moves = dr.get("forbidden_moves") or []
            if isinstance(forbidden_moves, list):
                observations.append(f"forbidden_moves: {len(forbidden_moves)}")

            # turns since guidance build
            last_turn_idx = cached.last_turn if cached.last_turn is not None else -1
            if req.turn_index >= 0 and last_turn_idx >= 0:
                _turns_elapsed = req.turn_index - last_turn_idx
                observations.append(f"turns_since_guidance_build: {_turns_elapsed}")

            # ?? L-1c: refresh_suggestions (rule-based, shadow-only) ??
            # 媛?洹쒖튃? ?낅┰?곸쑝濡??먯젙 ??蹂듭닔 ?쒖븞 媛??
            # guidance state瑜?諛붽씀吏 ?딄퀬 ?ㅼ쓬 maintenance 二쇨린??諛섏쁺???쒖븞留??앹꽦.
            if current_state_status == "empty":
                # ?꾩쭅 guidance媛 ??踰덈룄 鍮뚮뱶?섏? ?딆? ?몄뀡
                refresh_suggestions.append("initial_guidance_needed")

            if _turns_elapsed >= 5:
                # 5???댁긽 guidance媛 媛깆떊?섏? ?딆쑝硫?rebuild 沅뚭퀬
                refresh_suggestions.append("guidance_rebuild_suggested")

            if _pressure in ("strong", "critical") and _n_required >= 2:
                # 媛뺥븳 ?뺣컯 ?곹솴?먯꽌 誘몄셿 required_outcomes媛 2媛??댁긽
                refresh_suggestions.append("high_pressure_outcomes_pending")

            if _n_tensions >= 3:
                # active_tensions媛 3媛??댁긽 ??湲댁옣媛?怨쇰???
                refresh_suggestions.append("tension_overload_noted")

            if _n_next_beats == 0 and current_state_status not in ("empty", "no_state"):
                # next_beats媛 鍮꾩뼱?덈뒗??guidance state???쒖꽦 ?곹깭
                refresh_suggestions.append("next_beats_missing")

            if _n_anchors == 0 and _n_required >= 1:
                # continuity anchor ?놁씠 required_outcomes媛 ?⑥븘 ?덉쓬
                refresh_suggestions.append("anchors_missing")

        except Exception as obs_err:
            logger.debug("[L-1b/L-1c] observation/suggestion build failed (non-fatal): %s", obs_err)
            # observations/suggestions 鍮뚮뱶 ?ㅽ뙣?대룄 鍮?由ъ뒪?몃줈 怨꾩냽 吏꾪뻾

        # ?? L-2b: drift signal ?먯? ?????????????????????????????????????
        # arc_mismatch / forbidden_conflict / anchor_break
        # heuristic keyword matching ??LLM ?놁쓬, shadow_only=True ?좎?.
        # assistant_response媛 鍮꾩뼱?덉쑝硫??꾩껜 skip (?띿뒪???щ즺 ?놁쓬).
        # ?먯? ?ㅽ뙣??non-fatal (drift_signals 鍮?由ъ뒪?몃줈 怨꾩냽 吏꾪뻾).
        try:
            _resp_text = (req.assistant_response or "").strip()
            _resp_lower = _resp_text.lower()

            if _resp_text and len(_resp_text) >= 20 and current_state_status not in ("no_state",):
                # ?? arc_mismatch ??????????????????????????????????????????
                # active_tensions + next_beats?먯꽌 ?ㅼ썙?쒕? 異붿텧??
                # ?묐떟???섎굹??留ㅼ묶?섏? ?딆쑝硫?arc? 臾닿????댁슜?쇰줈 ?먯젙.
                # 議곌굔: ?ㅼ썙???⑷퀎 3媛??댁긽 & 0媛?留ㅼ묶 (蹂댁닔???꾧퀎媛? false positive ?듭젣).
                if current_state_status not in ("empty",):
                    _arc_kws: list[str] = []
                    for _t in (active_tensions if isinstance(active_tensions, list) else []):
                        if isinstance(_t, str):
                            _arc_kws.extend(_extract_drift_keywords(_t))
                    for _b in (next_beats if isinstance(next_beats, list) else []):
                        if isinstance(_b, str):
                            _arc_kws.extend(_extract_drift_keywords(_b))
                    _arc_kws = list(set(_arc_kws))

                    # L-2d: 珥덇린 ??turns_elapsed < 2) ?먮뒗 吏㏃? ?묐떟(< 60?? ??arc_mismatch ?듭젣
                    # guidance 鍮뚮뱶 吏곹썑??arc媛 ?꾩쭅 ?뺤갑 ?? 吏㏃? ?묐떟? scene-setter 媛?μ꽦
                    _arc_mismatch_suppressed = (
                        (0 <= _turns_elapsed < 2) or len(_resp_text) < 60
                    )
                    if len(_arc_kws) >= 3 and not _arc_mismatch_suppressed:
                        _arc_matched = sum(1 for kw in _arc_kws if kw in _resp_lower)
                        if _arc_matched == 0:
                            _tension_preview = ", ".join(
                                str(t) for t in (active_tensions or [])[:2]
                            )
                            drift_signals.append(DriftSignal(
                                signal_type="arc_mismatch",
                                severity="low",
                                detail=(
                                    f"response shares no keywords with active arc "
                                    f"({len(_arc_kws)} arc keywords, 0 matched)"
                                ),
                                correction_hint=(
                                    f"refocus on active tensions: {_tension_preview}"
                                    if _tension_preview else "refocus on current arc"
                                ),
                                source="story_plan",
                            ))

                # ?? forbidden_conflict ????????????????????????????????????
                # forbidden_moves 媛???ぉ???ㅼ썙?쒓? 紐⑤몢 ?묐떟???ы븿?섎㈃ conflict.
                # ??ぉ???덈Т 吏㏃쑝硫?(< 4?? false positive ?꾪뿕 ??skip.
                # over-signal ?듭젣: 泥?踰덉㎏ conflict留?蹂닿퀬 ??break.
                _fb_conflict_found = False
                for _fb in (forbidden_moves if isinstance(forbidden_moves, list) else []):
                    if _fb_conflict_found:
                        break
                    if not isinstance(_fb, str):
                        continue
                    _fb = _fb.strip()
                    if len(_fb) < 4:
                        continue
                    _fb_kws = _extract_drift_keywords(_fb)
                    if not _fb_kws:
                        continue
                    # forbidden move ?ㅼ썙??理쒕? 3媛?以?紐⑤몢 ?묐떟???깆옣?댁빞 conflict
                    _check_kws = _fb_kws[:3]
                    # L-2d: check_kws 以?4???댁긽 ?ㅼ썙?쒓? ?놁쑝硫??덈Т 吏㏃븘 false positive ?꾪뿕 ??skip
                    if not any(len(kw) >= 4 for kw in _check_kws):
                        continue
                    if all(kw in _resp_lower for kw in _check_kws):
                        _fb_preview = _fb[:60]
                        drift_signals.append(DriftSignal(
                            signal_type="forbidden_conflict",
                            severity="high",
                            detail=f"response may contain forbidden pattern: '{_fb_preview}'",
                            correction_hint=f"avoid: '{_fb_preview}'",
                            source="director",
                        ))
                        _fb_conflict_found = True

                # ?? anchor_break ??????????????????????????????????????????
                # continuity_anchors媛 2媛??댁긽 ?덇퀬 ?묐떟??異⑸텇??湲???0?? 寃쎌슦留??먯젙.
                # anchor ?ㅼ썙??2媛??댁긽 ?덇퀬 0媛쒕룄 留ㅼ묶 ???섎㈃ anchor_break.
                if len(_resp_text) >= 80:
                    _anchor_list = (
                        continuity_anchors if isinstance(continuity_anchors, list) else []
                    )
                    if len(_anchor_list) >= 2:
                        _anchor_kws: list[str] = []
                        for _anc in _anchor_list:
                            if isinstance(_anc, str):
                                _anchor_kws.extend(_extract_drift_keywords(_anc))
                        _anchor_kws = list(set(_anchor_kws))

                        if len(_anchor_kws) >= 2:
                            _anchor_matched = sum(
                                1 for kw in _anchor_kws if kw in _resp_lower
                            )
                            if _anchor_matched == 0:
                                _anchor_preview = ", ".join(
                                    str(a) for a in _anchor_list[:2]
                                )
                                drift_signals.append(DriftSignal(
                                    signal_type="anchor_break",
                                    severity="low",
                                    detail=(
                                        f"response shares no keywords with continuity_anchors "
                                        f"({len(_anchor_list)} anchors, 0 matched)"
                                    ),
                                    correction_hint=(
                                        f"maintain continuity with: {_anchor_preview}"
                                        if _anchor_preview else "maintain continuity anchors"
                                    ),
                                    source="story_plan",
                                ))

                # L-2d: arc_mismatch + anchor_break ?숈떆 諛쒗솕 dedup
                # anchor_break媛 ??援ъ껜?곸씠誘濡?arc_mismatch瑜??쒓굅 (?댁쨷 蹂닿퀬 諛⑹?)
                _types_now = {ds.signal_type for ds in drift_signals}
                if "arc_mismatch" in _types_now and "anchor_break" in _types_now:
                    drift_signals = [
                        ds for ds in drift_signals if ds.signal_type != "arc_mismatch"
                    ]

        except Exception as drift_err:
            logger.debug("[L-2b] drift detection failed (non-fatal): %s", drift_err)
            drift_signals = []  # ?먯? ?ㅽ뙣 ??鍮?由ъ뒪?몃줈 怨꾩냽

        # ?? L-2f: pattern guard ???????????????????????????????????????????
        # recent_responses (理쒕? 5媛??먯꽌 諛섎났 ?쒗쁽/臾멸뎄 ?⑦꽩 ?먯?.
        # ?먯? 寃곌낵 ??pattern_repeat DriftSignal濡??몄엯.
        # 議곌굔: recent_responses 2媛??댁긽 & current_state_status not in (no_state, empty).
        # ?먯? ?ㅽ뙣??non-fatal.
        try:
            _recent = [r for r in (req.recent_responses or []) if isinstance(r, str) and r.strip()]
            # 理쒕? 5媛쒕줈 ?쒗븳, 媛??묐떟 理쒕? 500?먮줈 ?섎씪 ?깅뒫 蹂댄샇
            _recent = [r[:500] for r in _recent[-5:]]

            if len(_recent) >= 2 and current_state_status not in ("no_state", "empty"):
                _patterns = _detect_pattern_repeat(_recent)
                if _patterns:
                    # ?⑦꽩 ?좏삎蹂??뚰듃 ?앹꽦
                    _opening_patterns = [p for p in _patterns if p.startswith("opening_phrase_repeat:")]
                    _bigram_patterns = [p for p in _patterns if p.startswith("bigram_repeat:")]

                    _detail_parts: list[str] = []
                    if _opening_patterns:
                        _detail_parts.append(
                            f"repeated opening phrase detected ({len(_opening_patterns)} pattern(s))"
                        )
                    if _bigram_patterns:
                        _detail_parts.append(
                            f"high-frequency bigram(s) across recent responses ({len(_bigram_patterns)} pattern(s))"
                        )

                    _pattern_preview = "; ".join(p.split(":", 1)[-1] for p in _patterns[:2])
                    drift_signals.append(DriftSignal(
                        signal_type="pattern_repeat",
                        severity="medium",
                        detail=", ".join(_detail_parts),
                        correction_hint=(
                            f"vary expression style; avoid repeating: {_pattern_preview}"
                            if _pattern_preview else "vary expression style"
                        ),
                        source="pattern_guard",
                    ))
        except Exception as pg_err:
            logger.debug("[L-2f] pattern guard failed (non-fatal): %s", pg_err)

        # ?? TM-1a: canonical state active consistency drift ??????????????
        # relationship_state ??CharacterState.relationships_json
        # unresolved_threads.opened ??PendingThread(status="open")
        # scene_state.location ??recent Memory archive_wing/archive_room
        # ?쎄린 ?꾩슜 愿李??④퀎?대ŉ, drift signal留?異붽??쒕떎.
        try:
            tm1a_signals = _tm1a_collect_canonical_consistency_drift_signals(
                db,
                chat_session_id=sid,
                current_turn=req.turn_index,
            )
            if tm1a_signals:
                drift_signals.extend(tm1a_signals)
                observations.append(
                    f"canonical_consistency_drift_signals[{TM1A_CANONICAL_CONSISTENCY_POLICY_VERSION}]: {len(tm1a_signals)}"
                )
        except Exception as tm1a_err:
            logger.debug("[TM-1a] canonical consistency drift detection failed (non-fatal): %s", tm1a_err)

        # ?? L-2c: correction_hints + patch_suggestions ????????????????????
        # drift_signals?먯꽌 ?뚯깮 ??LLM ?놁쓬, rule-based 吏묎퀎.
        # correction_hints: non-empty correction_hint瑜?severity 湲곗? ?뺣젹 ??理쒕? 3媛?
        #   high ?????묐몢?щ줈 媛뺤“, ?ㅼ쓬 ??supervisor 二쇱엯 ?щ즺.
        # patch_suggestions: signal_type蹂?1??援ъ“??patch ?쒖븞
        #   (refresh_suggestions??guidance rebuild 二쇨린 ?쒖븞, ?댁そ? drift-specific ?됰룞 ?쒖븞).
        # ?먯? ?ㅽ뙣??non-fatal ??鍮?由ъ뒪?몃줈 怨꾩냽.
        correction_hints: list[str] = []
        patch_suggestions: list[str] = []
        try:
            _sev_order = {"high": 0, "medium": 1, "low": 2}
            _sorted_signals = sorted(
                drift_signals, key=lambda d: _sev_order.get(d.severity, 9)
            )

            # correction_hints ??non-empty hint留? 理쒕? 3媛?
            for _ds in _sorted_signals:
                if not _ds.correction_hint:
                    continue
                if len(correction_hints) >= 3:
                    break
                _prefix = "??" if _ds.severity == "high" else ""
                correction_hints.append(
                    f"{_prefix}[{_ds.signal_type}] {_ds.correction_hint}"
                )

            # patch_suggestions ??signal_type蹂?1??(dedup)
            _seen_patch: set[str] = set()
            for _ds in _sorted_signals:
                if _ds.signal_type in _seen_patch:
                    continue
                _seen_patch.add(_ds.signal_type)
                if _ds.signal_type == "arc_mismatch":
                    patch_suggestions.append("suggest_story_plan_next_beats_reinforce")
                elif _ds.signal_type == "forbidden_conflict":
                    patch_suggestions.append("suggest_forbidden_moves_reinforce")
                elif _ds.signal_type == "anchor_break":
                    patch_suggestions.append("suggest_continuity_anchors_reinforce")
                elif _ds.signal_type == "checklist_stale":
                    patch_suggestions.append("suggest_checklist_review")
                elif _ds.signal_type == "pattern_repeat":
                    patch_suggestions.append("suggest_expression_diversity")
                elif _ds.signal_type == "canonical_relationship_mismatch":
                    patch_suggestions.append("suggest_character_state_relationship_reconcile")
                elif _ds.signal_type == "canonical_unresolved_thread_mismatch":
                    patch_suggestions.append("suggest_pending_thread_reconcile")
                elif _ds.signal_type == "canonical_scene_archive_mismatch":
                    patch_suggestions.append("suggest_scene_archive_slot_review")

        except Exception as c_err:
            logger.debug("[L-2c] correction hints build failed (non-fatal): %s", c_err)
            correction_hints = []
            patch_suggestions = []

        # ?? World Rule Sync (supervisor_result ?쒓났 ?? ?????????????????
        # maintenance pass媛 supervisor result瑜?諛쏆븯????world rules瑜?DB?????
        # postWorldRulesSync(plugin)? ?숈씪??濡쒖쭅 ???듯빀 寃쎈줈.
        # ?ㅽ뙣??non-fatal (world rule ????ㅽ뙣媛 maintenance pass ?꾩껜瑜?留됱? ?딆쓬).
        try:
            if req.supervisor_result and isinstance(req.supervisor_result, dict):
                _sv = req.supervisor_result
                # directive ?섑띁瑜?踰쀪꺼??(plugin??directive ?꾨뱶瑜?媛먯? ???덉쓬)
                _directive = _sv.get("directive") or _sv
                _sw = _directive.get("section_world") if isinstance(_directive, dict) else None
                if _sw and isinstance(_sw, dict) and _sw.get("applies") is not False:
                    _candidates = _parse_world_rules_from_supervisor(_directive)
                    _validated_wr: list[dict] = []
                    for _c in _candidates:
                        if not _validate_world_rule_candidate(_c):
                            _validated_wr.append(_c)
                    if _validated_wr:
                        for _c in _validated_wr:
                            _key = _c["key"]
                            _scope = _c.get("scope", "root")
                            _scope_name = _c.get("scope_name") or None
                            _q = (
                                db.query(WorldRule)
                                .filter(
                                    WorldRule.chat_session_id == sid,
                                    WorldRule.scope == _scope,
                                    WorldRule.key == _key,
                                )
                            )
                            if _scope_name is None:
                                _q = _q.filter(WorldRule.scope_name.is_(None))
                            else:
                                _q = _q.filter(WorldRule.scope_name == _scope_name)
                            _existing = _q.first()
                            if _existing:
                                if _c.get("value_json"):
                                    _existing.value_json = _c["value_json"]
                                if _c.get("category"):
                                    _existing.category = _c["category"]
                                if _c.get("genre"):
                                    _existing.genre = _c["genre"]
                                if _scope_name is not None:
                                    _existing.scope_name = _scope_name
                                _existing.source_turn = req.turn_index
                            else:
                                db.add(WorldRule(
                                    chat_session_id=sid,
                                    scope=_scope,
                                    scope_name=_scope_name,
                                    category=_c.get("category", "custom"),
                                    key=_key,
                                    value_json=_c.get("value_json"),
                                    genre=_c.get("genre"),
                                    source_turn=req.turn_index,
                                ))
                        db.commit()
                        observations.append(f"world_rules_synced: {len(_validated_wr)}")
                        logger.debug(
                            "[maintenance] world rules synced for session %s, turn %d, count %d",
                            sid, req.turn_index, len(_validated_wr),
                        )
        except Exception as wr_err:
            logger.debug("[maintenance] world rule sync failed (non-fatal): %s", wr_err)
            try:
                db.rollback()
            except Exception:
                pass

        tm1c_importance_result = {
            "policy_version": TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
            "updates": [],
            "protected_count": 0,
            "boosted_count": 0,
            "decayed_count": 0,
        }
        try:
            tm1c_importance_result = _tm1c_apply_memory_importance_reevaluation(
                db,
                chat_session_id=sid,
                current_turn=req.turn_index,
            )
            if tm1c_importance_result.get("updates") or tm1c_importance_result.get("protected_count"):
                observations.append(
                    "memory_importance_reevaluated[{policy}]: updated={updated}, boosted={boosted}, decayed={decayed}, protected={protected}".format(
                        policy=tm1c_importance_result.get("policy_version") or TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
                        updated=len(tm1c_importance_result.get("updates") or []),
                        boosted=int(tm1c_importance_result.get("boosted_count") or 0),
                        decayed=int(tm1c_importance_result.get("decayed_count") or 0),
                        protected=int(tm1c_importance_result.get("protected_count") or 0),
                    )
                )
        except Exception as tm1c_err:
            logger.debug("[TM-1c] memory importance reevaluation failed (non-fatal): %s", tm1c_err)
            try:
                db.rollback()
            except Exception:
                pass
            tm1c_importance_result = {
                "policy_version": TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
                "updates": [],
                "protected_count": 0,
                "boosted_count": 0,
                "decayed_count": 0,
            }

        canonical_provenance_updates: list[dict] = []
        try:
            canonical_provenance_updates = _tm1b_apply_canonical_provenance_maintenance(
                db,
                chat_session_id=sid,
                current_turn=req.turn_index,
                drift_signals=drift_signals,
            )
            if canonical_provenance_updates:
                verified_count = sum(1 for item in canonical_provenance_updates if item.get("status") == "verified")
                drifted_count = sum(
                    1 for item in canonical_provenance_updates if item.get("status") == "confidence_degraded"
                )
                observations.append(
                    f"canonical_provenance_maintenance[{TM1B_CANONICAL_MAINTENANCE_POLICY_VERSION}]: verified={verified_count}, drifted={drifted_count}"
                )
        except Exception as tm1b_err:
            logger.debug("[TM-1b] canonical provenance maintenance failed (non-fatal): %s", tm1b_err)
            try:
                db.rollback()
            except Exception:
                pass
            canonical_provenance_updates = []

        result = MaintenancePassResult(
            status="ok",
            chat_session_id=sid,
            executed_at=executed_at,
            turn_index=req.turn_index,
            shadow_only=shadow_only,
            state_status=current_state_status,
            observations=observations,
            drift_signals=drift_signals,
            refresh_suggestions=refresh_suggestions,
            correction_hints=correction_hints,
            patch_suggestions=patch_suggestions,
            story_plan_refreshed=False,
            director_refreshed=False,
        )

        # DB 湲곕줉 (trace?? non-fatal)
        try:
            pass_row = MaintenancePassState(
                chat_session_id=sid,
                turn_index=req.turn_index,
                status="ok",
                shadow_only=shadow_only,
                observations_json=_json.dumps(observations, ensure_ascii=False),
                drift_signals_json=_json.dumps([ds.model_dump() for ds in drift_signals], ensure_ascii=False),
                refresh_suggestions_json=_json.dumps(refresh_suggestions, ensure_ascii=False),
                story_plan_refreshed=False,
                director_refreshed=False,
            )
            db.add(pass_row)
            db.commit()
            db.refresh(pass_row)
            drifted_updates = [
                item for item in canonical_provenance_updates if item.get("status") == "confidence_degraded"
            ]
            if drifted_updates:
                drift_details = {
                    "policy_version": TM1B_CANONICAL_MAINTENANCE_POLICY_VERSION,
                    "turn_index": req.turn_index,
                    "maintenance_pass_id": pass_row.id,
                    "confidence_floor": TM1B_CONFIDENCE_FLOOR,
                    "drift_signal_types": sorted({item.get("signal_type") for item in drifted_updates if item.get("signal_type")}),
                    "canonical_updates": canonical_provenance_updates,
                }
                drift_details.update(
                    _tm1d_build_audit_replay_contract(
                        event_type="drift_detected",
                        details=drift_details,
                    )
                )
                append_audit_log(
                    event_type="drift_detected",
                    chat_session_id=sid,
                    target_type="maintenance_pass",
                    target_id=pass_row.id,
                    summary=f"TM-1b detected canonical drift across {len(drifted_updates)} layer(s)",
                    details=drift_details,
                    source="maintenance",
                )
            if tm1c_importance_result.get("updates"):
                importance_details = {
                    "policy_version": tm1c_importance_result.get("policy_version") or TM1C_MEMORY_IMPORTANCE_POLICY_VERSION,
                    "turn_index": req.turn_index,
                    "maintenance_pass_id": pass_row.id,
                    "updated_count": len(tm1c_importance_result.get("updates") or []),
                    "boosted_count": int(tm1c_importance_result.get("boosted_count") or 0),
                    "decayed_count": int(tm1c_importance_result.get("decayed_count") or 0),
                    "protected_count": int(tm1c_importance_result.get("protected_count") or 0),
                    "memory_updates": tm1c_importance_result.get("updates") or [],
                }
                importance_details.update(
                    _tm1d_build_audit_replay_contract(
                        event_type="importance_reevaluation",
                        details=importance_details,
                    )
                )
                append_audit_log(
                    event_type="importance_reevaluation",
                    chat_session_id=sid,
                    target_type="maintenance_pass",
                    target_id=pass_row.id,
                    summary=(
                        f"TM-1c reevaluated {len(tm1c_importance_result.get('updates') or [])} memory row(s)"
                    ),
                    details=importance_details,
                    source="maintenance",
                )
            logger.debug("[L-1b] maintenance pass recorded for session %s, turn %d", sid, req.turn_index)
        except Exception as rec_err:
            logger.debug("[L-1b] maintenance record save failed (non-fatal): %s", rec_err)
            db.rollback()

        return Utf8JSONResponse(content=result.model_dump())

    except Exception as e:
        logger.warning("[L-1b] maintenance pass failed (non-fatal): %s", e)
        try:
            db.rollback()
        except Exception:
            pass
        # non-fatal: ?먮윭 諛쒖깮?대룄 梨꾪똿???곹뼢 ?녿룄濡??뺤긽 ?묐떟 諛섑솚
        return Utf8JSONResponse(content=MaintenancePassResult(
            status="error",
            chat_session_id=sid,
            executed_at=executed_at,
            turn_index=req.turn_index,
            shadow_only=shadow_only,
            state_status="error",
        ).model_dump())
    finally:
        db.close()


