@app.post("/turns")
def save_turn(req: SaveTurnRequest):
    try:
        result = librarian.save_turn(
            req.turn_index,
            req.user_content or "",
            req.assistant_content or "",
            chat_session_id=req.chat_session_id or None,
        )
        if not result.get("ok"):
            raise RuntimeError(str(result.get("error") or "save_turn_failed"))
        if req.chat_session_id:
            _mark_retrieval_index_dirty_q1c(
                req.chat_session_id,
                reason="turn_saved",
                turn_index=req.turn_index,
            )
        return {"status": "ok", "turn_index": req.turn_index}
    except Exception as exc:
        logger.error("POST /turns ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={"status": "error", "turn_index": req.turn_index, "detail": str(exc)},
            status_code=500,
        )


@app.post("/turns/repair-replay")
def repair_turn_replay(req: ChatLogRepairReplayRequest):
    try:
        session_id = (req.chat_session_id or "").strip()
        if not session_id:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id媛 ?꾩슂?⑸땲??", "results": []},
                status_code=400,
            )

        results: list[dict] = []
        failed_turns: list[int] = []
        repaired_turns: list[int] = []
        conflict_turns: list[int] = []
        total_missing_role_count = 0
        total_repaired_role_count = 0
        total_conflict_role_count = 0

        for entry in (req.entries or [])[:200]:
            item_result = librarian.repair_turn(
                turn_index=entry.turn_index,
                user_content=entry.user_content or "",
                assistant_content=entry.assistant_content or "",
                chat_session_id=session_id,
                dry_run=bool(req.dry_run),
            )
            results.append(item_result)
            total_missing_role_count += len(item_result.get("missing_roles") or [])
            total_repaired_role_count += len(item_result.get("repaired_roles") or [])
            total_conflict_role_count += len(item_result.get("conflict_roles") or [])
            if not item_result.get("ok"):
                failed_turns.append(entry.turn_index)
            if item_result.get("repaired_roles"):
                repaired_turns.append(entry.turn_index)
            if item_result.get("conflict_roles"):
                conflict_turns.append(entry.turn_index)

        if repaired_turns:
            _mark_retrieval_index_dirty_q1c(
                session_id,
                reason="chat_log_repair_replayed",
                turn_index=max(repaired_turns),
            )

        status = "ok"
        if failed_turns:
            status = "partial" if results else "error"

        return {
            "status": status,
            "chat_session_id": session_id,
            "dry_run": bool(req.dry_run),
            "candidate_count": len(req.entries or []),
            "processed_count": len(results),
            "failed_turns": failed_turns,
            "repaired_turns": repaired_turns,
            "conflict_turns": conflict_turns,
            "total_missing_role_count": total_missing_role_count,
            "total_repaired_role_count": total_repaired_role_count,
            "total_conflict_role_count": total_conflict_role_count,
            "results": results,
        }
    except Exception as exc:
        logger.error("POST /turns/repair-replay ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc), "results": []},
            status_code=500,
        )


@app.post("/effective-inputs")
def save_effective_input(req: SaveEffectiveInputRequest):
    db = SessionLocal()
    try:
        session_id = (req.chat_session_id or "").strip() or "default"
        text = (req.effective_input or "").strip()
        if not text:
            return {"status": "ignored", "reason": "empty_effective_input", "turn_index": req.turn_index}

        row = EffectiveInputLog(
            chat_session_id=session_id,
            turn_index=req.turn_index,
            effective_input=text,
        )
        db.add(row)
        db.commit()
        return {
            "status": "ok",
            "turn_index": req.turn_index,
            "chat_session_id": session_id,
            "id": row.id,
        }
    except Exception as exc:
        db.rollback()
        logger.error("POST /effective-inputs failed: %s", exc)
        return Utf8JSONResponse(
            content={
                "status": "error",
                "turn_index": req.turn_index,
                "detail": str(exc),
            },
            status_code=500,
        )
    finally:
        db.close()


@app.delete("/rollback/{turn_index}")
def rollback(turn_index: int, chat_session_id: str = "", req_source: str = ""):
    try:
        if turn_index < 0:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "invalid turn_index"},
                status_code=400,
            )
        source = "auto_rollback" if req_source == "auto" else "manual_ui"
        result = librarian.rollback(turn_index, chat_session_id=chat_session_id or None)
        # N-1c: rollback 吏곹썑 ?대떦 ?몄뀡??pending maintenance job discard
        if chat_session_id:
            _mq_discard_session(chat_session_id)
            _discard_retrieval_index_q1c(
                chat_session_id,
                reason="rollback",
                turn_index=turn_index,
            )
        append_audit_log(
            event_type="rollback",
            chat_session_id=chat_session_id or None,
            summary=f"Rollback to turn {turn_index}",
            details={"turn_index": turn_index, **result},
            source=source,
        )
        return {"status": "ok", **result}
    except Exception as exc:
        logger.error("DELETE /rollback/%d ?ㅽ뙣: %s", turn_index, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


@app.post("/search")
def search(req: SearchRequest):
    try:
        safe_input = (req.user_input or "").strip()
        if not safe_input:
            return {
                "items": [], "injection_text": "",
                "memory_count": 0, "fallback_count": 0,
                "has_fallback": False, "total_count": 0,
            }
        items = storyteller.search(
            user_input=safe_input,
            wing=req.wing,
            top_k=req.top_k,
            chat_session_id=req.chat_session_id or None,
        )
        injection_text = storyteller.format_for_injection(items)
        memory_count = sum(1 for i in items if i.get("source") == "memory")
        fallback_count = sum(1 for i in items if i.get("source") == "chat_log")
        return {
            "items": items,
            "injection_text": injection_text,
            "memory_count": memory_count,
            "fallback_count": fallback_count,
            "has_fallback": fallback_count > 0,
            "total_count": len(items),
        }
    except Exception as exc:
        logger.error("POST /search ?ㅽ뙣: %s", exc)
        return {
            "items": [], "injection_text": "",
            "memory_count": 0, "fallback_count": 0,
            "has_fallback": False, "total_count": 0,
            "status": "error", "detail": str(exc),
        }


