@app.post("/turns/complete")
def complete_turn(req: CompleteTurnRequest, background_tasks: BackgroundTasks):
    try:
        safe_content = (req.turn_content or "").strip()
        safe_context = req.context if isinstance(req.context, list) else []
        if _looks_like_ooc_text_main(safe_content):
            logger.info(
                "POST /turns/complete skipped by ooc guard (turn=%d, session=%s)",
                req.turn_index,
                req.chat_session_id or "default",
            )
            return {
                "status": "accepted",
                "turn_index": req.turn_index,
                "skipped": True,
                "skip_reason": "ooc_turn_guard",
            }
        background_tasks.add_task(
            critic.run,
            req.turn_index,
            safe_content,
            safe_context,
            req.chat_session_id or None,
            req.output_language_override,
        )
        logger.info("POST /turns/complete accepted (turn=%d, session=%s)", req.turn_index, req.chat_session_id or "default")
        return {"status": "accepted", "turn_index": req.turn_index}
    except Exception as exc:
        logger.error("POST /turns/complete ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={"status": "error", "turn_index": req.turn_index, "detail": str(exc)},
            status_code=500,
        )


