@app.post("/kg/recall")
def kg_recall(req: KGRecallRequest):
    """?꾩옱 session??KG triple 以?entities??留ㅼ묶?섎뒗 ??ぉ??諛섑솚?쒕떎."""
    try:
        entities = req.entities if isinstance(req.entities, list) else []
        # 鍮?entity 紐⑸줉?대㈃ 鍮?寃곌낵 諛섑솚 (?먮윭 ?꾨떂)
        if not entities or not any(str(e).strip() for e in entities):
            return {"status": "ok", "items": [], "count": 0, "entities_received": 0}

        safe_entities = [str(e).strip() for e in entities if str(e).strip()][:30]  # 理쒕? 30媛?entity
        limit = max(1, min(50, req.limit)) if isinstance(req.limit, int) and req.limit > 0 else 20

        items = palace.recall_kg_triples(
            chat_session_id=req.chat_session_id or None,
            entities=safe_entities,
            limit=limit,
            current_turn=req.current_turn,
        )
        return {
            "status": "ok",
            "items": items,
            "count": len(items),
            "entities_received": len(safe_entities),
        }
    except Exception as exc:
        logger.error("POST /kg/recall ?ㅽ뙣: %s", exc)
        return {
            "status": "error",
            "items": [],
            "count": 0,
            "entities_received": 0,
            "detail": str(exc),
        }


@app.get("/kg/recall")
def kg_recall_legacy_get(
    chat_session_id: str = "",
    session_id: str = "",
    limit: int = 30,
    offset: int = 0,
):
    """?덇굅??explorer ?몄텧怨?cached bundle???꾪빐 GET /kg/recall???좎??쒕떎."""
    try:
        sid = chat_session_id or session_id or None
        if not sid:
            return {
                "status": "ok",
                "items": [],
                "total": 0,
                "limit": max(1, min(200, limit)) if isinstance(limit, int) else 30,
                "offset": max(0, offset) if isinstance(offset, int) else 0,
                "count": 0,
                "has_more": False,
                "legacy_compat": True,
            }

        result = palace.get_kg_triples(
            chat_session_id=sid,
            limit=limit,
            offset=offset,
        )
        return {
            "status": "ok",
            **result,
            "count": len(result.get("items") or []),
            "legacy_compat": True,
        }
    except Exception as exc:
        logger.error("GET /kg/recall ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={
                "status": "error",
                "items": [],
                "total": 0,
                "limit": max(1, int(limit or 30)),
                "offset": max(0, int(offset or 0)),
                "count": 0,
                "legacy_compat": True,
                "detail": str(exc),
            },
            status_code=500,
        )


