@app.post("/supervisor")
def supervisor_directive(req: SupervisorRequest):
    try:
        safe_ctx = req.context_messages if isinstance(req.context_messages, list) else []

        # E-1f: ?쒖꽦 ?ㅽ넗由щ씪??而⑦뀓?ㅽ듃 議곕┰
        storylines_context = ""
        storyline_selection_trace = {
            "reference_turn": None,
            "total_active_count": 0,
            "selected_count": 0,
            "dropped_count": 0,
            "selected": [],
            "dropped": [],
        }
        if req.chat_session_id:
            try:
                db = SessionLocal()
                try:
                    rows = (
                        db.query(Storyline)
                        .filter(
                            Storyline.chat_session_id == req.chat_session_id,
                            Storyline.status == "active",
                        )
                        .order_by(Storyline.last_turn.desc().nullslast(), Storyline.id.desc())
                        .all()
                    )
                    if rows:
                        selection = _select_storylines_for_supervisor(rows, limit=5)
                        storylines_context = _format_storylines_for_supervisor(selection)
                        storyline_selection_trace = _summarize_storyline_selection(selection)
                finally:
                    db.close()
            except Exception as sl_err:
                logger.warning("Storyline context fetch failed (non-fatal): %s", sl_err)

        # L-4a: trigger semantics 濡쒓퉭 (shadow留? ?숈옉 蹂寃??놁쓬)
        _aat = req.auto_advance_trigger or "none"
        if _aat not in ("none", ""):
            logger.info("supervisor: auto_advance_trigger=%s session=%s", _aat, req.chat_session_id or "?")

        result = supervisor.get_directive(
            context_messages=safe_ctx,
            wake_up_context=req.wake_up_context or "",
            chat_session_id=req.chat_session_id or None,
            storylines_context=storylines_context,
            guide_suffix=req.guide_suffix or "",
            narrative_stance=req.narrative_stance or "balanced",
            narrative_stance_suffix=req.narrative_stance_suffix or "",
            narrative_stance_bounds=req.narrative_stance_bounds if isinstance(req.narrative_stance_bounds, dict) else {},
            momentum_packet=req.momentum_packet if isinstance(req.momentum_packet, dict) else None,
            persistent_guidance=req.persistent_guidance or "",
        )
        return {"status": "ok", "directive": result, "storyline_selection": storyline_selection_trace, "auto_advance_trigger": _aat}
    except Exception as exc:
        logger.error("POST /supervisor ?ㅽ뙣: %s", exc)
        return {"status": "ok", "directive": supervisor._default_directive()}


