@app.get("/prompts/{prompt_name}")
def prompt_get(prompt_name: str):
    try:
        prompt = {
            **get_prompt_metadata(prompt_name),
            "content": read_prompt(prompt_name),
        }
        return {"status": "ok", "prompt": prompt}
    except PromptNotFoundError:
        return Utf8JSONResponse(
            content={"status": "error", "detail": f"unknown prompt: {prompt_name}"},
            status_code=404,
        )
    except Exception as exc:
        logger.error("GET /prompts/%s ?ㅽ뙣: %s", prompt_name, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


@app.put("/prompts/{prompt_name}")
def prompt_update(prompt_name: str, req: PromptUpdateRequest):
    try:
        meta = write_prompt(prompt_name, req.content)
        prompt = {
            **meta,
            "content": read_prompt(prompt_name, use_cache=False),
        }
        return {"status": "ok", "prompt": prompt}
    except PromptNotFoundError:
        return Utf8JSONResponse(
            content={"status": "error", "detail": f"unknown prompt: {prompt_name}"},
            status_code=404,
        )
    except InvalidPromptContentError as exc:
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=400,
        )
    except Exception as exc:
        logger.error("PUT /prompts/%s ?ㅽ뙣: %s", prompt_name, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


