@app.post("/episodes/generate")
def generate_episode(req: EpisodeGenerateRequest, background_tasks: BackgroundTasks):
    """吏?뺣맂 turn range???먰뵾?뚮뱶 ?붿빟???앹꽦?쒕떎."""
    try:
        sid = (req.chat_session_id or "").strip()
        if not sid:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id is required"},
                status_code=400,
            )
        if req.from_turn < 0 or req.to_turn < req.from_turn:
            return Utf8JSONResponse(
                content={"status": "error", "detail": f"invalid turn range: {req.from_turn}-{req.to_turn}"},
                status_code=400,
            )

        result = generate_episode_summary(
            chat_session_id=sid,
            from_turn=req.from_turn,
            to_turn=req.to_turn,
            force=req.force,
        )

        logger.info(
            "POST /episodes/generate (session=%s, range=%d-%d, status=%s)",
            sid, req.from_turn, req.to_turn, result.get("status"),
        )

        status_code = 200 if result.get("status") in ("generated", "skipped") else 500
        return Utf8JSONResponse(content=result, status_code=status_code)
    except Exception as exc:
        logger.error("POST /episodes/generate ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


