@app.patch("/episodes/{episode_id}")
def patch_episode(episode_id: int, req: PatchEpisodeRequest):
    """?먰뵾?뚮뱶 ?붿빟 1嫄댁쓣 ?섎룞 ?섏젙?쒕떎."""
    try:
        fields = req.model_dump(exclude_unset=True)
        if not fields:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "?섏젙???꾨뱶媛 ?놁뒿?덈떎."},
                status_code=400,
            )

        db = SessionLocal()
        try:
            row = db.query(EpisodeSummary).filter(EpisodeSummary.id == episode_id).first()
            if not row:
                return Utf8JSONResponse(
                    content={"status": "error", "detail": f"episode {episode_id} not found"},
                    status_code=404,
                )

            next_from_turn = fields.get("from_turn", row.from_turn)
            next_to_turn = fields.get("to_turn", row.to_turn)
            if next_from_turn is not None and next_to_turn is not None and next_to_turn < next_from_turn:
                return Utf8JSONResponse(
                    content={"status": "error", "detail": "invalid turn range"},
                    status_code=400,
                )

            if "summary_text" in fields and not str(fields["summary_text"] or "").strip():
                return Utf8JSONResponse(
                    content={"status": "error", "detail": "summary_text must not be empty"},
                    status_code=400,
                )

            for key, val in fields.items():
                setattr(row, key, val)

            db.commit()
            db.refresh(row)
            logger.info("PATCH /episodes/%d ??updated fields: %s", episode_id, list(fields.keys()))
            return Utf8JSONResponse(content={
                "status": "ok",
                "episode_id": row.id,
                "updated_fields": list(fields.keys()),
            })
        finally:
            db.close()
    except Exception as exc:
        logger.error("PATCH /episodes/%d ?ㅽ뙣: %s", episode_id, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


