@app.get("/storylines/{chat_session_id}")
def get_storylines(chat_session_id: str, current_turn: int | None = None):
    """?몄뀡???ㅽ넗由щ씪??紐⑸줉??諛섑솚?쒕떎."""
    try:
        sid = (chat_session_id or "").strip()
        if not sid:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id is required"},
                status_code=400,
            )
        db = SessionLocal()
        try:
            rows = (
                db.query(Storyline)
                .filter(Storyline.chat_session_id == sid)
                .order_by(Storyline.last_turn.desc().nullslast(), Storyline.id.desc())
                .all()
            )
            reference_turn = _resolve_storyline_reference_turn(rows, current_turn)
            items = []
            for r in rows:
                stale_snapshot = _build_storyline_stale_snapshot(r, reference_turn)
                items.append({
                    "id": r.id,
                    "chat_session_id": r.chat_session_id,
                    "name": r.name,
                    "status": r.status,
                    "entities_json": r.entities_json,
                    "current_context": r.current_context,
                    "key_points_json": _normalize_storyline_list_json(r.key_points_json, preserve_original_on_invalid=True),
                    "ongoing_tensions_json": _normalize_storyline_list_json(r.ongoing_tensions_json, preserve_original_on_invalid=True),
                    "confidence": r.confidence,
                    "evidence_count": r.evidence_count,
                    "last_evidence_turn": r.last_evidence_turn,
                    "last_observed_turn": stale_snapshot["last_observed_turn"],
                    "freshness_turn_gap": stale_snapshot["freshness_turn_gap"],
                    "stale_after_turns": stale_snapshot["stale_after_turns"],
                    "is_stale": stale_snapshot["is_stale"],
                    "stale_reason": stale_snapshot["stale_reason"],
                    "first_turn": r.first_turn,
                    "last_turn": r.last_turn,
                    "pinned": bool(r.pinned),
                    "suppressed": bool(r.suppressed),
                    "user_corrected": bool(r.user_corrected),
                    "created_at": r.created_at.isoformat() if r.created_at else None,
                    "updated_at": r.updated_at.isoformat() if r.updated_at else None,
                })
        finally:
            db.close()
        return Utf8JSONResponse(content={
            "status": "ok",
            "chat_session_id": sid,
            "reference_turn": reference_turn,
            "storylines": items,
            "count": len(items),
        })
    except Exception as exc:
        logger.error("GET /storylines/%s ?ㅽ뙣: %s", chat_session_id, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


