class StorylineSyncRequest(BaseModel):
    chat_session_id: str = ""
    supervisor_result: dict = Field(default_factory=dict)
    mode: str = "dry_run"  # "dry_run" | "apply"
    turn_index: int | None = None


def _parse_storylines_from_supervisor(supervisor_result: dict) -> list[dict]:
    """supervisor ?묐떟?먯꽌 storyline ?꾨낫瑜?異붿텧?쒕떎.

    supervisor JSON??`storylines` ?ㅻ? ?ы븿?섎㈃ 洹몃?濡??ъ슜?섍퀬,
    ?놁쑝硫?book_author?먯꽌 媛꾩씠 異붿텧???쒕룄?쒕떎.
    """
    candidates: list[dict] = []

    # Case 1: supervisor媛 紐낆떆??storylines 諛곗뿴??諛섑솚??寃쎌슦
    raw_list = supervisor_result.get("storylines")
    if isinstance(raw_list, list):
        for item in raw_list:
            if not isinstance(item, dict):
                continue
            name = (item.get("name") or "").strip()
            if not name:
                continue
            candidates.append({
                "name": name,
                "status": item.get("status", "active"),
                "entities_json": json.dumps(item.get("entities", []), ensure_ascii=False) if item.get("entities") else None,
                "current_context": item.get("current_context") or item.get("context") or None,
                "key_points_json": json.dumps(item.get("key_points", []), ensure_ascii=False) if item.get("key_points") else None,
                "ongoing_tensions_json": json.dumps(item.get("ongoing_tensions", []), ensure_ascii=False) if item.get("ongoing_tensions") else None,
                "confidence": item.get("confidence"),
                "evidence_count": item.get("evidence_count"),
                "last_evidence_turn": item.get("last_evidence_turn"),
            })
        return candidates

    # Case 2: book_author?먯꽌 媛꾩씠 異붿텧 (current_arc ???ㅽ넗由щ씪??1媛?
    author = supervisor_result.get("book_author")
    if isinstance(author, dict):
        arc = (author.get("current_arc") or "").strip()
        if arc:
            tensions = author.get("ongoing_tensions") or author.get("guardrails") or []
            candidates.append({
                "name": arc,
                "status": "active",
                "entities_json": None,
                "current_context": author.get("narrative_goal") or None,
                "key_points_json": json.dumps(author.get("next_beats", []), ensure_ascii=False) if author.get("next_beats") else None,
                "ongoing_tensions_json": json.dumps(tensions, ensure_ascii=False) if tensions else None,
                "confidence": None,
                "evidence_count": None,
                "last_evidence_turn": None,
            })

    return candidates


def _validate_storyline_candidate(c: dict) -> list[str]:
    """?꾨낫???꾩닔 ?꾨뱶瑜?寃利앺븯怨??ㅻ쪟 硫붿떆吏 紐⑸줉??諛섑솚."""
    errors: list[str] = []
    if not c.get("name"):
        errors.append("name is required")
    if c.get("status") and c["status"] not in ("active", "paused", "resolved"):
        errors.append(f"invalid status: {c['status']}")
    if c.get("confidence") is not None:
        try:
            conf = float(c["confidence"])
        except Exception:
            errors.append("confidence must be a number")
        else:
            if conf < 0.0 or conf > 1.0:
                errors.append("confidence must be between 0.0 and 1.0")
    for int_field in ("evidence_count", "last_evidence_turn"):
        if c.get(int_field) is not None:
            try:
                value = int(c[int_field])
            except Exception:
                errors.append(f"{int_field} must be an integer")
            else:
                if value < 0:
                    errors.append(f"{int_field} must be >= 0")
    return errors


def _coerce_storyline_non_negative_int(value: object) -> int | None:
    if value is None or value == "":
        return None
    try:
        parsed = int(value)
    except Exception:
        return None
    return parsed if parsed >= 0 else None


def _decode_storyline_text_list(value: object) -> list[str] | None:
    raw = value
    if raw is None:
        return []
    if isinstance(raw, str):
        text_value = raw.strip()
        if not text_value:
            return []
        try:
            raw = json.loads(text_value)
        except Exception:
            return None
    if not isinstance(raw, list):
        return None

    seen: set[str] = set()
    items: list[str] = []
    for item in raw:
        if item is None:
            continue
        text_value = str(item).strip()
        if not text_value:
            continue
        dedupe_key = text_value.casefold()
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        items.append(text_value)
    return items


def _normalize_storyline_list_json(value: object, preserve_original_on_invalid: bool = False) -> str | None:
    items = _decode_storyline_text_list(value)
    if items is None:
        return value if (preserve_original_on_invalid and isinstance(value, str)) else None
    return json.dumps(items, ensure_ascii=False) if items else None


def _normalize_storyline_candidate(candidate: dict) -> dict:
    normalized = dict(candidate)
    for field in ("key_points_json", "ongoing_tensions_json"):
        if field in normalized and normalized.get(field) is not None:
            normalized[field] = _normalize_storyline_list_json(
                normalized.get(field),
                preserve_original_on_invalid=True,
            )
    return normalized


def _resolve_storyline_reference_turn(rows: list[Storyline], current_turn: int | None) -> int | None:
    explicit_turn = _coerce_storyline_non_negative_int(current_turn)
    if explicit_turn is not None:
        return explicit_turn

    latest_turn: int | None = None
    for row in rows:
        for candidate_turn in (
            _coerce_storyline_non_negative_int(getattr(row, "last_evidence_turn", None)),
            _coerce_storyline_non_negative_int(getattr(row, "last_turn", None)),
        ):
            if candidate_turn is None:
                continue
            if latest_turn is None or candidate_turn > latest_turn:
                latest_turn = candidate_turn
    return latest_turn


def _build_storyline_stale_snapshot(row: Storyline, reference_turn: int | None) -> dict:
    evidence_count = _coerce_storyline_non_negative_int(getattr(row, "evidence_count", None)) or 0
    last_evidence_turn = _coerce_storyline_non_negative_int(getattr(row, "last_evidence_turn", None))
    last_turn = _coerce_storyline_non_negative_int(getattr(row, "last_turn", None))
    last_observed_turn = last_evidence_turn if last_evidence_turn is not None else last_turn
    freshness_turn_gap = None
    if reference_turn is not None and last_observed_turn is not None:
        freshness_turn_gap = max(reference_turn - last_observed_turn, 0)

    stale_after_turns = max(3, min(8, evidence_count + 2))
    if getattr(row, "status", None) != "active" or freshness_turn_gap is None:
        return {
            "last_observed_turn": last_observed_turn,
            "freshness_turn_gap": freshness_turn_gap,
            "stale_after_turns": stale_after_turns,
            "is_stale": False,
            "stale_reason": None,
        }

    is_stale = freshness_turn_gap >= stale_after_turns
    stale_reason = None
    if is_stale:
        stale_reason = "low_evidence_gap" if evidence_count <= 1 else "freshness_gap"

    return {
        "last_observed_turn": last_observed_turn,
        "freshness_turn_gap": freshness_turn_gap,
        "stale_after_turns": stale_after_turns,
        "is_stale": is_stale,
        "stale_reason": stale_reason,
    }


def _coerce_storyline_confidence(value: object) -> float | None:
    if value is None or value == "":
        return None
    try:
        confidence = float(value)
    except Exception:
        return None
    if confidence < 0.0 or confidence > 1.0:
        return None
    return confidence


def _build_storyline_selection_entry(row: Storyline, reference_turn: int | None) -> dict:
    stale_snapshot = _build_storyline_stale_snapshot(row, reference_turn)
    return {
        "row": row,
        "confidence": _coerce_storyline_confidence(getattr(row, "confidence", None)),
        "evidence_count": _coerce_storyline_non_negative_int(getattr(row, "evidence_count", None)) or 0,
        "last_observed_turn": stale_snapshot["last_observed_turn"],
        "freshness_turn_gap": stale_snapshot["freshness_turn_gap"],
        "stale_after_turns": stale_snapshot["stale_after_turns"],
        "is_stale": stale_snapshot["is_stale"],
        "stale_reason": stale_snapshot["stale_reason"],
    }


def _storyline_selection_sort_key(entry: dict) -> tuple:
    freshness_gap = entry.get("freshness_turn_gap")
    last_observed_turn = entry.get("last_observed_turn")
    confidence = entry.get("confidence")
    return (
        1 if entry.get("is_stale") else 0,
        freshness_gap if freshness_gap is not None else 10**6,
        -(confidence if confidence is not None else 0.5),
        -entry.get("evidence_count", 0),
        -(last_observed_turn if last_observed_turn is not None else -1),
        -(getattr(entry.get("row"), "last_turn", None) if getattr(entry.get("row"), "last_turn", None) is not None else -1),
        getattr(entry.get("row"), "id", 0),
    )


def _select_storylines_for_supervisor(rows: list[Storyline], current_turn: int | None = None, limit: int = 5) -> dict:
    active_rows = [row for row in rows if getattr(row, "status", None) == "active"]
    reference_turn = _resolve_storyline_reference_turn(active_rows, current_turn)
    entries = [_build_storyline_selection_entry(row, reference_turn) for row in active_rows]
    entries.sort(key=_storyline_selection_sort_key)

    fresh_entries = [entry for entry in entries if not entry.get("is_stale")]
    stale_entries = [entry for entry in entries if entry.get("is_stale")]

    if fresh_entries:
        selected = fresh_entries[:limit]
        dropped = fresh_entries[limit:] + stale_entries
    else:
        selected = stale_entries[:1]
        dropped = stale_entries[1:]

    return {
        "reference_turn": reference_turn,
        "total_active_count": len(entries),
        "selected": selected,
        "dropped": dropped,
    }


def _format_storylines_for_supervisor(selection: dict) -> str:
    lines: list[str] = []
    for entry in selection.get("selected", []):
        row = entry["row"]
        item = f"??{row.name}"
        if row.current_context:
            item += f" ??{row.current_context}"
        lines.append(item)
        key_points = _decode_storyline_text_list(row.key_points_json) or []
        for key_point in key_points[:2]:
            lines.append(f"  - {key_point}")
        tensions = _decode_storyline_text_list(row.ongoing_tensions_json) or []
        for tension in tensions[:2]:
            lines.append(f"  ??{tension}")
    return "\n".join(lines)


def _summarize_storyline_selection(selection: dict) -> dict:
    def _serialize(entry: dict) -> dict:
        row = entry["row"]
        return {
            "name": row.name,
            "confidence": entry.get("confidence"),
            "evidence_count": entry.get("evidence_count"),
            "freshness_turn_gap": entry.get("freshness_turn_gap"),
            "is_stale": entry.get("is_stale"),
            "stale_reason": entry.get("stale_reason"),
            "last_observed_turn": entry.get("last_observed_turn"),
        }

    return {
        "reference_turn": selection.get("reference_turn"),
        "total_active_count": selection.get("total_active_count", 0),
        "selected_count": len(selection.get("selected", [])),
        "dropped_count": len(selection.get("dropped", [])),
        "selected": [_serialize(entry) for entry in selection.get("selected", [])],
        "dropped": [_serialize(entry) for entry in selection.get("dropped", [])],
    }


def _resolve_character_reference_turn(db, chat_session_id: str) -> int | None:
    latest_chat_turn = (
        db.query(func.max(ChatLog.turn_index))
        .filter(ChatLog.chat_session_id == chat_session_id)
        .scalar()
    )
    try:
        if latest_chat_turn is not None:
            return int(latest_chat_turn)
    except Exception:
        pass

    latest_character_turn = (
        db.query(func.max(CharacterState.turn_index))
        .filter(CharacterState.chat_session_id == chat_session_id)
        .scalar()
    )
    try:
        if latest_character_turn is not None:
            return int(latest_character_turn)
    except Exception:
        pass
    return None


def _build_character_state_stale_snapshot(
    row: CharacterState,
    *,
    reference_turn: int | None,
    recent_mention_text: str,
    recent_mention_keywords: set[str],
    recent_events: list[CharacterEvent] | None = None,
) -> dict:
    last_observed_turn = _coerce_storyline_non_negative_int(getattr(row, "turn_index", None))
    freshness_turn_gap = None
    if reference_turn is not None and last_observed_turn is not None:
        freshness_turn_gap = max(reference_turn - last_observed_turn, 0)

    descriptor_like = looks_like_transient_descriptor_character_name(getattr(row, "character_name", None))
    event_anchor_payload = [
        {"type": str(getattr(event, "event_type", "") or "").strip()}
        for event in (recent_events or [])
        if str(getattr(event, "event_type", "") or "").strip()
    ]
    anchor_types: list[str] = []
    if has_character_continuity_anchor(appearance_json=getattr(row, "appearance_json", None)):
        anchor_types.append("appearance")
    if has_character_continuity_anchor(personality_json=getattr(row, "personality_json", None)):
        anchor_types.append("personality")
    if has_character_continuity_anchor(relationships_json=getattr(row, "relationships_json", None)):
        anchor_types.append("relationships")
    if has_character_continuity_anchor(speech_style_json=getattr(row, "speech_style_json", None)):
        anchor_types.append("speech_style")
    if event_anchor_payload and has_character_continuity_anchor(events=event_anchor_payload):
        anchor_types.append("event_anchor")
    has_anchor = bool(anchor_types)
    stale_after_turns = TM1C_RECENT_REMENTION_TURN_WINDOW + 1
    recently_rementioned = descriptor_recently_rementioned(
        getattr(row, "character_name", None),
        recent_text=recent_mention_text,
        recent_keywords=recent_mention_keywords,
    )
    recent_event_count = len(event_anchor_payload)
    admission_basis = list(anchor_types)
    if recently_rementioned:
        admission_basis.append("recent_remention")
    if recent_event_count >= 2:
        admission_basis.append("recent_event_history")
    admission_class = (
        "major_recurring"
        if (has_anchor or recently_rementioned or recent_event_count >= 2)
        else ("transient_descriptor" if descriptor_like else "lightweight_named")
    )
    is_stale = bool(
        descriptor_like
        and not has_anchor
        and freshness_turn_gap is not None
        and freshness_turn_gap >= stale_after_turns
        and not recently_rementioned
    )
    stale_reason = "transient_descriptor_not_rementioned" if is_stale else None
    stale_guard = {
        "active": bool(
            is_stale
            or (
                freshness_turn_gap is not None
                and freshness_turn_gap >= stale_after_turns
                and not has_anchor
            )
        ),
        "reason": stale_reason or (
            "low_anchor_freshness_gap"
            if freshness_turn_gap is not None and freshness_turn_gap >= stale_after_turns and not has_anchor
            else None
        ),
        "allow_weak_input_carry_forward": bool(not is_stale and (has_anchor or recently_rementioned)),
        "admission_class": admission_class,
        "admission_basis": admission_basis,
    }

    return {
        "last_observed_turn": last_observed_turn,
        "freshness_turn_gap": freshness_turn_gap,
        "stale_after_turns": stale_after_turns,
        "is_stale": is_stale,
        "stale_reason": stale_reason,
        "admission_class": admission_class,
        "admission_basis": admission_basis,
        "continuity_anchor_types": anchor_types,
        "recent_event_count": recent_event_count,
        "stale_guard": stale_guard,
    }


_CHARACTER_STABLE_SHEET_SURFACE_VERSION = "cc14a.v1"
_CHARACTER_DYNAMIC_DIGEST_SURFACE_VERSION = "cc14b.v1"
_CHARACTER_RELATIONSHIP_LANE_SURFACE_VERSION = "rl14a.v1"
_CHARACTER_LATEST_INTERACTION_SURFACE_VERSION = "rl14b.v1"
_CC14_PROTAGONIST_DISPLAY_TARGET = "{{user}}"
_CC14_PLAYER_REFERENCE_KEYS = frozenset({
    "__player__",
    "{{user}}",
    "user",
    "player",
    "participant",
    "사용자",
    "?좎?",
    "?뚮젅?댁뼱",
})


def _cc14_parse_surface_payload(raw: object):
    if raw is None:
        return None
    if isinstance(raw, (dict, list, int, float, bool)):
        return raw
    text = str(raw).strip()
    if not text:
        return None
    try:
        return json.loads(text)
    except Exception:
        return text


def _cc14_has_surface_value(value: object) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, dict, tuple, set)):
        return bool(value)
    return True


def _cc14_collect_filled_axes(payloads: dict[str, object]) -> list[str]:
    return [name for name, value in payloads.items() if _cc14_has_surface_value(value)]


def _cc14_surface_status(payloads: dict[str, object]) -> str:
    filled_axes = _cc14_collect_filled_axes(payloads)
    if not filled_axes:
        return "empty"
    if len(filled_axes) == len(payloads):
        return "ready"
    return "partial"


def _cc14_preferred_summary_text(payload: object, *, preferred_keys: tuple[str, ...], max_len: int = 180) -> str | None:
    if isinstance(payload, dict):
        parts: list[str] = []
        raw_text_keys = {"summary", "summary_text", "detail", "note", "message", "interaction"}
        for key in preferred_keys:
            text = _clean_canonical_text_r1a(payload.get(key), max_len=90)
            if not text:
                continue
            parts.append(text if key in raw_text_keys else f"{key}: {text}")
            if len(parts) >= 3:
                break
        if parts:
            return _clean_canonical_text_r1a("; ".join(parts), max_len=max_len)
    summary = _summarize_canonical_value_r1a(payload, preferred_keys=preferred_keys)
    return summary or None


def _cc14_is_player_reference(value: object) -> bool:
    text = _clean_canonical_text_r1a(value, max_len=60)
    if not text:
        return False
    return text.casefold() in _CC14_PLAYER_REFERENCE_KEYS


def _cc14_relation_display_target(value: object) -> str:
    text = _clean_canonical_text_r1a(value, max_len=60)
    if not text:
        return ""
    if _cc14_is_player_reference(text):
        return _CC14_PROTAGONIST_DISPLAY_TARGET
    return text


def _cc14_project_relation_payload(payload: object):
    if isinstance(payload, dict):
        projected: dict[str, object] = {}
        for key, value in payload.items():
            if key in {"target", "name", "character_name", "owner", "subject", "object", "from", "to"}:
                display_value = _cc14_relation_display_target(value)
                if display_value:
                    projected[key] = display_value
                    continue
            projected[key] = _cc14_project_relation_payload(value)
        return projected
    if isinstance(payload, list):
        return [_cc14_project_relation_payload(item) for item in payload]
    if isinstance(payload, str) and _cc14_is_player_reference(payload):
        return _CC14_PROTAGONIST_DISPLAY_TARGET
    return payload


def _cc15_extract_relation_descriptor_bands(payload: object) -> list[str]:
    if not isinstance(payload, dict):
        return []
    bands: list[str] = []
    for key in _CC15_RELATION_DESCRIPTOR_KEYS:
        text = _clean_canonical_text_r1a(payload.get(key), max_len=60)
        if text:
            bands.append(f"{key}: {text}")
    return bands[:3]


def _cc15_is_snapshot_appearance_key(key: object) -> bool:
    text = "".join(str(key or "").strip().lower().split())
    if not text:
        return False
    return any(token in text for token in _CC15_APPEARANCE_SNAPSHOT_KEY_TOKENS)


def _cc15_is_non_observable_appearance_key(key: object) -> bool:
    text = "".join(str(key or "").strip().lower().split())
    if not text:
        return False
    return any(token in text for token in _CC15_NON_OBSERVABLE_APPEARANCE_KEY_TOKENS)


def _cc15_split_appearance_payload(payload: object) -> tuple[object, dict]:
    if not isinstance(payload, dict):
        return payload, {}
    durable: dict = {}
    snapshot: dict = {}
    for key, value in payload.items():
        if _cc15_is_snapshot_appearance_key(key):
            snapshot[key] = value
        else:
            durable[key] = value
    return durable or payload, snapshot


def _cc15_split_observable_appearance_payload(payload: object) -> tuple[object, dict]:
    if not isinstance(payload, dict):
        return payload, {}
    observable: dict = {}
    non_observable: dict = {}
    for key, value in payload.items():
        if _cc15_is_non_observable_appearance_key(key):
            non_observable[key] = value
        else:
            observable[key] = value
    return observable, non_observable


def _cc15_compact_snapshot_dict(payload: dict) -> dict:
    compacted: dict = {}
    for key, value in payload.items():
        if value in (None, "", [], {}):
            continue
        compacted[key] = value
    return compacted


def _cc15_character_event_priority(event_type: object) -> int:
    return _CC15_MILESTONE_EVENT_PRIORITY.get(
        str(event_type or "").strip(),
        len(_CC15_MILESTONE_EVENT_PRIORITY),
    )


def _cc15_build_character_event_ledger_candidate(event: CharacterEvent, *, recency_index: int) -> dict | None:
    details = _cc14_parse_surface_payload(getattr(event, "details_json", None))
    summary_text = _cc14_preferred_summary_text(
        details,
        preferred_keys=("interaction", "detail", "summary", "summary_text", "note", "message", "status", "change"),
    )
    if not summary_text:
        summary_text = _clean_canonical_text_r1a(getattr(event, "event_type", None), max_len=80)
    if not summary_text:
        return None
    return {
        "event_type": event.event_type,
        "turn_index": event.turn_index,
        "summary_text": summary_text,
        "details": details,
        "created_at": str(event.created_at) if event.created_at else None,
        "_event_priority": _cc15_character_event_priority(getattr(event, "event_type", None)),
        "_recency_index": recency_index,
    }


def _build_character_relationship_lane(row: CharacterState) -> dict:
    preferred_keys = (
        "summary",
        "summary_text",
        "status",
        "state",
        "detail",
        "note",
        "trust",
        "closeness",
        "tension",
    )
    parsed = _cc14_parse_surface_payload(getattr(row, "relationships_json", None))
    protagonist_items: list[dict] = []
    other_items: list[dict] = []
    seen: set[tuple[str, str]] = set()
    protagonist_relation: dict | None = None

    def _append_item(target_raw: object, payload: object) -> None:
        nonlocal protagonist_relation
        target = _cc14_relation_display_target(target_raw)
        if not target:
            return
        summary_text = _cc14_preferred_summary_text(payload, preferred_keys=preferred_keys)
        if not summary_text:
            summary_text = _clean_canonical_text_r1a(payload, max_len=180)
        if not summary_text:
            return
        dedupe_key = (target.casefold(), summary_text.casefold())
        if dedupe_key in seen:
            return
        seen.add(dedupe_key)
        is_protagonist = _cc14_is_player_reference(target_raw)
        item = {
            "target": target,
            "summary_text": summary_text,
            "state_snapshot": _cc14_project_relation_payload(
                payload if isinstance(payload, (dict, list)) else {"value": payload}
            ),
            "descriptor_bands": _cc15_extract_relation_descriptor_bands(payload),
            "display_priority": 0 if is_protagonist else 1,
        }
        if is_protagonist:
            protagonist_items.append(item)
            if protagonist_relation is None:
                protagonist_relation = item
            return
        other_items.append(item)

    if isinstance(parsed, dict):
        for key, value in parsed.items():
            target = key
            if isinstance(value, dict):
                target = value.get("target") or value.get("name") or value.get("character_name") or key
            _append_item(target, value)
    elif isinstance(parsed, list):
        for value in parsed[:6]:
            if not isinstance(value, dict):
                continue
            _append_item(
                value.get("target") or value.get("name") or value.get("character_name") or value.get("title") or value.get("scope_name"),
                value,
            )

    ordered_items = (protagonist_items + other_items)[:6]
    preferred_item = protagonist_relation or (ordered_items[0] if ordered_items else None)
    secondary_items = [item for item in ordered_items if item is not preferred_item]
    summary_text = (preferred_item or {}).get("summary_text") or _cc14_preferred_summary_text(parsed, preferred_keys=preferred_keys)
    lane_status = "ready" if ordered_items else ("summary_only" if summary_text else "empty")
    return {
        "surface_version": _CHARACTER_RELATIONSHIP_LANE_SURFACE_VERSION,
        "surface_type": "relationship_lane",
        "status": lane_status,
        "display_mode": "protagonist_first_then_observed_order",
        "count": len(protagonist_items) + len(other_items),
        "summary_text": summary_text,
        "descriptor_summary": "; ".join((preferred_item or {}).get("descriptor_bands") or [])[:180],
        "primary_target": (preferred_item or {}).get("target"),
        "primary_descriptor_bands": (preferred_item or {}).get("descriptor_bands") or [],
        "protagonist_relation": protagonist_relation,
        "other_relations": secondary_items[:5],
        "items": ordered_items,
    }


def _build_character_latest_interaction_anchor(latest_event: CharacterEvent | None) -> dict | None:
    if latest_event is None:
        return None
    details = _cc14_parse_surface_payload(getattr(latest_event, "details_json", None))
    summary_text = _cc14_preferred_summary_text(
        details,
        preferred_keys=("interaction", "detail", "summary", "summary_text", "note", "message", "status", "change"),
    )
    if not summary_text:
        summary_text = _clean_canonical_text_r1a(getattr(latest_event, "event_type", None), max_len=80)
    return {
        "surface_version": _CHARACTER_LATEST_INTERACTION_SURFACE_VERSION,
        "surface_type": "latest_interaction_anchor",
        "status": "ready",
        "event_type": latest_event.event_type,
        "turn_index": latest_event.turn_index,
        "summary_text": summary_text,
        "details": details,
        "created_at": str(latest_event.created_at) if latest_event.created_at else None,
    }


def _build_stable_character_sheet(row: CharacterState, snapshot: dict) -> dict:
    appearance = _cc14_parse_surface_payload(getattr(row, "appearance_json", None))
    personality = _cc14_parse_surface_payload(getattr(row, "personality_json", None))
    speech_style = _cc14_parse_surface_payload(getattr(row, "speech_style_json", None))
    appearance_core, appearance_snapshot = _cc15_split_appearance_payload(appearance)
    appearance_observable, appearance_non_observable = _cc15_split_observable_appearance_payload(appearance_core)
    axes = {
        "appearance": appearance_core,
        "personality": personality,
        "speech_style": speech_style,
    }
    filled_axes = _cc14_collect_filled_axes(axes)
    return {
        "surface_version": _CHARACTER_STABLE_SHEET_SURFACE_VERSION,
        "surface_type": "stable_character_sheet",
        "status": _cc14_surface_status(axes),
        "filled_axes": filled_axes,
        "appearance": appearance,
        "appearance_core": appearance_core,
        "appearance_observable": appearance_observable,
        "appearance_non_observable": appearance_non_observable,
        "appearance_snapshot_keys": sorted(appearance_snapshot.keys()),
        "personality": personality,
        "speech_style": speech_style,
        "durable_profile": {
            "appearance": appearance_observable,
            "personality": personality,
            "speech_style": speech_style,
        },
        "sparse_policy": {
            "mode": "omit_unknown_fields",
            "filled_axes": filled_axes,
            "empty_axes": [axis for axis in axes.keys() if axis not in filled_axes],
            "dynamic_redirects": [
                "current_status",
                "relationship_lane",
                "latest_interaction_anchor",
                "appearance_snapshot",
            ],
        },
        "source_turn": snapshot.get("last_observed_turn") if isinstance(snapshot, dict) else None,
    }


def _build_character_milestone_ledger(recent_events: list[CharacterEvent] | None) -> list[dict]:
    candidates: list[dict] = []
    for recency_index, event in enumerate(recent_events or []):
        candidate = _cc15_build_character_event_ledger_candidate(event, recency_index=recency_index)
        if candidate:
            candidates.append(candidate)
    if not candidates:
        return []

    selected: list[dict] = []
    seen: set[tuple[object, object, str]] = set()

    def _append_candidate(candidate: dict) -> None:
        dedupe_key = (
            candidate.get("event_type"),
            candidate.get("turn_index"),
            str(candidate.get("summary_text") or ""),
        )
        if dedupe_key in seen:
            return
        seen.add(dedupe_key)
        selected.append(candidate)

    _append_candidate(candidates[0])
    for candidate in sorted(
        candidates[1:],
        key=lambda item: (item.get("_event_priority", len(_CC15_MILESTONE_EVENT_PRIORITY)), item.get("_recency_index", 0)),
    ):
        if len(selected) >= _CC15_MILESTONE_LEDGER_CAP:
            break
        _append_candidate(candidate)

    if len(selected) < _CC15_MILESTONE_LEDGER_CAP:
        for candidate in candidates[1:]:
            if len(selected) >= _CC15_MILESTONE_LEDGER_CAP:
                break
            _append_candidate(candidate)

    selected.sort(key=lambda item: item.get("_recency_index", 0))
    return [
        {
            key: value
            for key, value in candidate.items()
            if not str(key).startswith("_")
        }
        for candidate in selected[:_CC15_MILESTONE_LEDGER_CAP]
    ]


def _build_dynamic_character_digest(
    row: CharacterState,
    snapshot: dict,
    *,
    relationship_lane: dict,
    latest_interaction_anchor: dict | None,
    recent_events: list[CharacterEvent] | None = None,
) -> dict:
    current_status = _cc14_parse_surface_payload(getattr(row, "status_json", None))
    appearance = _cc14_parse_surface_payload(getattr(row, "appearance_json", None))
    _appearance_core, appearance_snapshot = _cc15_split_appearance_payload(appearance)
    current_status_summary = _cc14_preferred_summary_text(
        current_status,
        preferred_keys=("location", "emotion", "goal", "status", "state", "condition", "mood"),
    )
    preferred_relationship = relationship_lane.get("protagonist_relation") or ((relationship_lane.get("items") or [None])[0])
    relationship_surface = preferred_relationship or relationship_lane.get("items") or relationship_lane.get("summary_text")
    priority_capped_relationships = (relationship_lane.get("items") or [])[:_CC15_DIGEST_RELATIONSHIP_CAP]
    relationship_descriptor_lane = [
        {
            "target": item.get("target"),
            "summary_text": item.get("summary_text"),
            "descriptor_bands": item.get("descriptor_bands") or [],
        }
        for item in priority_capped_relationships
    ]
    current_snapshot = _cc15_compact_snapshot_dict({
        "status": current_status,
        "appearance": appearance_snapshot,
        "relationship_focus": _cc15_compact_snapshot_dict({
            "target": (preferred_relationship or {}).get("target") if isinstance(preferred_relationship, dict) else None,
            "summary_text": (preferred_relationship or {}).get("summary_text") if isinstance(preferred_relationship, dict) else None,
            "descriptor_bands": (preferred_relationship or {}).get("descriptor_bands") if isinstance(preferred_relationship, dict) else None,
        }),
    })
    milestone_ledger = _build_character_milestone_ledger(recent_events)
    axes = {
        "current_status": current_status,
        "relationship_surface": relationship_surface,
        "latest_interaction_anchor": latest_interaction_anchor,
    }
    return {
        "surface_version": _CHARACTER_DYNAMIC_DIGEST_SURFACE_VERSION,
        "surface_type": "dynamic_continuity_digest",
        "status": _cc14_surface_status(axes),
        "filled_axes": _cc14_collect_filled_axes(axes),
        "admission_class": snapshot.get("admission_class") if isinstance(snapshot, dict) else None,
        "admission_basis": snapshot.get("admission_basis") if isinstance(snapshot, dict) else [],
        "stale_guard": snapshot.get("stale_guard") if isinstance(snapshot, dict) else None,
        "current_status": current_status,
        "current_status_summary": current_status_summary,
        "current_snapshot": current_snapshot,
        "appearance_snapshot": appearance_snapshot,
        "relationship_summary_text": relationship_lane.get("summary_text"),
        "relationship_primary_target": relationship_lane.get("primary_target"),
        "relationship_display_mode": relationship_lane.get("display_mode"),
        "protagonist_relation": relationship_lane.get("protagonist_relation"),
        "relationship_lane": relationship_lane.get("items") or [],
        "other_relations": relationship_lane.get("other_relations") or [],
        "relationship_descriptor_lane": relationship_descriptor_lane,
        "latest_interaction_anchor": latest_interaction_anchor,
        "milestone_ledger": milestone_ledger,
        "digest_budget": {
            "policy": "priority_capped",
            "relationship_lane_cap": _CC15_DIGEST_RELATIONSHIP_CAP,
            "milestone_cap": _CC15_MILESTONE_LEDGER_CAP,
            "milestone_read_window": _CC15_MILESTONE_READ_WINDOW,
            "milestone_selection_policy": "latest_plus_priority_events",
            "relationship_lane_used": len(relationship_descriptor_lane),
            "milestones_used": len(milestone_ledger),
        },
        "recent_change_summary": (latest_interaction_anchor or {}).get("summary_text") if isinstance(latest_interaction_anchor, dict) else None,
        "source_turn": snapshot.get("last_observed_turn") if isinstance(snapshot, dict) else None,
    }


def _select_latest_character_event(db, chat_session_id: str, character_name: str) -> CharacterEvent | None:
    sid = (chat_session_id or "").strip()
    cname = (character_name or "").strip()
    if not sid or not cname:
        return None
    return (
        db.query(CharacterEvent)
        .filter(CharacterEvent.chat_session_id == sid, CharacterEvent.character_name == cname)
        .order_by(CharacterEvent.turn_index.desc().nullslast(), CharacterEvent.created_at.desc(), CharacterEvent.id.desc())
        .first()
    )


def _select_recent_character_events(db, chat_session_id: str, character_name: str, *, limit: int = _CC15_MILESTONE_READ_WINDOW) -> list[CharacterEvent]:
    sid = (chat_session_id or "").strip()
    cname = (character_name or "").strip()
    if not sid or not cname:
        return []
    return (
        db.query(CharacterEvent)
        .filter(CharacterEvent.chat_session_id == sid, CharacterEvent.character_name == cname)
        .order_by(CharacterEvent.turn_index.desc().nullslast(), CharacterEvent.created_at.desc(), CharacterEvent.id.desc())
        .limit(max(1, int(limit or _CC15_MILESTONE_LEDGER_CAP)))
        .all()
    )


def _serialize_character_state_row(
    row: CharacterState,
    snapshot: dict,
    latest_event: CharacterEvent | None = None,
    recent_events: list[CharacterEvent] | None = None,
) -> dict:
    relationship_lane = _build_character_relationship_lane(row)
    latest_interaction_anchor = _build_character_latest_interaction_anchor(latest_event)
    stable_character_sheet = _build_stable_character_sheet(row, snapshot)
    dynamic_continuity_digest = _build_dynamic_character_digest(
        row,
        snapshot,
        relationship_lane=relationship_lane,
        latest_interaction_anchor=latest_interaction_anchor,
        recent_events=recent_events,
    )
    return {
        "id": row.id,
        "chat_session_id": row.chat_session_id,
        "character_name": row.character_name,
        "appearance_json": row.appearance_json,
        "personality_json": row.personality_json,
        "status_json": row.status_json,
        "relationships_json": row.relationships_json,
        "speech_style_json": row.speech_style_json,
        "turn_index": row.turn_index,
        "last_observed_turn": snapshot["last_observed_turn"],
        "freshness_turn_gap": snapshot["freshness_turn_gap"],
        "stale_after_turns": snapshot["stale_after_turns"],
        "is_stale": snapshot["is_stale"],
        "stale_reason": snapshot["stale_reason"],
        "admission_class": snapshot.get("admission_class"),
        "admission_basis": snapshot.get("admission_basis") or [],
        "continuity_anchor_types": snapshot.get("continuity_anchor_types") or [],
        "recent_event_count": snapshot.get("recent_event_count"),
        "stale_guard": snapshot.get("stale_guard") or {},
        "stable_character_sheet": stable_character_sheet,
        "dynamic_continuity_digest": dynamic_continuity_digest,
        "relationship_lane": relationship_lane,
        "latest_interaction_anchor": latest_interaction_anchor,
        "created_at": str(row.created_at) if row.created_at else None,
        "updated_at": str(row.updated_at) if row.updated_at else None,
    }


def _select_visible_character_states(db, chat_session_id: str) -> dict:
    from sqlalchemy import distinct as sa_distinct

    reference_turn = _resolve_character_reference_turn(db, chat_session_id)
    if reference_turn is not None:
        recent_mention_text, recent_mention_keywords = _tm1c_collect_recent_mention_keywords(
            db,
            chat_session_id=chat_session_id,
            current_turn=reference_turn,
        )
    else:
        recent_mention_text, recent_mention_keywords = "", set()

    names = [
        row[0]
        for row in db.query(sa_distinct(CharacterState.character_name))
        .filter(CharacterState.chat_session_id == chat_session_id)
        .all()
    ]
    selected: list[dict] = []
    dropped: list[dict] = []

    for name in sorted(names):
        latest = (
            db.query(CharacterState)
            .filter(CharacterState.chat_session_id == chat_session_id, CharacterState.character_name == name)
            .order_by(CharacterState.updated_at.desc())
            .first()
        )
        if not latest:
            continue
        recent_events = _select_recent_character_events(db, chat_session_id, name)
        snapshot = _build_character_state_stale_snapshot(
            latest,
            reference_turn=reference_turn,
            recent_mention_text=recent_mention_text,
            recent_mention_keywords=recent_mention_keywords,
            recent_events=recent_events[:_CC15_MILESTONE_LEDGER_CAP],
        )
        entry = {"row": latest, "snapshot": snapshot}
        if snapshot["is_stale"]:
            dropped.append(entry)
            continue
        entry["latest_event"] = recent_events[0] if recent_events else _select_latest_character_event(db, chat_session_id, name)
        entry["recent_events"] = recent_events
        selected.append(entry)

    return {
        "reference_turn": reference_turn,
        "selected": selected,
        "dropped": dropped,
    }


def _has_storyline_evidence_payload(candidate: dict) -> bool:
    return any(
        candidate.get(field)
        for field in ("current_context", "key_points_json", "ongoing_tensions_json", "entities_json")
    )


def _resolve_storyline_evidence_update(existing: Storyline | None, candidate: dict, turn_index: int | None) -> tuple[int | None, int | None]:
    """H-2b: sync apply ??evidence_count / last_evidence_turn ?꾩쟻 洹쒖튃.

    - explicit evidence_count媛 ?ㅻ㈃ ?대떦 媛믪쓣 ?대쾲 愿痢?increment濡??ъ슜?쒕떎.
    - explicit 媛믪씠 ?놁쑝硫??섎? ?덈뒗 storyline payload媛 愿痢〓맂 ?댁쓣 evidence 1?뚮줈 蹂몃떎.
    - 媛숈? turn?먯꽌 媛숈? storyline??以묐났 sync?섎㈃ evidence瑜??ㅼ떆 ?꾩쟻?섏? ?딅뒗??
    """
    explicit_increment = _coerce_storyline_non_negative_int(candidate.get("evidence_count"))
    explicit_turn = _coerce_storyline_non_negative_int(candidate.get("last_evidence_turn"))
    current_count = _coerce_storyline_non_negative_int(getattr(existing, "evidence_count", None)) or 0
    current_last_turn = _coerce_storyline_non_negative_int(getattr(existing, "last_evidence_turn", None))

    has_payload = _has_storyline_evidence_payload(candidate)
    increment = explicit_increment
    if increment is None:
        increment = 1 if (has_payload or explicit_turn is not None) else 0

    observed_turn = explicit_turn
    if observed_turn is None and increment > 0:
        observed_turn = turn_index

    if observed_turn is not None and current_last_turn == observed_turn:
        return current_count or None, current_last_turn

    if increment <= 0:
        return (current_count or None), current_last_turn

    new_count = current_count + increment
    return new_count, observed_turn


def _upsert_storylines(db, session_id: str, candidates: list[dict], turn_index: int | None):
    """storylines ?뚯씠釉붿뿉 UPSERT. name + session_id 湲곗??쇰줈 留ㅼ묶."""
    results: list[dict] = []
    for c in candidates:
        name = c["name"]
        existing = (
            db.query(Storyline)
            .filter(Storyline.chat_session_id == session_id, Storyline.name == name)
            .first()
        )
        if existing:
            new_evidence_count, new_last_evidence_turn = _resolve_storyline_evidence_update(existing, c, turn_index)
            # update
            for key in (
                "status",
                "entities_json",
                "current_context",
                "key_points_json",
                "ongoing_tensions_json",
                "confidence",
            ):
                val = c.get(key)
                if val is not None:
                    setattr(existing, key, val)
            existing.evidence_count = new_evidence_count
            existing.last_evidence_turn = new_last_evidence_turn
            if turn_index is not None:
                existing.last_turn = turn_index
            db.commit()
            db.refresh(existing)
            results.append({
                "action": "updated",
                "id": existing.id,
                "name": name,
                "evidence_count": existing.evidence_count,
                "last_evidence_turn": existing.last_evidence_turn,
            })
        else:
            # insert
            new_evidence_count, new_last_evidence_turn = _resolve_storyline_evidence_update(None, c, turn_index)
            new_row = Storyline(
                chat_session_id=session_id,
                name=name,
                status=c.get("status", "active"),
                entities_json=c.get("entities_json"),
                current_context=c.get("current_context"),
                key_points_json=c.get("key_points_json"),
                ongoing_tensions_json=c.get("ongoing_tensions_json"),
                confidence=c.get("confidence"),
                evidence_count=new_evidence_count,
                last_evidence_turn=new_last_evidence_turn,
                first_turn=turn_index,
                last_turn=turn_index,
            )
            db.add(new_row)
            db.commit()
            db.refresh(new_row)
            results.append({
                "action": "created",
                "id": new_row.id,
                "name": name,
                "evidence_count": new_row.evidence_count,
                "last_evidence_turn": new_row.last_evidence_turn,
            })
    return results


@app.post("/storylines/sync")
def sync_storylines(req: StorylineSyncRequest):
    """supervisor ?묐떟?먯꽌 storyline???뚯떛?섏뿬 寃利앺븯嫄곕굹 DB???곸슜?쒕떎."""
    try:
        sid = (req.chat_session_id or "").strip()
        if not sid:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id is required"},
                status_code=400,
            )
        mode = req.mode if req.mode in ("dry_run", "apply") else "dry_run"

        candidates = _parse_storylines_from_supervisor(req.supervisor_result)
        # 媛??꾨낫 寃利?
        validated: list[dict] = []
        validation_errors: list[dict] = []
        for c in candidates:
            normalized_candidate = _normalize_storyline_candidate(c)
            errs = _validate_storyline_candidate(normalized_candidate)
            if errs:
                validation_errors.append({"name": normalized_candidate.get("name"), "errors": errs})
            else:
                validated.append(normalized_candidate)

        if mode == "dry_run":
            return {
                "status": "ok",
                "mode": "dry_run",
                "parsed_count": len(candidates),
                "valid_count": len(validated),
                "candidates": validated,
                "validation_errors": validation_errors,
            }

        # mode == "apply"
        if not validated:
            return {
                "status": "ok",
                "mode": "apply",
                "parsed_count": len(candidates),
                "applied_count": 0,
                "results": [],
                "validation_errors": validation_errors,
            }

        db = SessionLocal()
        try:
            results = _upsert_storylines(db, sid, validated, req.turn_index)
        finally:
            db.close()

        logger.info(
            "POST /storylines/sync (session=%s, mode=%s, applied=%d)",
            sid, mode, len(results),
        )
        return {
            "status": "ok",
            "mode": "apply",
            "parsed_count": len(candidates),
            "applied_count": len(results),
            "results": results,
            "validation_errors": validation_errors,
        }
    except Exception as exc:
        logger.error("POST /storylines/sync ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


