@app.get("/characters/{chat_session_id}/{character_name}/events")
def get_character_events(chat_session_id: str, character_name: str, limit: int = 30, offset: int = 0):
    """罹먮┃???대깽???대젰 議고쉶."""
    try:
        sid = (chat_session_id or "").strip()
        cname = (character_name or "").strip()
        if not sid or not cname:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id and character_name are required"},
                status_code=400,
            )
        db = SessionLocal()
        try:
            q = (
                db.query(CharacterEvent)
                .filter(CharacterEvent.chat_session_id == sid, CharacterEvent.character_name == cname)
                .order_by(CharacterEvent.created_at.desc())
            )
            total = q.count()
            clamped_limit = max(1, min(limit, 100))
            clamped_offset = max(0, offset)
            rows = q.offset(clamped_offset).limit(clamped_limit).all()
            events = []
            for r in rows:
                events.append({
                    "id": r.id,
                    "chat_session_id": r.chat_session_id,
                    "character_name": r.character_name,
                    "turn_index": r.turn_index,
                    "event_type": r.event_type,
                    "details_json": r.details_json,
                    "created_at": str(r.created_at) if r.created_at else None,
                })
            return Utf8JSONResponse(content={
                "status": "ok",
                "chat_session_id": sid,
                "character_name": cname,
                "events": events,
                "total": total,
                "limit": clamped_limit,
                "offset": clamped_offset,
            })
        finally:
            db.close()
    except Exception as exc:
        logger.error("GET /characters/%s/%s/events ?ㅽ뙣: %s", chat_session_id, character_name, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


