@app.get("/world-rules/{chat_session_id}/inherited")
def get_inherited_world_rules(
    chat_session_id: str,
    active_scope: str | None = None,
    scope_name: str | None = None,
):
    """I-4b: scope inheritance ??active_scope 湲곗??쇰줈 ancestor scope rules瑜??④퍡 諛섑솚?쒕떎.

    - active_scope ?뚮씪誘명꽣 ?앸왂 ???몄뀡????λ맂 active scope瑜??ъ슜?쒕떎 (I-4c).
    - active_scope=location&scope_name=Ancient+Temple
      ??location(Ancient Temple) + region(?꾩껜) + root ?꾩껜 諛섑솚
    - 諛섑솚 援ъ“: { "rules": [...], "scope_chain": [...], "count": N }
    """
    try:
        sid = (chat_session_id or "").strip()
        if not sid:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id is required"},
                status_code=400,
            )

        # I-4c: active_scope ?뚮씪誘명꽣 ?놁쑝硫???λ맂 媛??ъ슜
        resolved_scope = active_scope
        resolved_scope_name = scope_name
        if resolved_scope is None:
            db_peek = SessionLocal()
            try:
                saved = (
                    db_peek.query(SessionActiveScopeCache)
                    .filter(SessionActiveScopeCache.chat_session_id == sid)
                    .first()
                )
                if saved:
                    resolved_scope = saved.active_scope
                    if resolved_scope_name is None:
                        resolved_scope_name = saved.scope_name
                else:
                    resolved_scope = "root"
            finally:
                db_peek.close()

        if resolved_scope not in WORLD_RULE_VALID_SCOPES:
            return Utf8JSONResponse(
                content={"status": "error", "detail": f"active_scope must be one of {list(WORLD_RULE_VALID_SCOPES)}"},
                status_code=422,
            )

        scope_chain = _get_ancestor_scopes(resolved_scope)

        db = SessionLocal()
        try:
            rules: list[dict] = []
            for sc in scope_chain:
                q = (
                    db.query(WorldRule)
                    .filter(
                        WorldRule.chat_session_id == sid,
                        WorldRule.scope == sc,
                        WorldRule.suppressed == False,  # noqa: E712
                    )
                )
                # active_scope ?덉씠?댁뿉留?scope_name ?꾪꽣 ?곸슜
                if sc == resolved_scope:
                    if resolved_scope_name:
                        q = q.filter(WorldRule.scope_name == resolved_scope_name)
                    else:
                        q = q.filter(WorldRule.scope_name.is_(None))
                q = q.order_by(WorldRule.pinned.desc(), WorldRule.category, WorldRule.key)
                rows = q.all()
                for r in rows:
                    rules.append({
                        "id": r.id,
                        "scope": r.scope,
                        "scope_name": r.scope_name,
                        "inherited": sc != resolved_scope,   # active_scope ?몃뒗 ?곸냽
                        "category": r.category,
                        "key": r.key,
                        "value_json": r.value_json,
                        "genre": r.genre,
                        "source_turn": r.source_turn,
                        "pinned": bool(r.pinned),
                        "suppressed": bool(r.suppressed),
                        "user_corrected": bool(r.user_corrected),
                    })
        finally:
            db.close()

        return {
            "status": "ok",
            "active_scope": resolved_scope,
            "scope_name": resolved_scope_name,
            "scope_chain": scope_chain,
            "rules": rules,
            "count": len(rules),
        }
    except Exception as exc:
        logger.error("GET /world-rules/%s/inherited ?ㅽ뙣: %s", chat_session_id, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


@app.post("/world-rules/sync")
def sync_world_rules(req: WorldRuleSyncRequest):
    """supervisor ?묐떟?먯꽌 world rules瑜??뚯떛?섏뿬 寃利앺븯嫄곕굹 DB???곸슜?쒕떎."""
    try:
        sid = (req.chat_session_id or "").strip()
        if not sid:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id is required"},
                status_code=400,
            )
        mode = req.mode if req.mode in ("dry_run", "apply") else "dry_run"
        turn_index = req.turn_index

        candidates = _parse_world_rules_from_supervisor(req.supervisor_response)

        validated: list[dict] = []
        validation_errors: list[dict] = []
        for c in candidates:
            errs = _validate_world_rule_candidate(c)
            if errs:
                validation_errors.append({"key": c.get("key"), "errors": errs})
            else:
                validated.append(c)

        if mode == "dry_run":
            return {
                "status": "ok",
                "mode": "dry_run",
                "parsed_count": len(candidates),
                "valid_count": len(validated),
                "candidates": validated,
                "validation_errors": validation_errors,
            }

        # mode == "apply"
        if not validated:
            return {
                "status": "ok",
                "mode": "apply",
                "parsed_count": len(candidates),
                "applied_count": 0,
                "results": [],
                "validation_errors": validation_errors,
            }

        db = SessionLocal()
        try:
            results = []
            for c in validated:
                key = c["key"]
                scope = c.get("scope", "root")
                scope_name = c.get("scope_name") or None  # I-4a
                # I-4a: scope_name??NULL?????덉쑝誘濡?IS NULL / = 遺꾧린
                q = (
                    db.query(WorldRule)
                    .filter(
                        WorldRule.chat_session_id == sid,
                        WorldRule.scope == scope,
                        WorldRule.key == key,
                    )
                )
                if scope_name is None:
                    q = q.filter(WorldRule.scope_name.is_(None))
                else:
                    q = q.filter(WorldRule.scope_name == scope_name)
                existing = q.first()
                if existing:
                    if c.get("value_json"):
                        existing.value_json = c["value_json"]
                    if c.get("category"):
                        existing.category = c["category"]
                    if c.get("genre"):
                        existing.genre = c["genre"]
                    if scope_name is not None:
                        existing.scope_name = scope_name
                    existing.source_turn = turn_index
                    db.commit()
                    results.append({"action": "updated", "id": existing.id, "key": key})
                else:
                    new_row = WorldRule(
                        chat_session_id=sid,
                        scope=scope,
                        scope_name=scope_name,   # I-4a
                        category=c.get("category", "custom"),
                        key=key,
                        value_json=c.get("value_json"),
                        genre=c.get("genre"),
                        source_turn=turn_index,
                    )
                    db.add(new_row)
                    db.commit()
                    db.refresh(new_row)
                    results.append({"action": "created", "id": new_row.id, "key": key})
        finally:
            db.close()

        logger.info(
            "POST /world-rules/sync (session=%s, mode=%s, applied=%d)",
            sid, mode, len(results),
        )
        return {
            "status": "ok",
            "mode": "apply",
            "parsed_count": len(candidates),
            "applied_count": len(results),
            "results": results,
            "validation_errors": validation_errors,
        }
    except Exception as exc:
        logger.error("POST /world-rules/sync ?ㅽ뙣: %s", exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


