@app.delete("/pending-threads/{hook_id}")
def delete_continuity_hook(hook_id: int):
    """continuity hook 1嫄댁쓣 ??젣?쒕떎."""
    try:
        db = SessionLocal()
        try:
            row = db.query(PendingThread).filter(PendingThread.id == hook_id).first()
            if not row:
                return Utf8JSONResponse(
                    content={"status": "error", "detail": f"hook {hook_id} not found"},
                    status_code=404,
                )

            sid = row.chat_session_id
            db.delete(row)
            db.commit()

            try:
                append_audit_log(
                    event_type="hook_delete",
                    chat_session_id=sid,
                    target_type="pending_thread",
                    target_id=hook_id,
                    summary=f"deleted continuity hook {hook_id}",
                    source="manual_ui",
                )
            except Exception:
                pass

            logger.info("DELETE /pending-threads/%d (session=%s)", hook_id, sid)
            return Utf8JSONResponse(content={
                "status": "ok",
                "deleted_id": hook_id,
                "chat_session_id": sid,
            })
        finally:
            db.close()
    except Exception as exc:
        logger.error("DELETE /pending-threads/%d ?ㅽ뙣: %s", hook_id, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


