@app.get("/session-state/{chat_session_id}")
def get_session_state(chat_session_id: str):
    """?몄뀡???듭떖 ?곹깭 ?뱀뀡???⑥씪 ?묐떟?쇰줈 臾띠뼱 諛섑솚?쒕떎.

    Step 9 P-1d: chapter_summaries??read-only snapshot surface濡??④퍡 ?몄텧?섎릺,
    snapshot_status 怨꾩궛? 湲곗〈 core 5媛?state section?먮쭔 ?섏〈?쒕떎.
    """
    try:
        from datetime import datetime, timezone
        generated_at = datetime.now(timezone.utc).isoformat()
        sid = (chat_session_id or "").strip()
        if not sid:
            return Utf8JSONResponse(
                content={"status": "error", "detail": "chat_session_id is required"},
                status_code=400,
            )

        db = SessionLocal()
        try:
            # ?? 1. active_states ??????????????????????????????????????????????
            raw_states = get_all_active_states_for_session(chat_session_id=sid)
            # get_all_active_states_for_session??dict list瑜?諛섑솚
            as_last_turn = max((s.get("last_turn") or s.get("turn_index") or 0 for s in raw_states), default=None) if raw_states else None
            as_updated = max((s.get("updated_at") or "" for s in raw_states), default=None) if raw_states else None

            # HS-1a: active_states? 蹂묓뻾?섎뒗 canonical state layer
            canonical_layers = get_all_canonical_state_layers_for_session(chat_session_id=sid)
            canonical_last_turn = max((s.get("turn_index") or 0 for s in canonical_layers), default=None) if canonical_layers else None
            canonical_updated = max((s.get("created_at") or "" for s in canonical_layers), default=None) if canonical_layers else None

            # ?? 2. storylines ?????????????????????????????????????????????????
            # I-3d: suppressed row??session-state injection?먯꽌 ?쒖쇅, pinned ?곗꽑
            sl_rows = (
                db.query(Storyline)
                .filter(
                    Storyline.chat_session_id == sid,
                    Storyline.suppressed == False,  # noqa: E712
                )
                .order_by(
                    Storyline.pinned.desc(),
                    Storyline.last_turn.desc().nullslast(),
                    Storyline.id.desc(),
                )
                .all()
            )
            sl_ref_turn = _resolve_storyline_reference_turn(sl_rows, None)
            storylines_data = []
            for r in sl_rows:
                snap = _build_storyline_stale_snapshot(r, sl_ref_turn)
                storylines_data.append({
                    "id": r.id,
                    "chat_session_id": r.chat_session_id,
                    "name": r.name,
                    "status": r.status,
                    "entities_json": r.entities_json,
                    "current_context": r.current_context,
                    "key_points_json": _normalize_storyline_list_json(r.key_points_json, preserve_original_on_invalid=True),
                    "ongoing_tensions_json": _normalize_storyline_list_json(r.ongoing_tensions_json, preserve_original_on_invalid=True),
                    "confidence": r.confidence,
                    "evidence_count": r.evidence_count,
                    "last_evidence_turn": r.last_evidence_turn,
                    "last_observed_turn": snap["last_observed_turn"],
                    "freshness_turn_gap": snap["freshness_turn_gap"],
                    "is_stale": snap["is_stale"],
                    "first_turn": r.first_turn,
                    "last_turn": r.last_turn,
                    "created_at": r.created_at.isoformat() if r.created_at else None,
                    "updated_at": r.updated_at.isoformat() if r.updated_at else None,
                })
            sl_last_turn = max((r.last_turn or 0 for r in sl_rows), default=None) if sl_rows else None
            sl_updated = max((r.updated_at.isoformat() if r.updated_at else "" for r in sl_rows), default=None) if sl_rows else None

            # ?? 3. characters ?????????????????????????????????????????????????
            character_selection = _select_visible_character_states(db, sid)
            characters_data = []
            ch_updated_candidates = []
            ch_turn_candidates = []
            for entry in character_selection["selected"]:
                latest = entry["row"]
                snapshot = entry["snapshot"]
                characters_data.append(
                    _serialize_character_state_row(
                        latest,
                        snapshot,
                        entry.get("latest_event"),
                        entry.get("recent_events"),
                    )
                )
                if latest.turn_index is not None:
                    ch_turn_candidates.append(latest.turn_index)
                if latest.updated_at:
                    ch_updated_candidates.append(latest.updated_at.isoformat())
            ch_last_turn = max(ch_turn_candidates) if ch_turn_candidates else None
            ch_updated = max(ch_updated_candidates) if ch_updated_candidates else None

            # ?? 4. world_rules ????????????????????????????????????????????????
            # I-3d: suppressed ?쒖쇅, pinned ?곗꽑
            wr_rows = (
                db.query(WorldRule)
                .filter(
                    WorldRule.chat_session_id == sid,
                    WorldRule.suppressed == False,  # noqa: E712
                )
                .order_by(
                    WorldRule.pinned.desc(),
                    WorldRule.scope,
                    WorldRule.category,
                    WorldRule.key,
                )
                .all()
            )
            world_rules_data = [
                {
                    "id": r.id,
                    "chat_session_id": r.chat_session_id,
                    "scope": r.scope,
                    "scope_name": r.scope_name,          # I-4a
                    "category": r.category,
                    "key": r.key,
                    "value_json": r.value_json,
                    "genre": r.genre,
                    "source_turn": r.source_turn,
                    "created_at": str(r.created_at) if r.created_at else None,
                    "updated_at": str(r.updated_at) if r.updated_at else None,
                }
                for r in wr_rows
            ]
            wr_last_turn = max((r.source_turn or 0 for r in wr_rows), default=None) if wr_rows else None
            wr_updated = max((str(r.updated_at) if r.updated_at else "" for r in wr_rows), default=None) if wr_rows else None

            # ?? 5. pending_threads (open + paused) ???????????????????????????
            # I-3d: suppressed ?쒖쇅, pinned ?곗꽑
            hook_rows = (
                db.query(PendingThread)
                .filter(
                    PendingThread.chat_session_id == sid,
                    PendingThread.status.in_(["open", "paused"]),
                    PendingThread.suppressed == False,  # noqa: E712
                )
                .order_by(
                    PendingThread.pinned.desc(),
                    PendingThread.last_seen_turn.desc(),
                    PendingThread.id.desc(),
                )
                .all()
            )
            hooks_data = [
                {
                    "id": r.id,
                    "chat_session_id": r.chat_session_id,
                    "thread_type": r.thread_type,
                    "title": r.title,
                    "status": r.status,
                    "owner": r.owner,
                    "target": r.target,
                    "source_turn": r.source_turn,
                    "last_seen_turn": r.last_seen_turn,
                    "confidence": r.confidence,
                    "details_json": r.details_json,
                    "resolution_note": r.resolution_note,
                    "created_at": r.created_at.isoformat() if r.created_at else None,
                    "updated_at": r.updated_at.isoformat() if r.updated_at else None,
                }
                for r in hook_rows
            ]
            hook_last_turn = max((r.last_seen_turn or 0 for r in hook_rows), default=None) if hook_rows else None
            hook_updated = max((r.updated_at.isoformat() if r.updated_at else "" for r in hook_rows), default=None) if hook_rows else None

            # ?? 6. chapter_summaries (read-only preview surface) ?????????????
            chapter_rows = (
                db.query(ChapterSummary)
                .filter(ChapterSummary.chat_session_id == sid)
                .order_by(
                    ChapterSummary.to_turn.desc().nullslast(),
                    ChapterSummary.id.desc(),
                )
                .all()
            )
            chapter_summaries_data = [
                {
                    "id": r.id,
                    "chat_session_id": r.chat_session_id,
                    "from_turn": r.from_turn,
                    "to_turn": r.to_turn,
                    "chapter_index": r.chapter_index,
                    "chapter_title": r.chapter_title,
                    "summary_text": r.summary_text,
                    "open_loops_json": r.open_loops_json,
                    "relationship_changes_json": r.relationship_changes_json,
                    "world_changes_json": r.world_changes_json,
                    "callback_candidates_json": r.callback_candidates_json,
                    "resume_text": r.resume_text,
                    "created_at": r.created_at.isoformat() if r.created_at else None,
                }
                for r in chapter_rows
            ]
            chapter_last_turn = max((r.to_turn or 0 for r in chapter_rows), default=None) if chapter_rows else None
            chapter_updated = max((r.created_at.isoformat() if r.created_at else "" for r in chapter_rows), default=None) if chapter_rows else None

        finally:
            db.close()

        # ?? section_meta 議곕┰ ?????????????????????????????????????????????????
        def _meta(count, last_turn, updated):
            return {
                "count": count,
                "last_turn": last_turn if last_turn else None,
                "updated_at": updated if updated else None,
                "ready": count > 0,
            }

        all_ready = all([
            len(raw_states) > 0,
            len(storylines_data) > 0,
            len(characters_data) > 0,
            len(world_rules_data) > 0,
            len(hooks_data) > 0,
        ])
        any_ready = any([
            len(raw_states) > 0,
            len(storylines_data) > 0,
            len(characters_data) > 0,
            len(world_rules_data) > 0,
            len(hooks_data) > 0,
        ])
        snapshot_status = "ready" if all_ready else ("partial" if any_ready else "empty")

        warnings: list[str] = []
        if character_selection["dropped"]:
            warnings.append(
                f"{len(character_selection['dropped'])} transient descriptor character(s) omitted from characters section."
            )

        return Utf8JSONResponse(content={
            "status": "ok",
            "chat_session_id": sid,
            "snapshot_status": snapshot_status,
            "generated_at": generated_at,
            "active_states": raw_states,
            "storylines": storylines_data,
            "characters": characters_data,
            "world_rules": world_rules_data,
            "pending_threads": hooks_data,
            "chapter_summaries": chapter_summaries_data,
            "canonical_state_layer": canonical_layers,
            "section_meta": {
                "active_states":    _meta(len(raw_states),      as_last_turn,   as_updated),
                "storylines":       _meta(len(storylines_data),  sl_last_turn,   sl_updated),
                "characters":       _meta(len(characters_data),  ch_last_turn,   ch_updated),
                "world_rules":      _meta(len(world_rules_data), wr_last_turn,   wr_updated),
                "pending_threads": _meta(len(hooks_data),       hook_last_turn, hook_updated),
                "chapter_summaries": _meta(len(chapter_summaries_data), chapter_last_turn, chapter_updated),
                "canonical_state_layer": _meta(len(canonical_layers), canonical_last_turn, canonical_updated),
            },
            "warnings": warnings,
        })
    except Exception as exc:
        logger.error("GET /session-state/%s ?ㅽ뙣: %s", chat_session_id, exc)
        return Utf8JSONResponse(
            content={"status": "error", "detail": str(exc)},
            status_code=500,
        )


