class MomentumItem(BaseModel):
    """momentum packet ??媛쒕퀎 ??ぉ ???쒖궗 ?먮쫫 ?쒖븞 1媛?"""
    label: str                         # ??以??붿빟 (injection??
    source_type: str = "storyline"     # storyline | hook | character | world_rule
    source_id: int | None = None       # 李몄“ row id (?덉쑝硫?
    source_name: str | None = None     # ?щ엺???쎌쓣 ???덈뒗 異쒖쿂 ?대쫫
    priority: float = 0.5              # 0.0~1.0 ???믪쓣?섎줉 癒쇱? 二쇱엯


class MomentumPacketResponse(BaseModel):
    """GET /momentum-packet/{session_id} ?묐떟 怨꾩빟.

    I-2a: skeleton ?④퀎.  4媛??щ’留??뺤쓽?섍퀬 items??鍮?list.
    I-2b?먯꽌 storyline + hook 湲곕컲 ?앹꽦 洹쒖튃?쇰줈 援먯껜?쒕떎.
    """
    status: str = "ok"
    chat_session_id: str
    packet_status: str = "skeleton_only"   # skeleton_only | partial | ready
    generated_at: str

    # 4媛??섎? ?щ’
    next_pressure: list[MomentumItem] = Field(default_factory=list)
    payoff_candidates: list[MomentumItem] = Field(default_factory=list)
    tension_to_reuse: list[MomentumItem] = Field(default_factory=list)
    beats_to_avoid: list[MomentumItem] = Field(default_factory=list)

    warnings: list[str] = Field(default_factory=list)


@app.get("/momentum-packet/{chat_session_id}")
def get_momentum_packet(chat_session_id: str):
    """?몄뀡???쒖궗 紐⑤찘? ?⑦궥??諛섑솚?쒕떎.

    I-2b: storyline + continuity_hook 湲곕컲 ?앹꽦 洹쒖튃?쇰줈 4媛??щ’??梨꾩슫??
    - next_pressure: active storyline 以?ongoing_tensions媛 ?덇굅??媛??理쒓렐???쒕룞??寃?
    - payoff_candidates: evidence_count ?믨퀬 confidence ?믪? storyline +
                         last_seen_turn???ㅻ옒??open hook
    - tension_to_reuse: last_seen_turn??媛???ㅻ옒??open/paused hook (?딇?吏??ㅽ???
    - beats_to_avoid: key_points_json??以묐났 ?⑦꽩???덈뒗 active storyline??諛섎났 beat
    """
    from datetime import datetime, timezone
    import json as _json

    sid = (chat_session_id or "").strip()
    if not sid:
        return Utf8JSONResponse(
            content={"status": "error", "detail": "chat_session_id is required"},
            status_code=400,
        )

    generated_at = datetime.now(timezone.utc).isoformat()
    db = SessionLocal()
    try:
        # ?? ?먯떆 ?곗씠??議고쉶 ????????????????????????????????????????
        # I-3d: suppressed=True row??momentum injection?먯꽌 ?쒖쇅
        #        pinned=True row???뺣젹 ?곗꽑?쒖쐞 ?곹뼢 (ORDER BY pinned DESC ?ы븿)
        active_storylines = (
            db.query(Storyline)
            .filter(
                Storyline.chat_session_id == sid,
                Storyline.status == "active",
                Storyline.suppressed == False,  # noqa: E712
            )
            .order_by(
                Storyline.pinned.desc(),  # pinned ?곗꽑
                Storyline.last_turn.desc().nullslast(),
                Storyline.id.desc(),
            )
            .limit(20)
            .all()
        )

        open_hooks = (
            db.query(PendingThread)
            .filter(
                PendingThread.chat_session_id == sid,
                PendingThread.status.in_(["open", "paused"]),
                PendingThread.suppressed == False,  # noqa: E712
            )
            .order_by(
                PendingThread.pinned.desc(),  # pinned ?곗꽑
                PendingThread.last_seen_turn.asc().nullsfirst(),
                PendingThread.id.asc(),
            )
            .limit(20)
            .all()
        )
    finally:
        db.close()

    # ?? ?ы띁: JSON ?꾨뱶 ?덉쟾 ?뚯떛 ??????????????????????????????????
    def _parse_json_list(raw: str | None) -> list:
        if not raw:
            return []
        try:
            val = _json.loads(raw)
            return val if isinstance(val, list) else []
        except Exception:
            return []

    # ?? ?щ’ ?앹꽦 洹쒖튃 ?????????????????????????????????????????????

    # 1. next_pressure ??ongoing_tensions媛 ?덈뒗 active storyline ?곗꽑,
    #    ?놁쑝硫?last_turn 理쒖떊 ?쒖쑝濡?理쒕? 3媛?
    next_pressure: list[dict] = []
    for sl in active_storylines:
        tensions = _parse_json_list(sl.ongoing_tensions_json)
        if tensions:
            label = f"{sl.name}: {tensions[0]}" if tensions else sl.name
            next_pressure.append({
                "label": label,
                "source_type": "storyline",
                "source_id": sl.id,
                "source_name": sl.name,
                "priority": min(1.0, (sl.confidence or 0.5) + 0.2),
            })
        if len(next_pressure) >= 3:
            break
    # tensions ?놁쓣 寃쎌슦 理쒖떊 active storyline?쇰줈 蹂댁땐 (理쒕? 2媛?
    if len(next_pressure) < 2:
        for sl in active_storylines:
            if any(p["source_id"] == sl.id for p in next_pressure):
                continue
            next_pressure.append({
                "label": sl.name,
                "source_type": "storyline",
                "source_id": sl.id,
                "source_name": sl.name,
                "priority": sl.confidence or 0.5,
            })
            if len(next_pressure) >= 2:
                break

    # 2. payoff_candidates ??evidence_count ?믨퀬 confidence ?믪? storyline +
    #    last_seen_turn???ㅻ옒???レ옄 ?묒?) open hook
    payoff_candidates: list[dict] = []
    # storyline 湲곗?: evidence_count >= 3 ?닿퀬 confidence >= 0.7
    for sl in sorted(active_storylines,
                     key=lambda s: (s.evidence_count or 0) * (s.confidence or 0.5),
                     reverse=True):
        if (sl.evidence_count or 0) >= 3 and (sl.confidence or 0.5) >= 0.7:
            payoff_candidates.append({
                "label": f"Arc payoff ready: {sl.name}",
                "source_type": "storyline",
                "source_id": sl.id,
                "source_name": sl.name,
                "priority": min(1.0, (sl.confidence or 0.7) + 0.1),
            })
        if len(payoff_candidates) >= 2:
            break
    # hook 湲곗?: open hook 以?last_seen_turn??媛???ㅻ옒??寃?(?숈꽦??hook)
    for hook in open_hooks[:2]:
        payoff_candidates.append({
            "label": f"Hook ready to close: {hook.title}",
            "source_type": "hook",
            "source_id": hook.id,
            "source_name": hook.title,
            "priority": min(1.0, (hook.confidence or 0.6) + 0.15),
        })
        if len(payoff_candidates) >= 4:
            break

    # 3. tension_to_reuse ??last_seen_turn??媛???ㅻ옒??open/paused hook
    #    (?딇?吏??ㅽ??????꾩옱 arc???ㅼ떆 ??쓣 寃?
    tension_to_reuse: list[dict] = []
    for hook in open_hooks:
        tension_to_reuse.append({
            "label": f"Forgotten thread: {hook.title}",
            "source_type": "hook",
            "source_id": hook.id,
            "source_name": hook.title,
            "priority": hook.confidence or 0.5,
        })
        if len(tension_to_reuse) >= 3:
            break

    # 4. beats_to_avoid ??active storyline??key_points?먯꽌 以묐났 ?⑦꽩 媛먯?
    #    ?숈씪 ?ㅼ썙?쒓? ?щ윭 turn???깆옣?섎㈃ 諛섎났 beat濡?媛꾩＜
    beats_to_avoid: list[dict] = []
    seen_keywords: dict[str, tuple[int, str]] = {}  # key ??(count, original_text)
    for sl in active_storylines:
        kps = _parse_json_list(sl.key_points_json)
        for kp in kps:
            if not isinstance(kp, str):
                continue
            # 以묐났 媛먯????뺢퇋???? ?뚮Ц??+ 泥?20??(?몄씠利??쒓굅??
            key = kp.strip()[:20].lower()
            if key:
                prev_count, prev_text = seen_keywords.get(key, (0, kp.strip()))
                seen_keywords[key] = (prev_count + 1, prev_text)
    for keyword, (count, original_text) in sorted(seen_keywords.items(), key=lambda x: -x[1][0]):
        if count >= 2:
            display = original_text[:60] + "..." if len(original_text) > 60 else original_text
            beats_to_avoid.append({
                "label": f"Avoid repeating: \"{display}\"",
                "source_type": "storyline",
                "source_id": None,
                "source_name": None,
                "priority": min(1.0, 0.3 + count * 0.1),
            })
        if len(beats_to_avoid) >= 3:
            break

    # ?? packet_status 寃곗젙 ?????????????????????????????????????????
    total_items = (len(next_pressure) + len(payoff_candidates)
                   + len(tension_to_reuse) + len(beats_to_avoid))
    if total_items == 0:
        packet_status = "empty"
    elif total_items >= 4:
        packet_status = "ready"
    else:
        packet_status = "partial"

    warnings: list[str] = []
    if not active_storylines and not open_hooks:
        warnings.append("No active storylines or open hooks found for this session.")

    return Utf8JSONResponse(content={
        "status": "ok",
        "chat_session_id": sid,
        "packet_status": packet_status,
        "generated_at": generated_at,
        "next_pressure": next_pressure,
        "payoff_candidates": payoff_candidates,
        "tension_to_reuse": tension_to_reuse,
        "beats_to_avoid": beats_to_avoid,
        "warnings": warnings,
    })


# ------------------------------------------------------------------ #
#  K-1b: Narrative Control State ??skeleton endpoint (Step 7)
#  MO??session-scoped DB 援ъ“? FastAPI ?⑦꽩??留욎떠 ?낆옄 援ы쁽?쒕떎.
#  K-2b: GuidancePlanState cache lookup + conservative update 異붽?.
#         fresh evidence ?놁쑝硫?罹먯떆 ?좎? (hold rule).
#         stale ?먮뒗 誘몄큹湲고솕?대㈃ heuristic ?ъ“由???conservative merge ???
# ------------------------------------------------------------------ #

# K-2a: 罹먯떆 ?좏슚 湲곗? ??DB ?먯궛??留덉?留됱쑝濡?蹂寃쎈맂 ???鍮?紐????대궡瑜?"fresh"濡?蹂?寃껋씤媛
_GUIDANCE_FRESHNESS_TURNS = 3

@app.get("/narrative-control/{chat_session_id}")
def get_narrative_control(chat_session_id: str):
    """?몄뀡??persistent guidance state(story plan + director)瑜?諛섑솚?쒕떎.

    K-1b: skeleton endpoint.
    K-1c: ?ㅼ젣 DB ?먯궛(storylines/hooks/momentum)?먯꽌 heuristic?쇰줈 partial read 議곕┰.
    K-2b: GuidancePlanState 罹먯떆 lookup + conservative update + ???
    """
    import json as _json
    from datetime import datetime, timezone

    sid = (chat_session_id or "").strip()
    if not sid:
        return Utf8JSONResponse(
            content={"status": "error", "detail": "chat_session_id is required"},
            status_code=400,
        )

    generated_at = datetime.now(timezone.utc).isoformat()
    warnings: list[str] = []

    db = SessionLocal()
    try:
        # ?? K-2b step 1: 罹먯떆 議고쉶 ????????????????????????????????????????
        cached: GuidancePlanState | None = (
            db.query(GuidancePlanState)
            .filter(GuidancePlanState.chat_session_id == sid)
            .first()
        )

        # ?? 1. active storylines 議고쉶 (suppressed ?쒖쇅, pinned ?곗꽑) ??????????
        active_storylines = (
            db.query(Storyline)
            .filter(
                Storyline.chat_session_id == sid,
                Storyline.status == "active",
                Storyline.suppressed == False,  # noqa: E712
            )
            .order_by(
                Storyline.pinned.desc(),
                Storyline.last_turn.desc().nullslast(),
                Storyline.id.desc(),
            )
            .limit(10)
            .all()
        )

        # ?? 2. open/paused continuity hooks 議고쉶 (suppressed ?쒖쇅, pinned ?곗꽑) ?
        open_hooks = (
            db.query(PendingThread)
            .filter(
                PendingThread.chat_session_id == sid,
                PendingThread.status.in_(["open", "paused"]),
                PendingThread.suppressed == False,  # noqa: E712
            )
            .order_by(
                PendingThread.pinned.desc(),
                PendingThread.last_seen_turn.desc().nullslast(),
                PendingThread.id.desc(),
            )
            .limit(10)
            .all()
        )

        # ?? 3. world_guardrails ??pinned WorldRule 以?physics/exists 移댄뀒怨좊━ ?
        key_world_rules = (
            db.query(WorldRule)
            .filter(
                WorldRule.chat_session_id == sid,
                WorldRule.suppressed == False,  # noqa: E712
                WorldRule.category.in_(["exists", "physics", "systems"]),
            )
            .order_by(WorldRule.pinned.desc(), WorldRule.id.desc())
            .limit(8)
            .all()
        )

        # ?? 4. 留덉?留??섑뻾 ??異붿쟻 ?????????????????????????????????????????
        db_last_turn = 0
        if active_storylines:
            db_last_turn = max(
                (s.last_turn or 0 for s in active_storylines), default=0
            )
        if open_hooks:
            db_last_turn = max(
                db_last_turn,
                max((h.last_seen_turn or 0 for h in open_hooks), default=0),
            )

        # ?? K-2b step 2: freshness ?먯젙 ??罹먯떆媛 異⑸텇??理쒖떊?대㈃ 諛섑솚 ????????
        #    fresh 議곌굔: cached媛 ?덇퀬, cached.last_turn >= db_last_turn - FRESHNESS_TURNS
        #    利?DB ?먯궛??罹먯떆 ?댄썑 FRESHNESS_TURNS ???댁긽 ?덈줈 諛붾뚯? ?딆븯?쇰㈃ hold.
        #    K-3d: user_patched ?곹깭??freshness ?먯젙 臾닿??섍쾶 ??긽 罹먯떆 ?곗꽑 諛섑솚.
        #    backward freshness: db_last_turn??cached.last_turn蹂대떎 2???댁긽 ??쑝硫?
        #    DB ?먯궛??援먯껜/媛깆떊??寃껋씠誘濡?罹먯떆瑜?臾댄슚?뷀븳??
        #    (??hooks????? turn 踰덊샇濡?異붽???寃쎌슦 ??
        is_user_patched = (cached is not None and cached.state_status == "user_patched")
        if (
            cached is not None
            and cached.state_status not in ("empty", None)
            and cached.story_plan_json
            and cached.director_json
            and (
                is_user_patched
                or (
                    cached.last_turn >= max(0, db_last_turn - _GUIDANCE_FRESHNESS_TURNS)
                    and db_last_turn >= max(0, cached.last_turn - 1)  # backward freshness
                )
            )
        ):
            try:
                sp_cached = _json.loads(cached.story_plan_json)
                dr_cached = _json.loads(cached.director_json)
                story_plan = StoryPlanState(**{
                    k: sp_cached.get(k, v)
                    for k, v in StoryPlanState().model_dump().items()
                })
                director = DirectorState(**{
                    k: dr_cached.get(k, v)
                    for k, v in DirectorState().model_dump().items()
                })
                state_status = cached.state_status
                last_turn = cached.last_turn
                w_cached = []
                try:
                    w_cached = _json.loads(cached.warnings_json or "[]") or []
                except Exception:
                    pass
                warnings.extend(w_cached)
                progression_ledger = _build_progression_ledger_n2a(
                    story_plan_data=story_plan.model_dump(),
                    director_data=director.model_dump(),
                    last_turn=last_turn,
                    state_status=state_status,
                )
                story_guidance = _build_story_guidance_surface_sg14(
                    story_plan.model_dump(),
                    director.model_dump(),
                )
                # 罹먯떆 ?덊듃 ??利됱떆 諛섑솚
                resp = NarrativeControlStateResponse(
                    status="ok",
                    chat_session_id=sid,
                    generated_at=generated_at,
                    skeleton_only=(state_status == "skeleton"),
                    state_status=state_status,
                    story_plan=story_plan,
                    director=director,
                    last_advanced_turn=progression_ledger.get("last_advanced_turn"),
                    last_validated_turn=progression_ledger.get("last_validated_turn"),
                    progression_ledger=ProgressionLedgerState(**progression_ledger),
                    story_guidance=StoryGuidanceState(**story_guidance),
                    warnings=warnings,
                )
                return Utf8JSONResponse(content=resp.model_dump())
            except Exception as cache_err:
                logger.warning(f"[narrative-control] cache parse failed, rebuilding: {cache_err}")
                # 罹먯떆 ?뚯떛 ?ㅽ뙣 ??heuristic ?ъ“由?吏꾪뻾

        # ?? 5. StoryPlanState heuristic 議곕┰ ??????????????????????????????
        #    lorebook ???MO??Storyline/PendingThread DB瑜??ъ슜?쒕떎.
        current_arc = ""
        narrative_goal = ""
        active_tensions: list[str] = []
        next_beats: list[str] = []
        continuity_anchors: list[str] = []
        focus_characters: list[str] = []

        if active_storylines:
            primary = active_storylines[0]
            current_arc = primary.name or ""
            narrative_goal = (primary.current_context or "").strip()[:200]

            # ongoing_tensions ??active_tensions
            try:
                tensions = _json.loads(primary.ongoing_tensions_json or "[]")
                active_tensions = [str(t) for t in tensions if t][:4]
            except Exception:
                pass

            # key_points ??continuity_anchors (留덉?留?2媛?
            try:
                kps = _json.loads(primary.key_points_json or "[]")
                continuity_anchors = [str(k) for k in kps[-2:] if k]
            except Exception:
                pass

            # entities ??focus_characters
            try:
                ents = _json.loads(primary.entities_json or "[]")
                focus_characters = [str(e) for e in ents if e][:4]
            except Exception:
                pass

            # ?섎㉧吏 active storylines?먯꽌 tension 蹂댁땐
            for sl in active_storylines[1:3]:
                try:
                    t2 = _json.loads(sl.ongoing_tensions_json or "[]")
                    for t in t2[:1]:
                        if t and str(t) not in active_tensions:
                            active_tensions.append(str(t))
                except Exception:
                    pass

        # open hooks ??next_beats / continuity_anchors
        for hook in open_hooks[:4]:
            beat = f"[{hook.thread_type}] {hook.title}"
            next_beats.append(beat)
            if hook.thread_type in ("promise", "unresolved_goal"):
                continuity_anchors.append(hook.title)

        # guardrails: world rules 湲곕컲
        guardrails: list[str] = []
        for wr in key_world_rules[:3]:
            try:
                val = _json.loads(wr.value_json or "null")
                if isinstance(val, dict):
                    desc = val.get("description") or val.get("value") or str(val)
                else:
                    desc = str(val) if val else wr.key
                guardrails.append(f"{wr.key}: {str(desc)[:80]}")
            except Exception:
                guardrails.append(wr.key)

        # ?? K-2c: conservative merge ??罹먯떆? ??heuristic 鍮꾧탳 ??蹂댁닔??寃고빀 ?
        #    arc ?숈씪 ??湲곗〈 beats/anchors ?곗꽑 ?좎?, ????ぉ 蹂댁땐
        #    arc 蹂寃?????arc 梨꾪깮, 湲곗〈 unresolved beats???욎뿉???댁뼱諛쏆쓬
        if cached and cached.story_plan_json:
            try:
                sp_prev = _json.loads(cached.story_plan_json)
                prev_arc = sp_prev.get("current_arc", "")
                prev_beats = sp_prev.get("next_beats", [])
                prev_anchors = sp_prev.get("continuity_anchors", [])

                if prev_arc and prev_arc == current_arc:
                    # 媛숈? arc: 湲곗〈 beats ?욎뿉 ?좎?, ??beats濡?蹂댁땐
                    merged_beats = list(prev_beats)
                    for b in next_beats:
                        if b not in merged_beats:
                            merged_beats.append(b)
                    next_beats = merged_beats[:6]
                    # anchors: 湲곗〈 ?좎? + ????ぉ 蹂묓빀, dedup
                    merged_anchors = list(prev_anchors)
                    for a in continuity_anchors:
                        if a not in merged_anchors:
                            merged_anchors.append(a)
                    continuity_anchors = merged_anchors[:4]
                else:
                    # arc ?꾪솚: unresolved beats(promise/goal ?좏삎)留??댁뼱諛쏆쓬
                    carried = [b for b in prev_beats if b.startswith("[promise]") or b.startswith("[unresolved_goal]")]
                    next_beats = (next_beats + carried)[:6]
            except Exception:
                pass  # merge ?ㅽ뙣 ????heuristic 洹몃?濡??ъ슜

        new_plan_status = "heuristic" if (active_storylines or open_hooks) else "empty"
        story_plan = StoryPlanState(
            current_arc=current_arc,
            narrative_goal=narrative_goal,
            active_tensions=active_tensions[:4],
            next_beats=next_beats[:6],
            continuity_anchors=continuity_anchors[:4],
            guardrails=guardrails[:4],
            persona_priorities=[],   # K-3f?먯꽌 異붽?
            execution_notes=[],      # L-2f(pattern guard)?먯꽌 異붽?
            focus_characters=focus_characters[:4],
            last_plan_turn=db_last_turn,
            state_status=new_plan_status,
        )

        # ?? 6. DirectorState heuristic 議곕┰ ????????????????????????????????
        #    MO??PendingThread / WorldRule DB?먯꽌 required/forbidden??異붿텧?쒕떎.
        required_outcomes: list[str] = []
        forbidden_moves: list[str] = []
        execution_checklist: list[str] = []
        world_guardrails: list[str] = []

        # pinned hooks ??required_outcomes
        for hook in open_hooks:
            if hook.pinned:
                required_outcomes.append(f"Carry forward: {hook.title}")
            if hook.thread_type == "risk":
                forbidden_moves.append(f"Do not abruptly resolve: {hook.title}")

        # active storylines ??execution_checklist (K-3c: 湲곕낯 ??ぉ 異붽?)
        if active_storylines:
            execution_checklist.append(
                "Continue from the current scene state; do not open a new scene without cause."
            )
            execution_checklist.append(
                "Deliver at least one visible beat before the response ends."
            )

        # world rules (physics) ??world_guardrails
        for wr in key_world_rules:
            if wr.category == "physics":
                try:
                    val = _json.loads(wr.value_json or "null")
                    desc = val.get("description") or str(val) if isinstance(val, dict) else str(val or wr.key)
                    world_guardrails.append(f"World rule [{wr.key}]: {str(desc)[:80]}")
                except Exception:
                    world_guardrails.append(f"World rule: {wr.key}")

        # ?? K-3b: director conservative merge ?????????????????????????????
        #   湲곗〈 罹먯떆 director_json ?鍮?蹂寃쎈맂 ?먮쭔 蹂댁닔?곸쑝濡?諛섏쁺?쒕떎.
        #
        #   required_outcomes:
        #     - 湲곗〈 ??ぉ 以????hook???ъ쟾??open ???좎?
        #     - 湲곗〈 ??ぉ 以?hook??resolved/?щ씪吏???resolved_outcomes濡??대룞 (K-3d compact)
        #     - ??pinned hook ???좉퇋 異붽?
        #
        #   forbidden_moves:
        #     - 湲곗〈 ??ぉ 以????risk hook???ъ쟾??open ???좎?
        #     - 湲곗〈 ??ぉ 以?risk hook??resolved ??expired_forbidden?쇰줈 ?대룞 (decay)
        #
        #   execution_checklist (K-3c):
        #     - 湲곗〈 ??ぉ 以??ъ쟾???섎??덈뒗 寃껋? ?좎?, dedup
        #     - 理쒕? 4媛??쒗븳
        #
        #   world_guardrails (K-3c):
        #     - 湲곗〈 ??ぉ 以?key媛 ?ъ쟾??world_rules??議댁옱?섎㈃ ?좎?
        #     - ????ぉ 異붽?, 理쒕? 4媛??쒗븳

        resolved_outcomes: list[str] = []
        expired_forbidden: list[str] = []
        # K-5b: ?대쾲 ?댁뿉 ?덈줈 異붽?????ぉ留?蹂꾨룄 異붿쟻 (compact write ???
        newly_resolved: list[str] = []
        newly_expired: list[str] = []

        open_titles  = {h.title for h in open_hooks}
        open_risk_titles = {h.title for h in open_hooks if h.thread_type == "risk"}
        active_world_keys = {wr.key for wr in key_world_rules}

        if cached and cached.director_json:
            try:
                dr_prev = _json.loads(cached.director_json)
                prev_required  = dr_prev.get("required_outcomes", [])
                prev_forbidden = dr_prev.get("forbidden_moves", [])
                prev_checklist = dr_prev.get("execution_checklist", [])
                prev_guardrails= dr_prev.get("world_guardrails", [])
                prev_resolved  = dr_prev.get("resolved_outcomes", [])
                prev_expired   = dr_prev.get("expired_forbidden", [])

                # required_outcomes: still-open ?좎?, ?댁냼??寃껋? resolved_outcomes濡?
                for req in prev_required:
                    label = req.removeprefix("Carry forward: ").strip()
                    if label in open_titles:
                        if req not in required_outcomes:
                            required_outcomes.append(req)
                    else:
                        # hook???щ씪議뚮떎 = resolved / ?쒓굅????compact history
                        compact_entry = f"[resolved] {label}"
                        if compact_entry not in prev_resolved and compact_entry not in resolved_outcomes:
                            resolved_outcomes.append(compact_entry)
                            newly_resolved.append(compact_entry)  # K-5b

                # forbidden_moves: still-open risk ?좎?, resolved risk??expired_forbidden?쇰줈
                for fb in prev_forbidden:
                    risk_label = fb.removeprefix("Do not abruptly resolve: ").strip()
                    if risk_label in open_risk_titles:
                        if fb not in forbidden_moves:
                            forbidden_moves.append(fb)
                    else:
                        expired_entry = f"[expired] {risk_label}"
                        if expired_entry not in prev_expired and expired_entry not in expired_forbidden:
                            expired_forbidden.append(expired_entry)
                            newly_expired.append(expired_entry)  # K-5b

                # K-3c: execution_checklist 蹂댁닔??異뺤쟻 ??湲곗〈 ??ぉ dedup ???좎?
                for item in prev_checklist:
                    if item not in execution_checklist:
                        execution_checklist.append(item)

                # K-3c: world_guardrails 蹂댁닔??異뺤쟻 ???ъ쟾???좏슚??world_rule ??ぉ ?좎?
                for wg in prev_guardrails:
                    # "World rule [key]: desc" ?뺥깭?먯꽌 key 異붿텧
                    try:
                        wg_key = wg.split("[")[1].split("]")[0] if "[" in wg else ""
                    except Exception:
                        wg_key = ""
                    if wg_key and wg_key in active_world_keys and wg not in world_guardrails:
                        world_guardrails.append(wg)

                # 湲곗〈 resolved/expired ?댁썡 (compact history ?꾩쟻)
                resolved_outcomes = (prev_resolved + resolved_outcomes)[-8:]
                expired_forbidden = (prev_expired + expired_forbidden)[-8:]

            except Exception:
                pass  # 罹먯떆 ?뚯떛 ?ㅽ뙣 ????heuristic 洹몃?濡?

        # ?ш린 ?쒗븳
        required_outcomes = required_outcomes[:4]
        forbidden_moves   = forbidden_moves[:4]
        execution_checklist = list(dict.fromkeys(execution_checklist))[:4]  # dedup ?좎? ?쒖꽌
        world_guardrails  = world_guardrails[:4]

        # pressure_level 寃곗젙: pinned hook ?섏? active tension ??湲곕컲 heuristic
        pinned_count = sum(1 for h in open_hooks if h.pinned)
        tension_count = len(active_tensions)
        if pinned_count >= 2 or tension_count >= 3:
            pressure_level = "strong"
        elif pinned_count >= 1 or tension_count >= 1:
            pressure_level = "steady"
        else:
            pressure_level = "light"

        # ?? K-3f: persona guardrails 議곕┰ ?????????????????????????????????
        #   CharacterState DB?먯꽌 focus_characters??personality / speech_style /
        #   status ?뺣낫瑜??쎌뼱 蹂댁“ 而⑦뀓?ㅽ듃 ?뚰듃(guardrail)瑜??앹꽦?쒕떎.
        #   - lorebook ???FastAPI character_states ?뚯씠釉붿뿉??議고쉶
        #   - ?꾨＼?꾪듃 吏곸젒 ?쎌엯???꾨땶 guardrail ?뚰듃 紐⑸줉?쇰줈留??쒗쁽
        #   - user intent瑜??泥댄븯吏 ?딆쓬 (蹂댁“ 而⑦뀓?ㅽ듃濡쒕쭔 ?ъ슜)
        persona_guardrails: list[str] = []
        if focus_characters:
            try:
                char_states = (
                    db.query(CharacterState)
                    .filter(
                        CharacterState.chat_session_id == sid,
                        CharacterState.character_name.in_(focus_characters),
                    )
                    .order_by(CharacterState.turn_index.desc().nullslast())
                    .all()
                )
                # 罹먮┃?곕떦 理쒖떊 1媛쒕쭔 ?ъ슜
                seen_chars: set[str] = set()
                for cs in char_states:
                    if cs.character_name in seen_chars:
                        continue
                    seen_chars.add(cs.character_name)
                    hints: list[str] = []
                    # speech_style ?뚰듃
                    if cs.speech_style_json:
                        try:
                            style = _json.loads(cs.speech_style_json)
                            if isinstance(style, dict):
                                tone = style.get("tone") or style.get("style") or ""
                                if tone:
                                    hints.append(f"speaks {str(tone)[:60]}")
                            elif isinstance(style, str) and style.strip():
                                hints.append(f"speaks {style.strip()[:60]}")
                        except Exception:
                            pass
                    # personality ?듭떖 ?뱀꽦 ?뚰듃 (理쒕? 1媛?
                    if cs.personality_json:
                        try:
                            pers = _json.loads(cs.personality_json)
                            if isinstance(pers, dict):
                                trait = (
                                    pers.get("core_trait")
                                    or pers.get("trait")
                                    or pers.get("personality")
                                    or ""
                                )
                                if trait:
                                    hints.append(f"core trait: {str(trait)[:60]}")
                            elif isinstance(pers, list) and pers:
                                hints.append(f"core trait: {str(pers[0])[:60]}")
                        except Exception:
                            pass
                    if hints:
                        line = f"[{cs.character_name}] " + "; ".join(hints)
                        persona_guardrails.append(line)
                persona_guardrails = persona_guardrails[:4]
            except Exception as pg_err:
                logger.debug("[K-3f] persona guardrails build failed (non-fatal): %s", pg_err)

        director = DirectorState(
            scene_mandate=f"Continue arc: {current_arc}" if current_arc else "",
            required_outcomes=required_outcomes,
            forbidden_moves=forbidden_moves,
            pressure_level=pressure_level,
            execution_checklist=execution_checklist,
            persona_guardrails=persona_guardrails,   # K-3f
            world_guardrails=world_guardrails,
            focus_characters=focus_characters[:4],
            last_turn=db_last_turn,
            state_status="heuristic" if (active_storylines or open_hooks) else "empty",
            resolved_outcomes=resolved_outcomes,   # K-3a
            expired_forbidden=expired_forbidden,   # K-3a
        )

        # ?? 7. ?꾩껜 state_status 寃곗젙 ??????????????????????????????????????
        has_plan = bool(story_plan.current_arc or story_plan.next_beats)
        has_director = bool(director.required_outcomes or director.scene_mandate)
        if has_plan and has_director:
            state_status = "ready"
        elif has_plan or has_director:
            state_status = "partial"
        else:
            state_status = "skeleton"
            warnings.append("No active storylines or open hooks found. Returning skeleton state.")

        last_turn = db_last_turn

        # ?? K-2b step 3: 寃곌낵瑜?GuidancePlanState?????(upsert) ????????????
        try:
            new_sp_json = _json.dumps(story_plan.model_dump(), ensure_ascii=False)
            new_dr_json = _json.dumps(director.model_dump(), ensure_ascii=False)
            new_warn_json = _json.dumps(warnings, ensure_ascii=False)
            if cached is not None:
                cached.story_plan_json = new_sp_json
                cached.director_json = new_dr_json
                cached.state_status = state_status
                cached.last_turn = last_turn
                cached.warnings_json = new_warn_json
            else:
                new_cache = GuidancePlanState(
                    chat_session_id=sid,
                    story_plan_json=new_sp_json,
                    director_json=new_dr_json,
                    state_status=state_status,
                    last_turn=last_turn,
                    warnings_json=new_warn_json,
                )
                db.add(new_cache)
            db.commit()
        except Exception as save_err:
            logger.warning(f"[narrative-control] cache save failed (non-fatal): {save_err}")
            db.rollback()

        # ?? K-5b: active ??compact transition ?????????????????????????????
        #   ?대쾲 ?댁뿉 ?덈줈 resolved/expired????ぉ怨?status="resolved" ?ㅽ넗由щ씪?몄쓣
        #   GuidanceCompactRecord 濡??대룞?쒕떎.
        #   - ?ㅽ뙣?대룄 梨꾪똿/guidance 寃곌낵???곹뼢 ?놁쓬 (non-fatal)
        #   - emotional_weight: K-5f emotion signal heuristic
        #       base  = pressure_level proxy (strong=0.8, steady=0.5, light=0.2)
        #       boost = active_tensions ??횞 0.04 (理쒕? +0.12)
        #     ??0.0~1.0 clamp. LLM ?몄텧 ?놁씠 湲곗〈 DB ?먯궛留??ъ슜.
        try:
            _ew_map = {"strong": 0.8, "steady": 0.5, "light": 0.2}
            _ew_base = _ew_map.get(pressure_level, 0.5)
            # K-5f: active_tensions ?섎? emotion intensity proxy濡?異붽? 蹂댁젙
            _tension_boost = min(len(active_tensions) * 0.04, 0.12)
            _ew = min(_ew_base + _tension_boost, 1.0)

            # ?대? compact???쒕ぉ 吏묓빀 (以묐났 諛⑹?)
            existing_titles: set[str] = {
                r.title for r in db.query(GuidanceCompactRecord.title)
                .filter(GuidanceCompactRecord.chat_session_id == sid)
                .all()
            }

            compact_batch: list[GuidanceCompactRecord] = []

            # 1) ?덈줈 resolved??required_outcome
            for entry in newly_resolved:
                clean_title = entry.removeprefix("[resolved] ").strip()
                if clean_title not in existing_titles:
                    compact_batch.append(GuidanceCompactRecord(
                        chat_session_id=sid,
                        record_type="resolved_outcome",
                        title=clean_title,
                        compact_summary=f"Resolved: {clean_title}",
                        original_content_json=_json.dumps({"raw": entry}, ensure_ascii=False),
                        origin_type="director_outcome",
                        origin_id=None,
                        emotional_weight=_ew,
                        source_turn=db_last_turn,
                        compacted_turn=db_last_turn,
                    ))
                    existing_titles.add(clean_title)

            # 2) ?덈줈 expired??forbidden_move
            for entry in newly_expired:
                clean_title = entry.removeprefix("[expired] ").strip()
                if clean_title not in existing_titles:
                    compact_batch.append(GuidanceCompactRecord(
                        chat_session_id=sid,
                        record_type="expired_forbidden",
                        title=clean_title,
                        compact_summary=f"Forbidden (expired): {clean_title}",
                        original_content_json=_json.dumps({"raw": entry}, ensure_ascii=False),
                        origin_type="director_forbidden",
                        origin_id=None,
                        emotional_weight=_ew,
                        source_turn=db_last_turn,
                        compacted_turn=db_last_turn,
                    ))
                    existing_titles.add(clean_title)

            # 3) status="resolved" ??storyline 以?compact record媛 ?녿뒗 寃?
            resolved_storylines = (
                db.query(Storyline)
                .filter(
                    Storyline.chat_session_id == sid,
                    Storyline.status == "resolved",
                )
                .all()
            )
            for sl in resolved_storylines:
                if sl.name not in existing_titles:
                    arc_summary = sl.current_context or sl.name
                    # K-5f: pinned storyline? 媛먯젙 以묒슂?꾧? ???믩떎怨?媛꾩＜
                    _ew_sl = min(_ew + (0.1 if sl.pinned else 0.0), 1.0)
                    compact_batch.append(GuidanceCompactRecord(
                        chat_session_id=sid,
                        record_type="resolved_arc",
                        title=sl.name,
                        compact_summary=f"Arc resolved: {arc_summary[:120]}",
                        original_content_json=_json.dumps({
                            "name": sl.name,
                            "context": sl.current_context,
                            "first_turn": sl.first_turn,
                            "last_turn": sl.last_turn,
                            "pinned": sl.pinned,
                        }, ensure_ascii=False),
                        origin_type="storyline",
                        origin_id=sl.id,
                        emotional_weight=_ew_sl,
                        source_turn=sl.first_turn,
                        compacted_turn=db_last_turn,
                    ))
                    existing_titles.add(sl.name)

            if compact_batch:
                db.add_all(compact_batch)
                db.commit()
                logger.debug("[K-5b] compact records written: %d", len(compact_batch))

        except Exception as compact_err:
            logger.warning("[K-5b] compact write failed (non-fatal): %s", compact_err)
            db.rollback()

        # ?? K-5c: closed hook handoff ??????????????????????????????????????
        #   PendingThread.status == "resolved" ??hook??GuidanceCompactRecord濡??대룞.
        #   K-5b??hook?먯꽌 ?뚯깮??director ??ぉ(required/forbidden)??compact?섍퀬,
        #   K-5c??hook ?뷀떚???먯껜瑜?compact??origin_type="hook" ?덉퐫?쒕? ?앹꽦?쒕떎.
        #
        #   thread_type 留ㅽ븨:
        #     "risk"                  ??record_type = "expired_forbidden"
        #     湲고? (promise/goal ??  ??record_type = "resolved_outcome"
        #
        #   resolution_note ?덉쑝硫?compact_summary???ы븿.
        #   non-fatal: ?ㅽ뙣?대룄 guidance ?묐떟???곹뼢 ?놁쓬.
        try:
            # ?대쾲 K-5c ?꾩슜 existing_titles ?ъ“??(K-5b 吏곹썑 ?곹깭 諛섏쁺)
            existing_hook_titles: set[str] = {
                r.title for r in db.query(GuidanceCompactRecord.title)
                .filter(GuidanceCompactRecord.chat_session_id == sid)
                .all()
            }

            _ew_map_c = {"strong": 0.8, "steady": 0.5, "light": 0.2}
            # K-5f: K-5b? ?숈씪??emotion signal heuristic ?곸슜
            _ew_c_base = _ew_map_c.get(pressure_level, 0.5)
            _ew_c_tension = min(len(active_tensions) * 0.04, 0.12)
            _ew_c = min(_ew_c_base + _ew_c_tension, 1.0)

            resolved_hooks = (
                db.query(PendingThread)
                .filter(
                    PendingThread.chat_session_id == sid,
                    PendingThread.status == "resolved",
                )
                .all()
            )

            hook_batch: list[GuidanceCompactRecord] = []
            for hook in resolved_hooks:
                if hook.title in existing_hook_titles:
                    continue  # ?대? compact????ぉ 嫄대꼫?

                is_risk = (hook.thread_type == "risk")
                rec_type = "expired_forbidden" if is_risk else "resolved_outcome"

                if hook.resolution_note:
                    summary = f"{'Forbidden (expired)' if is_risk else 'Resolved'}: {hook.title} ??{hook.resolution_note[:80]}"
                else:
                    summary = f"{'Forbidden (expired)' if is_risk else 'Resolved'}: {hook.title}"

                hook_batch.append(GuidanceCompactRecord(
                    chat_session_id=sid,
                    record_type=rec_type,
                    title=hook.title,
                    compact_summary=summary,
                    original_content_json=_json.dumps({
                        "thread_type": hook.thread_type,
                        "title": hook.title,
                        "owner": hook.owner,
                        "target": hook.target,
                        "resolution_note": hook.resolution_note,
                        "source_turn": hook.source_turn,
                        "last_seen_turn": hook.last_seen_turn,
                    }, ensure_ascii=False),
                    origin_type="hook",
                    origin_id=hook.id,
                    # K-5f: pinned hook? 媛먯젙 以묒슂??+0.1 蹂댁젙
                    emotional_weight=min(_ew_c + (0.1 if hook.pinned else 0.0), 1.0),
                    source_turn=hook.source_turn,
                    compacted_turn=db_last_turn,
                ))
                existing_hook_titles.add(hook.title)

            if hook_batch:
                db.add_all(hook_batch)
                db.commit()
                logger.debug("[K-5c] hook compact records written: %d", len(hook_batch))

        except Exception as hook_compact_err:
            logger.warning("[K-5c] hook compact write failed (non-fatal): %s", hook_compact_err)
            db.rollback()

        # ?? K-5d: compact_history 議고쉶 (continuity-friendly summary 鍮뚮뱶) ??
        #   K-5b/K-5c 吏곹썑 GuidanceCompactRecord?먯꽌 理쒓렐 ??ぉ???쎌뼱
        #   prompt 蹂댁“ 而⑦뀓?ㅽ듃濡??ъ슜 媛?ν븳 ??以??붿빟 紐⑸줉??留뚮뱺??
        #   - emotional_weight ?대┝李⑥닚, compacted_turn ?대┝李⑥닚?쇰줈 理쒕? 6媛?
        #   - compact_summary ?띿뒪?몃쭔 諛섑솚 (?먮낯 JSON ?쒖쇅)
        #   - ?ㅽ뙣?대룄 鍮?紐⑸줉?쇰줈 ?泥?(non-fatal)
        compact_history: list[str] = []
        try:
            recent_records = (
                db.query(GuidanceCompactRecord)
                .filter(GuidanceCompactRecord.chat_session_id == sid)
                .order_by(
                    GuidanceCompactRecord.emotional_weight.desc().nullslast(),
                    GuidanceCompactRecord.compacted_turn.desc().nullslast(),
                    GuidanceCompactRecord.id.desc(),
                )
                .limit(6)
                .all()
            )
            compact_history = [
                r.compact_summary for r in recent_records
                if r.compact_summary
            ]
        except Exception as ch_err:
            logger.warning("[K-5d] compact_history fetch failed (non-fatal): %s", ch_err)

    except Exception as e:
        logger.warning(f"[narrative-control] DB read failed: {e}")
        warnings.append(f"DB read error: {str(e)[:120]}. Returning skeleton fallback.")
        story_plan = StoryPlanState()
        director = DirectorState()
        state_status = "skeleton"
        last_turn = 0
        compact_history = []
    finally:
        db.close()

    progression_ledger = _build_progression_ledger_n2a(
        story_plan_data=story_plan.model_dump(),
        director_data=director.model_dump(),
        last_turn=last_turn,
        state_status=state_status,
    )
    story_guidance = _build_story_guidance_surface_sg14(
        story_plan.model_dump(),
        director.model_dump(),
    )

    resp = NarrativeControlStateResponse(
        status="ok",
        chat_session_id=sid,
        generated_at=generated_at,
        skeleton_only=(state_status == "skeleton"),
        state_status=state_status,
        story_plan=story_plan,
        director=director,
        last_advanced_turn=progression_ledger.get("last_advanced_turn"),
        last_validated_turn=progression_ledger.get("last_validated_turn"),
        progression_ledger=ProgressionLedgerState(**progression_ledger),
        story_guidance=StoryGuidanceState(**story_guidance),
        warnings=warnings,
        compact_history=compact_history,   # K-5d
    )
    return Utf8JSONResponse(content=resp.model_dump())


# ------------------------------------------------------------------ #
#  M-1b: POST /prepare-turn ??skeleton endpoint (Step 8)
#
#  ?꾩옱 ?④퀎(M-1)?먯꽌??怨꾩궛 ?놁씠 skeleton shape留?諛섑솚?쒕떎.
#  ?ㅼ젣 recall / supervisor / injection 議곕┰? M-2/M-3?먯꽌 ?④퀎?곸쑝濡?異붽??쒕떎.
#
#  plugin????endpoint???묎렐?섎㈃:
#    - source="skeleton" ?묐떟??諛쏅뒗??
#    - fallback_reason="skeleton_only" 濡?local orchestration path瑜?洹몃?濡??좎??쒕떎
#    - backend媛 二쎌뼱 ?덉쑝硫?plugin??ConnectionError/timeout??諛쏆븘 local path濡?fallback?쒕떎
#
#  M-1c?먯꽌 plugin.js beforeRequest??thin adapter skeleton??遺숆린 ?꾧퉴吏,
#  ??endpoint??backend 履?怨꾩빟留?怨좎젙?섎뒗 ?⑸룄??
# ------------------------------------------------------------------ #

# ?? M-2a: prepare-turn ?대? 踰덈뱾 read helpers ?????????????????????????????????
# prepare_turn ?먯꽌留??몄텧?섎뒗 lightweight read ?⑥닔??
# 湲곗〈 /session-state / /narrative-control / /continuity-pack endpoint??蹂寃쏀븯吏 ?딅뒗??

def _bundle_read_narrative_control(sid: str) -> dict | None:
    """M-2a: GuidancePlanState 罹먯떆?먯꽌 narrative-control ?곗씠?곕? ?쎌뼱 諛섑솚.
    罹먯떆媛 ?녾굅??state_status媛 empty?대㈃ None??諛섑솚 ??plugin??媛쒕퀎 fetch濡?fallback.
    """
    import json as _json
    try:
        db = SessionLocal()
        try:
            cached: GuidancePlanState | None = (
                db.query(GuidancePlanState)
                .filter(GuidancePlanState.chat_session_id == sid)
                .first()
            )
            if not cached or not cached.story_plan_json or not cached.director_json:
                return None
            if cached.state_status in ("empty", None):
                return None
            sp = _json.loads(cached.story_plan_json)
            dr = _json.loads(cached.director_json)
            warnings_raw = _json.loads(cached.warnings_json) if cached.warnings_json else []
            last_turn = cached.last_turn if isinstance(cached.last_turn, int) else 0
            progression_ledger = _build_progression_ledger_n2a(
                story_plan_data=sp,
                director_data=dr,
                last_turn=last_turn,
                state_status=cached.state_status or "heuristic",
            )
            story_guidance = _build_story_guidance_surface_sg14(
                sp,
                dr,
            )
            compact_history: list[str] = []
            compact_history_records: list[dict] = []
            try:
                recent_records = (
                    db.query(GuidanceCompactRecord)
                    .filter(GuidanceCompactRecord.chat_session_id == sid)
                    .order_by(
                        GuidanceCompactRecord.emotional_weight.desc().nullslast(),
                        GuidanceCompactRecord.compacted_turn.desc().nullslast(),
                        GuidanceCompactRecord.id.desc(),
                    )
                    .limit(6)
                    .all()
                )
                compact_history = [
                    r.compact_summary for r in recent_records
                    if r.compact_summary
                ]
                compact_history_records = [
                    {
                        "record_type": r.record_type or "",
                        "title": r.title or "",
                        "compact_summary": r.compact_summary,
                        "origin_type": r.origin_type or "",
                        "source_turn": r.source_turn,
                        "compacted_turn": r.compacted_turn,
                        "emotional_weight": float(r.emotional_weight) if r.emotional_weight is not None else None,
                    }
                    for r in recent_records
                    if r.compact_summary
                ]
            except Exception as compact_err:
                logger.warning("[R-1a] compact_history bundle read failed (non-fatal): %s", compact_err)
            return {
                "state_status": cached.state_status or "heuristic",
                "skeleton_only": False,
                "story_plan": sp,
                "director": dr,
                "last_advanced_turn": progression_ledger.get("last_advanced_turn"),
                "last_validated_turn": progression_ledger.get("last_validated_turn"),
                "progression_ledger": progression_ledger,
                "story_guidance": story_guidance,
                "warnings": warnings_raw if isinstance(warnings_raw, list) else [],
                "generated_at": cached.updated_at.isoformat() if cached.updated_at else None,
                "compact_history": compact_history,
                "compact_history_records": compact_history_records,
                "fetched": True,
            }
        finally:
            db.close()
    except Exception as exc:
        logger.warning("[prepare-turn] narrative_control bundle read failed: %s", exc)
        return None


def _bundle_read_session_state(sid: str) -> dict | None:
    """M-2a: session-state core 5媛??뱀뀡(+HS-1a canonical layer)???쎌뼱 踰덈뱾 dict濡?諛섑솚.
    plugin??fetchSessionState ?뺢퇋???뺤떇??留욊쾶 flat dict瑜?諛섑솚?쒕떎.
    """
    from datetime import datetime, timezone
    try:
        db = SessionLocal()
        try:
            generated_at = datetime.now(timezone.utc).isoformat()
            raw_states = get_all_active_states_for_session(chat_session_id=sid)
            canonical_layers = get_all_canonical_state_layers_for_session(chat_session_id=sid)
            sl_rows = (
                db.query(Storyline)
                .filter(Storyline.chat_session_id == sid, Storyline.suppressed == False)  # noqa: E712
                .order_by(Storyline.pinned.desc(), Storyline.last_turn.desc().nullslast(), Storyline.id.desc())
                .all()
            )
            storylines_data = [
                {
                    "id": r.id, "chat_session_id": r.chat_session_id, "name": r.name,
                    "status": r.status, "current_context": r.current_context,
                    "last_turn": r.last_turn, "pinned": r.pinned,
                }
                for r in sl_rows
            ]
            character_selection = _select_visible_character_states(db, sid)
            characters_data = []
            for entry in character_selection["selected"]:
                latest = entry["row"]
                snapshot = entry["snapshot"]
                characters_data.append(
                    _serialize_character_state_row(
                        latest,
                        snapshot,
                        entry.get("latest_event"),
                        entry.get("recent_events"),
                    )
                )
            wr_rows = (
                db.query(WorldRule)
                .filter(WorldRule.chat_session_id == sid, WorldRule.suppressed == False)  # noqa: E712
                .order_by(WorldRule.pinned.desc(), WorldRule.id.desc())
                .all()
            )
            world_rules_data = [
                {
                    "id": r.id, "chat_session_id": r.chat_session_id,
                    "scope": r.scope, "scope_name": r.scope_name,
                    "category": r.category, "key": r.key, "value_json": r.value_json,
                }
                for r in wr_rows
            ]
            hook_rows = (
                db.query(PendingThread)
                .filter(
                    PendingThread.chat_session_id == sid,
                    PendingThread.status.in_(["open", "paused"]),
                    PendingThread.suppressed == False,  # noqa: E712
                )
                .order_by(PendingThread.pinned.desc(), PendingThread.last_seen_turn.desc(), PendingThread.id.desc())
                .all()
            )
            hooks_data = [
                {
                    "id": r.id, "thread_type": r.thread_type, "title": r.title,
                    "status": r.status, "last_seen_turn": r.last_seen_turn,
                    "chat_session_id": r.chat_session_id,
                }
                for r in hook_rows
            ]
            any_ready = any([raw_states, storylines_data, world_rules_data, hooks_data])
            all_ready = all([raw_states, storylines_data, world_rules_data, hooks_data])
            warnings: list[str] = []
            if character_selection["dropped"]:
                warnings.append(
                    f"{len(character_selection['dropped'])} transient descriptor character(s) omitted from session_state."
                )
            return {
                "status": "ok",
                "chat_session_id": sid,
                "snapshot_status": "ready" if all_ready else ("partial" if any_ready else "empty"),
                "generated_at": generated_at,
                "active_states": raw_states,
                "temporal_state": _build_temporal_state_surface_sc19(raw_states),
                "storylines": storylines_data,
                "characters": characters_data,
                "world_rules": world_rules_data,
                "pending_threads": hooks_data,
                "canonical_state_layer": canonical_layers,
                "section_meta": {},
                "warnings": warnings,
            }
        finally:
            db.close()
    except Exception as exc:
        logger.warning("[prepare-turn] session_state bundle read failed: %s", exc)
        return None


def _bundle_read_continuity_pack(sid: str) -> dict | None:
    """M-2a: _build_continuity_pack_response瑜??ъ슜??continuity-pack 踰덈뱾 dict瑜?諛섑솚."""
    try:
        return _build_continuity_pack_response(sid).model_dump()
    except Exception as exc:
        logger.warning("[prepare-turn] continuity_pack bundle read failed: %s", exc)
        return None


