import re as _re

def _simple_extract_entities(text: str) -> list[str]:
    """M-2b: raw_user_input?먯꽌 ?臾몄옄濡??쒖옉?섎뒗 ?⑥뼱 / ?곗샂?????대쫫??heuristic?쇰줈 異붿텧.
    plugin??extractEntitiesFromText? ?숈씪 ?섏???lightweight 異붿텧.
    """
    if not text:
        return []
    found: list[str] = []
    # ?곗샂?????대쫫 (?쒓뎅???ы븿)
    for m in _re.finditer(r'["""]([\w\s媛-??{2,30})["""]', text):
        candidate = m.group(1).strip()
        if candidate:
            found.append(candidate)
    # ?곷Ц ?臾몄옄 ?쒖옉 ?⑥뼱 (2湲???댁긽)
    for m in _re.finditer(r'\b([A-Z][a-z]{1,30})\b', text):
        candidate = m.group(1)
        if candidate not in found:
            found.append(candidate)
    # ?쒓? 2~8???⑹뼱由?(怨좎쑀紐낆궗 ?꾨낫)
    for m in _re.finditer(r'[媛-??{2,8}', text):
        candidate = m.group(0)
        if candidate not in found:
            found.append(candidate)
    return found[:20]


def _safe_json_loads_q1a(raw: object):
    if isinstance(raw, (dict, list)):
        return raw
    if not isinstance(raw, str):
        return None
    text = raw.strip()
    if not text:
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def _clean_canonical_text_r1a(raw: object, *, max_len: int = 180) -> str:
    text = " ".join(str(raw or "").split()).strip()
    if len(text) > max_len:
        text = text[: max_len - 3] + "..."
    return text


def _summarize_canonical_value_r1a(raw: object, *, preferred_keys: tuple[str, ...] = ()) -> str:
    parsed = _safe_json_loads_q1a(raw)
    parts: list[str] = []
    if isinstance(parsed, dict):
        ordered_keys = list(preferred_keys) + [key for key in parsed.keys() if key not in preferred_keys]
        for key in ordered_keys[:6]:
            value = parsed.get(key)
            if value in (None, "", [], {}):
                continue
            if isinstance(value, (dict, list)):
                summary = _summarize_canonical_value_r1a(value)
            else:
                summary = _clean_canonical_text_r1a(value, max_len=90)
            if summary:
                parts.append(f"{key}: {summary}" if key in preferred_keys else summary)
            if len(parts) >= 3:
                break
    elif isinstance(parsed, list):
        for item in parsed[:3]:
            if isinstance(item, dict):
                label = _clean_canonical_text_r1a(
                    item.get("target") or item.get("name") or item.get("title") or item.get("scope_name") or item.get("character_name"),
                    max_len=40,
                )
                summary = _clean_canonical_text_r1a(
                    item.get("summary") or item.get("summary_text") or item.get("status") or item.get("value_json") or item.get("event_type"),
                    max_len=90,
                )
                if label and summary:
                    parts.append(f"{label}: {summary}")
                else:
                    fallback = _clean_canonical_text_r1a(item, max_len=90)
                    if fallback:
                        parts.append(fallback)
            else:
                summary = _clean_canonical_text_r1a(item, max_len=90)
                if summary:
                    parts.append(summary)
    elif parsed is not None:
        summary = _clean_canonical_text_r1a(parsed, max_len=160)
        if summary:
            parts.append(summary)
    else:
        summary = _clean_canonical_text_r1a(raw, max_len=160)
        if summary:
            parts.append(summary)

    unique_parts: list[str] = []
    for part in parts:
        if part and part not in unique_parts:
            unique_parts.append(part)
    return _clean_canonical_text_r1a("; ".join(unique_parts), max_len=180)


def _canonical_priority_rules_r1b() -> dict:
    return {
        "version": "r1b.v1",
        "mode": "policy_only",
        "characters": {
            "prefer_sources": ["session_state"],
            "conflict_mode": "session_state_source_of_truth",
        },
        "relationships": {
            "prefer_sources": ["character_state", "continuity_pack"],
            "conflict_mode": "stable_state_before_recent_shift",
        },
        "world_rules": {
            "prefer_sources": ["session_state", "continuity_pack"],
            "conflict_mode": "session_state_fill_then_pack",
        },
        "open_obligations": {
            "prefer_source_layers": ["session_state", "continuity_pack"],
            "prefer_types": ["storyline", "continuity_hook"],
            "conflict_mode": "session_state_fill_then_pack",
        },
    }


def _priority_rank_for_canonical_source_r1b(source: str) -> int:
    if source in {"session_state", "character_state"}:
        return 1
    if source == "continuity_pack":
        return 2
    return 3


def _compact_history_promotion_policy_r1c() -> dict:
    return {
        "version": "r1c.v1",
        "mode": "policy_only",
        "status": "unavailable",
        "max_promoted_items": 3,
        "min_emotional_weight": 0.55,
        "always_promote_record_types": ["resolved_arc"],
        "always_promote_origin_types": ["hook"],
        "suppressed_record_types_below_threshold": ["expired_forbidden"],
        "fallback_mode": "text_only_fail_open",
    }


def _coerce_float_r1c(raw: object) -> float | None:
    try:
        if raw is None:
            return None
        return float(raw)
    except Exception:
        return None


def _promote_compact_history_r1c(narrative_control_data: dict | None) -> tuple[list[str], dict, list[dict]]:
    policy = _compact_history_promotion_policy_r1c()
    decisions: list[dict] = []
    text_history = [
        _clean_canonical_text_r1a(item, max_len=180)
        for item in (((narrative_control_data or {}).get("compact_history") or []) if isinstance(narrative_control_data, dict) else [])
        if _clean_canonical_text_r1a(item, max_len=180)
    ]
    if not isinstance(narrative_control_data, dict):
        return [], policy, decisions

    structured_records = [
        item for item in (narrative_control_data.get("compact_history_records") or [])
        if isinstance(item, dict)
    ]
    if not structured_records:
        if text_history:
            policy["status"] = "fallback_text_only"
            return text_history[:4], policy, decisions
        return [], policy, decisions

    policy["status"] = "ready"
    max_items = int(policy.get("max_promoted_items") or 0)
    min_weight = float(policy.get("min_emotional_weight") or 0.0)
    promoted: list[str] = []
    for record in structured_records[:6]:
        summary = _clean_canonical_text_r1a(record.get("compact_summary"), max_len=180)
        if not summary:
            continue
        title = _clean_canonical_text_r1a(record.get("title"), max_len=80)
        record_type = _clean_canonical_text_r1a(record.get("record_type"), max_len=40)
        origin_type = _clean_canonical_text_r1a(record.get("origin_type"), max_len=40)
        emotional_weight = _coerce_float_r1c(record.get("emotional_weight"))
        promoted_flag = False
        reason = "below_promotion_threshold"
        if record_type == "resolved_arc":
            promoted_flag = True
            reason = "resolved_arc_backbone"
        elif origin_type == "hook":
            promoted_flag = True
            reason = "hook_reappearance_value"
        elif emotional_weight is not None and emotional_weight >= min_weight:
            promoted_flag = True
            reason = "high_emotional_weight"
        elif record_type == "expired_forbidden":
            reason = "expired_forbidden_below_threshold"

        if promoted_flag and len(promoted) < max_items:
            promoted.append(summary)
            decisions.append({
                "title": title,
                "record_type": record_type,
                "origin_type": origin_type,
                "emotional_weight": emotional_weight,
                "promoted": True,
                "reason": reason,
                "selected_rank": len(promoted),
                "summary": summary,
            })
        elif promoted_flag:
            decisions.append({
                "title": title,
                "record_type": record_type,
                "origin_type": origin_type,
                "emotional_weight": emotional_weight,
                "promoted": False,
                "reason": "promotion_budget_exceeded",
                "candidate_reason": reason,
                "summary": summary,
            })
        else:
            decisions.append({
                "title": title,
                "record_type": record_type,
                "origin_type": origin_type,
                "emotional_weight": emotional_weight,
                "promoted": False,
                "reason": reason,
                "summary": summary,
            })
    return promoted, policy, decisions


def _build_canonical_ledger_r1a(
    session_state_data: dict | None,
    continuity_pack_data: dict | None,
    narrative_control_data: dict | None,
) -> dict:
    sources_used: list[str] = []
    warnings: list[str] = []
    characters: list[dict] = []
    relationships: list[dict] = []
    world_rules: list[dict] = []
    open_obligations: list[dict] = []
    resolved_compact_history: list[str] = []
    priority_rules = _canonical_priority_rules_r1b()
    priority_decisions: list[dict] = []
    relationship_slots: dict[str, dict[str, dict | None]] = {}
    relationship_order: list[str] = []
    world_rule_slots: dict[tuple[str, str, str], dict] = {}
    world_rule_source_ranks: dict[tuple[str, str, str], int] = {}
    obligation_slots: dict[tuple[str, str], dict] = {}
    obligation_source_ranks: dict[tuple[str, str], int] = {}

    def _record_priority_decision(section: str, payload: dict) -> None:
        decision = {"section": section, **payload}
        if decision not in priority_decisions:
            priority_decisions.append(decision)

    def _ensure_relationship_slot(label: str) -> dict[str, dict | None]:
        if label not in relationship_slots:
            relationship_slots[label] = {"stable": None, "shift": None}
            relationship_order.append(label)
        return relationship_slots[label]

    def _append_relationship(label: object, summary: object, source: str) -> None:
        clean_label = _clean_canonical_text_r1a(label, max_len=40)
        clean_summary = _clean_canonical_text_r1a(summary, max_len=180)
        if not clean_label or not clean_summary:
            return
        slot = _ensure_relationship_slot(clean_label)
        if source == "character_state":
            slot["stable"] = {
                "label": clean_label,
                "summary": clean_summary,
                "source": "character_state",
                "source_layer": "session_state",
                "relationship_role": "stable_state",
                "priority_rank": 1,
                "priority_reason": "session_state_relationship_is_current_canon",
            }
            if slot.get("shift") is not None:
                slot["shift"]["priority_rank"] = 2
        elif source == "continuity_pack":
            stable_summary = ((slot.get("stable") or {}).get("summary") if isinstance(slot.get("stable"), dict) else None)
            if stable_summary == clean_summary:
                return
            slot["shift"] = {
                "label": clean_label,
                "summary": clean_summary,
                "source": "continuity_pack",
                "source_layer": "continuity_pack",
                "relationship_role": "recent_shift",
                "priority_rank": 2 if slot.get("stable") is not None else 1,
                "priority_reason": "continuity_pack_shift_augments_current_relationship_state",
            }

    def _append_world_rule(item: dict, source: str) -> None:
        scope = _clean_canonical_text_r1a(item.get("scope"), max_len=24)
        scope_name = _clean_canonical_text_r1a(item.get("scope_name"), max_len=40)
        key = _clean_canonical_text_r1a(item.get("key"), max_len=40)
        if not key:
            return
        dedupe_key = (scope, scope_name, key)
        source_rank = _priority_rank_for_canonical_source_r1b(source)
        candidate = {
            "scope": scope,
            "scope_name": scope_name,
            "key": key,
            "value_summary": _summarize_canonical_value_r1a(item.get("value_json")),
            "source": source,
            "source_layer": source,
            "priority_rank": 1,
            "priority_reason": "session_state_world_rule_is_current_canon" if source == "session_state" else "continuity_pack_world_rule_fills_missing_slot",
        }
        existing = world_rule_slots.get(dedupe_key)
        if existing is None:
            world_rule_slots[dedupe_key] = candidate
            world_rule_source_ranks[dedupe_key] = source_rank
            return
        existing_rank = int(world_rule_source_ranks.get(dedupe_key) or 99)
        if source_rank < existing_rank:
            _record_priority_decision(
                "world_rules",
                {
                    "slot": "|".join(dedupe_key),
                    "selected_source": source,
                    "suppressed_source": existing.get("source"),
                    "reason": "higher_priority_world_rule_source",
                },
            )
            world_rule_slots[dedupe_key] = candidate
            world_rule_source_ranks[dedupe_key] = source_rank
            return
        if existing.get("source") != source:
            _record_priority_decision(
                "world_rules",
                {
                    "slot": "|".join(dedupe_key),
                    "selected_source": existing.get("source"),
                    "suppressed_source": source,
                    "reason": "session_state_world_rule_beats_pack_duplicate" if existing.get("source") == "session_state" else "existing_world_rule_beats_duplicate",
                },
            )

    def _append_open_obligation(
        kind: str,
        title: object,
        status: object,
        summary: object,
        source: str,
        source_layer: str,
    ) -> None:
        clean_title = _clean_canonical_text_r1a(title, max_len=80)
        clean_kind = _clean_canonical_text_r1a(kind, max_len=32) or "unknown"
        if not clean_title:
            return
        dedupe_key = (clean_kind, clean_title)
        source_rank = 1 if source_layer == "session_state" else 2
        candidate = {
            "kind": clean_kind,
            "title": clean_title,
            "status": _clean_canonical_text_r1a(status, max_len=24),
            "summary": _clean_canonical_text_r1a(summary, max_len=180),
            "source": source,
            "source_layer": source_layer,
            "priority_rank": 1,
            "priority_reason": "session_state_open_obligation_is_current_canon" if source_layer == "session_state" else "continuity_pack_open_obligation_fills_missing_slot",
        }
        existing = obligation_slots.get(dedupe_key)
        if existing is None:
            obligation_slots[dedupe_key] = candidate
            obligation_source_ranks[dedupe_key] = source_rank
            return
        existing_rank = int(obligation_source_ranks.get(dedupe_key) or 99)
        if source_rank < existing_rank:
            _record_priority_decision(
                "open_obligations",
                {
                    "slot": f"{clean_kind}|{clean_title}",
                    "selected_source_layer": source_layer,
                    "suppressed_source_layer": existing.get("source_layer"),
                    "reason": "higher_priority_open_obligation_source",
                },
            )
            obligation_slots[dedupe_key] = candidate
            obligation_source_ranks[dedupe_key] = source_rank
            return
        if existing.get("source_layer") != source_layer:
            _record_priority_decision(
                "open_obligations",
                {
                    "slot": f"{clean_kind}|{clean_title}",
                    "selected_source_layer": existing.get("source_layer"),
                    "suppressed_source_layer": source_layer,
                    "reason": "session_state_open_obligation_beats_pack_duplicate" if existing.get("source_layer") == "session_state" else "existing_open_obligation_beats_duplicate",
                },
            )

    if isinstance(session_state_data, dict):
        sources_used.append("session_state")
        for character in (session_state_data.get("characters") or [])[:6]:
            character_name = _clean_canonical_text_r1a(character.get("character_name"), max_len=40)
            if not character_name:
                continue
            characters.append({
                "character_name": character_name,
                "status_summary": _summarize_canonical_value_r1a(
                    character.get("status_json"),
                    preferred_keys=("location", "emotion", "goal", "status"),
                ),
                "source": "session_state",
                "source_layer": "session_state",
                "priority_rank": 1,
                "priority_reason": "session_state_character_status_is_current_canon",
            })
            relationship_summary = _summarize_canonical_value_r1a(character.get("relationships_json"))
            if relationship_summary:
                _append_relationship(character_name, relationship_summary, "character_state")
        for world_rule in (session_state_data.get("world_rules") or [])[:8]:
            _append_world_rule(world_rule, "session_state")
        for storyline in (session_state_data.get("storylines") or [])[:4]:
            _append_open_obligation(
                "storyline",
                storyline.get("name"),
                storyline.get("status") or "active",
                storyline.get("current_context") or storyline.get("name"),
                "storyline",
                "session_state",
            )
        for hook in (session_state_data.get("pending_threads") or [])[:4]:
            hook_summary = "; ".join(
                part for part in [
                    _clean_canonical_text_r1a(hook.get("owner"), max_len=30),
                    _clean_canonical_text_r1a(hook.get("target"), max_len=30),
                ]
                if part
            )
            _append_open_obligation(
                hook.get("thread_type") or "hook",
                hook.get("title"),
                hook.get("status"),
                hook_summary or hook.get("title"),
                "continuity_hook",
                "session_state",
            )

    if isinstance(continuity_pack_data, dict):
        sources_used.append("continuity_pack")
        for relationship_shift in (continuity_pack_data.get("relationship_shifts") or [])[:4]:
            label = _clean_canonical_text_r1a(relationship_shift.get("character_name") or relationship_shift.get("title"), max_len=40)
            summary = _clean_canonical_text_r1a(
                relationship_shift.get("summary_text") or relationship_shift.get("event_type") or relationship_shift.get("status"),
                max_len=180,
            )
            if label and summary:
                _append_relationship(label, summary, "continuity_pack")
        for world_rule in (continuity_pack_data.get("world_constraints") or [])[:8]:
            _append_world_rule(world_rule, "continuity_pack")
        for storyline in (continuity_pack_data.get("active_storylines") or [])[:4]:
            _append_open_obligation(
                "storyline",
                storyline.get("name"),
                storyline.get("status") or "active",
                storyline.get("current_context") or storyline.get("name"),
                "storyline",
                "continuity_pack",
            )
        for hook in (continuity_pack_data.get("pending_threads") or [])[:4]:
            hook_summary = "; ".join(
                part for part in [
                    _clean_canonical_text_r1a(hook.get("owner"), max_len=30),
                    _clean_canonical_text_r1a(hook.get("target"), max_len=30),
                ]
                if part
            )
            _append_open_obligation(
                hook.get("thread_type") or "hook",
                hook.get("title"),
                hook.get("status"),
                hook_summary or hook.get("title"),
                "continuity_hook",
                "continuity_pack",
            )

    for label in relationship_order:
        slot = relationship_slots.get(label) or {}
        stable_item = slot.get("stable")
        if stable_item:
            relationships.append(stable_item)
    for label in relationship_order:
        slot = relationship_slots.get(label) or {}
        shift_item = slot.get("shift")
        if shift_item:
            relationships.append(shift_item)

    world_rules = sorted(
        world_rule_slots.values(),
        key=lambda item: (
            int(item.get("priority_rank") or 99),
            str(item.get("scope") or ""),
            str(item.get("scope_name") or ""),
            str(item.get("key") or ""),
        ),
    )
    open_obligations = sorted(
        obligation_slots.values(),
        key=lambda item: (
            int(item.get("priority_rank") or 99),
            str(item.get("kind") or ""),
            str(item.get("title") or ""),
        ),
    )

    compact_history = ((narrative_control_data or {}).get("compact_history") or []) if isinstance(narrative_control_data, dict) else []
    compact_history_promotion_policy = _compact_history_promotion_policy_r1c()
    compact_history_promotion_decisions: list[dict] = []
    if compact_history:
        sources_used.append("narrative_control_compact_history")
        resolved_compact_history, compact_history_promotion_policy, compact_history_promotion_decisions = _promote_compact_history_r1c(
            narrative_control_data=narrative_control_data,
        )

    if not characters:
        warnings.append("canonical_ledger: no character canon available")
    if not world_rules:
        warnings.append("canonical_ledger: no world canon available")
    if not open_obligations:
        warnings.append("canonical_ledger: no open obligations available")
    if not resolved_compact_history:
        warnings.append("canonical_ledger: no resolved compact history available")

    if not (characters or relationships or world_rules or open_obligations or resolved_compact_history):
        ledger_status = "empty"
    elif len(sources_used) == 3 and characters and relationships and world_rules and open_obligations and resolved_compact_history:
        ledger_status = "ready"
    else:
        ledger_status = "partial"

    def _section_meta(payload: list | dict) -> dict:
        count = len(payload) if isinstance(payload, list) else (1 if payload else 0)
        return {"count": count, "ready": count > 0}

    return {
        "version": "r1a.v1",
        "ledger_status": ledger_status,
        "mode": "contract_only",
        "sources_used": sources_used,
        "characters": characters,
        "relationships": relationships,
        "world_rules": world_rules,
        "open_obligations": open_obligations,
        "resolved_compact_history": resolved_compact_history,
        "compact_history_promotion": compact_history_promotion_policy,
        "compact_history_promotion_decisions": compact_history_promotion_decisions,
        "priority_rules": priority_rules,
        "priority_decisions": priority_decisions,
        "section_meta": {
            "characters": _section_meta(characters),
            "relationships": _section_meta(relationships),
            "world_rules": _section_meta(world_rules),
            "open_obligations": _section_meta(open_obligations),
            "resolved_compact_history": _section_meta(resolved_compact_history),
        },
        "warnings": warnings,
    }


def _clean_retrieval_text_q1a(raw: object, *, max_len: int = 600) -> str:
    text = " ".join(str(raw or "").split()).strip()
    if len(text) > max_len:
        text = text[: max_len - 3] + "..."
    return text


def _to_float_q1a(value: object) -> float | None:
    try:
        return round(float(value), 4)
    except Exception:
        return None


def _build_retrieval_document_q1a(tier: str, item: dict, sid: str) -> dict | None:
    if not isinstance(item, dict):
        return None

    source_type = str(item.get("source_type") or item.get("source") or tier).strip().lower() or tier
    source_row_id = item.get("id") if isinstance(item.get("id"), int) else None
    turn_index = item.get("turn_index") if isinstance(item.get("turn_index"), int) else None
    from_turn = item.get("from_turn") if isinstance(item.get("from_turn"), int) else None
    to_turn = item.get("to_turn") if isinstance(item.get("to_turn"), int) else None
    title = None
    text = ""
    source_subtype = None
    source_table = None
    metadata: dict = {}

    if tier == "memory":
        raw_summary = item.get("summary_json") or item.get("summary") or item.get("content") or ""
        parsed = _safe_json_loads_q1a(raw_summary)
        if isinstance(parsed, dict):
            text = _clean_retrieval_text_q1a(
                parsed.get("turn_summary") or parsed.get("summary") or parsed.get("text") or raw_summary
            )
        else:
            text = _clean_retrieval_text_q1a(item.get("content") or raw_summary)
        if turn_index is not None:
            from_turn = turn_index
            to_turn = turn_index
        title = (
            f"Memory @ turn {turn_index}"
            if source_type == "memory"
            else f"Chat Log @ turn {turn_index}"
        )
        source_subtype = "semantic_search" if source_type == "memory" else "fallback_verbatim"
        source_table = "memories" if source_type == "memory" else "chat_logs"
        metadata = {
            "importance": item.get("importance"),
            "final_score": item.get("final_score"),
            "semantic_rank_score": _to_float_q1a(item.get("semantic_rank_score")),
            "keyword_overlap_score": _to_float_q1a(item.get("keyword_overlap_score")),
            "hybrid_baseline_score": _to_float_q1a(item.get("hybrid_baseline_score")),
            "soft_bias_score": _to_float_q1a(item.get("soft_bias_score")),
            "speaker_bias_score": _to_float_q1a(item.get("speaker_bias_score")),
            "location_bias_score": _to_float_q1a(item.get("location_bias_score")),
            "storyline_bias_score": _to_float_q1a(item.get("storyline_bias_score")),
            "keyword_overlap_terms": item.get("keyword_overlap_terms"),
            "speaker_bias_terms": item.get("speaker_bias_terms"),
            "location_bias_terms": item.get("location_bias_terms"),
            "storyline_bias_terms": item.get("storyline_bias_terms"),
            "hybrid_baseline_policy_version": item.get("hybrid_baseline_policy_version"),
            "soft_bias_policy_version": item.get("soft_bias_policy_version"),
            "tail_budget_policy_version": item.get("tail_budget_policy_version"),
            "tail_budget_original_rank": item.get("tail_budget_original_rank"),
            "tail_budget_promoted": item.get("tail_budget_promoted"),
            "tail_budget_reason": item.get("tail_budget_reason"),
            "tail_budget_score_gap": _to_float_q1a(item.get("tail_budget_score_gap")),
            "archive_wing": item.get("archive_wing") or item.get("library_wing"),
            "archive_room": item.get("archive_room") or item.get("library_room"),
            "role": item.get("role"),
        }
    elif tier == "episode":
        text = _clean_retrieval_text_q1a(item.get("summary_text"))
        title = f"Episode {from_turn}-{to_turn}" if from_turn is not None and to_turn is not None else "Episode Summary"
        source_subtype = "semantic_search"
        source_table = "episode_summaries"
        metadata = {
            "key_entities": item.get("key_entities"),
            "key_events": item.get("key_events"),
            "open_loops_json": item.get("open_loops_json"),
            "relationship_changes_json": item.get("relationship_changes_json"),
        }
    elif tier == "chapter":
        text = _clean_retrieval_text_q1a(item.get("resume_text") or item.get("summary_text"))
        chapter_index = item.get("chapter_index")
        title = item.get("chapter_title") or (
            f"Chapter {chapter_index}" if chapter_index is not None else "Chapter Summary"
        )
        source_subtype = "legacy_keyword_fallback" if source_type == "chat_log_fallback" else "semantic_search"
        source_table = "chat_logs" if source_type == "chat_log_fallback" else "chapter_summaries"
        metadata = {
            "chapter_index": chapter_index,
            "open_loops_json": item.get("open_loops_json"),
            "relationship_changes_json": item.get("relationship_changes_json"),
            "world_changes_json": item.get("world_changes_json"),
            "callback_candidates_json": item.get("callback_candidates_json"),
        }
    elif tier == "arc":
        text = _clean_retrieval_text_q1a(item.get("arc_resume_text") or item.get("core_conflict"))
        arc_index = item.get("arc_index")
        title = item.get("arc_name") or (f"Arc {arc_index}" if arc_index is not None else "Arc Summary")
        source_subtype = "semantic_search"
        source_table = "arc_summaries"
        metadata = {
            "arc_index": arc_index,
            "arc_status": item.get("arc_status"),
            "active_promises_json": item.get("active_promises_json"),
            "unresolved_debts_json": item.get("unresolved_debts_json"),
            "resolved_payoffs_json": item.get("resolved_payoffs_json"),
            "callback_candidates_json": item.get("callback_candidates_json"),
            "irreversible_turns_json": item.get("irreversible_turns_json"),
            "callback_debts_json": item.get("callback_debts_json"),
            "relationship_pivots_json": item.get("relationship_pivots_json"),
            "future_payoff_candidates_json": item.get("future_payoff_candidates_json"),
        }
    elif tier == "saga":
        text = _clean_retrieval_text_q1a(item.get("resume_pack_text") or item.get("saga_summary"), max_len=900)
        title = item.get("era_label") or (
            f"Saga {from_turn}-{to_turn}" if from_turn is not None and to_turn is not None else "Saga Digest"
        )
        source_subtype = "semantic_search"
        source_table = "saga_digests"
        metadata = {
            "persistent_facts_json": item.get("persistent_facts_json"),
            "never_drop_candidates_json": item.get("never_drop_candidates_json"),
        }
    else:
        return None

    ann_metadata = {
        "base_similarity": _to_float_q1a(item.get("ann_base_similarity") or item.get("similarity")),
        "rerank_score": _to_float_q1a(item.get("ann_rerank_score")),
        "recency_score": _to_float_q1a(item.get("ann_recency_score")),
        "importance_score": _to_float_q1a(item.get("ann_importance_score")),
        "pinned_hint": item.get("ann_pinned_hint") if isinstance(item.get("ann_pinned_hint"), bool) else None,
        "pinned_score": _to_float_q1a(item.get("ann_pinned_score")),
        "status": item.get("ann_status"),
        "status_score": _to_float_q1a(item.get("ann_status_score")),
        "bucket_distance": item.get("ann_bucket_distance") if isinstance(item.get("ann_bucket_distance"), int) else None,
        "candidate_rank": item.get("ann_candidate_rank") if isinstance(item.get("ann_candidate_rank"), int) else None,
        "merge_rank": item.get("ann_merge_rank") if isinstance(item.get("ann_merge_rank"), int) else None,
        "merge_pass": item.get("ann_merge_pass") if isinstance(item.get("ann_merge_pass"), str) else None,
    }
    ann_metadata = {key: value for key, value in ann_metadata.items() if value is not None}
    if ann_metadata:
        metadata["ann"] = ann_metadata

    chroma_live_metadata = {
        "contract_version": item.get("chroma_live_contract_version"),
        "state": item.get("chroma_live_state"),
        "mode": item.get("chroma_live_mode"),
        "candidate_limit": item.get("chroma_live_candidate_limit") if isinstance(item.get("chroma_live_candidate_limit"), int) else None,
        "candidate_count": item.get("chroma_live_candidate_count") if isinstance(item.get("chroma_live_candidate_count"), int) else None,
        "hydrated_count": item.get("chroma_live_hydrated_count") if isinstance(item.get("chroma_live_hydrated_count"), int) else None,
        "hydrated": item.get("chroma_live_hydrated") if isinstance(item.get("chroma_live_hydrated"), bool) else None,
        "truth_authority": item.get("chroma_live_truth_authority"),
        "supporting_only": item.get("chroma_live_supporting_only") if isinstance(item.get("chroma_live_supporting_only"), bool) else None,
        "support_surface_mode": item.get("chroma_live_support_surface_mode"),
        "cannot_override_current_user_input": item.get("chroma_live_cannot_override_current_user_input") if isinstance(item.get("chroma_live_cannot_override_current_user_input"), bool) else None,
        "cannot_override_verified_direct_evidence": item.get("chroma_live_cannot_override_verified_direct_evidence") if isinstance(item.get("chroma_live_cannot_override_verified_direct_evidence"), bool) else None,
        "precedence_ceiling": item.get("chroma_live_precedence_ceiling"),
        "hydration_source_table": item.get("chroma_live_hydration_source_table"),
        "hydration_source_row_id": item.get("chroma_live_hydration_source_row_id") if isinstance(item.get("chroma_live_hydration_source_row_id"), int) else None,
        "merge_candidate_limit": item.get("chroma_live_merge_candidate_limit") if isinstance(item.get("chroma_live_merge_candidate_limit"), int) else None,
        "merged": item.get("chroma_live_merged") if isinstance(item.get("chroma_live_merged"), bool) else None,
        "merge_rank": item.get("chroma_live_merge_rank") if isinstance(item.get("chroma_live_merge_rank"), int) else None,
        "merge_reason": item.get("chroma_live_merge_reason"),
        "merge_score_gap": _to_float_q1a(item.get("chroma_live_merge_score_gap")),
        "merge_policy_version": item.get("chroma_live_merge_policy_version"),
        "candidate_rank": item.get("chroma_live_candidate_rank") if isinstance(item.get("chroma_live_candidate_rank"), int) else None,
        "distance": _to_float_q1a(item.get("chroma_live_distance")),
        "reason": item.get("chroma_live_reason"),
    }
    chroma_live_metadata = {key: value for key, value in chroma_live_metadata.items() if value is not None}
    if chroma_live_metadata:
        metadata["chroma_live"] = chroma_live_metadata

    metadata = {key: value for key, value in metadata.items() if value is not None}
    source_key = source_row_id if source_row_id is not None else (turn_index if turn_index is not None else f"{from_turn}-{to_turn}")
    doc = RetrievalDocumentQ1A(
        document_id=f"{tier}:{source_key}",
        tier=tier,
        source_type=source_type,
        source_subtype=source_subtype,
        source_row_id=source_row_id,
        source_table=source_table,
        chat_session_id=str(item.get("chat_session_id") or sid),
        from_turn=from_turn,
        to_turn=to_turn,
        turn_index=turn_index,
        title=str(title) if title is not None else None,
        text=text,
        similarity=_to_float_q1a(item.get("similarity")),
        created_at=item.get("created_at"),
        query_matched=True,
        metadata=metadata,
    )
    return doc.model_dump()


def _bundle_retrieval_documents_q1a(
    *,
    sid: str,
    search_items: list[dict],
    episode_items: list[dict],
    chapter_items: list[dict],
    arc_items: list[dict],
    saga_items: list[dict],
) -> list[dict]:
    documents: list[dict] = []
    for item in search_items:
        doc = _build_retrieval_document_q1a("memory", item, sid)
        if doc:
            documents.append(doc)
    for tier, items in (
        ("episode", episode_items),
        ("chapter", chapter_items),
        ("arc", arc_items),
        ("saga", saga_items),
    ):
        for item in items:
            doc = _build_retrieval_document_q1a(tier, item, sid)
            if doc:
                documents.append(doc)
    return documents


def _update_retrieval_index_q1b(sid: str, documents: list[dict]) -> dict:
    runtime = retrieval_index_registry.get_runtime_config()
    if runtime.get("mode") != "shadow":
        snapshot = retrieval_index_registry.snapshot(sid)
        return {**snapshot, "reason": "runtime_toggle_off"}

    try:
        return retrieval_index_registry.replace_session_documents(
            sid,
            documents,
            reason="prepare_turn_refresh",
        )
    except Exception as exc:
        logger.warning("[prepare-turn] retrieval index update failed: %s", exc)
        return {
            "status": "degraded",
            "index_version": retrieval_index_registry.INDEX_VERSION,
            "chat_session_id": sid,
            "session_partitioned": True,
            "partition_count": 0,
            "document_count": 0,
            "tier_counts": {tier: 0 for tier in retrieval_index_registry.ALLOWED_TIERS},
            "source_type_counts": {},
            "updated_at": None,
            "reason": "index_update_failed",
        }


def _mark_retrieval_index_dirty_q1c(
    sid: str,
    *,
    reason: str,
    turn_index: int | None = None,
) -> dict | None:
    if not retrieval_index_registry.is_shadow_mode_enabled():
        return retrieval_index_registry.snapshot(sid)

    try:
        return retrieval_index_registry.mark_session_dirty(
            sid,
            reason=reason,
            turn_index=turn_index,
        )
    except Exception as exc:
        logger.warning("[retrieval-index] mark dirty failed: %s", exc)
        return None


def _discard_retrieval_index_q1c(
    sid: str,
    *,
    reason: str,
    turn_index: int | None = None,
) -> dict | None:
    if not retrieval_index_registry.is_shadow_mode_enabled():
        return retrieval_index_registry.snapshot(sid)

    try:
        return retrieval_index_registry.discard_session(
            sid,
            reason=reason,
            turn_index=turn_index,
        )
    except Exception as exc:
        logger.warning("[retrieval-index] discard failed: %s", exc)
        return None


def _empty_ann_candidate_snapshot_q2a(
    sid: str,
    *,
    status: str = "empty",
    reason: str | None = None,
    context_window_profile: str = "mid_context_300k",
) -> dict:
    normalized_profile = (
        context_window_profile
        if context_window_profile in _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE
        else "mid_context_300k"
    )
    active_overlap_min = float(
        _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE.get(
            normalized_profile,
            _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO,
        )
    )
    snapshot = {
        "status": status,
        "version": "q2a.v1",
        "chat_session_id": sid,
        "source": "summary_ann_shadow",
        "context_window_profile": normalized_profile,
        "overlap_guard_version": _S1F_LONG_TIER_ANN_GUARD_VERSION,
        "query_embedding_ready": False,
        "default_takeover_applied": False,
        "default_takeover_reason": "not_evaluated",
        "default_takeover_policy": "benchmark_guard_v1",
        "default_takeover_overlap_ratio_min": active_overlap_min,
        "default_takeover_overlap_ratio_profile_map": {
            key: float(value)
            for key, value in _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE.items()
        },
        "benchmark": {
            "status": "skipped" if reason else "empty",
            "strategy": "full_scan_rerank_merge_v1",
            "timeout_budget_ms": 250,
            "shadow_selection_latency_ms": 0.0,
            "baseline_selection_latency_ms": 0.0,
            "latency_delta_ms": 0.0,
            "latency_improved": False,
            "shadow_candidate_count": 0,
            "baseline_candidate_count": 0,
            "shadow_tier_diversity": 0,
            "baseline_tier_diversity": 0,
            "diversity_delta": 0,
            "diversity_guard_ok": True,
            "overlap_count": 0,
            "overlap_ratio": 0.0,
            "top_hit_match": False,
            "shadow_tier_sequence": [],
            "baseline_tier_sequence": [],
        },
        "rerank_applied": False,
        "rerank_strategy": "metadata_hint_v1",
        "merge_applied": False,
        "merge_policy": "tier_head_then_rerank_v1",
        "merged_tier_sequence": [],
        "merged_items": [],
        "candidate_limit_per_tier": 0,
        "candidate_count": 0,
        "tier_counts": {tier: 0 for tier in ("episode", "chapter", "arc", "saga")},
        "indexed_row_counts": {tier: 0 for tier in ("episode", "chapter", "arc", "saga")},
        "bucket_counts": {tier: 0 for tier in ("episode", "chapter", "arc", "saga")},
        "filtered_out_counts": {tier: 0 for tier in ("episode", "chapter", "arc", "saga")},
        "filtered_out_reasons": {tier: {} for tier in ("episode", "chapter", "arc", "saga")},
        "filtered_out_total": 0,
        "fallback_tiers": [],
        "document_schema_version": _RETRIEVAL_DOCUMENT_SCHEMA_Q1A["version"],
        "documents": [],
    }
    if reason:
        snapshot["reason"] = reason
        snapshot["benchmark"]["reason"] = reason
        snapshot["default_takeover_reason"] = reason
    return snapshot


