def _build_q20a_relative_label_catalog() -> tuple[dict, ...]:
    catalog: list[dict] = []
    seen_keys: set[str] = set()
    for locale_key, locale_pack in (_SC19_RELATION_SCHEMA.get("locale_packs") or {}).items():
        if not isinstance(locale_pack, dict):
            continue
        for label in (locale_pack.get("compact_relative_label_rules") or {}):
            clean_label = " ".join(str(label or "").split()).strip()
            token_key = _normalize_sc19_relative_lookup_key(clean_label, mode="compact_casefold")
            if not clean_label or not token_key or token_key in seen_keys:
                continue
            normalized_fields = _normalize_relative_label_fields_sc19(
                clean_label,
                active_locale_keys=(str(locale_key),),
            )
            if not normalized_fields:
                continue
            catalog.append(
                {
                    "cue_token": clean_label,
                    "token_key": token_key,
                    "normalized_fields": normalized_fields,
                }
            )
            seen_keys.add(token_key)
    catalog.sort(
        key=lambda item: len(str(item.get("token_key") or "")),
        reverse=True,
    )
    return tuple(catalog)


_Q20A_RELATIVE_LABEL_CATALOG = _build_q20a_relative_label_catalog()
_Q20A_RELATIVE_LABEL_TOKENS = tuple(
    str(item.get("cue_token") or "")
    for item in _Q20A_RELATIVE_LABEL_CATALOG
    if str(item.get("cue_token") or "")
)
_Q20A_RELATIVE_LABEL_BY_KEY = {
    str(item.get("token_key") or ""): item
    for item in _Q20A_RELATIVE_LABEL_CATALOG
    if str(item.get("token_key") or "")
}
