_INTENT_ROUTING_RUNTIME_VERSION = "v0c.v1"
_INTENT_ROUTING_ALLOWED_MODES = ("single_query_shared", "per_intent_shadow")
_intent_routing_runtime_lock = _threading.RLock()
_intent_routing_runtime_mode = "single_query_shared"
_intent_routing_runtime_updated_at = datetime.now(timezone.utc).astimezone(timezone(timedelta(hours=9))).strftime("%Y-%m-%d %H:%M:%S")
_intent_routing_runtime_reason = "default"


def _resolve_ann_takeover_overlap_min_s1f(context_window_profile: str | None) -> float:
    profile = str(context_window_profile or "").strip()
    if profile in _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE:
        return float(_Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE[profile])
    return float(_Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE["mid_context_300k"])


def get_intent_routing_runtime_config() -> dict:
    with _intent_routing_runtime_lock:
        return {
            "mode": _intent_routing_runtime_mode,
            "updated_at": _intent_routing_runtime_updated_at,
            "reason": _intent_routing_runtime_reason,
            "version": _INTENT_ROUTING_RUNTIME_VERSION,
            "supported_modes": list(_INTENT_ROUTING_ALLOWED_MODES),
        }


def set_intent_routing_runtime_mode(mode: str, *, reason: str = "api_runtime_toggle") -> dict:
    normalized_mode = " ".join(str(mode or "").split()).strip().lower()
    if normalized_mode not in _INTENT_ROUTING_ALLOWED_MODES:
        raise ValueError(
            f"unsupported intent routing mode: {mode!r} (allowed: {', '.join(_INTENT_ROUTING_ALLOWED_MODES)})"
        )

    now_text = datetime.now(timezone.utc).astimezone(timezone(timedelta(hours=9))).strftime("%Y-%m-%d %H:%M:%S")
    global _intent_routing_runtime_mode, _intent_routing_runtime_updated_at, _intent_routing_runtime_reason
    with _intent_routing_runtime_lock:
        previous_mode = _intent_routing_runtime_mode
        _intent_routing_runtime_mode = normalized_mode
        _intent_routing_runtime_updated_at = now_text
        _intent_routing_runtime_reason = reason

    return {
        "mode": normalized_mode,
        "previous_mode": previous_mode,
        "updated_at": now_text,
        "reason": reason,
        "version": _INTENT_ROUTING_RUNTIME_VERSION,
        "supported_modes": list(_INTENT_ROUTING_ALLOWED_MODES),
    }


def _collect_query_class_signal_terms_qr1a(text: str, tokens: tuple[str, ...]) -> list[str]:
    normalized_text = " ".join(str(text or "").split()).strip()
    if not normalized_text:
        return []

    haystack = f" {normalized_text.casefold()} "
    compact_haystack = re.sub(r"\s+", "", haystack)
    matched_terms: list[str] = []
    seen_terms: set[str] = set()
    for token in tokens:
        normalized = " ".join(str(token or "").split()).strip()
        if not normalized:
            continue
        folded = normalized.casefold()
        compact = re.sub(r"\s+", "", folded)
        if f" {folded} " in haystack or folded in haystack or (compact and compact in compact_haystack):
            dedupe_key = compact or folded
            if dedupe_key in seen_terms:
                continue
            seen_terms.add(dedupe_key)
            matched_terms.append(normalized)
    return matched_terms


def _contains_query_class_signal_qr1a(text: str, tokens: tuple[str, ...]) -> bool:
    return bool(_collect_query_class_signal_terms_qr1a(text, tokens))


def _get_query_class_signal_rule_qr1a(query_class: str) -> dict:
    return dict(_QR1A_QUERY_CLASS_SIGNAL_RULES.get(query_class) or {})


def _get_query_class_description_qr1a(query_class: str) -> str:
    return str(_get_query_class_signal_rule_qr1a(query_class).get("description") or query_class)


def _get_query_class_lexical_cues_qr1a(query_class: str) -> tuple[str, ...]:
    rule = _get_query_class_signal_rule_qr1a(query_class)
    raw_tokens = rule.get("lexical_cue_tokens") or ()
    return tuple(str(token) for token in raw_tokens if str(token or "").strip())


def _dedupe_query_terms_q20a(*term_groups: list[str]) -> list[str]:
    unique_terms: list[str] = []
    seen_terms: set[str] = set()
    for group in term_groups:
        for term in group or []:
            clean_term = " ".join(str(term or "").split()).strip()
            if not clean_term:
                continue
            dedupe_key = clean_term.casefold()
            if dedupe_key in seen_terms:
                continue
            unique_terms.append(clean_term)
            seen_terms.add(dedupe_key)
    return unique_terms


def _collect_relative_label_matches_q20a(text: str) -> list[dict]:
    matched_terms = _collect_query_class_signal_terms_qr1a(text, _Q20A_RELATIVE_LABEL_TOKENS)
    matches: list[dict] = []
    seen_keys: set[str] = set()
    for term in matched_terms:
        token_key = _normalize_sc19_relative_lookup_key(term, mode="compact_casefold")
        if token_key in seen_keys:
            continue
        entry = _Q20A_RELATIVE_LABEL_BY_KEY.get(token_key)
        if not isinstance(entry, dict):
            continue
        matches.append(dict(entry))
        seen_keys.add(token_key)
    return matches


def _is_current_day_label_q20a(relative_fields: dict) -> bool:
    return (
        str(relative_fields.get("offset_unit") or "unknown") == "day"
        and relative_fields.get("offset_value_min") == 0
        and relative_fields.get("offset_value_max") == 0
        and str(relative_fields.get("precision") or "unknown") == "exact"
    )


def _resolve_relative_profile_q20a(relative_fields: dict) -> dict | None:
    signature = (
        str(relative_fields.get("offset_unit") or "unknown"),
        relative_fields.get("offset_value_min"),
        relative_fields.get("offset_value_max"),
        str(relative_fields.get("precision") or "unknown"),
    )
    profile = _Q20A_RELATIVE_EXPANSION_PROFILES.get(signature)
    return dict(profile) if isinstance(profile, dict) else None


def _build_temporal_query_expansion_q20a(shared_query: str) -> dict:
    base_payload = {
        "version": _Q20A_TEMPORAL_QUERY_EXPANSION_VERSION,
        "status": "none",
        "mode": "query_builder_contract_only",
        "focus_mode": "none",
        "range_kind": "none",
        "granularity": "none",
        "cue_terms": [],
        "prefer_current_truth": False,
        "prefer_event_retrieval": False,
        "prefer_validity_window": False,
        "note_surface": "temporal_query_expansion_contract",
    }

    normalized_query = " ".join(str(shared_query or "").split()).strip()
    if not normalized_query:
        return base_payload

    relative_label_matches = _collect_relative_label_matches_q20a(normalized_query)
    current_day_terms = [
        str(entry.get("cue_token") or "")
        for entry in relative_label_matches
        if _is_current_day_label_q20a(entry.get("normalized_fields") or {})
    ]
    current_clock_anchor_terms = _collect_query_class_signal_terms_qr1a(
        normalized_query,
        _Q20A_CURRENT_CLOCK_ANCHOR_CUE_TOKENS,
    )
    current_clock_day_query_terms = _collect_query_class_signal_terms_qr1a(
        normalized_query,
        _Q20A_CURRENT_CLOCK_DAY_QUERY_TOKENS,
    )

    if current_clock_day_query_terms or (current_clock_anchor_terms and current_day_terms):
        return {
            **base_payload,
            "status": "expanded",
            "focus_mode": "current_clock",
            "range_kind": "current_anchor",
            "granularity": "day",
            "cue_terms": _dedupe_query_terms_q20a(
                current_clock_anchor_terms,
                current_clock_day_query_terms,
                current_day_terms,
            ),
            "prefer_current_truth": True,
            "prefer_event_retrieval": False,
            "prefer_validity_window": False,
        }

    for entry in relative_label_matches:
        profile = _resolve_relative_profile_q20a(entry.get("normalized_fields") or {})
        if not profile:
            continue
        return {
            **base_payload,
            "status": "expanded",
            "focus_mode": str(profile.get("focus_mode") or "none"),
            "range_kind": str(profile.get("range_kind") or "none"),
            "granularity": str(profile.get("granularity") or "none"),
            "cue_terms": [str(entry.get("cue_token") or "")],
            "prefer_current_truth": bool(profile.get("prefer_current_truth") or False),
            "prefer_event_retrieval": bool(profile.get("prefer_event_retrieval") or False),
            "prefer_validity_window": bool(profile.get("prefer_validity_window") or False),
        }

    generic_temporal_terms = _collect_query_class_signal_terms_qr1a(
        normalized_query,
        _get_query_class_lexical_cues_qr1a("temporal"),
    )
    if generic_temporal_terms:
        return {
            **base_payload,
            "status": "expanded",
            "focus_mode": "timeline_order",
            "range_kind": "chronology",
            "granularity": "relative_order",
            "cue_terms": generic_temporal_terms,
            "prefer_current_truth": False,
            "prefer_event_retrieval": True,
            "prefer_validity_window": True,
        }

    return base_payload


def _build_temporal_validity_read_policy_q20b(temporal_query_expansion: dict | None) -> dict:
    expansion = dict(temporal_query_expansion or {}) if isinstance(temporal_query_expansion, dict) else {}
    focus_mode = str(expansion.get("focus_mode") or "none")
    range_kind = str(expansion.get("range_kind") or "none")
    base_payload = {
        "version": _Q20B_TEMPORAL_VALIDITY_READ_POLICY_VERSION,
        "status": "default",
        "mode": "query_builder_contract_only",
        "temporal_focus_mode": focus_mode,
        "temporal_range_kind": range_kind,
        "read_priority": "shared_default",
        "current_truth_read_mode": "defer",
        "old_truth_read_mode": "off",
        "separation_rule": "follow_primary_query_class",
        "note_surface": "temporal_validity_read_contract",
    }

    if str(expansion.get("status") or "none") != "expanded":
        return base_payload

    rule = _Q20B_TEMPORAL_VALIDITY_READ_RULES.get((focus_mode, range_kind))
    if not isinstance(rule, dict):
        rule = {
            "read_priority": (
                "current_truth_first"
                if bool(expansion.get("prefer_current_truth"))
                else "bounded_validity_window_first"
                if bool(expansion.get("prefer_validity_window"))
                else "exact_past_event_first"
                if bool(expansion.get("prefer_event_retrieval"))
                else "shared_default"
            ),
            "current_truth_read_mode": "primary" if bool(expansion.get("prefer_current_truth")) else "defer",
            "old_truth_read_mode": (
                "bounded_window_lane"
                if bool(expansion.get("prefer_validity_window"))
                else "exact_event_lane"
                if bool(expansion.get("prefer_event_retrieval"))
                else "off"
            ),
            "separation_rule": (
                "current_truth_only"
                if bool(expansion.get("prefer_current_truth"))
                else "window_before_current_compare"
                if bool(expansion.get("prefer_validity_window"))
                else "separate_current_and_old_truth"
                if bool(expansion.get("prefer_event_retrieval"))
                else "follow_primary_query_class"
            ),
        }

    return {
        **base_payload,
        "status": "defined",
        "read_priority": str(rule.get("read_priority") or "shared_default"),
        "current_truth_read_mode": str(rule.get("current_truth_read_mode") or "defer"),
        "old_truth_read_mode": str(rule.get("old_truth_read_mode") or "off"),
        "separation_rule": str(rule.get("separation_rule") or "follow_primary_query_class"),
    }


