def _normalize_entity_index_text_q20f(value: object, *, compact: bool = False) -> str:
    text = " ".join(str(value or "").split()).strip().casefold()
    if not text:
        return ""
    text = re.sub(r"[^\w\s]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if compact:
        return re.sub(r"\s+", "", text)
    return text


def _query_contains_structured_label_q20f(shared_query: str, label: str) -> bool:
    normalized = _normalize_entity_index_text_q20f(shared_query)
    normalized_label = _normalize_entity_index_text_q20f(label)
    if not normalized or not normalized_label:
        return False

    query_tokens = [token for token in normalized.split() if token]
    label_tokens = [token for token in normalized_label.split() if token]
    if not query_tokens or not label_tokens:
        return False

    compact_label = "".join(label_tokens)
    max_window_size = max(1, len(label_tokens))
    for start_index in range(len(query_tokens)):
        compact_candidate = ""
        for offset in range(max_window_size):
            token_index = start_index + offset
            if token_index >= len(query_tokens):
                break
            compact_candidate += query_tokens[token_index]
            if compact_candidate.startswith(compact_label):
                return True
            if len(compact_candidate) >= len(compact_label):
                break
    return False


def _append_entity_index_entry_q20f(
    entries: list[dict],
    seen_keys: set[tuple[str, str]],
    *,
    label: object,
    bucket: str,
    source: str,
) -> None:
    clean_label = " ".join(str(label or "").split()).strip()
    match_key = _normalize_entity_index_text_q20f(clean_label, compact=True)
    if not clean_label or not match_key:
        return
    dedupe_key = (bucket, match_key)
    if dedupe_key in seen_keys:
        return
    seen_keys.add(dedupe_key)
    entries.append(
        {
            "label": clean_label,
            "bucket": bucket,
            "source": source,
            "match_key": match_key,
        }
    )


def _load_relationship_entries_q20f(raw_value: object) -> list[dict]:
    if isinstance(raw_value, list):
        return [item for item in raw_value if isinstance(item, dict)]
    if not isinstance(raw_value, str):
        return []
    raw_text = raw_value.strip()
    if not raw_text:
        return []
    try:
        parsed = json.loads(raw_text)
    except Exception:
        return []
    if not isinstance(parsed, list):
        return []
    return [item for item in parsed if isinstance(item, dict)]


def _build_lightweight_entity_index_catalog_q20f(
    *,
    session_state_data: dict | None,
    continuity_pack_data: dict | None,
) -> list[dict]:
    entries: list[dict] = []
    seen_keys: set[tuple[str, str]] = set()
    session_state = session_state_data or {}
    continuity_pack = continuity_pack_data or {}

    for row in (session_state.get("characters") or []):
        if not isinstance(row, dict):
            continue
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=row.get("character_name"),
            bucket="character",
            source="session_state.characters",
        )
        for rel_entry in _load_relationship_entries_q20f(row.get("relationships_json"))[:6]:
            _append_entity_index_entry_q20f(
                entries,
                seen_keys,
                label=rel_entry.get("target"),
                bucket="relationship_target",
                source="session_state.relationships_json",
            )

    for rule in (session_state.get("world_rules") or []):
        if not isinstance(rule, dict):
            continue
        scope = str(rule.get("scope") or "").strip().lower()
        if scope not in {"location", "region", "place", "area"}:
            continue
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=rule.get("scope_name") or rule.get("key"),
            bucket="location",
            source="session_state.world_rules",
        )

    for hook in (session_state.get("pending_threads") or []):
        if not isinstance(hook, dict):
            continue
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=hook.get("owner"),
            bucket="pending_thread_owner",
            source="session_state.pending_threads",
        )
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=hook.get("target"),
            bucket="pending_thread_target",
            source="session_state.pending_threads",
        )

    for rule in (continuity_pack.get("world_constraints") or []):
        if not isinstance(rule, dict):
            continue
        scope = str(rule.get("scope") or "").strip().lower()
        if scope not in {"location", "region", "place", "area"}:
            continue
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=rule.get("scope_name") or rule.get("key"),
            bucket="location",
            source="continuity_pack.world_constraints",
        )

    for hook in (continuity_pack.get("pending_threads") or []):
        if not isinstance(hook, dict):
            continue
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=hook.get("owner"),
            bucket="pending_thread_owner",
            source="continuity_pack.pending_threads",
        )
        _append_entity_index_entry_q20f(
            entries,
            seen_keys,
            label=hook.get("target"),
            bucket="pending_thread_target",
            source="continuity_pack.pending_threads",
        )

    return entries


def _resolve_entity_index_match_position_q20f(shared_query: str, label: str) -> int:
    normalized_query = _normalize_entity_index_text_q20f(shared_query)
    normalized_label = _normalize_entity_index_text_q20f(label)
    if normalized_query and normalized_label:
        position = normalized_query.find(normalized_label)
        if position >= 0:
            return position
    compact_query = _normalize_entity_index_text_q20f(shared_query, compact=True)
    compact_label = _normalize_entity_index_text_q20f(label, compact=True)
    if compact_query and compact_label:
        position = compact_query.find(compact_label)
        if position >= 0:
            return position
    return 10**6


def _build_lightweight_entity_index_q20f(
    *,
    shared_query: str,
    session_state_data: dict | None,
    continuity_pack_data: dict | None,
) -> dict:
    base_payload = {
        "version": _Q20F_LIGHTWEIGHT_ENTITY_INDEX_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "index_mode": "off",
        "activation_rule": "structured_focus_terms_only",
        "focus_terms": [],
        "index_entries": [],
        "bucket_counts": {},
        "source_catalogs": [],
        "generic_entity_tokens_trusted": False,
        "boost_authority": "soft_boost_only",
        "graph_support_mode": "deferred_to_20_2b",
        "note_surface": "lightweight_entity_index_contract",
    }

    normalized_query = _normalize_entity_index_text_q20f(shared_query)
    if not normalized_query:
        return base_payload

    catalog = _build_lightweight_entity_index_catalog_q20f(
        session_state_data=session_state_data,
        continuity_pack_data=continuity_pack_data,
    )
    if not catalog:
        return base_payload

    matched_entries: list[dict] = []
    for entry in catalog:
        label = str(entry.get("label") or "")
        if not label:
            continue
        if _query_contains_structured_label_q20f(shared_query, label):
            matched_entries.append(
                {
                    "label": label,
                    "bucket": str(entry.get("bucket") or "unknown"),
                    "source": str(entry.get("source") or "unknown"),
                    "position": _resolve_entity_index_match_position_q20f(shared_query, label),
                }
            )

    if not matched_entries:
        return base_payload

    matched_entries.sort(
        key=lambda item: (
            int(item.get("position")) if isinstance(item.get("position"), int) else 10**6,
            int(_Q20F_BUCKET_PRIORITY.get(str(item.get("bucket") or "unknown"), 99)),
            str(item.get("label") or "").casefold(),
        )
    )

    focus_terms: list[str] = []
    seen_terms: set[str] = set()
    source_catalogs: list[str] = []
    seen_sources: set[str] = set()
    bucket_counts: dict[str, int] = {}
    index_entries: list[dict] = []

    for entry in matched_entries:
        label = str(entry.get("label") or "")
        bucket = str(entry.get("bucket") or "unknown")
        source = str(entry.get("source") or "unknown")
        if label.casefold() not in seen_terms:
            focus_terms.append(label)
            seen_terms.add(label.casefold())
        if source not in seen_sources:
            source_catalogs.append(source)
            seen_sources.add(source)
        bucket_counts[bucket] = int(bucket_counts.get(bucket) or 0) + 1
        index_entries.append(
            {
                "label": label,
                "bucket": bucket,
                "source": source,
            }
        )

    return {
        **base_payload,
        "status": "defined",
        "index_mode": "structured_entity_side_index",
        "focus_terms": focus_terms,
        "index_entries": index_entries,
        "bucket_counts": bucket_counts,
        "source_catalogs": source_catalogs,
    }


def _build_graph_like_support_catalog_q20g(
    *,
    session_state_data: dict | None,
    continuity_pack_data: dict | None,
) -> list[dict]:
    catalog: list[dict] = []
    seen_keys: set[tuple[str, str, str]] = set()
    session_state = session_state_data or {}
    continuity_pack = continuity_pack_data or {}

    for row in (session_state.get("characters") or []):
        if not isinstance(row, dict):
            continue
        anchor_label = " ".join(str(row.get("character_name") or "").split()).strip()
        if not anchor_label:
            continue
        for rel_entry in _load_relationship_entries_q20f(row.get("relationships_json"))[:6]:
            target_label = " ".join(str(rel_entry.get("target") or "").split()).strip()
            if not target_label:
                continue
            dedupe_key = (anchor_label.casefold(), target_label.casefold(), "relationship_target_pair")
            if dedupe_key in seen_keys:
                continue
            seen_keys.add(dedupe_key)
            catalog.append(
                {
                    "anchor_label": anchor_label,
                    "target_label": target_label,
                    "edge_kind": "relationship_target_pair",
                    "source": "session_state.relationships_json",
                }
            )

    for hook_source, hooks in (
        ("session_state.pending_threads", session_state.get("pending_threads") or []),
        ("continuity_pack.pending_threads", continuity_pack.get("pending_threads") or []),
    ):
        for hook in hooks[:6]:
            if not isinstance(hook, dict):
                continue
            anchor_label = " ".join(str(hook.get("owner") or "").split()).strip()
            target_label = " ".join(str(hook.get("target") or "").split()).strip()
            if not anchor_label or not target_label:
                continue
            dedupe_key = (anchor_label.casefold(), target_label.casefold(), "pending_thread_pair")
            if dedupe_key in seen_keys:
                continue
            seen_keys.add(dedupe_key)
            catalog.append(
                {
                    "anchor_label": anchor_label,
                    "target_label": target_label,
                    "edge_kind": "pending_thread_pair",
                    "source": hook_source,
                }
            )

    return catalog


def _build_graph_like_support_signal_q20g(
    *,
    lightweight_entity_index: dict | None,
    session_state_data: dict | None,
    continuity_pack_data: dict | None,
) -> dict:
    entity_index = dict(lightweight_entity_index or {}) if isinstance(lightweight_entity_index, dict) else {}
    focus_terms = [
        " ".join(str(term or "").split()).strip()
        for term in (entity_index.get("focus_terms") or [])
        if " ".join(str(term or "").split()).strip()
    ]
    focus_term_keys = {term.casefold() for term in focus_terms}
    base_payload = {
        "version": _Q20G_GRAPH_LIKE_SUPPORT_SIGNAL_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "graph_support_mode": "off",
        "activation_rule": "requires_entity_focus_and_structured_link",
        "source_lanes": [],
        "edge_candidates": [],
        "fail_open_without_graph_signal": True,
        "inspection_surface_mode": "deferred_to_20_2c",
        "relation_edge_mode": "deferred_to_20_2g",
        "note_surface": "graph_like_support_signal_contract",
    }

    if str(entity_index.get("status") or "not_needed") != "defined" or not focus_term_keys:
        return base_payload

    catalog = _build_graph_like_support_catalog_q20g(
        session_state_data=session_state_data,
        continuity_pack_data=continuity_pack_data,
    )
    if not catalog:
        return base_payload

    matched_edges: list[dict] = []
    source_lanes: list[str] = []
    seen_sources: set[str] = set()
    for edge in catalog:
        anchor_key = str(edge.get("anchor_label") or "").casefold()
        target_key = str(edge.get("target_label") or "").casefold()
        if anchor_key not in focus_term_keys and target_key not in focus_term_keys:
            continue
        source = str(edge.get("source") or "unknown")
        if source not in seen_sources:
            source_lanes.append(source)
            seen_sources.add(source)
        matched_edges.append(
            {
                "anchor_label": str(edge.get("anchor_label") or ""),
                "target_label": str(edge.get("target_label") or ""),
                "edge_kind": str(edge.get("edge_kind") or "unknown"),
                "source": source,
            }
        )

    if not matched_edges:
        return base_payload

    return {
        **base_payload,
        "status": "defined",
        "graph_support_mode": "optional_graph_accelerator",
        "source_lanes": source_lanes,
        "edge_candidates": matched_edges,
    }


