def _build_relation_edge_support_ledger_q20l(
    *,
    lightweight_entity_index: dict | None,
    session_state_data: dict | None,
) -> dict:
    entity_index = dict(lightweight_entity_index or {}) if isinstance(lightweight_entity_index, dict) else {}
    focus_terms = {
        " ".join(str(term or "").split()).strip().casefold()
        for term in (entity_index.get("focus_terms") or [])
        if " ".join(str(term or "").split()).strip()
    }
    base_payload = {
        "version": _Q20L_RELATION_EDGE_SUPPORT_LEDGER_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "ledger_mode": "off",
        "activation_rule": "requires_entity_focus_and_structured_relationship_state",
        "source_lanes": [],
        "edge_entries": [],
        "graph_truth_write_mode": "forbidden",
        "note_surface": "relation_edge_support_ledger_contract",
    }

    if str(entity_index.get("status") or "not_needed") != "defined" or not focus_terms:
        return base_payload

    session_state = session_state_data or {}
    source_lanes: list[str] = []
    edge_entries: list[dict] = []
    for row in (session_state.get("characters") or []):
        if not isinstance(row, dict):
            continue
        character_name = " ".join(str(row.get("character_name") or "").split()).strip()
        if not character_name:
            continue
        for rel_entry in _load_relationship_entries_q20f(row.get("relationships_json"))[:6]:
            target_label = " ".join(str(rel_entry.get("target") or "").split()).strip()
            if not target_label:
                continue
            if character_name.casefold() not in focus_terms and target_label.casefold() not in focus_terms:
                continue
            current_dynamic = " ".join(
                str(
                    rel_entry.get("current_dynamic")
                    or rel_entry.get("dynamic")
                    or rel_entry.get("sentiment")
                    or rel_entry.get("affection")
                    or ""
                ).split()
            ).strip()
            trust_level = " ".join(str(rel_entry.get("trust_level") or rel_entry.get("trust") or "").split()).strip()
            imbalance = " ".join(str(rel_entry.get("imbalance") or rel_entry.get("power_balance") or "").split()).strip()
            recent_shift = " ".join(
                str(rel_entry.get("recent_shift") or rel_entry.get("recent_change") or rel_entry.get("shift") or "").split()
            ).strip()
            if not any((current_dynamic, trust_level, imbalance, recent_shift)):
                continue
            if "session_state.relationships_json" not in source_lanes:
                source_lanes.append("session_state.relationships_json")
            edge_entries.append(
                {
                    "pair": f"{character_name} <-> {target_label}",
                    "current_dynamic": current_dynamic or "unknown",
                    "trust_level": trust_level or "unknown",
                    "imbalance": imbalance or "unknown",
                    "recent_shift": recent_shift or "none",
                    "source": "session_state.relationships_json",
                }
            )

    if not edge_entries:
        return base_payload

    return {
        **base_payload,
        "status": "defined",
        "ledger_mode": "support_only_edge_summary",
        "source_lanes": source_lanes,
        "edge_entries": edge_entries,
    }


def _build_temporal_ambiguity_support_note_q20m(
    *,
    temporal_query_expansion: dict | None,
    temporal_validity_read_policy: dict | None,
    temporal_event_invalidation_support: dict | None,
    temporal_promotion_lag_support: dict | None,
    temporal_hot_recall_buffer: dict | None,
) -> dict:
    expansion = dict(temporal_query_expansion or {}) if isinstance(temporal_query_expansion, dict) else {}
    read_policy = (
        dict(temporal_validity_read_policy or {})
        if isinstance(temporal_validity_read_policy, dict)
        else {}
    )
    invalidation_support = (
        dict(temporal_event_invalidation_support or {})
        if isinstance(temporal_event_invalidation_support, dict)
        else {}
    )
    promotion_lag_support = (
        dict(temporal_promotion_lag_support or {})
        if isinstance(temporal_promotion_lag_support, dict)
        else {}
    )
    hot_recall_buffer = (
        dict(temporal_hot_recall_buffer or {})
        if isinstance(temporal_hot_recall_buffer, dict)
        else {}
    )

    focus_mode = str(expansion.get("focus_mode") or "none")
    range_kind = str(expansion.get("range_kind") or "none")
    read_priority = str(read_policy.get("read_priority") or "shared_default")
    base_payload = {
        "version": _Q20M_TEMPORAL_AMBIGUITY_SUPPORT_NOTE_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "note_mode": "off",
        "activation_rule": "requires_temporal_compare_or_order_query",
        "temporal_focus_mode": focus_mode,
        "temporal_range_kind": range_kind,
        "read_priority": read_priority,
        "primary_note_surface": "off",
        "support_surfaces": [],
        "note_emission_rule": "off",
        "reader_decision_rule": str(read_policy.get("separation_rule") or "follow_primary_query_class"),
        "compare_timing": "not_applicable",
        "pending_current_note_mode": str(promotion_lag_support.get("promotion_lag_note_mode") or "off"),
        "hot_buffer_mode": str(hot_recall_buffer.get("hot_buffer_mode") or "off"),
        "thin_support_tag_mode": str(hot_recall_buffer.get("thin_support_tag_mode") or "off"),
        "deferred_components": [],
        "authority_notice": "support_only_no_truth_override",
        "note_surface": "temporal_ambiguity_support_note_contract",
    }

    if str(expansion.get("status") or "none") != "expanded":
        return base_payload

    primary_note_surface = str(invalidation_support.get("support_surface_mode") or "off")
    support_surfaces: list[str] = []
    if primary_note_surface != "off":
        support_surfaces.append(primary_note_surface)

    pending_current_support_surface = str(promotion_lag_support.get("pending_current_support_surface") or "off")
    if pending_current_support_surface != "off":
        support_surfaces.append(pending_current_support_surface)

    bridge_lane_surface = str(hot_recall_buffer.get("bridge_lane_surface") or "off")
    if bridge_lane_surface != "off" and bridge_lane_surface not in support_surfaces:
        support_surfaces.append(bridge_lane_surface)

    deferred_components: list[str] = []
    if str(promotion_lag_support.get("status") or "not_needed") == "deferred":
        deferred_components.append("temporal_promotion_lag_support")
    if str(hot_recall_buffer.get("status") or "not_needed") == "deferred":
        deferred_components.append("temporal_hot_recall_buffer")

    if not support_surfaces and not deferred_components:
        return base_payload

    return {
        **base_payload,
        "status": "defined",
        "note_mode": "temporal_ambiguity_support_note",
        "primary_note_surface": primary_note_surface,
        "support_surfaces": support_surfaces,
        "note_emission_rule": str(invalidation_support.get("note_emission_rule") or "off"),
        "compare_timing": str(invalidation_support.get("current_truth_compare_timing") or "not_applicable"),
        "deferred_components": deferred_components,
    }


def _build_alias_entity_conflict_disambiguation_q20n(
    *,
    lightweight_entity_index: dict | None,
    session_state_data: dict | None,
    continuity_pack_data: dict | None,
) -> dict:
    entity_index = dict(lightweight_entity_index or {}) if isinstance(lightweight_entity_index, dict) else {}
    focus_terms = [
        " ".join(str(term or "").split()).strip()
        for term in (entity_index.get("focus_terms") or [])
        if " ".join(str(term or "").split()).strip()
    ]
    base_payload = {
        "version": _Q20N_ALIAS_ENTITY_CONFLICT_DISAMBIGUATION_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "conflict_mode": "off",
        "activation_rule": "requires_structured_focus_term_collision",
        "alias_source_mode": "structured_label_collision_only",
        "focus_terms": [],
        "conflict_entries": [],
        "reader_decision_rule": "surface_conflict_without_auto_resolution",
        "truth_write_mode": "forbidden",
        "note_surface": "alias_entity_conflict_disambiguation_contract",
    }

    if str(entity_index.get("status") or "not_needed") != "defined" or not focus_terms:
        return base_payload

    catalog = _build_lightweight_entity_index_catalog_q20f(
        session_state_data=session_state_data,
        continuity_pack_data=continuity_pack_data,
    )
    if not catalog:
        return base_payload

    conflict_focus_terms: list[str] = []
    conflict_entries: list[dict] = []
    for focus_term in focus_terms:
        focus_key = _normalize_entity_index_text_q20f(focus_term, compact=True)
        if not focus_key:
            continue
        candidate_entries: list[dict] = []
        seen_candidates: set[tuple[str, str, str]] = set()
        for entry in catalog:
            if str(entry.get("match_key") or "") != focus_key:
                continue
            label = " ".join(str(entry.get("label") or "").split()).strip()
            bucket = str(entry.get("bucket") or "unknown")
            source = str(entry.get("source") or "unknown")
            candidate_key = (label.casefold(), bucket, source)
            if not label or candidate_key in seen_candidates:
                continue
            seen_candidates.add(candidate_key)
            candidate_entries.append(
                {
                    "label": label,
                    "bucket": bucket,
                    "source": source,
                }
            )
        if len(candidate_entries) < 2:
            continue
        candidate_entries.sort(
            key=lambda item: (
                int(_Q20F_BUCKET_PRIORITY.get(str(item.get("bucket") or "unknown"), 99)),
                str(item.get("source") or "unknown"),
                str(item.get("label") or "").casefold(),
            )
        )
        conflict_focus_terms.append(focus_term)
        conflict_entries.append(
            {
                "focus_term": focus_term,
                "candidate_entries": candidate_entries,
            }
        )

    if not conflict_entries:
        return base_payload

    return {
        **base_payload,
        "status": "defined",
        "conflict_mode": "structured_label_collision",
        "focus_terms": conflict_focus_terms,
        "conflict_entries": conflict_entries,
    }


def _append_source_tag_entry_q20o(
    entries: list[dict],
    seen_components: set[str],
    *,
    component: str,
    raw_tags: object,
) -> None:
    if component in seen_components:
        return
    clean_tags: list[str] = []
    seen_tags: set[str] = set()
    for raw_tag in (raw_tags or []):
        clean_tag = " ".join(str(raw_tag or "").split()).strip()
        if not clean_tag or clean_tag in seen_tags:
            continue
        seen_tags.add(clean_tag)
        clean_tags.append(clean_tag)
    if not clean_tags:
        return
    seen_components.add(component)
    entries.append(
        {
            "component": component,
            "tags": clean_tags,
        }
    )


