def _build_recall_cue_rescue_rule_q20q(
    *,
    shared_query: str,
    temporal_query_expansion: dict | None,
    query_class_contract: dict | None,
    query_class_route_policy: dict | None,
) -> dict:
    expansion = dict(temporal_query_expansion or {}) if isinstance(temporal_query_expansion, dict) else {}
    class_contract = dict(query_class_contract or {}) if isinstance(query_class_contract, dict) else {}
    route_policy = dict(query_class_route_policy or {}) if isinstance(query_class_route_policy, dict) else {}
    selection_signals = (
        dict(class_contract.get("selection_signals") or {})
        if isinstance(class_contract.get("selection_signals"), dict)
        else {}
    )
    focus_mode = str(expansion.get("focus_mode") or "none")
    base_payload = {
        "version": _Q20Q_RECALL_CUE_RESCUE_RULE_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "rescue_mode": "off",
        "activation_rule": "requires_temporal_recall_or_callback_old_detail_signal",
        "cue_signal_mode": "none",
        "cue_sources": [],
        "cue_terms": [],
        "target_routes": [],
        "callback_rescue_enabled": False,
        "old_detail_rescue_enabled": False,
        "stale_arc_auto_foreground": False,
        "foreground_guard": "support_only_widening_no_auto_foreground",
        "truth_write_mode": "forbidden",
        "note_surface": "recall_cue_rescue_rule_contract",
    }

    temporal_recall_active = (
        str(expansion.get("status") or "none") == "expanded"
        and focus_mode in {"past_event", "past_window", "timeline_order"}
    )
    callback_lexical_terms = _collect_query_class_signal_terms_qr1a(
        shared_query,
        _get_query_class_lexical_cues_qr1a("callback"),
    )
    callback_lexical_active = bool(selection_signals.get("callback_lexical_signal") or callback_lexical_terms)
    old_detail_terms = _collect_query_class_signal_terms_qr1a(shared_query, _QR1D_OLD_DETAIL_CUE_TOKENS)
    old_detail_active = bool(route_policy.get("old_detail_signal") or old_detail_terms)

    cue_sources: list[str] = []
    if temporal_recall_active:
        cue_sources.append("temporal_query_expansion")
    if callback_lexical_active:
        cue_sources.append("query_class_contract.callback_lexical_signal")
    if old_detail_active:
        cue_sources.append("query_class_route_policy.old_detail_signal")

    if not cue_sources:
        return base_payload

    cue_signal_mode = "old_detail_signal"
    if temporal_recall_active and callback_lexical_active and old_detail_active:
        cue_signal_mode = "temporal_recall_callback_lexical_and_old_detail_signal"
    elif temporal_recall_active and callback_lexical_active:
        cue_signal_mode = "temporal_recall_and_callback_lexical_signal"
    elif temporal_recall_active and old_detail_active:
        cue_signal_mode = "temporal_recall_and_old_detail_signal"
    elif temporal_recall_active:
        cue_signal_mode = "temporal_recall_query"
    elif callback_lexical_active and old_detail_active:
        cue_signal_mode = "callback_lexical_and_old_detail_signal"
    elif callback_lexical_active:
        cue_signal_mode = "callback_lexical_signal"

    target_routes: list[str] = []
    if callback_lexical_active:
        target_routes.append("callback_rescue")
    if temporal_recall_active or old_detail_active:
        target_routes.append("old_detail_bridge")

    cue_terms = _dedupe_query_terms_q20a(
        list(expansion.get("cue_terms") or []) if temporal_recall_active else [],
        callback_lexical_terms if callback_lexical_active else [],
        old_detail_terms if old_detail_active else [],
    )

    return {
        **base_payload,
        "status": "defined",
        "rescue_mode": "recall_cue_widening",
        "cue_signal_mode": cue_signal_mode,
        "cue_sources": cue_sources,
        "cue_terms": cue_terms,
        "target_routes": target_routes,
        "callback_rescue_enabled": "callback_rescue" in target_routes,
        "old_detail_rescue_enabled": "old_detail_bridge" in target_routes,
    }


def _build_wide_gather_validity_join_rule_q20r(
    *,
    query_class_contract: dict | None,
    query_class_budget_policy: dict | None,
    temporal_ambiguity_support_note: dict | None,
    recall_cue_rescue_rule: dict | None,
) -> dict:
    class_contract = dict(query_class_contract or {}) if isinstance(query_class_contract, dict) else {}
    budget_policy = dict(query_class_budget_policy or {}) if isinstance(query_class_budget_policy, dict) else {}
    ambiguity_support_note = (
        dict(temporal_ambiguity_support_note or {})
        if isinstance(temporal_ambiguity_support_note, dict)
        else {}
    )
    rescue_rule = dict(recall_cue_rescue_rule or {}) if isinstance(recall_cue_rescue_rule, dict) else {}
    temporal_query_expansion = (
        dict(class_contract.get("temporal_query_expansion") or {})
        if isinstance(class_contract.get("temporal_query_expansion"), dict)
        else {}
    )
    temporal_read_policy = (
        dict(class_contract.get("temporal_validity_read_policy") or {})
        if isinstance(class_contract.get("temporal_validity_read_policy"), dict)
        else {}
    )
    temporal_budget = (
        dict((budget_policy.get("query_classes") or {}).get("temporal") or {})
        if isinstance((budget_policy.get("query_classes") or {}).get("temporal"), dict)
        else {}
    )
    candidate_budget = (
        dict(temporal_budget.get("candidate_budget") or {})
        if isinstance(temporal_budget.get("candidate_budget"), dict)
        else {}
    )
    focus_mode = str(temporal_query_expansion.get("focus_mode") or "none")
    base_payload = {
        "version": _Q20R_WIDE_GATHER_VALIDITY_JOIN_RULE_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "join_mode": "off",
        "activation_rule": "requires_temporal_validity_read_lane",
        "gather_budget_source": "off",
        "gather_retrieval_depth": "off",
        "gather_priority_order": [],
        "gather_layer_caps": {},
        "gather_top_k_cap": 0,
        "join_authorities": [],
        "read_priority": str(temporal_read_policy.get("read_priority") or "shared_default"),
        "compare_note_surface": "off",
        "reader_decision_rule": str(temporal_read_policy.get("separation_rule") or "follow_primary_query_class"),
        "rescue_route_targets": [],
        "truth_write_mode": "forbidden",
        "authority_notice": "support_only_join_rule",
        "note_surface": "wide_gather_validity_join_rule_contract",
    }

    temporal_join_active = (
        str(temporal_query_expansion.get("status") or "none") == "expanded"
        and focus_mode in {"past_event", "past_window", "timeline_order"}
    )
    if not temporal_join_active:
        return base_payload

    gather_priority_order = list(candidate_budget.get("priority_order") or [])
    gather_layer_caps = dict(candidate_budget.get("retrieval_layer_caps") or {})
    if not temporal_budget or not gather_priority_order:
        return base_payload

    return {
        **base_payload,
        "status": "defined",
        "join_mode": "wide_gather_then_validity_join",
        "gather_budget_source": str(temporal_budget.get("budget_source") or "off"),
        "gather_retrieval_depth": str(temporal_budget.get("retrieval_depth") or "off"),
        "gather_priority_order": gather_priority_order,
        "gather_layer_caps": gather_layer_caps,
        "gather_top_k_cap": int(candidate_budget.get("top_k_cap") or 0),
        "join_authorities": ["sqlite_canonical_truth", "storyline_status", "temporal_validity"],
        "read_priority": str(temporal_read_policy.get("read_priority") or "shared_default"),
        "compare_note_surface": str(ambiguity_support_note.get("primary_note_surface") or "off"),
        "reader_decision_rule": str(
            ambiguity_support_note.get("reader_decision_rule")
            or temporal_read_policy.get("separation_rule")
            or "follow_primary_query_class"
        ),
        "rescue_route_targets": list(rescue_rule.get("target_routes") or []),
    }


def _build_thin_support_tag_fallback_q20s(
    *,
    wide_gather_validity_join_rule: dict | None,
    temporal_hot_recall_buffer: dict | None,
    temporal_entity_source_tag_rule: dict | None,
) -> dict:
    join_rule = (
        dict(wide_gather_validity_join_rule or {})
        if isinstance(wide_gather_validity_join_rule, dict)
        else {}
    )
    hot_recall_buffer = (
        dict(temporal_hot_recall_buffer or {})
        if isinstance(temporal_hot_recall_buffer, dict)
        else {}
    )
    source_tag_rule = (
        dict(temporal_entity_source_tag_rule or {})
        if isinstance(temporal_entity_source_tag_rule, dict)
        else {}
    )
    thin_support_tag_mode = str(hot_recall_buffer.get("thin_support_tag_mode") or "off")
    base_payload = {
        "version": _Q20S_THIN_SUPPORT_TAG_FALLBACK_VERSION,
        "status": "not_needed",
        "mode": "query_builder_contract_only",
        "fallback_mode": "off",
        "activation_rule": "requires_wide_gather_join_and_thin_tag_capable_support",
        "thin_support_tag_mode": thin_support_tag_mode,
        "fallback_reason": "off",
        "source_components": [],
        "source_tags": [],
        "reader_notice": "low_density_support_not_truth",
        "truth_write_mode": "forbidden",
        "note_surface": "thin_support_tag_fallback_contract",
    }

    if str(join_rule.get("status") or "not_needed") != "defined":
        return base_payload
    if thin_support_tag_mode != "allow_degrade_to_thin_tag":
        return base_payload

    source_components: list[str] = []
    source_tags: list[str] = []
    seen_components: set[str] = set()
    seen_tags: set[str] = set()
    for entry in (source_tag_rule.get("source_tag_entries") or []):
        if not isinstance(entry, dict):
            continue
        component = " ".join(str(entry.get("component") or "").split()).strip()
        if component and component not in seen_components:
            source_components.append(component)
            seen_components.add(component)
        for tag in (entry.get("tags") or []):
            clean_tag = " ".join(str(tag or "").split()).strip()
            if not clean_tag or clean_tag in seen_tags:
                continue
            source_tags.append(clean_tag)
            seen_tags.add(clean_tag)

    if not source_components:
        source_components.append("temporal_hot_recall_buffer")
    if not source_tags:
        for tag in (hot_recall_buffer.get("source_surfaces") or []):
            clean_tag = " ".join(str(tag or "").split()).strip()
            if not clean_tag or clean_tag in seen_tags:
                continue
            source_tags.append(clean_tag)
            seen_tags.add(clean_tag)

    return {
        **base_payload,
        "status": "defined",
        "fallback_mode": "thin_support_tag_fallback",
        "fallback_reason": "weak_linkage_after_validity_join",
        "source_components": source_components,
        "source_tags": source_tags,
    }


def _build_query_class_contract_qr1a(
    *,
    shared_query: str,
    trigger_raw: str,
    callback_signal_used: bool,
    resume_signal_used: bool,
    canon_session_signal: bool,
    canon_pack_signal: bool,
) -> dict:
    temporal_signal_terms = _collect_query_class_signal_terms_qr1a(
        shared_query,
        _get_query_class_lexical_cues_qr1a("temporal"),
    )
    temporal_signal = bool(temporal_signal_terms)
    temporal_query_expansion = _build_temporal_query_expansion_q20a(shared_query)
    temporal_validity_read_policy = _build_temporal_validity_read_policy_q20b(
        temporal_query_expansion,
    )
    temporal_event_invalidation_support = _build_temporal_event_invalidation_support_q20c(
        temporal_query_expansion,
        temporal_validity_read_policy,
    )
    temporal_promotion_lag_support = _build_temporal_promotion_lag_support_q20d(
        temporal_validity_read_policy,
        temporal_event_invalidation_support,
    )
    temporal_hot_recall_buffer = _build_temporal_hot_recall_buffer_q20e(
        temporal_promotion_lag_support,
    )
    callback_lexical_signal = _contains_query_class_signal_qr1a(
        shared_query,
        _get_query_class_lexical_cues_qr1a("callback"),
    )
    canon_lexical_signal = _contains_query_class_signal_qr1a(
        shared_query,
        _get_query_class_lexical_cues_qr1a("canon"),
    )
    resume_trigger_signal = trigger_raw in {"resume", "manual_resume", "idle", "idle_reentry", "empty", "empty_input"}

    if temporal_signal:
        primary_query_class = "temporal"
        selection_reason = "explicit_temporal_cue"
    elif resume_trigger_signal or resume_signal_used:
        primary_query_class = "resume"
        selection_reason = "resume_trigger_or_pack"
    elif canon_lexical_signal or canon_session_signal or canon_pack_signal:
        primary_query_class = "canon"
        selection_reason = "canon_guard_signal"
    elif callback_lexical_signal or callback_signal_used:
        primary_query_class = "callback"
        selection_reason = "callback_recovery_signal"
    else:
        primary_query_class = "scene"
        selection_reason = "scene_fallback"

    query_classes = {
        name: {
            "query_class": name,
            "status": "defined",
            "description": _get_query_class_description_qr1a(name),
            "intent_binding": name if name in _Q3A_INTENT_ORDER else None,
            "execution_binding": "single_query_shared",
            "contract_only": name == "temporal",
            "temporal_query_expansion_status": temporal_query_expansion["status"] if name == "temporal" else "not_applicable",
            "temporal_focus_mode": temporal_query_expansion["focus_mode"] if name == "temporal" else "none",
            "temporal_validity_read_status": temporal_validity_read_policy["status"] if name == "temporal" else "not_applicable",
            "temporal_validity_read_priority": temporal_validity_read_policy["read_priority"] if name == "temporal" else "none",
            "temporal_event_support_status": temporal_event_invalidation_support["status"] if name == "temporal" else "not_applicable",
            "temporal_event_support_mode": temporal_event_invalidation_support["support_surface_mode"] if name == "temporal" else "none",
            "temporal_promotion_lag_status": temporal_promotion_lag_support["status"] if name == "temporal" else "not_applicable",
            "temporal_promotion_lag_mode": temporal_promotion_lag_support["promotion_lag_note_mode"] if name == "temporal" else "none",
            "temporal_hot_buffer_status": temporal_hot_recall_buffer["status"] if name == "temporal" else "not_applicable",
            "temporal_hot_buffer_mode": temporal_hot_recall_buffer["hot_buffer_mode"] if name == "temporal" else "none",
        }
        for name in _QR1A_QUERY_CLASS_ORDER
    }

    return {
        "version": _QR1A_QUERY_CLASS_CONTRACT_VERSION,
        "status": "defined",
        "execution_mode": "contract_only_fail_open",
        "primary_query_class": primary_query_class,
        "selection_reason": selection_reason,
        "selection_signals": {
            "temporal_signal": temporal_signal,
            "temporal_signal_terms": temporal_signal_terms,
            "temporal_focus_mode": temporal_query_expansion["focus_mode"],
            "temporal_range_kind": temporal_query_expansion["range_kind"],
            "temporal_read_priority": temporal_validity_read_policy["read_priority"],
            "resume_trigger_signal": resume_trigger_signal,
            "resume_pack_signal": resume_signal_used,
            "callback_signal": callback_signal_used,
            "callback_lexical_signal": callback_lexical_signal,
            "canon_session_signal": canon_session_signal,
            "canon_pack_signal": canon_pack_signal,
            "canon_lexical_signal": canon_lexical_signal,
        },
        "temporal_query_expansion": temporal_query_expansion,
        "temporal_validity_read_policy": temporal_validity_read_policy,
        "temporal_event_invalidation_support": temporal_event_invalidation_support,
        "temporal_promotion_lag_support": temporal_promotion_lag_support,
        "temporal_hot_recall_buffer": temporal_hot_recall_buffer,
        "query_classes": query_classes,
    }


def _normalize_budget_caps_qr1b(raw_caps: object) -> dict[str, int]:
    if not isinstance(raw_caps, dict):
        return {}
    normalized: dict[str, int] = {}
    for key, value in raw_caps.items():
        clean_key = str(key or "").strip()
        if not clean_key:
            continue
        try:
            normalized[clean_key] = max(0, int(value))
        except Exception:
            continue
    return normalized


def _scale_query_class_cap_qr1b(shared_top_k: int, ratio: float) -> int:
    return max(1, min(shared_top_k, int(math.ceil(shared_top_k * float(ratio or 0.0)))))


def _build_temporal_candidate_budget_qr1b(*, shared_top_k: int, context_window_profile: str) -> dict:
    profile = (
        context_window_profile
        if context_window_profile in _QR1B_TEMPORAL_BUDGET_PROFILE_TEMPLATES
        else "mid_context_300k"
    )
    template = _QR1B_TEMPORAL_BUDGET_PROFILE_TEMPLATES[profile]
    retrieval_layer_caps = {
        "temporal_integrity": _scale_query_class_cap_qr1b(shared_top_k, template.get("temporal_integrity_ratio") or 0.4),
        "direct_evidence": _scale_query_class_cap_qr1b(shared_top_k, template.get("direct_evidence_ratio") or 0.8),
        "search": _scale_query_class_cap_qr1b(shared_top_k, template.get("search_ratio") or 0.4),
    }
    return {
        "top_k_cap": max(retrieval_layer_caps.values()),
        "retrieval_layer_caps": retrieval_layer_caps,
        "support_surface_caps": {
            "temporal_integrity": retrieval_layer_caps["temporal_integrity"],
            "direct_evidence": retrieval_layer_caps["direct_evidence"],
            "search": retrieval_layer_caps["search"],
        },
        "priority_order": ["temporal_integrity", "direct_evidence", "search"],
        "context_window_profile": profile,
    }


def _build_query_class_budget_policy_qr1b(
    *,
    shared_top_k: int,
    context_window_profile: str,
    intent_packet_budgets: dict[str, dict],
    query_classes: dict[str, dict],
) -> tuple[dict, dict[str, dict]]:
    normalized_profile = (
        context_window_profile
        if context_window_profile in _QR1B_TEMPORAL_BUDGET_PROFILE_TEMPLATES
        else "mid_context_300k"
    )
    class_budgets: dict[str, dict] = {}
    enriched_query_classes: dict[str, dict] = {}

    for query_class in _QR1A_QUERY_CLASS_ORDER:
        query_class_entry = dict((query_classes or {}).get(query_class) or {})
        retrieval_depth = _QR1B_QUERY_CLASS_RETRIEVAL_DEPTHS.get(query_class) or "shared_query_fallback"

        if query_class in intent_packet_budgets:
            intent_budget = dict(intent_packet_budgets.get(query_class) or {})
            candidate_budget = {
                "top_k_cap": int(intent_budget.get("top_k_cap") or 0),
                "packet_char_cap": int(intent_budget.get("packet_char_cap") or 0),
                "input_context_char_cap": int(intent_budget.get("input_context_char_cap") or 0),
                "retrieval_layer_caps": _normalize_budget_caps_qr1b(intent_budget.get("retrieval_layer_caps")),
                "support_surface_caps": _normalize_budget_caps_qr1b(intent_budget.get("support_surface_caps")),
            }
            budget_source = "intent_packet_budget_reuse"
        else:
            candidate_budget = _build_temporal_candidate_budget_qr1b(
                shared_top_k=shared_top_k,
                context_window_profile=normalized_profile,
            )
            budget_source = "temporal_evidence_first_overlay"

        class_budget = {
            "query_class": query_class,
            "status": "defined",
            "mode": "policy_only",
            "budget_policy_version": _QR1B_QUERY_CLASS_BUDGET_POLICY_VERSION,
            "budget_source": budget_source,
            "retrieval_depth": retrieval_depth,
            "candidate_budget": candidate_budget,
        }
        class_budgets[query_class] = class_budget

        query_class_entry["retrieval_depth"] = retrieval_depth
        query_class_entry["candidate_budget"] = candidate_budget
        query_class_entry["budget_policy_version"] = _QR1B_QUERY_CLASS_BUDGET_POLICY_VERSION
        query_class_entry["budget_source"] = budget_source
        enriched_query_classes[query_class] = query_class_entry

    return {
        "version": _QR1B_QUERY_CLASS_BUDGET_POLICY_VERSION,
        "status": "defined",
        "mode": "policy_only",
        "context_window_profile": normalized_profile,
        "shared_top_k": shared_top_k,
        "query_classes": class_budgets,
    }, enriched_query_classes


def _build_query_class_note_policy_qr1c(*, query_classes: dict[str, dict]) -> tuple[dict, dict[str, dict]]:
    class_note_policies: dict[str, dict] = {}
    enriched_query_classes: dict[str, dict] = {}

    for query_class in _QR1A_QUERY_CLASS_ORDER:
        rule = dict(_QR1C_QUERY_CLASS_NOTE_RULES.get(query_class) or {})
        query_class_entry = dict((query_classes or {}).get(query_class) or {})
        extract_before_read = bool(rule.get("extract_before_read"))
        retrieval_note_surface = str(rule.get("retrieval_note_surface") or "support_surface")
        pre_extract_rule = str(rule.get("pre_extract_rule") or "disabled_by_default")
        note_policy = {
            "query_class": query_class,
            "status": "defined",
            "mode": "policy_only",
            "note_policy_version": _QR1C_QUERY_CLASS_NOTE_POLICY_VERSION,
            "note_delivery": "support_surface_first",
            "extract_before_read": extract_before_read,
            "retrieval_note_surface": retrieval_note_surface,
            "pre_extract_rule": pre_extract_rule,
        }
        class_note_policies[query_class] = note_policy

        query_class_entry["extract_before_read"] = extract_before_read
        query_class_entry["retrieval_note_surface"] = retrieval_note_surface
        query_class_entry["pre_extract_rule"] = pre_extract_rule
        query_class_entry["note_delivery"] = "support_surface_first"
        query_class_entry["note_policy_version"] = _QR1C_QUERY_CLASS_NOTE_POLICY_VERSION
        enriched_query_classes[query_class] = query_class_entry

    return {
        "version": _QR1C_QUERY_CLASS_NOTE_POLICY_VERSION,
        "status": "defined",
        "mode": "policy_only",
        "note_delivery": "support_surface_first",
        "query_classes": class_note_policies,
    }, enriched_query_classes


def _build_query_class_route_policy_qr1d(
    *,
    shared_query: str,
    primary_query_class: str,
    query_classes: dict[str, dict],
) -> tuple[dict, dict[str, dict]]:
    explicit_detail_signal = _contains_query_class_signal_qr1a(shared_query, _QR1D_EXPLICIT_DETAIL_CUE_TOKENS)
    old_detail_signal = _contains_query_class_signal_qr1a(shared_query, _QR1D_OLD_DETAIL_CUE_TOKENS)
    long_tail_route_active = explicit_detail_signal or old_detail_signal
    class_route_policies: dict[str, dict] = {}
    enriched_query_classes: dict[str, dict] = {}

    for query_class in _QR1A_QUERY_CLASS_ORDER:
        query_class_entry = dict((query_classes or {}).get(query_class) or {})
        default_route = _QR1D_DEFAULT_ROUTE_BY_QUERY_CLASS.get(query_class) or "scene_default"
        long_tail_route = _QR1D_LONG_TAIL_ROUTE_BY_QUERY_CLASS.get(query_class)
        selected_route = long_tail_route if long_tail_route_active and long_tail_route else default_route
        selection_reason = (
            "explicit_detail_or_old_detail_signal"
            if long_tail_route and selected_route == long_tail_route
            else "query_class_default"
        )
        route_candidates = [default_route]
        if long_tail_route and long_tail_route != default_route:
            if selected_route == long_tail_route:
                route_candidates = [long_tail_route, default_route]
            else:
                route_candidates = [default_route, long_tail_route]
        route_policy = {
            "query_class": query_class,
            "status": "defined",
            "mode": "policy_only",
            "route_policy_version": _QR1D_QUERY_CLASS_ROUTE_POLICY_VERSION,
            "route_family": selected_route,
            "route_candidates": route_candidates,
            "selected_route": selected_route,
            "selection_reason": selection_reason,
        }
        class_route_policies[query_class] = route_policy

        query_class_entry["route_family"] = selected_route
        query_class_entry["route_candidates"] = route_candidates
        query_class_entry["selected_route"] = selected_route
        query_class_entry["route_policy_version"] = _QR1D_QUERY_CLASS_ROUTE_POLICY_VERSION
        enriched_query_classes[query_class] = query_class_entry

    primary_selected_route = (
        class_route_policies.get(primary_query_class, {}).get("selected_route")
        or _QR1D_DEFAULT_ROUTE_BY_QUERY_CLASS.get(primary_query_class)
        or "scene_default"
    )
    return {
        "version": _QR1D_QUERY_CLASS_ROUTE_POLICY_VERSION,
        "status": "defined",
        "mode": "policy_only",
        "route_execution_mode": "shared_query_fallback",
        "explicit_detail_signal": explicit_detail_signal,
        "old_detail_signal": old_detail_signal,
        "long_tail_route_active": long_tail_route_active,
        "primary_query_class": primary_query_class,
        "primary_selected_route": primary_selected_route,
        "query_classes": class_route_policies,
    }, enriched_query_classes
