def _build_ann_candidate_snapshot_q2a(
    sid: str,
    query_text: str,
    *,
    top_k: int,
    context_window_profile: str = "mid_context_300k",
) -> dict:
    if not retrieval_index_registry.is_shadow_mode_enabled():
        return _empty_ann_candidate_snapshot_q2a(
            sid,
            status="off",
            reason="runtime_toggle_off",
            context_window_profile=context_window_profile,
        )

    try:
        raw_snapshot = preview_summary_ann_candidates(
            query=query_text,
            chat_session_id=sid,
            top_k=top_k,
        )
    except Exception as exc:
        logger.warning("[prepare-turn] ann candidate preview failed: %s", exc)
        return _empty_ann_candidate_snapshot_q2a(
            sid,
            status="degraded",
            reason="ann_candidate_failed",
            context_window_profile=context_window_profile,
        )

    candidate_documents: list[dict] = []
    merged_items = raw_snapshot.get("merged_items") or []
    if not merged_items:
        tier_items = raw_snapshot.get("tier_items") or {}
        for tier in ("episode", "chapter", "arc", "saga"):
            merged_items.extend(tier_items.get(tier) or [])

    for item in merged_items:
        tier = str(item.get("source_type") or item.get("source") or "").strip().lower()
        doc = _build_retrieval_document_q1a(tier, item, sid) if tier else None
        if doc:
            candidate_documents.append(doc)

    snapshot = {k: v for k, v in raw_snapshot.items() if k != "tier_items"}
    normalized_profile = (
        context_window_profile
        if context_window_profile in _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE
        else "mid_context_300k"
    )
    snapshot["context_window_profile"] = normalized_profile
    snapshot["overlap_guard_version"] = _S1F_LONG_TIER_ANN_GUARD_VERSION
    snapshot["default_takeover_overlap_ratio_profile_map"] = {
        key: float(value)
        for key, value in _Q2E_DEFAULT_TAKEOVER_MIN_OVERLAP_RATIO_BY_PROFILE.items()
    }
    snapshot["default_takeover_overlap_ratio_min"] = _resolve_ann_takeover_overlap_min_s1f(normalized_profile)
    snapshot["documents"] = candidate_documents
    snapshot["candidate_count"] = len(candidate_documents)
    snapshot["document_schema_version"] = _RETRIEVAL_DOCUMENT_SCHEMA_Q1A["version"]
    return snapshot
def _serialize_source_row_q1d(source_table: str, row) -> dict | None:
    if row is None:
        return None
    table = str(source_table or "").strip().lower()
    if table == "memories":
        return {
            "id": row.id,
            "chat_session_id": row.chat_session_id,
            "turn_index": row.turn_index,
            "summary_json": row.summary_json,
            "importance": row.importance,
            "archive_wing": row.archive_wing,
            "archive_room": row.archive_room,
            "created_at": to_kst(row.created_at),
        }
    if table == "chat_logs":
        return {
            "id": row.id,
            "chat_session_id": row.chat_session_id,
            "turn_index": row.turn_index,
            "role": row.role,
            "content": row.content,
            "created_at": to_kst(row.created_at),
        }
    if table == "episode_summaries":
        return {
            "id": row.id,
            "chat_session_id": row.chat_session_id,
            "from_turn": row.from_turn,
            "to_turn": row.to_turn,
            "summary_text": row.summary_text,
            "created_at": to_kst(row.created_at),
        }
    if table == "chapter_summaries":
        return {
            "id": row.id,
            "chat_session_id": row.chat_session_id,
            "from_turn": row.from_turn,
            "to_turn": row.to_turn,
            "chapter_index": row.chapter_index,
            "chapter_title": row.chapter_title,
            "summary_text": row.summary_text,
            "resume_text": row.resume_text,
            "created_at": to_kst(row.created_at),
        }
    if table == "arc_summaries":
        return {
            "id": row.id,
            "chat_session_id": row.chat_session_id,
            "from_turn": row.from_turn,
            "to_turn": row.to_turn,
            "arc_index": row.arc_index,
            "arc_name": row.arc_name,
            "arc_status": row.arc_status,
            "core_conflict": row.core_conflict,
            "arc_resume_text": row.arc_resume_text,
            "irreversible_turns_json": row.irreversible_turns_json,
            "callback_debts_json": row.callback_debts_json,
            "relationship_pivots_json": row.relationship_pivots_json,
            "created_at": to_kst(row.created_at),
        }
    if table == "saga_digests":
        return {
            "id": row.id,
            "chat_session_id": row.chat_session_id,
            "from_turn": row.from_turn,
            "to_turn": row.to_turn,
            "era_label": row.era_label,
            "saga_summary": row.saga_summary,
            "resume_pack_text": row.resume_pack_text,
            "created_at": to_kst(row.created_at),
        }
    return None


def _resolve_retrieval_source_row_q1d(chat_session_id: str, document_id: str) -> tuple[dict | None, dict | None, str]:
    sid = " ".join(str(chat_session_id or "").split()).strip()
    doc_id = " ".join(str(document_id or "").split()).strip()
    if not sid or not doc_id:
        return None, None, "invalid_request"

    document = retrieval_index_registry.get_document(sid, doc_id)
    if document is None:
        return None, None, "document_not_found"

    source_table = str(document.get("source_table") or "").strip().lower()
    source_row_id = document.get("source_row_id")
    if not source_table or not isinstance(source_row_id, int):
        return document, None, "source_reference_missing"

    table_map = {
        "memories": Memory,
        "chat_logs": ChatLog,
        "episode_summaries": EpisodeSummary,
        "chapter_summaries": ChapterSummary,
        "arc_summaries": ArcSummary,
        "saga_digests": SagaDigest,
    }
    model = table_map.get(source_table)
    if model is None:
        return document, None, "unsupported_source_table"

    db = SessionLocal()
    try:
        row = (
            db.query(model)
            .filter(model.id == source_row_id, model.chat_session_id == sid)
            .first()
        )
        if row is None:
            return document, None, "source_row_not_found"
        return document, _serialize_source_row_q1d(source_table, row), "ok"
    finally:
        db.close()




