def _build_long_session_health_r3a(
    *,
    recall_data: dict | None,
    continuity_pack_data: dict | None,
    trace_preview_data: dict | None,
    recall_latency_ms: float | None,
    context_window_profile: str,
    resume_pack_data: dict | None = None,
    bundle_read_source: str = "unknown",   # R-3e Hardening: prepare-turn bundle read 寃곌낵
    bundle_fallback_reason: str = "",       # R-3e Hardening: skeleton_only / partial_reads / ""
) -> dict:
    """R-3a: long-session health metric contract (read-only, fail-open).

    This helper defines three proxy metrics without changing runtime decisions:
    - recall_latency
    - recall_hit_quality
    - hook_survival
    """
    version = _R3B_LONG_SESSION_HEALTH_VERSION
    strategy = "long_session_proxy_metrics_v1"
    warnings: list[str] = []

    def _norm_text(value: str | None, *, max_len: int = 120) -> str:
        text = " ".join(str(value or "").split()).strip().lower()
        if len(text) > max_len:
            text = text[:max_len]
        return text

    active_profile = (
        context_window_profile
        if context_window_profile in _CONTEXT_WINDOW_PROFILES_P4D
        else "mid_context_300k"
    )
    has_recall_bundle = isinstance(recall_data, dict)
    recall_payload = recall_data or {}

    # 1) recall latency metric
    latency_value_ms = round(max(0.0, float(recall_latency_ms or 0.0)), 3)
    if has_recall_bundle:
        latency_status = "ready"
        latency_reason = "measured"
        if latency_value_ms >= 1500.0:
            latency_severity = "degraded"
        elif latency_value_ms >= 800.0:
            latency_severity = "warning"
        else:
            latency_severity = "ok"
    else:
        latency_status = "empty"
        latency_reason = "recall_bundle_missing"
        latency_severity = "unknown"
        latency_value_ms = 0.0

    # 2) recall hit quality metric
    search_payload = recall_payload.get("search") or {}
    tier_counts = {
        "memory": int(search_payload.get("total_count") or 0),
        "episode": int((recall_payload.get("episode") or {}).get("count") or 0),
        "chapter": int((recall_payload.get("chapter") or {}).get("count") or 0),
        "arc": int((recall_payload.get("arc") or {}).get("count") or 0),
        "saga": int((recall_payload.get("saga") or {}).get("count") or 0),
    }
    total_hit_count = sum(max(0, count) for count in tier_counts.values())
    tier_coverage_count = sum(1 for count in tier_counts.values() if count > 0)
    tier_coverage_ratio = round(tier_coverage_count / 5.0, 4)

    intent_hit_preview = (trace_preview_data or {}).get("intent_hit_preview") or {}
    intent_retrieval_hit_count = int(intent_hit_preview.get("retrieval_hit_count") or 0)
    if intent_retrieval_hit_count <= 0 and has_recall_bundle:
        scene_hit = bool(tier_counts["memory"] or tier_counts["episode"] or tier_counts["chapter"])
        callback_hit = bool(tier_counts["chapter"] or tier_counts["arc"] or tier_counts["saga"])
        intent_retrieval_hit_count = int(scene_hit) + int(callback_hit) + int(callback_hit) + int(callback_hit)
    intent_retrieval_ratio = round(min(4, max(0, intent_retrieval_hit_count)) / 4.0, 4)

    ann_snapshot = recall_payload.get("ann_candidate_snapshot") or {}
    ann_benchmark = ann_snapshot.get("benchmark") or {}
    ann_overlap_ratio = round(float(ann_benchmark.get("overlap_ratio") or 0.0), 4)
    ann_benchmark_status = str(ann_benchmark.get("status") or "empty")

    hit_quality_score = round((tier_coverage_ratio * 0.6) + (intent_retrieval_ratio * 0.4), 4)
    if not has_recall_bundle:
        hit_quality_status = "empty"
        hit_quality_reason = "recall_bundle_missing"
        hit_quality_score = 0.0
    elif total_hit_count <= 0:
        hit_quality_status = "empty"
        hit_quality_reason = "no_recall_hits"
    else:
        hit_quality_status = "ready"
        hit_quality_reason = "computed"

    # 3) hook survival metric
    open_hook_titles: list[str] = []
    for item in (continuity_pack_data or {}).get("pending_threads") or []:
        if not isinstance(item, dict):
            continue
        hook_status = str(item.get("status") or "").strip().lower()
        if hook_status and hook_status not in {"open", "paused", "active"}:
            continue
        title = " ".join(
            str(item.get("title") or item.get("name") or item.get("thread_type") or "").split()
        ).strip()
        if title and title not in open_hook_titles:
            open_hook_titles.append(title)

    recall_corpus_parts: list[str] = []
    for doc in recall_payload.get("documents") or []:
        if not isinstance(doc, dict):
            continue
        for key in ("title", "text", "query_matched"):
            token = _norm_text(doc.get(key), max_len=300)
            if token:
                recall_corpus_parts.append(token)
    recall_corpus = "\n".join(recall_corpus_parts)

    survived_hooks: list[str] = []
    missing_hooks: list[str] = []
    for title in open_hook_titles:
        token = _norm_text(title)
        if token and token in recall_corpus:
            survived_hooks.append(title)
        else:
            missing_hooks.append(title)

    open_hook_count = len(open_hook_titles)
    survived_hook_count = len(survived_hooks)
    hook_survival_ratio = round((survived_hook_count / open_hook_count), 4) if open_hook_count else 0.0
    if open_hook_count <= 0:
        hook_survival_status = "empty"
        hook_survival_reason = "no_open_hooks"
    elif not has_recall_bundle:
        hook_survival_status = "degraded"
        hook_survival_reason = "recall_bundle_missing"
    else:
        hook_survival_status = "ready"
        hook_survival_reason = "computed"
        if not recall_corpus:
            warnings.append("long_session_health: recall documents empty while open hooks exist")

    # 4) callback recovery metric (R-3b)
    active_storylines_raw = (continuity_pack_data or {}).get("active_storylines") or []
    callback_candidate_titles: list[str] = []
    for sl in active_storylines_raw:
        if not isinstance(sl, dict):
            continue
        sl_status = str(sl.get("status") or "").strip().lower()
        if sl_status and sl_status not in {"active", "open", "ongoing", "paused"}:
            continue
        title_raw = sl.get("name") or sl.get("title") or sl.get("storyline_title") or ""
        title = " ".join(str(title_raw).split()).strip()
        if title and title not in callback_candidate_titles:
            callback_candidate_titles.append(title)

    recovered_callbacks: list[str] = []
    missing_callbacks: list[str] = []
    for title in callback_candidate_titles:
        token = _norm_text(title)
        if token and token in recall_corpus:
            recovered_callbacks.append(title)
        else:
            missing_callbacks.append(title)

    callback_candidate_count = len(callback_candidate_titles)
    recovered_callback_count = len(recovered_callbacks)
    callback_recovery_rate = (
        round(recovered_callback_count / callback_candidate_count, 4)
        if callback_candidate_count > 0
        else 0.0
    )
    if callback_candidate_count <= 0:
        callback_recovery_status = "empty"
        callback_recovery_reason = "no_active_storylines"
    elif not has_recall_bundle:
        callback_recovery_status = "degraded"
        callback_recovery_reason = "recall_bundle_missing"
    else:
        callback_recovery_status = "ready"
        callback_recovery_reason = "computed"

    # 5) resume quality metric (R-3b)
    rp = resume_pack_data or {}
    rp_pack_status = str(rp.get("pack_status") or "empty").strip().lower()
    rp_layer_count = int(rp.get("layer_count") or 0)
    rp_sources_used: list[str] = list(rp.get("sources_used") or [])
    _max_resume_layers = 3
    resume_quality_score = (
        round(min(1.0, rp_layer_count / _max_resume_layers), 4)
        if rp_layer_count > 0
        else 0.0
    )
    long_gap_resume_ready = rp_layer_count >= 1

    if not resume_pack_data:
        resume_quality_status = "empty"
        resume_quality_reason = "resume_trigger_not_active"
        resume_quality_score = 0.0
        long_gap_resume_ready = False
    elif rp_pack_status != "ready" or rp_layer_count <= 0:
        resume_quality_status = "empty"
        resume_quality_reason = "no_hierarchy_layers"
        resume_quality_score = 0.0
        long_gap_resume_ready = False
    else:
        resume_quality_status = "ready"
        resume_quality_reason = "computed"

    metric_statuses = [
        latency_status,
        hit_quality_status,
        hook_survival_status,
        callback_recovery_status,
        resume_quality_status,
    ]
    if all(status == "ready" for status in metric_statuses):
        overall_status = "ready"
    elif any(status == "ready" for status in metric_statuses):
        overall_status = "partial"
    elif any(status == "degraded" for status in metric_statuses):
        overall_status = "degraded"
    else:
        overall_status = "empty"

    # R-3e Hardening: bundle read ?ㅽ뙣 ??health status瑜?degraded濡?媛뺥솕?쒕떎
    _bundle_src = str(bundle_read_source or "unknown").strip()
    _bundle_fb = str(bundle_fallback_reason or "").strip()
    bundle_degraded = False
    if _bundle_src == "skeleton":
        overall_status = "degraded"
        bundle_degraded = True
        if _bundle_fb:
            warnings.append(f"bundle_read_degraded: {_bundle_fb}")
        else:
            warnings.append("bundle_read_degraded: skeleton_only")
    elif _bundle_src == "partial" and _bundle_fb == "partial_reads":
        # partial read?먯꽌??status瑜???텛吏 ?딅릺 寃쎄퀬留?異붽?
        if overall_status == "ready":
            overall_status = "partial"
        warnings.append(f"bundle_read_partial: {_bundle_fb}")

    # Hardening 泥댄겕由ъ뒪??4: stale summary / canon freshness gate (fail-open, additive)
    # hierarchy tier (chapter/arc/saga)媛 ?ъ슜 以묒씠怨?canon_drift_ratio媛 ?믪쑝硫?staleness ?꾪뿕??寃쎄퀬?쒕떎.
    # injection ?숈옉? 諛붽씀吏 ?딅뒗????warning 異붽?? hierarchy_freshness ?꾨뱶 ?몄텧留??쒕떎.
    _canon_drift_ratio = round(
        float((trace_preview_data or {}).get("canon_drift_ratio") or 0.0), 4
    )
    _hierarchy_tier_count = sum(
        1 for _t in ("chapter", "arc", "saga") if tier_counts.get(_t, 0) > 0
    )
    _STALE_DRIFT_THRESHOLD = 0.3  # canon 30% ?댁긽 drift + hierarchy hit ??staleness ?꾪뿕
    hierarchy_stale_risk = False
    if _hierarchy_tier_count >= 1 and _canon_drift_ratio >= _STALE_DRIFT_THRESHOLD:
        hierarchy_stale_risk = True
        warnings.append(
            f"stale_summary_risk: hierarchy_tier_count={_hierarchy_tier_count}"
            f" canon_drift_ratio={_canon_drift_ratio:.2f}"
        )
    _hierarchy_freshness_reason = (
        "stale_risk_detected" if hierarchy_stale_risk
        else ("no_hierarchy_tiers_active" if _hierarchy_tier_count == 0 else "ok")
    )

    return {
        "version": version,
        "status": overall_status,
        "mode": "contract_only",
        "strategy": strategy,
        "context_window_profile": active_profile,
        "bundle_read_source": _bundle_src,
        "bundle_fallback_reason": _bundle_fb,
        "bundle_degraded": bundle_degraded,
        "hierarchy_freshness": {
            "stale_risk": hierarchy_stale_risk,
            "reason": _hierarchy_freshness_reason,
            "canon_drift_ratio": _canon_drift_ratio,
            "hierarchy_tier_count": _hierarchy_tier_count,
            "drift_threshold": _STALE_DRIFT_THRESHOLD,
        },
        "metrics": {
            "recall_latency": {
                "status": latency_status,
                "reason": latency_reason,
                "severity": latency_severity,
                "value_ms": latency_value_ms,
                "warning_threshold_ms": 800.0,
                "degraded_threshold_ms": 1500.0,
                "source": "prepare_turn_bundle_timer",
            },
            "recall_hit_quality": {
                "status": hit_quality_status,
                "reason": hit_quality_reason,
                "score": hit_quality_score,
                "score_max": 1.0,
                "total_hit_count": total_hit_count,
                "tier_counts": tier_counts,
                "tier_coverage_count": tier_coverage_count,
                "tier_coverage_ratio": tier_coverage_ratio,
                "intent_retrieval_hit_count": max(0, intent_retrieval_hit_count),
                "intent_retrieval_ratio": intent_retrieval_ratio,
                "ann_overlap_ratio": ann_overlap_ratio,
                "ann_benchmark_status": ann_benchmark_status,
            },
            "hook_survival": {
                "status": hook_survival_status,
                "reason": hook_survival_reason,
                "open_hook_count": open_hook_count,
                "survived_hook_count": survived_hook_count,
                "survival_ratio": hook_survival_ratio,
                "open_hooks": open_hook_titles[:12],
                "survived_hooks": survived_hooks[:12],
                "missing_hooks": missing_hooks[:12],
                "source": "pending_threads_vs_recall_documents",
            },
            "callback_recovery": {
                "status": callback_recovery_status,
                "reason": callback_recovery_reason,
                "candidate_count": callback_candidate_count,
                "recovered_count": recovered_callback_count,
                "recovery_rate": callback_recovery_rate,
                "candidates": callback_candidate_titles[:12],
                "recovered": recovered_callbacks[:12],
                "missing": missing_callbacks[:12],
                "source": "active_storylines_vs_recall_documents",
            },
            "resume_quality": {
                "status": resume_quality_status,
                "reason": resume_quality_reason,
                "score": resume_quality_score,
                "score_max": 1.0,
                "layer_count": rp_layer_count,
                "max_layers": _max_resume_layers,
                "sources_used": rp_sources_used,
                "long_gap_resume_ready": long_gap_resume_ready,
                "source": "resume_pack_hierarchy_layers",
            },
        },
        "summary": {
            "recall_latency_ms": latency_value_ms,
            "recall_hit_quality_score": hit_quality_score,
            "hook_survival_ratio": hook_survival_ratio,
            "callback_recovery_rate": callback_recovery_rate,
            "resume_quality_score": resume_quality_score,
            "resume_layer_count": rp_layer_count,
            "resume_ready": long_gap_resume_ready,
            "hierarchy_stale_risk": hierarchy_stale_risk,
        },
        "warnings": warnings,
    }


