_U1A_LAST_GOOD_SUMMARY_FALLBACK_VERSION = "u1a.v1"
_U1B_SUMMARY_STALENESS_VERSION = "u1b.v1"
_U1C_SUMMARY_RETRY_ENQUEUE_VERSION = "u1c.v1"
_U1D_SUMMARY_FAILURE_TRACE_VERSION = "u1d.v1"
_U1B_SUMMARY_STALENESS_DEFAULT_THRESHOLDS = {
    "episode": 10,
    "chapter": 60,
    "arc": 240,
    "saga": 960,
}



