def _r3d_write_health_snapshot(
    session_id: str,
    health_data: dict | None,
    turn_index: int | None,
) -> None:
    """R-3d: prepare-turn?먯꽌 怨꾩궛??long_session_health瑜?per-session 罹먯떆????ν븳??

    fail-open: ?덉쇅 諛쒖깮 ??臾댁떆?쒕떎.
    """
    if not session_id or not health_data:
        return
    from datetime import datetime, timezone
    try:
        summary = dict((health_data or {}).get("summary") or {})
        snapshot = {
            "version": _R3D_LONG_SESSION_HEALTH_SURFACE_VERSION,
            "session_id": session_id,
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "turn_index": turn_index,
            "status": str(health_data.get("status") or "empty"),
            "health_version": str(health_data.get("version") or ""),
            "summary": summary,
            "warnings": list(health_data.get("warnings") or []),
        }
        _r3d_set_health_snapshot(session_id, snapshot)
    except Exception:
        pass  # fail-open


def _looks_like_ooc_text_main(text: str) -> bool:
    content = str(text or "").strip()
    if not content:
        return False
    if _OOC_PREFIX_PATTERN_MAIN.match(content):
        return True
    return False


def _should_apply_ooc_guard_main(*, user_input: str, assistant_content: str = "", context_messages: list[dict]) -> bool:
    return should_apply_complete_turn_ooc_guard(
        user_input=user_input,
        assistant_content=assistant_content,
        context_messages=context_messages,
        looks_like_ooc_text=_looks_like_ooc_text_main,
    )


def _purge_turn_artifacts_for_ooc(session_id: str, turn_index: int) -> dict:
    sid = (session_id or "").strip()
    if not sid:
        return {"status": "off", "reason": "session_missing"}

    db = SessionLocal()
    try:
        deleted_chat_logs = (
            db.query(ChatLog)
            .filter(ChatLog.chat_session_id == sid, ChatLog.turn_index == turn_index)
            .delete(synchronize_session=False)
        )
        deleted_memories = (
            db.query(Memory)
            .filter(Memory.chat_session_id == sid, Memory.turn_index == turn_index)
            .delete(synchronize_session=False)
        )
        deleted_kg_triples = (
            db.query(KGTriple)
            .filter(KGTriple.chat_session_id == sid, KGTriple.source_turn == turn_index)
            .delete(synchronize_session=False)
        )
        deleted_direct_evidence = (
            db.query(DirectEvidenceRecord)
            .filter(
                DirectEvidenceRecord.chat_session_id == sid,
                DirectEvidenceRecord.source_turn_start <= turn_index,
                DirectEvidenceRecord.source_turn_end >= turn_index,
            )
            .delete(synchronize_session=False)
        )
        deleted_character_states = (
            db.query(CharacterState)
            .filter(CharacterState.chat_session_id == sid, CharacterState.turn_index == turn_index)
            .delete(synchronize_session=False)
        )
        deleted_character_events = (
            db.query(CharacterEvent)
            .filter(CharacterEvent.chat_session_id == sid, CharacterEvent.turn_index == turn_index)
            .delete(synchronize_session=False)
        )
        deleted_pending_threads = (
            db.query(PendingThread)
            .filter(PendingThread.chat_session_id == sid, PendingThread.source_turn == turn_index)
            .delete(synchronize_session=False)
        )
        db.commit()
        return {
            "status": "ok",
            "deleted_chat_logs": int(deleted_chat_logs or 0),
            "deleted_memories": int(deleted_memories or 0),
            "deleted_kg_triples": int(deleted_kg_triples or 0),
            "deleted_direct_evidence": int(deleted_direct_evidence or 0),
            "deleted_character_states": int(deleted_character_states or 0),
            "deleted_character_events": int(deleted_character_events or 0),
            "deleted_pending_threads": int(deleted_pending_threads or 0),
        }
    except Exception as exc:
        db.rollback()
        return {"status": "error", "reason": str(exc)[:160]}
    finally:
        db.close()


